-- Runtime scheduler required by identity, profile and outfit timers.
do
    local R = rawget(_G, "OwenRuntimeGuard")
    if type(R) ~= "table" or type(R.Start) ~= "function" or type(R.Stop) ~= "function" or type(R.Call) ~= "function" or type(R.Loops) ~= "table" then
        if R and type(R.StopAll) == "function" then pcall(R.StopAll) end
        R = { Loops = {}, Build = "chan_runtime_guard_v1" }
        _G.OwenRuntimeGuard = R
        function R.Call(_, fn, ...)
            if type(fn) ~= "function" then return false, "invalid_callback" end
            return pcall(fn, ...)
        end
        function R.Stop(key)
            local state = R.Loops[key]
            R.Loops[key] = nil
            if state then
                state.Active = false
                if state.Handle ~= nil and state.Ticker and type(state.Ticker.RemoveTimer) == "function" then
                    pcall(state.Ticker.RemoveTimer, state.Handle)
                end
                state.Handle = nil
                state.Fn = nil
            end
        end
        function R.StopAll()
            local keys = {}
            for key in pairs(R.Loops) do keys[#keys + 1] = key end
            for _, key in ipairs(keys) do R.Stop(key) end
        end
        function R.Start(key, interval, fn, initialDelay)
            if type(key) ~= "string" or type(fn) ~= "function" then return false end
            interval = math.max(tonumber(interval) or 1, 1 / 60)
            R.Stop(key)
            local loaded, ticker = pcall(require, "common.time_ticker")
            if not loaded or type(ticker) ~= "table" or type(ticker.AddTimerOnce) ~= "function" then return false end
            local state = { Active = true, Ticker = ticker, Fn = fn, Failures = 0 }
            R.Loops[key] = state
            local schedule, step
            schedule = function(delay)
                if not state.Active or R.Loops[key] ~= state then return false end
                local ok, handle = pcall(ticker.AddTimerOnce, delay, step)
                if not ok or handle == false then R.Stop(key); return false end
                state.Handle = handle
                return true
            end
            step = function()
                if not state.Active or R.Loops[key] ~= state or _G.OwenRuntimeGuard ~= R then return end
                state.Handle = nil
                local ok = R.Call(key, state.Fn)
                state.Failures = ok and 0 or math.min(8, state.Failures + 1)
                local delay = ok and interval or math.min(5, math.max(interval, 0.25) * (2 ^ (state.Failures - 1)))
                schedule(delay)
            end
            return schedule(math.max(tonumber(initialDelay) or interval, 0))
        end
    end
end

