-- ============================================================================
-- SRC-style graphics customization, adapted to LexusConfig / Chann menu.
-- Values are only applied when the master switch is enabled and are restored
-- only while the current value is still the value owned by this module.
-- ============================================================================
do
    local G = rawget(_G,"OwenGraphics")
    if type(G)~="table" then G={} end
    G.Owned=G.Owned or {}; G.Status=G.Status or {}; G.Attempts=G.Attempts or {}; G.Next=G.Next or 0
    G.Specs = {
            {Key="GraphicsPost", CVar="r.MobilePostProcessQuality", Values={false,0,1,2,3}, MinUI=-1, MaxUI=3},
            {Key="GraphicsResolutionPercent", CVar="r.ScreenPercentage_GamePlay", Values={false}, MinUI=0, MaxUI=100, Scale=1},
            {Key="GraphicsShadow", CVar="r.ShadowQuality", Values={false,0,1,2,3,4,5}, MinUI=-1, MaxUI=5},
            {Key="GraphicsBloom", CVar="r.BloomQuality", Values={false,0,1,2,3,4,5}, MinUI=-1, MaxUI=5},
            {Key="GraphicsDOF", CVar="r.DepthOfFieldQuality", Values={false,0,1,2,3}, MinUI=-1, MaxUI=3},
            {Key="GraphicsAA", CVar="r.MobileMSAA", Values={false,1,2,4}, MinUI=-1, MaxUI=4},
            {Key="GraphicsAnisotropy", CVar="r.MaxAnisotropy", Values={false,1,2,4,8}, MinUI=-1, MaxUI=8},
            {Key="GraphicsViewDistance", CVar="r.ViewDistanceScale", Values={false}, MinUI=0, MaxUI=125, Scale=100},
            {Key="GraphicsSceneLOD", CVar="r.StaticMeshLODDistanceScale", Values={false}, MinUI=0, MaxUI=200, Scale=100},
            {Key="GraphicsFoliageLOD", CVar="foliage.LODDistanceScale", Values={false}, MinUI=0, MaxUI=150, Scale=100},
            {Key="GraphicsMaterial", CVar="r.MaterialQualityLevel", Values={false,0,1,2}, MinUI=-1, MaxUI=2}
    }
    _G.OwenGraphics = G

    local cfg = _G.LexusConfig
    for _, spec in ipairs(G.Specs) do
        if spec.Key == "GraphicsResolutionPercent" then
            for n=50,100 do spec.Values[#spec.Values+1]=n end
        elseif spec.Key == "GraphicsViewDistance" then
            for n=50,125 do spec.Values[#spec.Values+1]=n/100 end
        elseif spec.Key == "GraphicsSceneLOD" then
            for n=50,200 do spec.Values[#spec.Values+1]=n/100 end
        elseif spec.Key == "GraphicsFoliageLOD" then
            for n=50,150 do spec.Values[#spec.Values+1]=n/100 end
        end
    end

    function G.Enabled()
        local c=_G.LexusConfig or {}
        return c.GraphicsCustomize==true or c.GraphicsCustomize==1
    end
    function G.Index(spec, value)
        local n=tonumber(value)
        if n and n==n and n%1==0 and n>=1 and n<=#spec.Values then return n end
        return 1
    end
    function G.Equal(a,b)
        return type(a)=="number" and type(b)=="number" and math.abs(a-b)<=0.0001*math.max(1,math.abs(b))
    end
    function G.Read(lib,name)
        if not lib or type(lib.GetConsoleVariableFloatValue)~="function" then return nil end
        local ok,v=pcall(lib.GetConsoleVariableFloatValue,name)
        v=ok and tonumber(v) or nil
        if v and v==v and v~=math.huge and v~=-math.huge then return v end
        return nil
    end
    function G.Write(gi,lib,name,value)
        if not gi or type(gi.ExecuteCMD)~="function" then return false end
        local ok,result=pcall(gi.ExecuteCMD,gi,name,tostring(value))
        return ok and result~=false and G.Equal(G.Read(lib,name),value)
    end
    function G.GetAPI()
        local ok,setting=pcall(require,"client.slua.logic.setting.logic_setting_graphics")
        local gi
        if ok and setting and type(setting.GetGameInstance)=="function" then
            local got,value=pcall(setting.GetGameInstance)
            if got then gi=value end
        end
        if not gi then
            local ok2,ui=pcall(require,"client.common.ui_util")
            if ok2 and ui and type(ui.GetGameInstance)=="function" then
                local got,value=pcall(ui.GetGameInstance)
                if got then gi=value end
            end
        end
        local loaded,lib=pcall(import,"KismetSystemLibrary")
        if not loaded then lib=nil end
        return gi,lib
    end
    function G.RestoreOne(gi,lib,name)
        local row=G.Owned[name]
        if not row then return true end
        local current=G.Read(lib,name)
        if current==nil then G.Status[name]="read_unavailable"; return false end
        if G.Equal(current,row.Original) then
            G.Owned[name]=nil; G.Status[name]="restored"; return true
        end
        if row.Applied~=nil and not G.Equal(current,row.Applied) then
            G.Owned[name]=nil; G.Status[name]="changed_externally"; return true
        end
        if (row.RestoreAttempts or 0)>=4 then G.Status[name]="restore_unconfirmed"; return false end
        row.RestoreAttempts=(row.RestoreAttempts or 0)+1
        if G.Write(gi,lib,name,row.Original) then
            G.Owned[name]=nil; G.Status[name]="restored"; return true
        end
        G.Status[name]="restore_pending"; return false
    end
    function G.Apply()
        if not G.Enabled() and next(G.Owned)==nil and not G.Baseline then return true end
        local gi,lib=G.GetAPI()
        if not gi or not lib or type(gi.ExecuteCMD)~="function" then
            G.LastError="graphics_api_unavailable"; return false
        end
        if G.Enabled() and not G.Baseline then
            local baseline={}
            for _,spec in ipairs(G.Specs) do
                local v=G.Read(lib,spec.CVar)
                if v==nil then G.LastError="baseline_read_unavailable"; return false end
                baseline[spec.CVar]=v
            end
            G.Baseline=baseline
        end
        local complete=true
        for _,spec in ipairs(G.Specs) do
            local name=spec.CVar
            local target=spec.Values[G.Index(spec,(_G.LexusConfig or {})[spec.Key])]
            if not G.Enabled() or target==false then
                if not G.RestoreOne(gi,lib,name) then complete=false end
            else
                local current=G.Read(lib,name)
                local row=G.Owned[name]
                if current==nil then
                    G.Status[name]="read_unavailable"; complete=false
                elseif row and row.Applied~=nil and not G.Equal(current,row.Applied) then
                    G.Status[name]="changed_externally"; G.Owned[name]=nil; complete=false
                elseif G.Equal(current,target) then
                    G.Status[name]="value_confirmed"
                    if not row then G.Owned[name]={Original=(G.Baseline and G.Baseline[name]) or current,Applied=current} end
                else
                    if (G.Attempts[name] or 0)>=4 then
                        G.Status[name]="write_unconfirmed"; complete=false
                    else
                        if not row then row={Original=(G.Baseline and G.Baseline[name]) or current,Applied=current}; G.Owned[name]=row end
                        G.Attempts[name]=(G.Attempts[name] or 0)+1
                        if G.Write(gi,lib,name,target) then
                            row.Applied=target; G.Status[name]="value_confirmed"
                        else
                            local observed=G.Read(lib,name)
                            if observed~=nil and not G.Equal(observed,current) then row.Applied=observed end
                            G.Status[name]="write_pending"; complete=false
                        end
                    end
                end
            end
        end
        if not G.Enabled() and next(G.Owned)==nil then G.Baseline=nil end
        G.LastError=complete and nil or "one_or_more_settings_unconfirmed"
        return complete
    end
    function G.FindSpec(key)
        for _,spec in ipairs(G.Specs) do if spec.Key==key then return spec end end
    end
    function G.GetSlider(key)
        local spec=G.FindSpec(key); if not spec then return 0 end
        local value=spec.Values[G.Index(spec,cfg[key])]
        if value==false then return spec.MinUI end
        if spec.Scale then return math.floor(value*spec.Scale+0.5) end
        return value
    end
    function G.SliderText(key,value)
        local spec=G.FindSpec(key)
        if not spec or value==spec.MinUI then return "Theo game" end
        if value==0 then return "Tắt (0)" end
        if spec.Scale then return tostring(value).."%" end
        if key=="GraphicsAA" or key=="GraphicsAnisotropy" then return tostring(value).."x" end
        return tostring(value)
    end
    function G.SetSlider(key,value)
        local spec=G.FindSpec(key); value=tonumber(value)
        if not spec or not value or value~=value then return false end
        value=math.max(spec.MinUI,math.min(spec.MaxUI,value))
        local index,best=1,math.huge
        if value>spec.MinUI then
            for i=2,#spec.Values do
                local candidate=spec.Values[i]
                if spec.Scale then candidate=candidate*spec.Scale end
                local d=math.abs(candidate-value)
                if d<best then index,best=i,d end
            end
        end
        return G.Set(key,index)
    end
    function G.Set(key,value)
        if key=="GraphicsCustomize" then
            cfg[key]=(value==true or value==1)
        elseif key=="GraphicsBuildingLOD" then
            local n=tonumber(value); if not n then return false end
            cfg[key]=math.max(0,math.min(2,math.floor(n)))
            if _G.OwenBuildingLOD then pcall(_G.OwenBuildingLOD.Tick,true) end
            return true
        elseif key=="GraphicsGloveLOD" then
            cfg[key]=(value==true or value==1)
            if _G.OwenGloveLOD then pcall(_G.OwenGloveLOD.Tick,true) end
            return true
        else
            local spec=G.FindSpec(key); if not spec then return false end
            cfg[key]=G.Index(spec,value)
        end
        G.Signature=nil; G.Tick(true)
        return true
    end
    function G.Tick(force)
        if _G.OwenBuildingLOD then pcall(_G.OwenBuildingLOD.Tick,force) end
        if _G.OwenGloveLOD then pcall(_G.OwenGloveLOD.Tick,force) end
        local now=os.clock and os.clock() or 0
        if not force and now<(G.Next or 0) then return end
        G.Next=now+1
        local parts={tostring(G.Enabled())}
        for _,spec in ipairs(G.Specs) do parts[#parts+1]=tostring(G.Index(spec,cfg[spec.Key])) end
        local signature=table.concat(parts,":")
        local ok,world=pcall(slua.getWorld)
        world=ok and world or nil
        if force or signature~=G.Signature or world~=G.World or G.Retry then
            if signature~=G.Signature or world~=G.World then G.Attempts={} end
            G.Signature=signature; G.World=world
            local complete=G.Apply()
            G.Retry=not complete
        end
    end
end

-- Experimental building LOD option from SRC, disabled by default.
do
    local B=rawget(_G,"OwenBuildingLOD")
    if type(B)~="table" then B={} end
    B.Rows=B.Rows or setmetatable({}, {__mode="k"}); B.Queue=B.Queue or {}; B.Head=B.Head or 1; B.Next=B.Next or 0; B.Status=B.Status or "off"
    _G.OwenBuildingLOD=B
    local function valid(v) return v and slua and slua.isValid and slua.isValid(v) end
    local function field(v,k) local ok,r=pcall(function() return v[k] end); if ok then return r end end
    local function selected()
        local c=_G.LexusConfig or {}
        if not (_G.OwenGraphics and _G.OwenGraphics.Enabled()) then return 0 end
        local n=tonumber(c.GraphicsBuildingLOD) or 0
        return math.max(0,math.min(2,math.floor(n)))
    end
    local function inMatch()
        local F=_G.AddOutfit
        if F and type(F.isInRealMatch)=="function" then
            local ok,v=pcall(F.isInRealMatch); return ok and v==true
        end
        return false
    end
    function B.Observe(actor)
        if selected()==0 or not inMatch() or not valid(actor) then return end
        local ok,class=pcall(import,"StaticMeshComponent")
        if not ok or not class or type(field(actor,"GetComponentsByClass"))~="function" then return end
        local got,components=pcall(actor.GetComponentsByClass,actor,class)
        if not got or not components then return end
        local nOK,count=pcall(function() return components:Num() end)
        if not nOK or type(count)~="number" then return end
        for i=0,math.min(count,128)-1 do
            local read,mesh=pcall(function() return components:Get(i) end)
            local current=read and tonumber(field(mesh,"ForcedLodModel"))
            if read and valid(mesh) and not B.Rows[mesh] and #B.Queue-B.Head<512 and current and current>=0
                and field(mesh,"Mobility")==0 and type(field(mesh,"SetForcedLodModel"))=="function" then
                local ownerOK,owner=pcall(function() return mesh:GetOwner() end)
                if ownerOK and owner==actor then
                    B.Rows[mesh]={Original=current,Asset=field(mesh,"StaticMesh")}
                    B.Queue[#B.Queue+1]=mesh
                end
            end
        end
    end
    function B.Install()
        if B.Hooked then return end
        local ok,mod=pcall(require,"GameLua.Mod.BaseMod.Actor.HouseActorBase")
        if not ok or type(mod)~="table" or type(mod.ReceiveBeginPlay)~="function" then return end
        local impl=rawget(mod,"__inner_impl") or mod
        local original=mod.ReceiveBeginPlay
        local unpack=unpack or table.unpack
        local function pack(...) return {n=select("#",...),...} end
        local wrapped=function(self,...)
            local result=pack(original(self,...)); pcall(B.Observe,self)
            return unpack(result,1,result.n)
        end
        rawset(impl,"ReceiveBeginPlay",wrapped)
        if impl~=mod then rawset(mod,"ReceiveBeginPlay",wrapped) end
        B.Hooked=true
    end
    function B.RestoreStep(limit)
        local done=0
        for mesh,row in pairs(B.Rows) do
            if done>=(limit or 16) then break end
            done=done+1
            local current=tonumber(field(mesh,"ForcedLodModel"))
            if not valid(mesh) or field(mesh,"StaticMesh")~=row.Asset or not row.Applied or current~=row.Applied then
                B.Rows[mesh]=nil
            else
                local ok=pcall(mesh.SetForcedLodModel,mesh,row.Original)
                if ok and tonumber(field(mesh,"ForcedLodModel"))==row.Original then B.Rows[mesh]=nil end
            end
        end
    end
    function B.Tick(force)
        local now=os.clock and os.clock() or 0
        if not force and now<(B.Next or 0) then return end
        local level=selected()
        local activeMatch=inMatch()
        B.Next=now+(next(B.Rows) and (level==0 or not activeMatch) and 0.05 or 1.0)
        if level==0 or not activeMatch then
            if next(B.Rows) then B.RestoreStep(16) end
            B.Queue={}; B.Head=1; B.Status=next(B.Rows) and "restore_pending" or "off"
            return
        end
        B.Install()
        local processed=0
        while B.Head<=#B.Queue and processed<16 do
            local mesh=B.Queue[B.Head]; B.Head=B.Head+1; processed=processed+1
            local row=B.Rows[mesh]
            if row and valid(mesh) and field(mesh,"StaticMesh")==row.Asset then
                local current=tonumber(field(mesh,"ForcedLodModel"))
                if current==(row.Applied or row.Original) then
                    local ok=pcall(mesh.SetForcedLodModel,mesh,level+1)
                    if ok and tonumber(field(mesh,"ForcedLodModel"))==level+1 then row.Applied=level+1; B.Status="applied" end
                else B.Rows[mesh]=nil end
            else B.Rows[mesh]=nil end
        end
        if B.Head>#B.Queue then B.Queue={}; B.Head=1 end
    end
end

-- SRC graphics option: low LOD for the local player's glove mesh.
do
    local GL=rawget(_G,"OwenGloveLOD")
    if type(GL)~="table" then GL={} end
    GL.Rows=GL.Rows or setmetatable({}, {__mode="k"}); GL.Next=GL.Next or 0; GL.Status=GL.Status or "idle"
    _G.OwenGloveLOD=GL
    local function valid(v)
        if not v or not slua or not slua.isValid then return false end
        local ok,r=pcall(slua.isValid,v); return ok and r==true
    end
    local function read(v,k)
        local ok,r=pcall(function() return v and v[k] end); if ok then return r end
    end
    local function integer(v)
        local n=tonumber(v); if n and n==n and n>=0 and n<65536 and n%1==0 then return n end
    end
    local function restore(mesh,row)
        if not valid(mesh) then return true end
        if integer(read(mesh,"MinLodModel"))~=row.Target then return true end
        local setter=read(mesh,"SetMinLOD"); if type(setter)~="function" then return false end
        local currentOverride=read(mesh,"bOverrideMinLOD")
        local ok=pcall(setter,mesh,row.OriginalMin)
        if not ok or integer(read(mesh,"MinLodModel"))~=row.OriginalMin then return false end
        if type(row.OriginalOverride)=="boolean" and currentOverride==row.AppliedOverride then
            pcall(function() mesh.bOverrideMinLOD=row.OriginalOverride end)
        end
        return true
    end
    function GL.Restore(limit)
        local done=0; local complete=true
        for mesh,row in pairs(GL.Rows) do
            if done>=(limit or 16) then complete=false; break end
            done=done+1
            if restore(mesh,row) then GL.Rows[mesh]=nil else complete=false end
        end
        GL.Status=complete and "restored" or "restore_pending"
        return complete
    end
    function GL.Tick(force)
        local cfg=_G.LexusConfig or {}
        local enabled=_G.OwenGraphics and _G.OwenGraphics.Enabled() and (cfg.GraphicsGloveLOD==true or cfg.GraphicsGloveLOD==1)
        local now=os.clock and os.clock() or 0
        if not enabled then
            if not force and now<(GL.Next or 0) then return end
            if next(GL.Rows) then GL.Restore(16) else GL.Status="off" end
            GL.Next=now+(next(GL.Rows) and 0.05 or 1.5)
            return
        end
        if not force and now<(GL.Next or 0) then return end
        GL.Next=now+1.5
        local outfit=_G.AddOutfit
        if type(outfit)~="table" or type(outfit.getLocalChar)~="function" or type(outfit.getAvatarComp2)~="function" then
            GL.Status="outfit_api_unavailable"; return
        end
        if type(outfit.isInRealMatch)=="function" then
            local okMatch,inMatch=pcall(outfit.isInRealMatch)
            if not okMatch or inMatch~=true then
                if next(GL.Rows) then GL.Restore(16) end
                GL.Status="waiting_for_match"; return
            end
        end
        local okChar,char=pcall(outfit.getLocalChar)
        if not okChar or not valid(char) then GL.Status="character_unavailable"; return end
        if char.bIsGunADS or char.bIsWeaponAiming or char.bIsFiringADS then GL.Status="native_ads"; return end
        local okComp,comp=pcall(outfit.getAvatarComp2,char)
        if not okComp or not valid(comp) then GL.Status="avatar_component_unavailable"; return end
        local slot=outfit.CUST_SLOT and outfit.CUST_SLOT.HandEffectEquipemtSlot
        local getter=read(comp,"GetMeshCompBySlot")
        if slot==nil or type(getter)~="function" then GL.Status="slot_api_unavailable"; return end
        local okMesh,mesh=pcall(getter,comp,slot)
        if not okMesh or not valid(mesh) or read(mesh,"bVisible")==false or read(mesh,"bVisible")==0 then GL.Status="mesh_pending"; return end
        local owner=read(comp,"GetOwner")
        if type(owner)=="function" then local ok,value=pcall(owner,comp); if ok then owner=value end end
        if valid(owner) and read(owner,"Mesh")==mesh then GL.Status="shared_body_mesh"; return end
        for _,otherSlot in ipairs({outfit.CUST_SLOT.ClothesEquipemtSlot,outfit.CUST_SLOT.PantsEquipemtSlot,outfit.CUST_SLOT.ShoesEquipemtSlot}) do
            if otherSlot~=slot then
                local got,other=pcall(getter,comp,otherSlot)
                if got and other==mesh then GL.Status="shared_body_mesh"; return end
            end
        end
        local info=read(mesh,"LODInfo"); local num=read(info,"Num")
        if type(num)~="function" then GL.Status="lod_info_unavailable"; return end
        local countOK,count=pcall(num,info); count=countOK and integer(count)
        if not count or count<1 or count>64 then GL.Status="lod_info_unavailable"; return end
        if count==1 then GL.Status="single_lod"; return end
        local setter=read(mesh,"SetMinLOD"); local current=integer(read(mesh,"MinLodModel"))
        if type(setter)~="function" or current==nil then GL.Status="min_lod_api_unavailable"; return end
        local asset=read(mesh,"SkeletalMesh"); local row=GL.Rows[mesh]
        if row and row.Asset~=asset then
            if not restore(mesh,row) then GL.Status="restore_pending"; return end
            GL.Rows[mesh]=nil; row=nil; current=integer(read(mesh,"MinLodModel"))
        end
        local target=count-1
        if current==target then GL.Status="low_lod_active"; return end
        if not row then row={Asset=asset,OriginalMin=current,OriginalOverride=read(mesh,"bOverrideMinLOD"),Target=target}; GL.Rows[mesh]=row end
        local applied=pcall(setter,mesh,target)
        row.AppliedOverride=read(mesh,"bOverrideMinLOD")
        if not applied or integer(read(mesh,"MinLodModel"))~=target then GL.Status="write_unconfirmed"; return end
        row.Applied=true; GL.Status="low_lod_active"
    end
end

local limitTime = os.time({ year = 2099, month = 8, day = 30, hour = 23, min = 59, sec = 0 })
local currentTime = os.time(os.date("!*t"))
local isExpired = false

pcall(function()
    local fileName = ".sys_time_cache" -- Tên file ẩn
    local paths = {
        -- ==========================================
        -- [ANDROID] THƯ MỤC SAVEGAMES (Tất cả phiên bản)
        -- ==========================================
        "//storage/emulated/0/Android/data/com.tencent.ig/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/" .. fileName,
        "//storage/emulated/0/Android/data/com.vng.pubgmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/" .. fileName,
        "//storage/emulated/0/Android/data/com.pubg.krmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/" .. fileName,
        "//storage/emulated/0/Android/data/com.rekoo.pubgm/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/" .. fileName,
        "//storage/emulated/0/Android/data/com.pubg.imobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/" .. fileName,


        "//storage/emulated/0/Android/data/com.tencent.igce/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/" .. fileName,        
        -- ==========================================
        -- [ANDROID] THƯ MỤC GAMELET/LOGS (Giấu sâu chống xóa)
        -- ==========================================
        "//storage/emulated/0/Android/data/com.tencent.ig/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName,
        "//storage/emulated/0/Android/data/com.tencent.igce/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName,
        "//storage/emulated/0/Android/data/com.vng.pubgmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName,
        "//storage/emulated/0/Android/data/com.pubg.krmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName,
        "//storage/emulated/0/Android/data/com.rekoo.pubgm/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName,
        "//storage/emulated/0/Android/data/com.pubg.imobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName,

        -- ==========================================
        -- [IOS / FALLBACK] Đường dẫn Sandbox Engine UE4
        -- ==========================================
        "Documents/ShadowTrackerExtra/Saved/SaveGames/" .. fileName,
        "Documents/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName,
        "/Documents/ShadowTrackerExtra/Saved/SaveGames/" .. fileName,
        "/Documents/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName,
        "ShadowTrackerExtra/Saved/SaveGames/" .. fileName,
        "ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName,
        "../../ShadowTrackerExtra/Saved/SaveGames/" .. fileName,
        "../../ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName
    }
    
    -- [IOS ĐẶC BIỆT] Dò tìm thư mục HOME thực tế
    if os and os.getenv then
        local homeDir = os.getenv("HOME")
        if homeDir and homeDir ~= "" then
            table.insert(paths, 1, homeDir .. "/Documents/ShadowTrackerExtra/Saved/SaveGames/" .. fileName)
            table.insert(paths, 2, homeDir .. "/Documents/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName)
        end
    end
    
    -- LỚP BẢO MẬT 1: Lấy thời gian thực từ Server Game (Anti-đổi giờ thiết bị)
    local tm = package.loaded["client.logic.common.TimeManager"]
    if not tm then 
        local s, r = pcall(require, "client.logic.common.TimeManager")
        if s and r then tm = r end
    end
    if tm and type(tm.GetServerTime) == "function" then
        local serverTime = tm.GetServerTime()
        if serverTime and serverTime > 1700000000 then 
            currentTime = serverTime -- Ưu tiên giờ Server
        end
    end

    -- LỚP BẢO MẬT 2: Đọc TẤT CẢ file ẩn tại SaveGames và Gamelet/logs (tìm mốc thời gian lớn nhất)
    local lastSeenTime = 0
    for _, path in ipairs(paths) do
        local file = io.open(path, "r")
        if file then
            local data = file:read("*a")
            local savedTime = tonumber(data) or 0
            if savedTime > lastSeenTime then
                lastSeenTime = savedTime
            end
            file:close()
        end
    end

    if currentTime < lastSeenTime then
        -- KHI BỊ LÙI NGÀY HOẶC ĐỔI GIỜ MÁY: Lấy lại mốc thời gian đã lưu lớn nhất
        currentTime = lastSeenTime
    else
        -- RẢI FILE ẨN: Lưu cập nhật thời gian mới nhất vào TẤT CẢ các thư mục có thể ghi được
        for _, path in ipairs(paths) do
            -- Hàm io.open("w") sẽ tự động bỏ qua nếu đường dẫn thư mục đó không tồn tại trên máy
            local file = io.open(path, "w")
            if file then
                file:write(tostring(currentTime))
                file:close()
            end
        end
    end
end)

isExpired = (currentTime > limitTime)

