local function SafeAddMark(id, pos, z, str, size, actor)
    local mark = nil
    pcall(function()
        local InGameMarkTools = require("GameLua.Mod.BaseMod.Common.InGameMarkTools")
        if InGameMarkTools and InGameMarkTools.ClientAddMapMark then
            mark = InGameMarkTools.ClientAddMapMark(id, pos, z, str, size, actor)
            if mark then _G.LexusState.TrackedMarks[mark] = true end
        end
    end)
    return mark
end

local SafeRemoveMark

_G.QueueChannWidgetCleanup = function(widget)
    if not widget then return end
    local state=_G.LexusState or {}
    local q=state.PendingWidgetCleanup
    if not q then q={Items={},Head=1}; state.PendingWidgetCleanup=q end
    q.Items[#q.Items+1]=widget
end

local function ProcessChannPendingCleanup()
    local state=_G.LexusState
    if not state then return end
    local q=state.PendingWidgetCleanup
    if q then
        local done=0
        while q.Head<=#q.Items and done<16 do
            local widget=q.Items[q.Head]; q.Items[q.Head]=false; q.Head=q.Head+1; done=done+1
            if widget and Valid(widget) then pcall(widget.RemoveFromParent,widget) end
        end
        if q.Head>#q.Items then state.PendingWidgetCleanup=nil
        elseif q.Head>64 then
            local compact={}; for i=q.Head,#q.Items do if q.Items[i] then compact[#compact+1]=q.Items[i] end end
            q.Items=compact; q.Head=1
        end
    end
    local marks=state.PendingMarkCleanup
    if marks then
        local done=0
        for mark in pairs(marks) do
            SafeRemoveMark(mark); marks[mark]=nil; done=done+1
            if done>=8 then break end
        end
        if next(marks)==nil then state.PendingMarkCleanup=nil end
    end
end

SafeRemoveMark = function(mark)
    if not mark then return end
    pcall(function()
        local InGameMarkTools = require("GameLua.Mod.BaseMod.Common.InGameMarkTools")
        if InGameMarkTools and InGameMarkTools.HideMapMark then
            InGameMarkTools.HideMapMark(mark)
        end
        if InGameMarkTools and InGameMarkTools.RemoveMapMark then
            InGameMarkTools.RemoveMapMark(mark)
        end
    end)
    _G.LexusState.TrackedMarks[mark] = nil
end

