local function GetConfigPaths(fileName)
    local paths = {
        "//storage/emulated/0/Android/data/com.tencent.ig/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "//storage/emulated/0/Android/data/com.tencent.igce/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "//storage/emulated/0/Android/data/com.vng.pubgmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "//storage/emulated/0/Android/data/com.pubg.krmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "//storage/emulated/0/Android/data/com.rekoo.pubgm/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "//storage/emulated/0/Android/data/com.pubg.imobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "/Documents/ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "/Documents/ShadowTrackerExtra/Saved/Paks/puffer_temp/" .. fileName,
        "/com.tencent.ig/Documents/ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "/com.tencent.igce/Documents/ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "/com.vng.pubgmobile/Documents/ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "/com.pubg.krmobile/Documents/ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "/com.rekoo.pubgm/Documents/ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "/com.pubg.imobile/Documents/ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "../../ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "../../../ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        "../../../../ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName,
        fileName
    }
    pcall(function()
        if os and os.getenv then
            local homeDir = os.getenv("HOME")
            if homeDir and homeDir ~= "" then
                table.insert(paths, 1, homeDir .. "/Documents/ShadowTrackerExtra/Saved/Paks/Paks/" .. fileName)
                table.insert(paths, 2, homeDir .. "/Documents/ShadowTrackerExtra/Saved/Paks/puffer_temp/" .. fileName)
            end
        end
    end)
    return paths
end

(function()
-- ==========================================
-- HỆ THỐNG LƯU SETTING: snapshot + một file, tương thích config cũ.
-- ==========================================
local ConfigFileName = "QuynhChann.json"
local LegacyConfigFileName = "qtrang_settings.txt"
local SaveMagic = "LXSV"
local SaveVersion = 2
local SaveKey = { 76, 101, 120, 117, 115, 77, 87, 33, 55, 145, 163, 94, 12, 107, 210, 31, 88, 201, 5, 66, 139, 250, 42, 173 }
local ChannUnpack = table.unpack or unpack
_G.LastConfigSaveStr = ""
_G.ChannSaveSnapshot = { Config = {}, Text = {}, Valid = false }

local function ChannCodec(value, encode)
    local out, chunk, count = {}, {}, 0
    for i = 1, #value do
        local b = string.byte(value, i)
        local k = (SaveKey[(i - 1) % #SaveKey + 1] + i * 7) % 256
        b = encode and ((b + k) % 256) or ((b - k) % 256)
        count = count + 1
        chunk[count] = b
        if count == 200 then
            out[#out + 1] = string.char(ChannUnpack(chunk, 1, count))
            chunk, count = {}, 0
        end
    end
    if count > 0 then out[#out + 1] = string.char(ChannUnpack(chunk, 1, count)) end
    return table.concat(out)
end

local function ChannSortedKeys(source)
    local keys = {}
    for key in pairs(source or {}) do
        if type(key) == "string" or type(key) == "number" then keys[#keys + 1] = key end
    end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
    return keys
end

local function ChannKeyText(key)
    if type(key) == "number" then return "[" .. tostring(key) .. "]" end
    return "[" .. string.format("%q", key) .. "]"
end

local function ChannValueText(value)
    local kind = type(value)
    if kind == "string" then return string.format("%q", value) end
    if kind == "number" then
        if value == value and value ~= math.huge and value ~= -math.huge then return tostring(value) end
    elseif kind == "boolean" then
        return tostring(value)
    end
    return nil
end

local function ChannSnapshotSame(source, snapshot)
    source = source or {}
    for key, value in pairs(source) do
        local kind = type(value)
        if (kind == "string" or kind == "number" or kind == "boolean") and snapshot[key] ~= value then return false end
    end
    for key in pairs(snapshot) do
        local value = source[key]
        if value == nil or (type(value) ~= "string" and type(value) ~= "number" and type(value) ~= "boolean") then return false end
    end
    return true
end

local function ChannSnapshotCopy(source, snapshot)
    for key in pairs(snapshot) do snapshot[key] = nil end
    for key, value in pairs(source or {}) do
        local kind = type(value)
        if kind == "string" or kind == "number" or kind == "boolean" then snapshot[key] = value end
    end
end

local function ChannSerialize()
    local config = _G.LexusConfig or {}
    local text = (_G.LexusState or {}).CustomTextData or {}
    local parts = { "return {\nV = ", tostring(SaveVersion), ",\nLexusConfig = {\n" }
    for _, key in ipairs(ChannSortedKeys(config)) do
        local value = ChannValueText(config[key])
        if value then parts[#parts + 1] = "  " .. ChannKeyText(key) .. " = " .. value .. ",\n" end
    end
    parts[#parts + 1] = "},\nCustomTextData = {\n"
    for _, key in ipairs(ChannSortedKeys(text)) do
        local value = ChannValueText(text[key])
        if value then parts[#parts + 1] = "  " .. ChannKeyText(key) .. " = " .. value .. ",\n" end
    end
    parts[#parts + 1] = "},\nOutfitData = " .. (type(_G.ChannOutfitData) == "string" and string.format("%q", _G.ChannOutfitData) or "nil") .. ",\n}"
    return table.concat(parts), config, text
end

local function ChannReadFile(path)
    local file
    local ok = pcall(function() file = io.open(path, "rb") end)
    if not ok or not file then return nil end
    local readOK, data = pcall(function() return file:read("*a") end)
    pcall(function() file:close() end)
    return readOK and type(data) == "string" and data ~= "" and data or nil
end

local function ChannLoadTable(data)
    if type(data) ~= "string" or data == "" then return nil end
    if data:sub(1, #SaveMagic) == SaveMagic then return nil end
    local loader = loadstring or load
    local chunk
    if _VERSION == "Lua 5.1" and loadstring then
        chunk = loader(data, "chann_config")
        if chunk and setfenv then setfenv(chunk, {}) end
    else
        chunk = loader(data, "chann_config", "t", {})
    end
    if type(chunk) ~= "function" then return nil end
    local ok, result = pcall(chunk)
    return ok and type(result) == "table" and result or nil
end

local function ChannDecodeFile(blob)
    if type(blob) ~= "string" or #blob <= #SaveMagic then return nil end
    local decodedOK, decoded = pcall(ChannCodec, blob, false)
    if not decodedOK or decoded:sub(1, #SaveMagic) ~= SaveMagic then return nil end
    local saved = ChannLoadTable(decoded:sub(#SaveMagic + 1))
    return saved and saved.V == SaveVersion and saved or nil
end

_G.SaveModSettings = function()
    local ok, saved = pcall(function()
        local quick = _G.ChannSaveSnapshot
        local config = _G.LexusConfig or {}
        local text = (_G.LexusState or {}).CustomTextData or {}
        if quick.Valid and quick.Outfit == _G.ChannOutfitData and ChannSnapshotSame(config, quick.Config) and ChannSnapshotSame(text, quick.Text) then return true end

        local data = ChannSerialize()
        if data == _G.LastConfigSaveStr then
            ChannSnapshotCopy(config, quick.Config)
            ChannSnapshotCopy(text, quick.Text)
            quick.Outfit = _G.ChannOutfitData
            quick.Valid = true
            return true
        end
        local blob = ChannCodec(SaveMagic .. data, true)
        local paths = GetConfigPaths(ConfigFileName)
        for _, path in ipairs(paths or {}) do
            if type(path) == "string" and path ~= "" then
                local tmp = path .. ".tmp"
                local file
                local openOK = pcall(function() file = io.open(tmp, "wb") end)
                if openOK and file then
                    local writeOK, written = pcall(file.write, file, blob)
                    local closeOK, closeResult = pcall(file.close, file)
                    if writeOK and written and closeOK and closeResult ~= nil then
                        local renameOK, renameResult = false, nil
                        if os and type(os.rename) == "function" then renameOK, renameResult = pcall(os.rename, tmp, path) end
                        local writeComplete = renameOK and renameResult ~= nil
                        if not writeComplete then
                            local direct
                            local directOpen = pcall(function() direct = io.open(path, "wb") end)
                            if directOpen and direct then
                                local directWrite, directResult = pcall(direct.write, direct, blob)
                                local directClose, closeResult = pcall(direct.close, direct)
                                writeComplete = directWrite and directResult ~= nil and directClose and closeResult ~= nil
                            end
                        end
                        if writeComplete then
                            _G.LastConfigSaveStr = data
                            ChannSnapshotCopy(config, quick.Config)
                            ChannSnapshotCopy(text, quick.Text)
                            quick.Outfit = _G.ChannOutfitData
                            quick.Valid = true
                            _G.LastConfigSaveError = nil
                            if os and type(os.remove) == "function" then pcall(os.remove, tmp) end
                            return true
                        end
                    end
                    if os and type(os.remove) == "function" then pcall(os.remove, tmp) end
                end
            end
        end
        _G.LastConfigSaveError = "write_failed"
        return false
    end)
    if not ok then _G.LastConfigSaveError = tostring(saved); return false end
    return saved == true
end

_G.LoadModSettings = function()
    local ok, loaded = pcall(function()
        local content
        for _, path in ipairs(GetConfigPaths(ConfigFileName) or {}) do
            local blob = ChannReadFile(path)
            if blob then
                local saved = ChannDecodeFile(blob)
                if saved then content = saved; break end
            end
        end
        -- Đọc cấu hình Lua cũ nếu file mới chưa có hoặc không hợp lệ.
        if not content then
            for _, path in ipairs(GetConfigPaths(LegacyConfigFileName) or {}) do
                local legacy = ChannReadFile(path)
                local saved = ChannLoadTable(legacy)
                if saved then content = saved; break end
            end
        end
        if not content then return false end

        local savedConfig = content.LexusConfig
        if type(savedConfig) == "table" then
            for key, value in pairs(savedConfig) do
                local kind = type(value)
                if kind == "string" or kind == "number" or kind == "boolean" then
                    _G.LexusConfig[key] = value
                end
            end
        end
        if type(content.OutfitData) == "string" and #content.OutfitData > 0 then
            _G.ChannPendingOutfitData = content.OutfitData
            _G.ChannOutfitData = content.OutfitData
        end
        local savedText = content.CustomTextData
        if type(savedText) == "table" then
            _G.LexusState.CustomTextData = _G.LexusState.CustomTextData or {}
            for key, value in pairs(savedText) do
                local kind = type(value)
                if kind == "string" or kind == "number" or kind == "boolean" then
                    _G.LexusState.CustomTextData[key] = value
                end
            end
        end
        return true
    end)
    _G.ModConfigLoadOK = ok and loaded == true
    if _G.ModConfigLoadOK then
        _G.LastConfigSaveStr = ""
        _G.ChannSaveSnapshot.Valid = false
        pcall(_G.SaveModSettings)
    end
    return _G.ModConfigLoadOK
end

-- Autosave thưa; snapshot khiến lần kiểm tra không phát sinh ghi file nếu không đổi.
local function AutoSaveLoop()
    if _G.SaveModSettings then pcall(_G.SaveModSettings) end
    local okTicker, ticker = pcall(require, "common.time_ticker")
    if okTicker and ticker and ticker.AddTimerOnce then ticker.AddTimerOnce(8.0, AutoSaveLoop) end
end

if not _G.ModConfigLoaded then
    _G.LoadModSettings()
    AutoSaveLoop()
    _G.ModConfigLoaded = true
end

_G.ReadLiveConfig = function()
    if _G.SaveModSettings then return _G.SaveModSettings() end
    return false
end



end)()

