        { Key = "ModMenu_Color_Visible",
          UI  = AliasMap.Switcher,
          Text = "Visible Color (Màu khi nhìn thấy)",
          SwitcherText  = COLOR_NAMES,
          SwitcherValue = COLOR_VALUES,
          GetFunc = function()
              return _G.LexusState.CustomTextData.WallColorVisible or 4
          end,
          SetFunc = function(_, v)
              _G.LexusState.CustomTextData.WallColorVisible = v
              _G.ColorConfig.VisibleColor = v
              if _G.SaveModSettings then pcall(_G.SaveModSettings) end
              return true
          end },

        { Key = "ModMenu_Color_Invisible",
          UI  = AliasMap.Switcher,
          Text = "Hidden Color (Màu khi bị che)",
          SwitcherText  = COLOR_NAMES,
          SwitcherValue = COLOR_VALUES,
          GetFunc = function()
              return _G.LexusState.CustomTextData.WallColorHidden or 1
          end,
          SetFunc = function(_, v)
              _G.LexusState.CustomTextData.WallColorHidden = v
              _G.ColorConfig.InvisibleColor = v
              if _G.SaveModSettings then pcall(_G.SaveModSettings) end
              return true
          end },

        { Key = "ModMenu_Color_Brightness",
          UI  = AliasMap.Slider,
          Text = "Brightness (Độ sáng 1-50, chuẩn 25)",
          Min = 1, Max = 50, Step = 1,
          GetFunc = function()
              return _G.LexusState.CustomTextData.WallColorBrightness or 25
          end,
          SetFunc = function(_, v)
              _G.LexusState.CustomTextData.WallColorBrightness = v
              _G.ColorConfig.Brightness = v
              if _G.SaveModSettings then pcall(_G.SaveModSettings) end
              return true
          end },

        { Key = "ModMenu_Color_Glow",
          UI  = AliasMap.Slider,
          Text = "Glow Intensity (Cường độ phát sáng 0-10)",
          Min = 0, Max = 10, Step = 0.5,
          GetFunc = function()
              return _G.LexusState.CustomTextData.WallColorGlow or 3.0
          end,
          SetFunc = function(_, v)
              _G.LexusState.CustomTextData.WallColorGlow = v
              _G.ColorConfig.Glow = v
              if _G.SaveModSettings then pcall(_G.SaveModSettings) end
              return true
          end },
    }

    local SettingPageDefine = require("client.logic.NewSetting.SettingPageDefine")
    if SettingPageDefine and SettingPageDefine.ModMenu then
        local page = SettingPageDefine.ModMenu
        page.Category = page.Category or {}

        for i = #page.Category, 1, -1 do
            if page.Category[i].Key == "Cat_WallColor" then
                table.remove(page.Category, i)
            end
        end

        local wallCategory = {
            Key   = "Cat_WallColor",
            Text  = "➠ WALLHACK COLOR",
            Stack = StackWallhackColor,
        }
        local graphicsIndex
        for i, category in ipairs(page.Category) do
            if category.Key == "Cat_Graphics" then
                graphicsIndex = i
                break
            end
        end
        if graphicsIndex then
            table.insert(page.Category, graphicsIndex, wallCategory)
        else
            table.insert(page.Category, wallCategory)
        end
    end
end)


    end

    local UIManager = _G.UIManager
    if UIManager and not UIManager._IsModMenuHooked then
        local old_ShowUI = UIManager.ShowUI
        UIManager.ShowUI = function(config, ...)
            local args = {...}
            local n = select('#', ...) 
            
            if config and config.keyName then
                local lowerKeyName = string.lower(config.keyName)
                if string.find(lowerKeyName, "setting_main") and not string.find(lowerKeyName, "custom") then
                    local catalog = args[1]
                    if type(catalog) == "table" and catalog[1] and type(catalog[1]) == "table" and catalog[1].Key then
                        local hasModMenu = false
                        for _, page in ipairs(catalog) do
                            if type(page) == "table" and page.Key == "ModMenu" then
                                hasModMenu = true
                                break
                            end
                        end
                        if not hasModMenu then
                            table.insert(catalog, 1, SettingPageDefine.ModMenu)
                        end
                    end
                end
            end
            local table_unpack = table.unpack or unpack
            return old_ShowUI(config, table_unpack(args, 1, n))
        end
        UIManager._IsModMenuHooked = true
    end
end


