_G.CachedItems = {}
_G.LastScanItemTime = 0

_G.CachedItems = _G.CachedItems or {}
_G.LastScanItemTime = _G.LastScanItemTime or 0
_G.ChanEspItemWidgets = _G.ChanEspItemWidgets or {}

-- Đồng hồ đơn điệu theo cách SRC.lua: tránh lệch nhịp khi world/time thay đổi.
_G.ItemESPNow = _G.ItemESPNow or function()
    local GS = _G._ItemESP_RealTimeGS
    if GS == nil then
        local ok, value = pcall(import, "GameplayStatics")
        GS = ok and value or false
        _G._ItemESP_RealTimeGS = GS
    end
    local t
    if GS then
        pcall(function()
            local world = slua.getWorld()
            if world then t = GS.GetRealTimeSeconds(world) end
        end)
    end
    if type(t) ~= "number" then t = os.clock() end
    local raw = _G._ItemESP_LastRaw
    local offset = _G._ItemESP_TimeOffset or 0
    local last = _G._ItemESP_LastTime or 0
    if raw and t < raw - 0.5 then
        offset = last - t + 0.001
        _G._ItemESP_TimeOffset = offset
    end
    local value = t + offset
    if value < last then value = last end
    _G._ItemESP_LastRaw = t
    _G._ItemESP_LastTime = value
    return value
end
_G.ChanEspItemWidgetPool = _G.ChanEspItemWidgetPool or {}
_G.LastChanEspItemDraw = 0
_G.ItemESPMaxDistance = 20000          -- 200m (UE units: cm)
_G.ItemESPScanInterval = 1.0           -- đồng bộ chu kỳ quét SRC.lua
_G.ItemESPMaxLabels = 80               -- giới hạn số nhãn để giảm tải
_G.ItemESPClass = _G.ItemESPClass or nil
_G.ItemESPWidgetCanvas = _G.ItemESPWidgetCanvas or nil

_G.ItemESPValid = function(obj)
    if obj == nil then return false end
    local ok, result = pcall(function()
        if type(Valid) == "function" then return Valid(obj) end
        if slua and type(slua.isValid) == "function" then return slua.isValid(obj) end
        return true
    end)
    return ok and (result == true or result == 1)
end

_G.ItemESPIsHidden = function(actor)
    local hidden = false
    pcall(function() hidden = not not actor.bHidden end)
    return hidden
end

_G.ItemESPCategoryEnabled = function(itemData, cfg)
    local cat = itemData and itemData.cat
    if cat == "AR" then return cfg.EspItem_AR == true end
    if cat == "Sniper" then return cfg.EspItem_Sniper == true end
    if cat == "SMG" then return cfg.EspItem_SMG == true end
    if cat == "Shotgun" then return cfg.EspItem_Shotgun == true end
    if cat == "LMG" then return cfg.EspItem_LMG == true end
    if cat == "Pistol" then return cfg.EspItem_Pistol == true end
    if cat == "Melee" then return cfg.EspItem_Melee == true end
    if cat == "Special" then return cfg.EspItem_Special == true end
    if cat == "Grenade" then return cfg.EspItem_Grenade == true end
    if cat == "Scope" then return cfg.EspItem_Scope == true end
    if cat == "Med" then return cfg.EspItem_Med == true end
    if cat == "Egg" then return cfg.EspItem_Egg == true end
    return false
end

_G.ItemESPRemoveWidget = function(data)
    if data and data.Widget and ItemESPValid(data.Widget) then
        pcall(function() data.Widget:RemoveFromParent() end)
    end
end

_G.ItemESPHideWidget = function(data)
    if data and data.Widget and ItemESPValid(data.Widget) and data.Visible then
        pcall(function()
            data.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
        end)
        data.Visible = false
    end
end

_G.ItemESPClearAllWidgets = function()
    for key, data in pairs(_G.ChanEspItemWidgets) do
        ItemESPRemoveWidget(data)
        _G.ChanEspItemWidgets[key] = nil
    end
    for i = #_G.ChanEspItemWidgetPool, 1, -1 do
        ItemESPRemoveWidget(_G.ChanEspItemWidgetPool[i])
        _G.ChanEspItemWidgetPool[i] = nil
    end
    _G.ItemESPWidgetCanvas = nil
end

_G.RunOptimizedItemAndVehicleESP = function(pc)
    local now = _G.ItemESPNow()
    local cfg = _G.LexusConfig or {}
    local widgets = _G.ChanEspItemWidgets
    local pool = _G.ChanEspItemWidgetPool

    if not cfg.EspItem_Master then
        _G.CachedItems = {}
        ItemESPClearAllWidgets()
        return
    end
    if not ItemESPValid(pc) then return end

    local player = nil
    pcall(function() player = GameplayData.GetPlayerCharacter() end)
    if not ItemESPValid(player) then return end

    -- Scan theo ChannLeak: chỉ nhận Pickup Actor còn hiện hữu và chưa bị ẩn.
    if now - (_G.LastScanItemTime or 0) >= _G.ItemESPScanInterval then
        _G.LastScanItemTime = now
        local pickupClass = _G.ItemESPClass
        if not pickupClass then
            local ok, class = pcall(function()
                return import("PickUpWrapperActor") or import("STPickupWrapperActor")
            end)
            if ok then
                pickupClass = class
                _G.ItemESPClass = class
            end
        end

        local candidates = {}
        if pickupClass then
            local actors = nil
            pcall(function() actors = Game:GetActorsByClass(pickupClass) end)
            if actors then
                local count = 0
                pcall(function() count = actors:Num() or 0 end)
                for i = 0, count - 1 do
                    local item = nil
                    pcall(function() item = actors:Get(i) end)
                    if ItemESPValid(item) and not ItemESPIsHidden(item) then
                        local distance = nil
                        pcall(function() distance = player:GetDistanceTo(item) end)
                        if type(distance) == "number" and distance <= _G.ItemESPMaxDistance then
                            local itemId = nil
                            pcall(function()
                                itemId = item.DefineID and item.DefineID.TypeSpecificID
                                if itemId == nil then itemId = item.DefineId end
                            end)
                            itemId = tonumber(itemId) or itemId
                            local itemData = itemId and ItemDatabase[itemId]
                            if itemData and ItemESPCategoryEnabled(itemData, cfg) then
                                candidates[#candidates + 1] = {
                                    act = item,
                                    id = itemId,
                                    name = itemData.name,
                                    color = itemData.color,
                                    cat = itemData.cat,
                                    distance = distance
                                }
                            end
                        end
                    end
                end
            end
        end

        table.sort(candidates, function(a, b)
            return a.distance < b.distance
        end)
        local fresh = {}
        local limit = math.min(#candidates, tonumber(_G.ItemESPMaxLabels) or 80)
        for i = 1, limit do
            fresh[i] = candidates[i]
        end
        _G.CachedItems = fresh
    end

    local chan = _G.ChanEsp
    if not chan then return end

    local canvas = nil
    pcall(function() canvas = chan.GetMainCanvas and chan.GetMainCanvas() end)
    if not ItemESPValid(canvas) or type(chan.ProjectWorldToCanvasLocal) ~= "function" then
        return
    end

    -- Canvas/HUD đổi thì không tái sử dụng widget thuộc canvas cũ.
    if _G.ItemESPWidgetCanvas ~= canvas then
        ItemESPClearAllWidgets()
        _G.ItemESPWidgetCanvas = canvas
    end

    if chan._LastCanvas ~= canvas or now - (chan._LastTransformTime or 0) >= 1.0 then
        if type(chan.UpdateCanvasTransform) == "function" then
            pcall(chan.UpdateCanvasTransform, pc)
        end
        chan._LastCanvas = canvas
        chan._LastTransformTime = now
    end

    local LinearColor = _G.ChanEspItemLinearColor or _G.FLinearColor
    local SlateColor = _G.ChanEspItemSlateColor or _G.FSlateColor
    local Vector2D = _G.ChanEspItemVector2D or _G.FVector2D
    if not LinearColor then
        local ok, value = pcall(import, "LinearColor")
        if ok then
            LinearColor = value
            _G.ChanEspItemLinearColor = value
        end
    end
    if not SlateColor then
        local ok, value = pcall(import, "SlateColor")
        if ok then
            SlateColor = value
            _G.ChanEspItemSlateColor = value
        end
    end
    if not Vector2D then
        local ok, value = pcall(import, "Vector2D")
        if ok then
            Vector2D = value
            _G.ChanEspItemVector2D = value
        end
    end
    if not LinearColor or not Vector2D then return end

    local function createWidget()
        local widget = nil
        pcall(function()
            widget = CGame:NewObjectFromPath("/Script/UMG.TextBlock", canvas)
        end)
        if not ItemESPValid(widget) then return nil end

        local ok = pcall(function()
            widget:SetText("")
            if widget.Font then
                local font = widget.Font
                font.Size = 13
                if font.OutlineSettings then
                    font.OutlineSettings.OutlineSize = 1
                    font.OutlineSettings.OutlineColor = LinearColor(0, 0, 0, 1)
                end
                if widget.SetFont then widget:SetFont(font) else widget.Font = font end
            end
            if widget.SetFontSize then widget:SetFontSize(13) end
            if widget.SetJustification then widget:SetJustification(1) end
            if widget.SetHorizontalAlignment then widget:SetHorizontalAlignment(1) end
            if widget.SetVerticalAlignment then widget:SetVerticalAlignment(1) end
            if widget.SetAutoWrapText then widget:SetAutoWrapText(false) end
            if widget.SetShadowOffset then widget:SetShadowOffset(Vector2D(1, 1)) end
            if widget.SetShadowColorAndOpacity then
                widget:SetShadowColorAndOpacity(LinearColor(0, 0, 0, 1))
            end
            widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
        end)
        if not ok then
            pcall(function() widget:RemoveFromParent() end)
            return nil
        end

        local slot = nil
        pcall(function() slot = canvas:AddChildToCanvas(widget) end)
        if not slot then
            pcall(function() widget:RemoveFromParent() end)
            return nil
        end
        pcall(function()
            slot:SetAutoSize(true)
            slot:SetZOrder(1000)
            slot:SetAlignment(Vector2D(0.5, 1.0))
        end)
        return {
            Widget = widget,
            Slot = slot,
            Position = Vector2D(0, 0),
            SmoothX = nil,
            SmoothY = nil,
            LastX = nil,
            LastY = nil,
            LastText = nil,
            LastColor = nil,
            LastUpdate = nil,
            Visible = false
        }
    end

    local function acquireWidget(key)
        local data = nil
        while #pool > 0 and not data do
            local candidate = table.remove(pool)
            if candidate and ItemESPValid(candidate.Widget) and candidate.Slot then
                data = candidate
            else
                ItemESPRemoveWidget(candidate)
            end
        end
        if not data then data = createWidget() end
        if data then
            data.SmoothX, data.SmoothY = nil, nil
            data.LastX, data.LastY = nil, nil
            data.LastText, data.LastColor = nil, nil
            data.LastUpdate = nil
            data.Visible = false
            widgets[key] = data
        end
        return data
    end

    local function releaseWidget(key, data)
        ItemESPHideWidget(data)
        widgets[key] = nil
        if data and ItemESPValid(data.Widget) and data.Slot and #pool < 100 then
            data.SmoothX, data.SmoothY = nil, nil
            data.LastX, data.LastY = nil, nil
            data.LastText, data.LastColor = nil, nil
            data.LastUpdate = nil
            pool[#pool + 1] = data
        else
            ItemESPRemoveWidget(data)
        end
    end

    local seen = {}
    local freshCache = {}

    -- Cập nhật mỗi frame như ItemLabels.Tick của ChannLeak; không khóa 30 FPS.
    for _, cached in ipairs(_G.CachedItems or {}) do
        local item = cached and cached.act
        if ItemESPValid(item) and not ItemESPIsHidden(item) then
            local distance = nil
            pcall(function() distance = player:GetDistanceTo(item) end)
            if type(distance) == "number" and distance <= _G.ItemESPMaxDistance then
                local worldLoc = nil
                pcall(function() worldLoc = item:K2_GetActorLocation() end)
                if worldLoc then
                    freshCache[#freshCache + 1] = cached
                    local key = tostring(item)
                    seen[key] = true
                    local data = widgets[key]
                    local drawLoc = {
                        X = worldLoc.X,
                        Y = worldLoc.Y,
                        Z = worldLoc.Z + 55
                    }
                    local projected, on, x, y = pcall(
                        chan.ProjectWorldToCanvasLocal, pc, drawLoc
                    )

                    if projected and on and type(x) == "number" and type(y) == "number" then
                        if not data or not ItemESPValid(data.Widget) then
                            data = acquireWidget(key)
                        end

                        if data and ItemESPValid(data.Widget) and data.Slot then
                            local meters = math.floor(distance / 100 + 0.5)
                            local displayText = string.format(
                                "%s [%dm]", tostring(cached.name or "Item"), meters
                            )
                            if data.LastText ~= displayText then
                                pcall(function() data.Widget:SetText(displayText) end)
                                data.LastText = displayText
                            end

                            local color = cached.color or
                                { R = 255, G = 255, B = 255, A = 255 }
                            local colorKey = tostring(color.R or 255) .. ":" ..
                                tostring(color.G or 255) .. ":" .. tostring(color.B or 255)
                            if data.LastColor ~= colorKey then
                                pcall(function()
                                    local linear = LinearColor(
                                        (color.R or 255) / 255,
                                        (color.G or 255) / 255,
                                        (color.B or 255) / 255,
                                        1
                                    )
                                    if SlateColor then
                                        data.Widget:SetColorAndOpacity(SlateColor(linear))
                                    else
                                        data.Widget:SetColorAndOpacity(linear)
                                    end
                                end)
                                data.LastColor = colorKey
                            end

                            -- Screen-space smoothing, with snap on large camera jumps.
                            local wasVisible = data.Visible == true
                            local dt = now - (data.LastUpdate or now)
                            if dt <= 0 or dt > 0.10 then dt = 0.016 end
                            local alpha = 1 - math.exp(-dt / 0.025)
                            if not wasVisible or data.SmoothX == nil or data.SmoothY == nil
                                or math.abs(x - data.SmoothX) > 160
                                or math.abs(y - data.SmoothY) > 160 then
                                data.SmoothX, data.SmoothY = x, y
                            else
                                data.SmoothX = data.SmoothX + (x - data.SmoothX) * alpha
                                data.SmoothY = data.SmoothY + (y - data.SmoothY) * alpha
                            end
                            data.LastUpdate = now

                            pcall(function()
                                if not data.Visible then
                                    data.Widget:SetWidgetVisibility(
                                        UEnums.ESlateVisibility.SelfHitTestInvisible
                                    )
                                    data.Visible = true
                                end
                                if data.LastX == nil or
                                    math.abs(data.SmoothX - data.LastX) > 0.25 or
                                    math.abs(data.SmoothY - data.LastY) > 0.25 then
                                    data.Position.X = data.SmoothX
                                    data.Position.Y = data.SmoothY
                                    data.Slot:SetPosition(data.Position)
                                    data.LastX, data.LastY = data.SmoothX, data.SmoothY
                                end
                            end)
                        end
                    elseif data then
                        ItemESPHideWidget(data)
                    end
                end
            end
        end
    end

    -- Hidden/destroyed/picked-up/out-of-range actors are removed immediately.
    _G.CachedItems = freshCache
    for key, data in pairs(widgets) do
        if not seen[key] then
            releaseWidget(key, data)
        end
    end
    _G.LastChanEspItemDraw = now
end


