-- ==============================================================================
-- CANVAS
-- ==============================================================================
function ChanEsp.GetMainCanvas()
    -- Never reuse a canvas from the previous match/HUD. A UObject can remain
    -- technically valid after its owning HUD has been replaced.
    local InGameUITools = package.loaded["GameLua.Mod.BaseMod.Common.UI.InGameUITools"]
    if not InGameUITools then
        local ok, value = pcall(require, "GameLua.Mod.BaseMod.Common.UI.InGameUITools")
        if ok then InGameUITools = value end
    end
    if not InGameUITools or type(InGameUITools.GetMainControlBaseUI) ~= "function" then
        ChanEsp.ESPCanvas = nil
        return nil
    end

    local okUI, MainUI = pcall(InGameUITools.GetMainControlBaseUI)
    if not okUI or not IsValid(MainUI) then
        ChanEsp.ESPCanvas = nil
        return nil
    end

    local ParentCanvas = nil
    if IsValid(MainUI.CanvasPanel_0) then
        ParentCanvas = MainUI.CanvasPanel_0
    elseif IsValid(MainUI.CanvasPanel_42) then
        ParentCanvas = MainUI.CanvasPanel_42
    end
    ChanEsp.ESPCanvas = IsValid(ParentCanvas) and ParentCanvas or nil
    return ChanEsp.ESPCanvas
end

-- ==============================================================================
-- CREATE ESP WIDGET
-- ==============================================================================
function ChanEsp.CreateESPWidget(ParentCanvas)
    if not FLinearColor or not FVector2D then return nil end

    local CornerContainer = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", ParentCanvas)
    if not IsValid(CornerContainer) then return nil end

    local CornerMainSlot = ParentCanvas:AddChildToCanvas(CornerContainer)
    if not CornerMainSlot then return nil end

    CornerMainSlot:SetAutoSize(false)
    CornerMainSlot:SetZOrder(995)
    CornerMainSlot:SetAlignment(FVector2D(0.5, 0.5))

    local whiteColor = FLinearColor(
        ChanEsp.CornerColor.R,
        ChanEsp.CornerColor.G,
        ChanEsp.CornerColor.B,
        ChanEsp.CornerColor.A
    )

    local function CreateBorderLine()
        local border = CGame:NewObjectFromPath("/Script/UMG.Border", CornerContainer)
        if border and IsValid(border) then
            border:SetBrushColor(whiteColor)
            border:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            local slot = CornerContainer:AddChildToCanvas(border)
            if slot then slot:SetAutoSize(false) end
            return { widget = border, slot = slot }
        end
        return nil
    end

    local CornerLines = {
        TopLeft_H     = CreateBorderLine(),
        TopLeft_V     = CreateBorderLine(),
        TopRight_H    = CreateBorderLine(),
        TopRight_V    = CreateBorderLine(),
        BottomLeft_H  = CreateBorderLine(),
        BottomLeft_V  = CreateBorderLine(),
        BottomRight_H = CreateBorderLine(),
        BottomRight_V = CreateBorderLine()
    }

    local BgImage = CGame:NewObjectFromPath("/Script/UMG.Image", ParentCanvas)
    if not IsValid(BgImage) then return nil end
    BgImage:SetColorAndOpacity(FLinearColor(ChanEsp.HealthBgColor.R, ChanEsp.HealthBgColor.G, ChanEsp.HealthBgColor.B, ChanEsp.HealthBgColor.A))
    BgImage:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)

    local BgSlot = ParentCanvas:AddChildToCanvas(BgImage)
    if not BgSlot then return nil end
    BgSlot:SetAutoSize(false)
    BgSlot:SetZOrder(998)
    BgSlot:SetAlignment(FVector2D(0.5, 1.0))

    local HealthImage = CGame:NewObjectFromPath("/Script/UMG.Image", ParentCanvas)
    if not IsValid(HealthImage) then return nil end
    HealthImage:SetColorAndOpacity(FLinearColor(ChanEsp.HealthColor.R, ChanEsp.HealthColor.G, ChanEsp.HealthColor.B, ChanEsp.HealthColor.A))
    HealthImage:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)

    local HealthSlot = ParentCanvas:AddChildToCanvas(HealthImage)
    if not HealthSlot then return nil end
    HealthSlot:SetAutoSize(false)
    HealthSlot:SetZOrder(999)
    HealthSlot:SetAlignment(FVector2D(0.5, 1.0))

    local function CreateStyledTextBlock(defaultColor, fontSize, alignment)
        local txt = CGame:NewObjectFromPath("/Script/UMG.TextBlock", ParentCanvas)
        local slot = nil
        if txt and IsValid(txt) then
            txt:SetText("")
            local intSize = math.floor(fontSize or 10)
            if txt.Font then
                local newFont = txt.Font
                newFont.Size = intSize
                if newFont.OutlineSettings then
                    newFont.OutlineSettings.OutlineSize = 1
                    newFont.OutlineSettings.OutlineColor = FLinearColor(0.0, 0.0, 0.0, 1.0)
                end
                if txt.SetFont then txt:SetFont(newFont) else txt.Font = newFont end
            end

            if txt.SetFontSize then txt:SetFontSize(intSize) end
            txt:SetJustification(1)
            if txt.SetHorizontalAlignment then txt:SetHorizontalAlignment(1) end
            if txt.SetVerticalAlignment then txt:SetVerticalAlignment(1) end
            if txt.SetAutoWrapText then txt:SetAutoWrapText(false) end

            if FSlateColor then txt:SetColorAndOpacity(FSlateColor(defaultColor))
            else txt:SetColorAndOpacity(defaultColor) end

            if txt.SetShadowOffset then txt:SetShadowOffset(FVector2D(0.0, 0.0)) end
            if txt.SetShadowColorAndOpacity then txt:SetShadowColorAndOpacity(FLinearColor(0.0, 0.0, 0.0, 0.0)) end
            txt:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)

            slot = ParentCanvas:AddChildToCanvas(txt)
            if slot then
                slot:SetAutoSize(true)
                slot:SetZOrder(1000)
                slot:SetAlignment(alignment or FVector2D(0.5, 0.0))
            end
        end
        return txt, slot
    end

    local WeaponWidget, WeaponSlot = CreateStyledTextBlock(ColorYellow, 13, FVector2D(0.5, 1.0))
    local NameWidget,   NameSlot   = CreateStyledTextBlock(ColorBlue,   13, FVector2D(0.5, 0.0))
    local DistWidget,   DistSlot   = CreateStyledTextBlock(ColorWhite,  13, FVector2D(0.5, 0.0))
    local StateWidget,  StateSlot  = CreateStyledTextBlock(ColorGreen,  13, FVector2D(0.5, 0.0))

    local FlagImage = CGame:NewObjectFromPath("/Script/UMG.Image", ParentCanvas)
    local FlagSlot  = nil
    if FlagImage and IsValid(FlagImage) then
        FlagImage:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
        FlagSlot = ParentCanvas:AddChildToCanvas(FlagImage)
        if FlagSlot then
            FlagSlot:SetAutoSize(false)
            FlagSlot:SetSize(FVector2D(14, 16))
            FlagSlot:SetZOrder(1000)
            FlagSlot:SetAlignment(FVector2D(0.5, 1.0))
        end
    end

    return {
        CornerContainer = CornerContainer,
        CornerSlot = CornerMainSlot,
        Corners = CornerLines,
        BgWidget = BgImage,
        BgSlot = BgSlot,
        HealthWidget = HealthImage,
        HealthSlot = HealthSlot,
        WeaponWidget = WeaponWidget,
        WeaponSlot = WeaponSlot,
        FlagWidget = FlagImage,
        FlagSlot = FlagSlot,
        NameWidget = NameWidget,
        NameSlot = NameSlot,
        DistWidget = DistWidget,
        DistSlot = DistSlot,
        StateWidget = StateWidget,
        StateSlot = StateSlot,
        _cachedWeapon = "",
        _cachedNation = nil,
        _cachedName = "",
        _cachedDist = "",
        _cachedState = "",
        _cachedIsCover = false,
        _cachedIsKnocked = false,
        _lastScanTime = 0,
        lastW = 0,
        lastH = 0,
        bVisible = true
    }
end

-- ==============================================================================
-- CORNER DIMENSIONS
-- ==============================================================================
function ChanEsp.UpdateCornerDimensions(boxData, width, height)
    if boxData.lastW and boxData.lastH then
        if math.abs(width - boxData.lastW) < 1.5 and math.abs(height - boxData.lastH) < 1.5 then
            return
        end
    end
    boxData.lastW = width
    boxData.lastH = height

    local t    = ChanEsp.CornerThickness
    local cLen = math.max(7, math.min(width, height) * ChanEsp.CornerLengthRatio)
    local C    = boxData.Corners

    boxData.CornerSlot:SetSize(FVector2D(width, height))

    if C.TopLeft_H and C.TopLeft_H.slot then
        C.TopLeft_H.slot:SetPosition(FVector2D(0, 0))
        C.TopLeft_H.slot:SetSize(FVector2D(cLen, t))
    end
    if C.TopLeft_V and C.TopLeft_V.slot then
        C.TopLeft_V.slot:SetPosition(FVector2D(0, 0))
        C.TopLeft_V.slot:SetSize(FVector2D(t, cLen))
    end
    if C.TopRight_H and C.TopRight_H.slot then
        C.TopRight_H.slot:SetPosition(FVector2D(width - cLen, 0))
        C.TopRight_H.slot:SetSize(FVector2D(cLen, t))
    end
    if C.TopRight_V and C.TopRight_V.slot then
        C.TopRight_V.slot:SetPosition(FVector2D(width - t, 0))
        C.TopRight_V.slot:SetSize(FVector2D(t, cLen))
    end
    if C.BottomLeft_H and C.BottomLeft_H.slot then
        C.BottomLeft_H.slot:SetPosition(FVector2D(0, height - t))
        C.BottomLeft_H.slot:SetSize(FVector2D(cLen, t))
    end
    if C.BottomLeft_V and C.BottomLeft_V.slot then
        C.BottomLeft_V.slot:SetPosition(FVector2D(0, height - cLen))
        C.BottomLeft_V.slot:SetSize(FVector2D(t, cLen))
    end
    if C.BottomRight_H and C.BottomRight_H.slot then
        C.BottomRight_H.slot:SetPosition(FVector2D(width - cLen, height - t))
        C.BottomRight_H.slot:SetSize(FVector2D(cLen, t))
    end
    if C.BottomRight_V and C.BottomRight_V.slot then
        C.BottomRight_V.slot:SetPosition(FVector2D(width - t, height - cLen))
        C.BottomRight_V.slot:SetSize(FVector2D(t, cLen))
    end
end

-- ==============================================================================
-- CANVAS TRANSFORM
-- ==============================================================================
function ChanEsp.UpdateCanvasTransform(PC)
    if not ChanEsp.ESPCanvas or not IsValid(ChanEsp.ESPCanvas) then return end

    local success = false
    if SlateBlueprintLibrary and SlateBlueprintLibrary.AbsoluteToLocal then
        local cg = ChanEsp.ESPCanvas:GetCachedGeometry()
        if cg then
            local pt0 = SlateBlueprintLibrary.AbsoluteToLocal(cg, FVector2D(0, 0))
            local pt1 = SlateBlueprintLibrary.AbsoluteToLocal(cg, FVector2D(100, 100))
            if pt0 and pt1 then
                ChanEsp._CanvasScaleX  = (pt1.X - pt0.X) / 100
                ChanEsp._CanvasScaleY  = (pt1.Y - pt0.Y) / 100
                ChanEsp._CanvasOffsetX = pt0.X
                ChanEsp._CanvasOffsetY = pt0.Y
                success = true
            end
        end
    end

    if not success and WidgetLayoutLibrary and WidgetLayoutLibrary.GetViewportScale then
        local scale = WidgetLayoutLibrary.GetViewportScale(PC) or 1.0
        ChanEsp._CanvasScaleX  = 1.0 / scale
        ChanEsp._CanvasScaleY  = 1.0 / scale
        ChanEsp._CanvasOffsetX = 0
        ChanEsp._CanvasOffsetY = 0
    end
end

function ChanEsp.ProjectWorldToCanvasLocal(PC, WorldLoc)
    if not IsValid(PC) or not WorldLoc or not TempProjVec2D then return false, 0, 0 end

    local res = PC:ProjectWorldLocationToScreen(WorldLoc, TempProjVec2D, true)
    if (res == true or res == 1) and (TempProjVec2D.X ~= 0 or TempProjVec2D.Y ~= 0) then
        local finalX = TempProjVec2D.X * ChanEsp._CanvasScaleX + ChanEsp._CanvasOffsetX
        local finalY = TempProjVec2D.Y * ChanEsp._CanvasScaleY + ChanEsp._CanvasOffsetY
        return true, finalX, finalY
    end
    return false, 0, 0
end

-- ==============================================================================
-- SNAP LINE
-- ==============================================================================
function ChanEsp.GetSnapLineStartPos(PC, ParentCanvas)
    local screenPixelW, screenPixelH = 0, 0
    local scale = 1.0

    pcall(function()
        if PC and PC.GetViewportSize then
            local vs = FVector2D(0, 0)
            PC:GetViewportSize(vs)
            if vs and vs.X and vs.X > 200 then
                screenPixelW = vs.X
                screenPixelH = vs.Y
            end
        end
    end)

    if screenPixelW <= 200 then
        pcall(function()
            if WidgetLayoutLibrary and WidgetLayoutLibrary.GetViewportSize then
                local vs = WidgetLayoutLibrary.GetViewportSize(PC)
                if vs and vs.X and vs.X > 200 then
                    screenPixelW = vs.X
                    screenPixelH = vs.Y
                end
            end
        end)
    end

    pcall(function()
        if WidgetLayoutLibrary and WidgetLayoutLibrary.GetViewportScale then
            local s = WidgetLayoutLibrary.GetViewportScale(PC)
            if s and type(s) == "number" and s > 0 then scale = s end
        end
    end)

    if screenPixelW <= 200 then
        screenPixelW = 1920 * scale
        screenPixelH = 1080 * scale
    end

    local centerPixelX = screenPixelW / 2.0
    local centerPixelY = ChanEsp.SnapLineOriginY * scale

    local fromX = centerPixelX * ChanEsp._CanvasScaleX + ChanEsp._CanvasOffsetX
    local fromY = centerPixelY * ChanEsp._CanvasScaleY + ChanEsp._CanvasOffsetY
    return fromX, fromY
end

function ChanEsp.CreateSnapLine(ParentCanvas)
    if not IsValid(ParentCanvas) then return nil end
    local border = CGame:NewObjectFromPath("/Script/UMG.Border", ParentCanvas)
    if not IsValid(border) then return nil end

    border:SetBrushColor(ColorWhite)
    border:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
    border.RenderTransformPivot = FVector2D(0.0, 0.5)
    border:SetRenderTransformPivot(FVector2D(0.0, 0.5))

    local slot = ParentCanvas:AddChildToCanvas(border)
    if slot then
        slot:SetAutoSize(false)
        slot:SetZOrder(990)
    end
    return { Widget = border, Slot = slot, bVisible = true }
end

function ChanEsp.UpdateSnapLine(KeyStr, toX, toY, fromX, fromY, CustomColor, ParentCanvas)
    local lineData = ChanEsp.LineWidgets[KeyStr]
    if not lineData or not IsValid(lineData.Widget) then
        lineData = ChanEsp.CreateSnapLine(ParentCanvas)
        if not lineData or not lineData.Widget or not lineData.Slot then return end
        ChanEsp.LineWidgets[KeyStr] = lineData
    end

    if not lineData.bVisible then
        lineData.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
        lineData.bVisible = true
    end

    if CustomColor then
        pcall(function() lineData.Widget:SetBrushColor(CustomColor) end)
    end

    local dx = toX - fromX
    local dy = toY - fromY
    local length = math.sqrt(dx * dx + dy * dy)
    local angle = (math.atan2 and math.atan2(dy, dx) or math.atan(dy, dx)) * (180.0 / math.pi)
    local t = ChanEsp.SnapLineThickness or 1.0

    if not lineData._CachedPosVec then
        lineData._CachedPosVec  = FVector2D(fromX, fromY - t * 0.5)
        lineData._CachedSizeVec = FVector2D(length, t)
    else
        lineData._CachedPosVec.X = fromX
        lineData._CachedPosVec.Y = fromY - t * 0.5
        lineData._CachedSizeVec.X = length
        lineData._CachedSizeVec.Y = t
    end

    pcall(function()
        lineData.Slot:SetPosition(lineData._CachedPosVec)
        lineData.Slot:SetSize(lineData._CachedSizeVec)
        lineData.Widget:SetRenderAngle(angle)
    end)
end

function ChanEsp.HideSnapLine(KeyStr)
    local lineData = ChanEsp.LineWidgets[KeyStr]
    if lineData and lineData.Widget and IsValid(lineData.Widget) and lineData.bVisible then
        lineData.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
        lineData.bVisible = false
    end
end

-- ==============================================================================
-- ENEMY COUNTER
-- ==============================================================================
function ChanEsp.CreateEnemyCounter(ParentCanvas, centerX, topY)
    local CD = ChanEsp.CounterData
    if CD.ImgPlayer and IsValid(CD.ImgPlayer) and CD.ImgBot and IsValid(CD.ImgBot) then
        return true
    end

    local imgPlayer = CGame:NewObjectFromPath("/Script/UMG.Image", ParentCanvas)
    local slotPlayer = nil
    if imgPlayer and IsValid(imgPlayer) then
        imgPlayer:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
        slotPlayer = ParentCanvas:AddChildToCanvas(imgPlayer)
        if slotPlayer then
            slotPlayer:SetAutoSize(false)
            slotPlayer:SetSize(FVector2D(BADGE_WIDTH, BADGE_HEIGHT))
            slotPlayer:SetPosition(FVector2D(centerX - BADGE_WIDTH, topY))
            slotPlayer:SetZOrder(1005)
        end
    end

    local imgBot = CGame:NewObjectFromPath("/Script/UMG.Image", ParentCanvas)
    local slotBot = nil
    if imgBot and IsValid(imgBot) then
        imgBot:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
        slotBot = ParentCanvas:AddChildToCanvas(imgBot)
        if slotBot then
            slotBot:SetAutoSize(false)
            slotBot:SetSize(FVector2D(BADGE_WIDTH, BADGE_HEIGHT))
            slotBot:SetPosition(FVector2D(centerX, topY))
            slotBot:SetZOrder(1005)
        end
    end

    local function MakeCounterText(posX, posY)
        local txt = CGame:NewObjectFromPath("/Script/UMG.TextBlock", ParentCanvas)
        local sl = nil
        if txt and IsValid(txt) then
            txt:SetText("0")
            if txt.Font then
                local font = txt.Font
                font.Size = 10
                if font.OutlineSettings then
                    font.OutlineSettings.OutlineSize = 0.0
                    font.OutlineSettings.OutlineColor = FLinearColor(0, 0, 0, 0)
                end
                txt.Font = font
            end
            if txt.SetFontSize then txt:SetFontSize(10) end
            txt:SetJustification(1)
            pcall(function() txt:SetAutoWrapText(false) end)
            if FSlateColor then txt:SetColorAndOpacity(FSlateColor(ColorWhite))
            else txt:SetColorAndOpacity(ColorWhite) end
            txt:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            sl = ParentCanvas:AddChildToCanvas(txt)
            if sl then
                sl:SetAutoSize(true)
                sl:SetAlignment(FVector2D(0.5, 0.5))
                sl:SetPosition(FVector2D(posX, posY))
                sl:SetZOrder(1010)
            end
        end
        return txt, sl
    end

    local txtPlayer, slotTxtPlayer = MakeCounterText(centerX - (BADGE_WIDTH * 0.25), topY + (BADGE_HEIGHT * 0.5))
    local txtBot,    slotTxtBot    = MakeCounterText(centerX + (BADGE_WIDTH * 0.65), topY + (BADGE_HEIGHT * 0.5))

    LoadBadgeTexture(imgPlayer, ENEMY_COUNTER_PLAYER_URLS, "ic_danger_enemy.png", "Player", CD)
    LoadBadgeTexture(imgBot,    ENEMY_COUNTER_BOT_URLS,    "ic_clear_boot.png",   "Bot",    CD)

    CD.ImgPlayer = imgPlayer; CD.SlotPlayer = slotPlayer
    CD.ImgBot = imgBot;       CD.SlotBot = slotBot
    CD.TxtPlayer = txtPlayer; CD.SlotTxtPlayer = slotTxtPlayer
    CD.TxtBot = txtBot;       CD.SlotTxtBot = slotTxtBot
    CD.bCreated = true
    return true
end

function ChanEsp.UpdateEnemyCounterDisplay(realCount, botCount, ParentCanvas, centerX, topY)
    local CD = ChanEsp.CounterData
    if not ChanEsp.bShowCounter then
        local col = UEnums.ESlateVisibility.Collapsed
        if CD.ImgPlayer and IsValid(CD.ImgPlayer) then CD.ImgPlayer:SetWidgetVisibility(col) end
        if CD.ImgBot    and IsValid(CD.ImgBot)    then CD.ImgBot:SetWidgetVisibility(col) end
        if CD.TxtPlayer and IsValid(CD.TxtPlayer) then CD.TxtPlayer:SetWidgetVisibility(col) end
        if CD.TxtBot    and IsValid(CD.TxtBot)    then CD.TxtBot:SetWidgetVisibility(col) end
        return
    end

    if not ChanEsp.CreateEnemyCounter(ParentCanvas, centerX, topY) then return end

    local now = os.clock()
    if (not CD.PlayerLoaded or not CD.BotLoaded) and (now - CD.LastDownloadRetry > 2.0) then
        CD.LastDownloadRetry = now
        if not CD.PlayerLoaded and CD.ImgPlayer then LoadBadgeTexture(CD.ImgPlayer, ENEMY_COUNTER_PLAYER_URLS, "ic_danger_enemy.png", "Player", CD) end
        if not CD.BotLoaded    and CD.ImgBot    then LoadBadgeTexture(CD.ImgBot,    ENEMY_COUNTER_BOT_URLS,    "ic_clear_boot.png",   "Bot",    CD) end
    end

    pcall(function()
        if CD.SlotPlayer then
            CD.SlotPlayer:SetSize(FVector2D(BADGE_WIDTH, BADGE_HEIGHT))
            CD.SlotPlayer:SetPosition(FVector2D(centerX - BADGE_WIDTH, topY))
        end
        if CD.SlotBot then
            CD.SlotBot:SetSize(FVector2D(BADGE_WIDTH, BADGE_HEIGHT))
            CD.SlotBot:SetPosition(FVector2D(centerX, topY))
        end
        if CD.SlotTxtPlayer then CD.SlotTxtPlayer:SetPosition(FVector2D(centerX - (BADGE_WIDTH * 0.25), topY + (BADGE_HEIGHT * 0.5))) end
        if CD.SlotTxtBot    then CD.SlotTxtBot:SetPosition(FVector2D(centerX + (BADGE_WIDTH * 0.65), topY + (BADGE_HEIGHT * 0.5))) end

        if CD.LastPlayerCount ~= realCount then
            if CD.TxtPlayer and IsValid(CD.TxtPlayer) then CD.TxtPlayer:SetText(tostring(realCount)) end
            CD.LastPlayerCount = realCount
        end
        if CD.LastBotCount ~= botCount then
            if CD.TxtBot and IsValid(CD.TxtBot) then CD.TxtBot:SetText(tostring(botCount)) end
            CD.LastBotCount = botCount
        end

        local vis = UEnums.ESlateVisibility.SelfHitTestInvisible
        if CD.ImgPlayer and IsValid(CD.ImgPlayer) then CD.ImgPlayer:SetWidgetVisibility(vis) end
        if CD.ImgBot    and IsValid(CD.ImgBot)    then CD.ImgBot:SetWidgetVisibility(vis) end
        if CD.TxtPlayer and IsValid(CD.TxtPlayer) then CD.TxtPlayer:SetWidgetVisibility(vis) end
        if CD.TxtBot    and IsValid(CD.TxtBot)    then CD.TxtBot:SetWidgetVisibility(vis) end
    end)
end

-- ==============================================================================
-- SHOW / HIDE WIDGET
-- ==============================================================================
function ChanEsp.HideWidget(boxData)
    if not boxData or not boxData.bVisible then return end
    boxData.bVisible = false
    local collapsed = UEnums.ESlateVisibility.Collapsed
    if boxData.CornerContainer then boxData.CornerContainer:SetWidgetVisibility(collapsed) end
    if boxData.BgWidget        then boxData.BgWidget:SetWidgetVisibility(collapsed) end
    if boxData.HealthWidget    then boxData.HealthWidget:SetWidgetVisibility(collapsed) end
    if boxData.WeaponWidget    then boxData.WeaponWidget:SetWidgetVisibility(collapsed) end
    if boxData.FlagWidget      then boxData.FlagWidget:SetWidgetVisibility(collapsed) end
    if boxData.NameWidget      then boxData.NameWidget:SetWidgetVisibility(collapsed) end
    if boxData.DistWidget      then boxData.DistWidget:SetWidgetVisibility(collapsed) end
    if boxData.StateWidget     then boxData.StateWidget:SetWidgetVisibility(collapsed) end
end

function ChanEsp.ShowWidget(boxData)
    if not boxData or boxData.bVisible then return end
    boxData.bVisible = true
    -- [FPS] Tôn trọng từng công tắc
    local visible = UEnums.ESlateVisibility.SelfHitTestInvisible
    local collapsed = UEnums.ESlateVisibility.Collapsed
    if boxData.CornerContainer then boxData.CornerContainer:SetWidgetVisibility(ChanEsp.bShowBox and visible or collapsed) end
    if boxData.BgWidget        then boxData.BgWidget:SetWidgetVisibility((ChanEsp.bShowBox or ChanEsp.bShowHealth) and visible or collapsed) end
    if boxData.HealthWidget    then boxData.HealthWidget:SetWidgetVisibility(ChanEsp.bShowHealth and visible or collapsed) end
    if boxData.WeaponWidget    then boxData.WeaponWidget:SetWidgetVisibility(ChanEsp.bShowWeapon and visible or collapsed) end
    if boxData.FlagWidget      then boxData.FlagWidget:SetWidgetVisibility(ChanEsp.bShowFlag and visible or collapsed) end
    if boxData.NameWidget      then boxData.NameWidget:SetWidgetVisibility(ChanEsp.bShowName and visible or collapsed) end
    if boxData.DistWidget      then boxData.DistWidget:SetWidgetVisibility(ChanEsp.bShowDist and visible or collapsed) end
    if boxData.StateWidget     then boxData.StateWidget:SetWidgetVisibility(ChanEsp.bShowState and visible or collapsed) end
end

-- ==============================================================================
-- [FPS] Force visibility mỗi frame theo config (không cần chờ ShowWidget)
-- ==============================================================================
function ChanEsp.ForceVisibility(boxData)
    if not boxData then return end
    local vis = UEnums.ESlateVisibility.SelfHitTestInvisible
    local col = UEnums.ESlateVisibility.Collapsed
    if boxData.CornerContainer then boxData.CornerContainer:SetWidgetVisibility(ChanEsp.bShowBox and vis or col) end
    if boxData.BgWidget        then boxData.BgWidget:SetWidgetVisibility((ChanEsp.bShowBox or ChanEsp.bShowHealth) and vis or col) end
    if boxData.HealthWidget    then boxData.HealthWidget:SetWidgetVisibility(ChanEsp.bShowHealth and vis or col) end
    if boxData.WeaponWidget    then boxData.WeaponWidget:SetWidgetVisibility(ChanEsp.bShowWeapon and vis or col) end
    if boxData.FlagWidget      then boxData.FlagWidget:SetWidgetVisibility(ChanEsp.bShowFlag and vis or col) end
    if boxData.NameWidget      then boxData.NameWidget:SetWidgetVisibility(ChanEsp.bShowName and vis or col) end
    if boxData.DistWidget      then boxData.DistWidget:SetWidgetVisibility(ChanEsp.bShowDist and vis or col) end
    if boxData.StateWidget     then boxData.StateWidget:SetWidgetVisibility(ChanEsp.bShowState and vis or col) end
end

-- ==============================================================================
-- [FPS] EARLY RETURN: nếu tất cả feature đều tắt → ẩn hết, không làm gì
-- ==============================================================================
function ChanEsp.IsAllDisabled()
    return not (ChanEsp.bShowBox or ChanEsp.bShowHealth or ChanEsp.bShowName 
             or ChanEsp.bShowDist or ChanEsp.bShowWeapon or ChanEsp.bShowState
             or ChanEsp.bShowFlag or ChanEsp.bShowLines or ChanEsp.bShowCounter)
end

-- ==============================================================================
-- MAIN UPDATE
-- ==============================================================================
function ChanEsp.UpdateESP(pcHint)
    if not _G.LexusConfig then return end
    local C   = _G.LexusConfig
    local CTD = (_G.LexusState and _G.LexusState.CustomTextData) or {}

    -- One-time migration: older Chann builds stored every Chan ESP child as
    -- false. When the user enables the master switch, seed a useful baseline
    -- once instead of silently rendering nothing. User can still turn items off.
    if (C.EspV3 == true or C.EspV3 == 1) and C._ChanEspDefaultsMigrated ~= true then
        local allOff = C.EspV3_Box == false and C.EspV3_Health == false
            and C.EspV3_Name == false and C.EspV3_Dist == false
            and C.EspV3_Weapon == false and C.EspV3_State == false
            and C.EspV3_Flag == false and C.EspV3_Line == false
            and C.EspV3_Counter == false and C.EspV3_Vis == false
        if allOff then
            C.EspV3_Box = true
            C.EspV3_Health = true
            C.EspV3_Name = true
            C.EspV3_Dist = true
            C.EspV3_Weapon = true
        end
        C._ChanEspDefaultsMigrated = true
    end

    -- Master switch
    ChanEsp.bActive = C.EspV3 ~= false

if not ChanEsp.bActive then
    if not ChanEsp._bDestroyedWhenOff then
        ChanEsp._bDestroyedWhenOff = true
        if ChanEsp.ResetWidgets then
            pcall(ChanEsp.ResetWidgets)
        end
    end
    return
else
    ChanEsp._bDestroyedWhenOff = false
end
    -- Feature toggles
    ChanEsp.bShowBox     = C.EspV3_Box     ~= false
    ChanEsp.bShowHealth  = C.EspV3_Health  ~= false
    ChanEsp.bShowName    = C.EspV3_Name    ~= false
    ChanEsp.bShowDist    = C.EspV3_Dist    ~= false
    ChanEsp.bShowWeapon  = C.EspV3_Weapon  ~= false
    ChanEsp.bShowState   = C.EspV3_State   ~= false
    ChanEsp.bShowFlag    = C.EspV3_Flag    ~= false
    ChanEsp.bShowLines   = C.EspV3_Line    ~= false
    ChanEsp.bShowCounter = C.EspV3_Counter ~= false
    ChanEsp.bCheckVis    = C.EspV3_Vis     ~= false

    -- [FPS] Nếu mọi tính năng tắt → ẩn hết, thoát sớm
    if ChanEsp.IsAllDisabled() then
        for _, bd in pairs(ChanEsp.BoxWidgets) do ChanEsp.HideWidget(bd) end
        for k, _ in pairs(ChanEsp.LineWidgets) do ChanEsp.HideSnapLine(k) end
        return
    end

    -- Slider values
    ChanEsp.SnapLineThickness = tonumber(CTD.EspV3_LineThick)   or 1.0
    ChanEsp.CornerThickness   = tonumber(CTD.EspV3_CornerThick) or 1.0
    ChanEsp.HealthBarWidth    = tonumber(CTD.EspV3_HealthWidth) or 2.0
    ChanEsp.SnapLineOriginY   = tonumber(CTD.EspV3_SnapY)       or 72

    -- Light rendering follows the configured frame rate (SRC-style split:
    -- cached player discovery, frequent position/widget updates).
    local updateHz = tonumber(CTD.EspV3_UpdateHz) or 60
    if updateHz < 10 then updateHz = 10 end
    if updateHz > 60 then updateHz = 60 end
    ChanEsp._UpdateInterval = 1.0 / updateHz

    local nowClock = os.clock and os.clock() or 0
    if nowClock - ChanEsp._LastUpdateTime < ChanEsp._UpdateInterval then return end
    ChanEsp._LastUpdateTime = nowClock

    -- ============ CODE GỐC ============
    local ParentCanvas = ChanEsp.GetMainCanvas()
    if not ParentCanvas then return end

    local GameplayData = package.loaded["GameLua.GameCore.Data.GameplayData"] or _G.GameplayData
    if not GameplayData then return end

    -- Reuse the controller already resolved by MainLoop. During match loading,
    -- GameplayData.GetPlayerCharacter() can briefly be nil while the controller
    -- already owns the new pawn.
    local PC = IsValid(pcHint) and pcHint or nil
    if not PC and type(GameplayData.GetPlayerController) == "function" then
        local okPC, valuePC = pcall(GameplayData.GetPlayerController)
        if okPC then PC = valuePC end
    end
    if not IsValid(PC) then return end

    local LocalPlayer = nil
    if type(GameplayData.GetPlayerCharacter) == "function" then
        local okPawn, valuePawn = pcall(GameplayData.GetPlayerCharacter)
        if okPawn then LocalPlayer = valuePawn end
    end
    if not IsValid(LocalPlayer) and type(PC.GetPlayerCharacterSafety) == "function" then
        local okPawn, valuePawn = pcall(PC.GetPlayerCharacterSafety, PC)
        if okPawn then LocalPlayer = valuePawn end
    end
    if not IsValid(LocalPlayer) then return end

    -- World identity is an additional match-transition boundary. Some game
    -- builds recycle the same pawn/controller while replacing the HUD canvas.
    local currentWorld = nil
    pcall(function() currentWorld = slua.getWorld() end)
    local worldChanged = ChanEsp._WidgetWorld ~= nil and currentWorld ~= nil
        and ChanEsp._WidgetWorld ~= currentWorld

    -- HUD canvas / local pawn / world can be replaced between matches.
    local canvasChanged = ChanEsp._WidgetCanvas ~= nil and ChanEsp._WidgetCanvas ~= ParentCanvas
    local pawnChanged = ChanEsp._WidgetOwner ~= nil and ChanEsp._WidgetOwner ~= LocalPlayer
    if worldChanged or canvasChanged or pawnChanged then
        if ChanEsp.ResetWidgets then pcall(ChanEsp.ResetWidgets) end
        if _G.ChanEspItemWidgets then
            for key, data in pairs(_G.ChanEspItemWidgets) do
                if data and data.Widget and IsValid(data.Widget) then
                    pcall(function() data.Widget:RemoveFromParent() end)
                end
                _G.ChanEspItemWidgets[key] = nil
            end
        end
        if ChanEsp.ResetVehicleESP then pcall(ChanEsp.ResetVehicleESP) end
        if _G.OwenNeonBomb and _G.OwenNeonBomb.Clear then
            pcall(_G.OwenNeonBomb.Clear, _G.OwenNeonBomb)
        end
        ChanEsp._LastCanvas = nil
        ChanEsp._LastTransformTime = 0
        ChanEsp._PawnScanCache = nil
        ChanEsp._LastPawnScanTime = 0
    end
    ChanEsp._WidgetCanvas = ParentCanvas
    ChanEsp._WidgetOwner = LocalPlayer
    ChanEsp._WidgetWorld = currentWorld or ChanEsp._WidgetWorld
    ChanEsp.ESPCanvas = ParentCanvas

    local curTime = os.clock and os.clock() or 0
    if ChanEsp._LastCanvas ~= ParentCanvas or (curTime - ChanEsp._LastTransformTime > 1.0) then
        ChanEsp.UpdateCanvasTransform(PC)
        ChanEsp._LastCanvas = ParentCanvas
        ChanEsp._LastTransformTime = curTime
    end

    local bRunHeavyTasks = (curTime - ChanEsp._LastHeavyUpdateTime > 0.2)   -- [FPS] 0.2s thay vì 0.15s
    if bRunHeavyTasks then ChanEsp._LastHeavyUpdateTime = curTime end

    local bUpdateVisCheck = (curTime - ChanEsp._LastVisCheckTime > 0.2)     -- [FPS] 0.2s thay vì 0.12s
    if bUpdateVisCheck then ChanEsp._LastVisCheckTime = curTime end

    local fromX, fromY = ChanEsp.GetSnapLineStartPos(PC, ParentCanvas)

    local TeamID = LocalPlayer.TeamID or (LocalPlayer.GetTeamID and LocalPlayer:GetTeamID()) or 0

    -- Refresh the player snapshot independently from per-frame rendering.
    -- Keep the lighter 0.25s scan cadence from Fixed1; retain Fixed2's
    -- CGameState fallback so the player list can recover after match changes.
    local scanInterval = 0.25
    if not ChanEsp._PawnScanCache or (curTime - (ChanEsp._LastPawnScanTime or 0)) >= scanInterval then
        local snapshot, seenPawns = {}, {}
        local playerCount = 0

        local function addPawn(key, pawn)
            if not IsValid(pawn) then return end
            local playerKey = nil
            pcall(function()
                if pawn.GetPlayerKey then playerKey = pawn:GetPlayerKey() end
                playerKey = playerKey or pawn.PlayerKey or (pawn.PlayerState and pawn.PlayerState.PlayerKey)
            end)
            if playerKey == 0 or playerKey == "" then playerKey = nil end
            local stableKey = playerKey or tostring(pawn)
            if not seenPawns[stableKey] then
                seenPawns[stableKey] = true
                playerCount = playerCount + 1
                snapshot[#snapshot + 1] = { Key = stableKey, Pawn = pawn }
            end
        end

        pcall(function()
            local allPawns = Game and Game.GetAllPlayerPawns and Game:GetAllPlayerPawns()
            if allPawns then
                for key, pawn in pairs(allPawns) do addPawn(key, pawn) end
            end
        end)

        -- SRC fallback: Game pawn enumeration can be incomplete after a round
        -- transition. CGameState's character list is the secondary source.
        if playerCount <= 1 then
            local gameState = _G.CGameState
            if not gameState then
                local okState, valueState = pcall(require, "GameLua.GameCore.Data.CGameState")
                if okState then gameState = valueState end
            end
            if gameState and type(gameState.GetAllCharacters) == "function" then
                pcall(function()
                    local allCharacters = gameState:GetAllCharacters()
                    if allCharacters then
                        for key, pawn in pairs(allCharacters) do addPawn(key, pawn) end
                    end
                end)
            end
        end

        ChanEsp._PawnScanCache = snapshot
        ChanEsp._LastPawnScanTime = curTime
    end

    local SeenKeys = {}
    local RealPlayerCount = 0
    local BotCount = 0

    for _, entry in ipairs(ChanEsp._PawnScanCache or {}) do
        local Key, Pawn = entry.Key, entry.Pawn
        if IsValid(Pawn) and Pawn ~= LocalPlayer then
            local pawnTeam = Pawn.TeamID or (Pawn.GetTeamID and Pawn:GetTeamID()) or -1
            local isAlive = (Pawn.Health and Pawn.Health > 0) or (Pawn.IsAlive and Pawn:IsAlive())

            if isAlive and pawnTeam ~= TeamID then
                local KeyStr = tostring(Key)
                SeenKeys[KeyStr] = true

                local ping = (Pawn.PlayerState and Pawn.PlayerState.Ping) or Pawn.Ping or (Pawn.GetPing and Pawn:GetPing()) or -1
                ping = tonumber(ping) or -1
                local isBot = (ping >= 0 and ping <= 3) or Pawn.bIsAI or Pawn.bIsAIBot or Pawn.bIsABot or (Game and Game.IsAI and Game:IsAI(Pawn))

                if isBot then BotCount = BotCount + 1
                else RealPlayerCount = RealPlayerCount + 1 end

                local Loc = Pawn.K2_GetActorLocation and Pawn:K2_GetActorLocation()
                if not Loc and Pawn.RootComponent then
                    Loc = Pawn.RootComponent:K2_GetComponentLocation()
                end

                if Loc then
                    local topWorldPos    = nil
                    local bottomWorldPos = nil

                    local mesh = Pawn.Mesh or (Pawn.GetMesh and Pawn:GetMesh()) or Pawn.CharacterMesh0
                    if mesh and mesh.GetSocketLocation then
                        local hLoc = mesh:GetSocketLocation("Head") or mesh:GetSocketLocation("head")
                        if hLoc and (hLoc.X ~= 0 or hLoc.Y ~= 0 or hLoc.Z ~= 0) then
                            topWorldPos = FVector(hLoc.X, hLoc.Y, hLoc.Z + 15)
                        end
                        local rLoc = mesh:GetSocketLocation("root") or mesh:GetSocketLocation("Root")
                        if rLoc and (rLoc.X ~= 0 or rLoc.Y ~= 0 or rLoc.Z ~= 0) then
                            bottomWorldPos = rLoc
                        end
                    end

                    local isProne = false
                    local isCrouch = false
                    if Pawn.bIsProning or Pawn.bIsProne or (Pawn.IsProne and Pawn:IsProne()) or Pawn.PoseState == 2 or Pawn.PoseState == "Prone" then
                        isProne = true
                    elseif Pawn.bIsCrouched or (Pawn.IsCrouched and Pawn:IsCrouched()) or Pawn.PoseState == 1 or Pawn.PoseState == "Crouch" then
                        isCrouch = true
                    end

                    if not topWorldPos or not bottomWorldPos then
                        local topOffset = isProne and 18 or (isCrouch and 50 or 88)
                        local bottomOffset = isProne and -22 or (isCrouch and -68 or -90)
                        topWorldPos    = topWorldPos    or FVector(Loc.X, Loc.Y, Loc.Z + topOffset)
                        bottomWorldPos = bottomWorldPos or FVector(Loc.X, Loc.Y, Loc.Z + bottomOffset)
                    end

                    local bTopOk, topX, topY       = ChanEsp.ProjectWorldToCanvasLocal(PC, topWorldPos)
                    local bBottomOk, bottomX, bottomY = ChanEsp.ProjectWorldToCanvasLocal(PC, bottomWorldPos)

                    local boxData = ChanEsp.BoxWidgets[KeyStr]
                    if not boxData then
                        boxData = ChanEsp.CreateESPWidget(ParentCanvas)
                        if boxData then ChanEsp.BoxWidgets[KeyStr] = boxData end
                    end

                    if boxData and IsValid(boxData.CornerContainer) then
                        if bTopOk and bBottomOk then
                            local boxHeight = math.max(28, math.abs(bottomY - topY))
                            local boxWidth  = math.max(15, boxHeight * (isProne and 1.1 or (isCrouch and 0.7 or 0.55)))

                            local centerX    = (topX + bottomX) * 0.5
                            local centerY    = (topY + bottomY) * 0.5
                            local boxTopY    = centerY - (boxHeight * 0.5)
                            local boxBottomY = centerY + (boxHeight * 0.5)

                            ChanEsp.UpdateCornerDimensions(boxData, boxWidth, boxHeight)
                            boxData.CornerSlot:SetPosition(FVector2D(centerX, centerY))
                            ChanEsp.ShowWidget(boxData)
                            ChanEsp.ForceVisibility(boxData)  -- [FPS] Force theo công tắc

                            -- HEALTH
                            if ChanEsp.bShowHealth then
                                local healthBarWidth = ChanEsp.HealthBarWidth or 2.0
                                local healthCenterX  = centerX - (boxWidth * 0.5) - 2.5 - (healthBarWidth * 0.5)
                                local health    = Pawn.Health or (Pawn.GetHealth and Pawn:GetHealth()) or 100
                                local healthMax = Pawn.HealthMax or (Pawn.GetHealthMax and Pawn:GetHealthMax()) or 100
                                if healthMax <= 0 then healthMax = 100 end

                                local healthPercent       = math.max(0, math.min(1, health / healthMax))
                                local currentHealthHeight = boxHeight * healthPercent

                                boxData.BgSlot:SetSize(FVector2D(healthBarWidth, boxHeight))
                                boxData.BgSlot:SetPosition(FVector2D(healthCenterX, boxBottomY))
                                boxData.HealthSlot:SetSize(FVector2D(healthBarWidth, currentHealthHeight))
                                boxData.HealthSlot:SetPosition(FVector2D(healthCenterX, boxBottomY))
                            end


                            -- WEAPON
                            if ChanEsp.bShowWeapon then
                                if bRunHeavyTasks or boxData._cachedWeapon == "" then
                                    local wep, weaponId, weaponName = nil, nil, "Tay Không"
                                    pcall(function()
                                        if type(Pawn.GetCurrentWeapon) == "function" then
                                            wep = Pawn:GetCurrentWeapon()
                                        end
                                        if not Valid(wep) then wep = Pawn.CurrentWeapon end
                                        if not Valid(wep) and type(Pawn.GetWeaponManager) == "function" then
                                            local manager = Pawn:GetWeaponManager()
                                            if Valid(manager) and type(manager.GetCurrentWeapon) == "function" then
                                                wep = manager:GetCurrentWeapon()
                                            end
                                        end
                                        if Valid(wep) then
                                            if type(wep.GetWeaponID) == "function" then weaponId = wep:GetWeaponID() end
                                            if not weaponId then weaponId = wep.WeaponID end
                                            if not weaponId and type(wep.GetItemID) == "function" then weaponId = wep:GetItemID() end
                                            if type(wep.GetWeaponName) == "function" then
                                                local value = wep:GetWeaponName()
                                                if value ~= nil and tostring(value) ~= "" then weaponName = tostring(value) end
                                            elseif wep.WeaponName ~= nil and tostring(wep.WeaponName) ~= "" then
                                                weaponName = tostring(wep.WeaponName)
                                            end
                                        end
                                        if not weaponId then
                                            local ps = nil
                                            if type(Pawn.GetPlayerStateSafety) == "function" then
                                                ps = Pawn:GetPlayerStateSafety()
                                            elseif type(Pawn.GetPlayerState) == "function" then
                                                ps = Pawn:GetPlayerState()
                                            end
                                            if Valid(ps) then
                                                if type(ps.GetCurrentWeaponID) == "function" then weaponId = ps:GetCurrentWeaponID() end
                                                if not weaponId then weaponId = ps.CurWeaponID end
                                            end
                                        end
                                    end)
                                    if weaponName == "Tay Không" and weaponId ~= nil then
                                        local id = tonumber(weaponId) or weaponId
                                        local itemInfo = ItemDatabase and (ItemDatabase[id] or ItemDatabase[tostring(id)])
                                        if itemInfo and itemInfo.name then weaponName = tostring(itemInfo.name) end
                                    end
                                    weaponName = tostring(weaponName):gsub("^BP_", ""):gsub("_C$", ""):gsub("_Wrapper$", "")
                                    if boxData._cachedWeapon ~= weaponName then
                                        boxData.WeaponWidget:SetText(weaponName)
                                        boxData._cachedWeapon = weaponName
                                    end
                                end
                                boxData.WeaponSlot:SetPosition(FVector2D(centerX, boxTopY - 3.5))
                            end

                            -- FLAG
                            if ChanEsp.bShowFlag then
                                if bRunHeavyTasks or not boxData._cachedNation then
                                    local playerNation = (Pawn.PlayerState and Pawn.PlayerState.Nation) or Pawn.Nation or ""
                                    playerNation = tostring(playerNation or "")
                                    if playerNation == "" or playerNation == "nil" or playerNation == "0" then
                                        playerNation = "G1"
                                    end

                                    if boxData._cachedNation ~= playerNation then
                                        local cfg = (CDataTable and CDataTable.GetTableData) and CDataTable.GetTableData("RegionConfig", playerNation)
                                        if not cfg or not cfg.res_path or cfg.res_path == "" then
                                            cfg = (CDataTable and CDataTable.GetTableData) and CDataTable.GetTableData("RegionConfig", "G1")
                                        end
                                        local flagPath = (cfg and cfg.res_path) or "/Game/UMG/Texture/Atlas/NationalflagUI/Frames/T_icon_flag_iland_png.T_icon_flag_iland_png"

                                        if boxData.FlagWidget and IsValid(boxData.FlagWidget) then
                                            local bSet = false
                                            if boxData.FlagWidget.SetBrushResourceFromPathSync then
                                                boxData.FlagWidget:SetBrushResourceFromPathSync(flagPath, false)
                                                bSet = true
                                            end
                                            if not bSet and boxData.FlagWidget.SetBrushFromPathAsync then
                                                boxData.FlagWidget:SetBrushFromPathAsync(flagPath, false)
                                                bSet = true
                                            end
                                            if not bSet then
                                                local util = package.loaded["client.slua_ui_framework.util"]
                                                if not util then pcall(function() util = require("client.slua_ui_framework.util") end) end
                                                if util and util.SetTexture then
                                                    util.SetTexture(boxData.FlagWidget, flagPath, { sync = true })
                                                    bSet = true
                                                end
                                            end
                                            if not bSet then
                                                local asset_util = package.loaded["common.asset_util"]
                                                if not asset_util then pcall(function() asset_util = require("common.asset_util") end) end
                                                local flagTex = (asset_util and asset_util.GetAssetSync and asset_util.GetAssetSync(flagPath))
                                                             or (CGame and CGame.LoadObject and CGame:LoadObject(flagPath))
                                                if flagTex and boxData.FlagWidget.SetBrushFromTexture then
                                                    boxData.FlagWidget:SetBrushFromTexture(flagTex, false)
                                                    bSet = true
                                                end
                                            end
                                            boxData.FlagWidget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                                        end
                                        boxData._cachedNation = playerNation
                                    end
                                end
                                if boxData.FlagSlot then
                                    boxData.FlagSlot:SetPosition(FVector2D(centerX, boxTopY - 22.0))
                                end
                            end

                            -- NAME
                            if ChanEsp.bShowName then
                                if bRunHeavyTasks or boxData._cachedName == "" then
                                    local playerName = isBot and "Bot" or (Pawn.PlayerName or Pawn.PlayerNamePublic or (Pawn.GetPlayerName and Pawn:GetPlayerName()) or "Player")
                                    playerName = tostring(playerName)
                                    if boxData._cachedName ~= playerName then
                                        boxData.NameWidget:SetText(playerName)
                                        boxData._cachedName = playerName
                                    end
                                end
                                boxData.NameSlot:SetPosition(FVector2D(centerX, boxBottomY + 4.0))
                            end

                            -- DISTANCE
                            if ChanEsp.bShowDist then
                                local distVal = math.floor(LocalPlayer:GetDistanceTo(Pawn) / 100.0)
                                local distStr = tostring(distVal) .. "m"
                                if boxData._cachedDist ~= distStr then
                                    boxData.DistWidget:SetText(distStr)
                                    boxData._cachedDist = distStr
                                end
                                boxData.DistSlot:SetPosition(FVector2D(centerX, boxBottomY + 20.5))
                            end

                            -- VIS
                            local isVisible = true
                            if ChanEsp.bCheckVis then
                                if bUpdateVisCheck or ChanEsp._VisCheckCache[KeyStr] == nil then
                                    ChanEsp._VisCheckCache[KeyStr] = (PC and PC.LineOfSightTo and PC:LineOfSightTo(Pawn)) or false
                                end
                                isVisible = ChanEsp._VisCheckCache[KeyStr]
                            end

                            -- STATE
                            if ChanEsp.bShowState then
                                if bRunHeavyTasks or boxData._cachedState == "" then
                                    local isKnocked = (Pawn.HealthStatus == 1 or Pawn.bIsKnocked or (Pawn.IsKnocked and Pawn:IsKnocked()))
                                    local stateStr = "Thấy"
                                    local slateCol = SlateColorGreen
                                    if isKnocked then
                                        stateStr = "Knocked"
                                        slateCol = SlateColorRed
                                    elseif not isVisible then
                                        stateStr = "Khuất"
                                        slateCol = SlateColorRed
                                    end

                                    if boxData._cachedState ~= stateStr then
                                        boxData.StateWidget:SetText(stateStr)
                                        boxData.StateWidget:SetColorAndOpacity(slateCol)
                                        boxData._cachedState = stateStr
                                    end
                                end
                                boxData.StateSlot:SetPosition(FVector2D(centerX, boxBottomY + 37.0))
                            end

                            -- SNAPLINE
                            if ChanEsp.bShowLines then
                                local lineColor = isVisible and ColorGreen or ColorRed
                                ChanEsp.UpdateSnapLine(KeyStr, centerX, boxTopY, fromX, fromY, lineColor, ParentCanvas)
                            else
                                ChanEsp.HideSnapLine(KeyStr)
                            end
                        else
                            ChanEsp.HideWidget(boxData)
                            ChanEsp.HideSnapLine(KeyStr)
                        end
                    end
                end
            end
        end
    end

    -- Clean stale
    for KeyStr, boxData in pairs(ChanEsp.BoxWidgets) do
        if not SeenKeys[KeyStr] then ChanEsp.HideWidget(boxData) end
    end
    for KeyStr, _ in pairs(ChanEsp.LineWidgets) do
        if not SeenKeys[KeyStr] then
            ChanEsp.HideSnapLine(KeyStr)
            ChanEsp._VisCheckCache[KeyStr] = nil
        end
    end

    -- Counter
    if ChanEsp.bShowCounter then
        local counterTopY = fromY - BADGE_HEIGHT - 2
        if counterTopY < 10 then counterTopY = 48 end
        ChanEsp.UpdateEnemyCounterDisplay(RealPlayerCount, BotCount, ParentCanvas, fromX, counterTopY)
    else
        local CD = ChanEsp.CounterData
        local col = UEnums.ESlateVisibility.Collapsed
        if CD.ImgPlayer and IsValid(CD.ImgPlayer) then CD.ImgPlayer:SetWidgetVisibility(col) end
        if CD.ImgBot    and IsValid(CD.ImgBot)    then CD.ImgBot:SetWidgetVisibility(col) end
        if CD.TxtPlayer and IsValid(CD.TxtPlayer) then CD.TxtPlayer:SetWidgetVisibility(col) end
        if CD.TxtBot    and IsValid(CD.TxtBot)    then CD.TxtBot:SetWidgetVisibility(col) end
    end
end

-- ChanEsp chỉ chạy trong MainLoop; không giữ timer trên PlayerController cũ.

_G.ChanEsp = ChanEsp

function ChanEsp.Start()
    ChanEsp.bActive = true
    ChanEsp._bDestroyedWhenOff = false
    ChanEsp._LastUpdateTime = 0
    ChanEsp._LastTransformTime = 0
    ChanEsp._LastHeavyUpdateTime = 0
    ChanEsp._LastVisCheckTime = 0
    ChanEsp._PawnScanCache = nil
    ChanEsp._LastPawnScanTime = 0
end

-- Gộp Player Box, vehicle wall và item labels dưới một bộ điều phối duy nhất.
ChanEsp.UpdateWorldESP = _G.RunOptimizedItemAndVehicleESP
_G.RunOptimizedItemAndVehicleESP = nil

ChanEsp.UpdateVehicleESP = function()
    if ChanEsp.Vehicle and ChanEsp.Vehicle.Update then
        return ChanEsp.Vehicle.Update()
    end
end

ChanEsp.ResetVehicleESP = function(deferRemoval)
    if ChanEsp.Vehicle and ChanEsp.Vehicle.Reset then
        return ChanEsp.Vehicle.Reset(deferRemoval)
    end
end

if not ChanEsp.Tick then
    ChanEsp.Tick = function(pc)
        -- Player ESP: keep player-render failures separate from item/vehicle
        -- updates and retain the latest error for diagnosis instead of hiding it.
        local okPlayer, playerErr = pcall(ChanEsp.UpdateESP, pc)
        if not okPlayer then
            ChanEsp.LastUpdateError = tostring(playerErr)
            ChanEsp.LastUpdateErrorAt = os.clock and os.clock() or 0
        else
            ChanEsp.LastUpdateError = nil
        end

        -- Item/vehicle chỉ quét khi ít nhất một nhánh được bật.
        local cfg = _G.LexusConfig or {}
        if cfg.EspItem_Master then
            pcall(ChanEsp.UpdateWorldESP, pc)
        elseif _G.ChanEspItemWidgets then
            for key, data in pairs(_G.ChanEspItemWidgets) do
                if data and data.Widget and Valid(data.Widget) then
                    pcall(function() data.Widget:RemoveFromParent() end)
                end
                _G.ChanEspItemWidgets[key] = nil
            end
        end

        -- Vehicle labels dùng cùng scheduler ChanEsp, không tự gắn GameTimer riêng.
        if ChanEsp.Vehicle and (cfg.EspVehicle or ChanEsp.Vehicle.bActive) then
            pcall(ChanEsp.UpdateVehicleESP)
        end

        -- Grenade ESP thuộc cùng scheduler/canvas với Player ESP.
        local bomb = _G.OwenNeonBomb
        if bomb then
            local bombCfg = _G.LexusConfig or {}
            local master = bombCfg.EspBomMaster
            if master == nil then master = bombCfg.EspBombMaster end
            local active = bombCfg.EspActiveBom
            if active == nil then active = bombCfg.EspBombActive end
            local enabled = (master == true or master == 1) and (active == true or active == 1)
            if enabled then
                local player = nil
                pcall(function()
                    if GameplayData and GameplayData.GetPlayerCharacter then player = GameplayData.GetPlayerCharacter() end
                end)
                if not Valid(player) and Valid(pc) and type(pc.GetPlayerCharacterSafety) == "function" then
                    pcall(function() player = pc:GetPlayerCharacterSafety() end)
                end
                _G.__ChanEspBombPlayer = player
                local adapter = _G.ChanEspBombAdapter
                if adapter then
                    adapter.ESPCanvas = ChanEsp.GetMainCanvas and ChanEsp.GetMainCanvas() or nil
                end
                local okBomb, bombResult = pcall(bomb.Tick, bomb, pc, player)
                if not okBomb then
                    ChanEsp.LastBombError = tostring(bombResult)
                elseif not Valid(player) then
                    ChanEsp.LastBombError = "local_player_unavailable"
                elseif not Valid(adapter and adapter.ESPCanvas) then
                    ChanEsp.LastBombError = "esp_canvas_unavailable"
                else
                    ChanEsp.LastBombError = nil
                end
            else
                pcall(bomb.Clear, bomb)
                ChanEsp.LastBombError = nil
            end
        end
    end
end


-- SRC bomb tracker adapter: use ChanEsp's canvas and projection, not PlayerMapMarker.
local PlayerMapMarker = {
    LabelFontName = 13,
    BoxColor = {R = 255, G = 80, B = 80, A = 255},
    _ProtectedWidgetStrs = {}
}
function PlayerMapMarker.GetMyLocation()
    local player = _G.__ChanEspBombPlayer
    if not Valid(player) then return nil end
    local loc = nil
    pcall(function() loc = player:K2_GetActorLocation() end)
    return loc
end
function PlayerMapMarker._Dist3D(a, b)
    if not a or not b then return nil end
    local dx, dy, dz = (a.X or 0) - (b.X or 0), (a.Y or 0) - (b.Y or 0), (a.Z or 0) - (b.Z or 0)
    return math.sqrt(dx * dx + dy * dy + dz * dz)
end
function PlayerMapMarker.ProjectWorldToCanvasLocal(pc, loc)
    local chan = _G.ChanEsp
    if not chan or not chan.ProjectWorldToCanvasLocal then return false, nil end
    local ok, x, y = chan.ProjectWorldToCanvasLocal(pc, loc)
    if not ok then return false, nil end
    return true, {X = x, Y = y}
end
function PlayerMapMarker._NewLabelText(canvas, fontSize, color, alignX, alignY)
    if not CGame or type(CGame.NewObjectFromPath) ~= "function" then return nil end
    local createOK, widget = pcall(function()
        return CGame:NewObjectFromPath("/Script/UMG.TextBlock", canvas)
    end)
    if not createOK or not Valid(widget) then return nil end
    local slot = nil
    pcall(function()
        widget:SetText("")
        local font = widget.Font
        if font then
            font.Size = math.floor(fontSize or 13)
            if font.OutlineSettings then
                font.OutlineSettings.OutlineSize = 1
                font.OutlineSettings.OutlineColor = FLinearColor(0, 0, 0, 1)
            end
            if widget.SetFont then widget:SetFont(font) else widget.Font = font end
        end
        if widget.SetFontSize then widget:SetFontSize(math.floor(fontSize or 13)) end
        if widget.SetJustification then widget:SetJustification(1) end
        if widget.SetHorizontalAlignment then widget:SetHorizontalAlignment(1) end
        if widget.SetVerticalAlignment then widget:SetVerticalAlignment(1) end
        if widget.SetAutoWrapText then widget:SetAutoWrapText(false) end
        local v2 = _G.FVector2D or import("Vector2D")
        if v2 and widget.SetShadowOffset then widget:SetShadowOffset(v2(1.0, 1.0)) end
        if widget.SetShadowColorAndOpacity then widget:SetShadowColorAndOpacity(FLinearColor(0, 0, 0, 1)) end
        widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
        slot = canvas:AddChildToCanvas(widget)
        if not slot then widget:RemoveFromParent(); widget = nil; return end
        slot:SetAutoSize(true)
        slot:SetZOrder(1001)
        slot:SetAlignment(FVector2D(alignX or 0.5, alignY or 1.0))
        local linear = FLinearColor(1, 0.32, 0.24, 1)
        if FSlateColor then widget:SetColorAndOpacity(FSlateColor(linear)) else widget:SetColorAndOpacity(linear) end
    end)
    if not Valid(widget) or not slot then return nil end
    return {w = widget, slot = slot}
end
function PlayerMapMarker._LabelText(item, value)
    if item and Valid(item.w) and item._lastText ~= value then
        pcall(function() item.w:SetText(value) end)
        item._lastText = value
    end
end
function PlayerMapMarker._LabelColor(item, color)
    if not item or not Valid(item.w) or type(color) ~= "table" then return end
    local r, g, b = tonumber(color.R) or 255, tonumber(color.G) or 255, tonumber(color.B) or 255
    local key = tostring(r) .. ":" .. tostring(g) .. ":" .. tostring(b)
    if item._lastColor == key then return end
    pcall(function()
        local linear = FLinearColor(r / 255, g / 255, b / 255, 1)
        if FSlateColor then item.w:SetColorAndOpacity(FSlateColor(linear))
        else item.w:SetColorAndOpacity(linear) end
        item._lastColor = key
    end)
end
function PlayerMapMarker._LabelSet(item, visible, x, y, scale)
    if not item or not Valid(item.w) or not item.slot then return end
    pcall(function()
        local wantVisible = visible == true
        if item._visible ~= wantVisible then
            item.w:SetWidgetVisibility(wantVisible and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
            item._visible = wantVisible
        end
        if wantVisible then
            if item._lastX == nil or math.abs(x - item._lastX) > 1.0 or math.abs(y - item._lastY) > 1.0 then
                item.slot:SetPosition(FVector2D(x, y))
                item._lastX, item._lastY = x, y
            end
            local s = scale or 1
            if item._lastScale ~= s and item.w.SetRenderScale then
                item.w:SetRenderScale(FVector2D(s, s))
                item._lastScale = s
            end
        end
    end)
end
_G.ChanEspBombAdapter = PlayerMapMarker

(function()
    local function bombNow()
      local gs = _G.__ChanEspBombStatics
      if gs == nil then
        local ok, value = pcall(import, 'GameplayStatics')
        if ok then gs = value end
        _G.__ChanEspBombStatics = gs or false
      elseif gs == false then
        gs = nil
      end
      if gs and type(gs.GetRealTimeSeconds) == 'function' then
        local ok, world = pcall(slua.getWorld)
        if ok and world then
          local got, value = pcall(gs.GetRealTimeSeconds, world)
          if got and type(value) == 'number' then return value end
        end
      end
      return (os.clock and os.clock()) or 0
    end

    local B = {
      Items = {},
      Buckets = {},
      Cursor = 1,
      NextScan = 0,
      Seen = {},
      Kinds = setmetatable( {}, { __mode = 'k' }),
      Held = {},
      HeldProjectiles = setmetatable( {}, { __mode = 'k' }),
      ThrowStates = setmetatable( {}, { __mode = 'k' }),
      Thrown = setmetatable( {}, { __mode = 'k' }),
      HeldT = setmetatable( {}, { __mode = 'k' })
    }
    _G.OwenNeonBomb = B
    function B:DropHeld(component)
      if component == nil then
        return
      end
      local thrownAt = bombNow()
      self.Thrown[component] = thrownAt
      local projectile = nil
      pcall(function() projectile = component.NewProjectile end)
      if Valid(projectile) then self.Thrown[projectile] = thrownAt end
      self.ThrowStates[component] = true
      if self.Held[component] then
        self.Held[component] = nil
      end
    end
    function B:Remaining(entity)
      if not Valid(entity) then
        return nil
      end
      for _, key in ipairs( { 'GetRemainingTimeBeforeExplode', 'GetGrenadeRemainingTime' }) do
        local got, getter = pcall(function()
          return entity[key]
        end)
        if got and type(getter) == 'function' then
          local ok, value = pcall(getter, entity)
          value = ok and tonumber(value)
          if value and value == value and value > 0.001 and value <= 60 then
            return value
          end
        end
      end
      return nil
    end
    function B:RawFuse(kind, entity)
      if not Valid(entity) then
        return nil
      end
      local ok, raw = pcall(function()
        return tonumber(entity.EffectDelay)
      end)
      if ok and raw and raw > 0.001 and raw <= 30 then
        return raw
      end
      local gidOK, gidRaw = pcall(function()
        return tonumber(entity.CurGrenadeID)
      end)
      local gid = gidOK and gidRaw or nil
      local utils = rawget(_G, 'UAESkillManagerUtils')
      if gid and gid > 0 and type(utils) == 'table' and type(utils.GetGrenadeCountDownTime) == 'function' then
        local ok2, raw2 = pcall(utils.GetGrenadeCountDownTime, gid)
        if ok2 then
          raw2 = tonumber(raw2);
          if raw2 and raw2 > 0.001 and raw2 <= 30 then
            return raw2
          end
        end
      end
      return nil
    end
    function B:FuseDuration(kind, entity)
      local value = self:RawFuse(kind, entity)
      if value then
        return value
      end
      return ( { Flash = 2.5, [602001] = 2.5, Molotov = 5.0, Smoke = 5.0, Grenade = 7.0, [602004] = 7.0,
      Launcher = 5.0 })[kind] or 7.0
    end
    function B:Countdown(kind, target, actor, anchor)
      local candidates = { anchor }
      if target then
        if target.Projectile then
          candidates[ # candidates + 1] = target.Projectile
        end
        if target.Weapon then
          candidates[ # candidates + 1] = target.Weapon
        end
      end
      if self.OwnHeldKey then
        candidates[ # candidates + 1] = self.OwnHeldKey
      end
      if actor then
        candidates[ # candidates + 1] = actor
      end
      local duration = nil
      local native = nil
      for i = 1, # candidates do
        local entity = candidates[i]
        if Valid(entity) then
          if not native then
            local okR, valueR = pcall(self.Remaining, self, entity)
            if okR and valueR ~= nil then
              native = valueR
            end
          end
          local okF, fuse = pcall(self.RawFuse, self, kind, entity)
          if okF and fuse and ( not duration or fuse > duration) then
            duration = fuse
          end
        end
      end
      if not duration then
        duration = self:FuseDuration(kind, nil)
      end
      if native then
        if native > duration then
          native = duration
        end
        return native
      end
      if not actor then return nil end
      local now = bombNow()
      local thrownAt = self.Thrown[anchor] or self.Thrown[actor]
      if not thrownAt and target then
        thrownAt = self.Thrown[target.Projectile] or self.Thrown[target.Weapon]
      end
      if thrownAt then return math.max(0, duration - (now - thrownAt)) end
      local row = self.HeldT[actor]
      if row then
        local endAt = row.Start + row.Dur
        if now > endAt then
          if now > endAt + 3 then
            self.HeldT[actor] = nil;
            return nil
          end
          return 0
        end
      end
      if not row then
        row = { Start = now, Dur = duration }
        self.HeldT[actor] = row
      elseif duration > row.Dur then
        row.Dur = duration
      end
      local remain = row.Start + row.Dur - now
      if remain < 0 then
        remain = 0
      end
      if remain > duration then
        remain = duration
      end
      return remain
    end
    function B:PinPulled(actor)
      for _, key in ipairs( { 'bIsPinPulled', 'bPinPulled', 'IsPinPulled' }) do
        local ok, value = pcall(function()
          local field = actor[key]
          if type(field) == 'function' then
            return field(actor)
          end
          return field
        end)
        if ok and (value == true or value == 1) then
          return true
        end
      end
      return false
    end
    function B:HasFuse(actor)
      for _, key in ipairs( { 'ExplosionTime', 'ExplodeTime' }) do
        local ok, value = pcall(function()
          return tonumber(actor[key])
        end)
        if ok and value and value > 0 then
          return true
        end
      end
      return false
    end
    function B:RecordHeld(component, remove, transition)
      if transition then
        self.ThrowStates[component] = not remove
      end
      if remove then
        self.Held[component] = nil;
        return
      end
      local thrownAt = self.Thrown[component]
      if thrownAt then
        if type(thrownAt) == 'number' and (bombNow() - thrownAt) < 3 then
          return
        end
        self.Thrown[component] = nil
      end
      if not transition and self.ThrowStates[component] == false then
        return
      end
      local cfg = _G.LexusConfig or {}
      local master = cfg.EspBomMaster
      if master == nil then master = cfg.EspBombMaster end
      local active = cfg.EspActiveBom
      if active == nil then active = cfg.EspBombActive end
      if not (master == true or master == 1) or not (active == true or active == 1) then return end
      local owner = component:GetOwnerPawn()
      if not Valid(owner) then
        return
      end
      local id = tonumber(component.CurGrenadeID)
      if not id then
        local def = component.CurWeaponID;
        id = tonumber(def and def.TypeSpecificID)
      end
      local kind = ( { [602001] = 'Flash', [602002] = 'Smoke', [602003] = 'Molotov', [602004] = 'Grenade' })[id]
      if not kind then
        return
      end
      local record = self.Held[component] or {} record.Actor = owner;
      record.Kind = kind;
      record.Active = true;
      record.Held = true
      record.Pinned = transition == true or self:PinPulled(component)
      record.Expires = bombNow() + 8;
      record.Projectile = component.NewProjectile
      record.Weapon = component
      self.Held[component] = record
    end
    function B:PollOwnGrenade(player)
      self.OwnHoldKnown = false;
      self.OwnHolding = false
      local stateOK, pawnStates = pcall(import, 'EPawnState')
      if stateOK and pawnStates and pawnStates.HoldGrenade ~= nil then
        local checked, value = pcall(function()
          return player:HasState(pawnStates.HoldGrenade)
        end)
        if checked then
          self.OwnHoldKnown = true;
          self.OwnHolding = value == true or value == 1
        end
      end
      local previous = self.OwnHeldKey
      if previous then
        self.Held[previous] = nil;
        self.OwnHeldKey = nil
      end
      local ok, weapon = pcall(function()
        if type(player.GetWeaponManager) == 'function' then
          local manager = player:GetWeaponManager()
          if Valid(manager) and type(manager.GetCurrentUsingWeapon) == 'function' then
            local weapon = manager:GetCurrentUsingWeapon()
            if Valid(weapon) then return weapon end
          end
        end
        if type(player.GetCurrentWeapon) == 'function' then return player:GetCurrentWeapon() end
        return player.CurrentWeapon
      end)
      if not ok or not Valid(weapon) then
        return
      end
      local id
      pcall(function()
        local definition = weapon.GetItemDefineID and weapon:GetItemDefineID() or weapon.ItemDefineID
        id = tonumber(definition and definition.TypeSpecificID)
        id = id or tonumber(weapon.CurGrenadeID or weapon.GrenadeID or weapon.ItemID or weapon.ItemId)
      end)
      local kind = ( { [602001] = 'Flash', [602002] = 'Smoke', [602003] = 'Molotov', [602004] = 'Grenade' })[id]
      if not kind then return end
      -- Show only when HoldGrenade is active or the weapon confirms its pin is pulled.
      -- Merely selecting a throwable is not an active warning.
      local held = self.OwnHolding or self:PinPulled(weapon)
      if not held then
        if self.HeldT[player] then
          self.HeldT[player] = nil
        end;
        return
      end
      local record = { Actor = player, Kind = kind, Active = true, Held = true, Projectile = weapon,
      Polled = true, Weapon = weapon, Pinned = self:PinPulled(weapon), Expires = bombNow() + 0.5 }
      self.Held[weapon] = record;
      self.OwnHeldKey = weapon
    end
    function B:InstallActorHook()
      if self.ActorHooked then
        return
      end
      local name = 'GameLua.Mod.BaseMod.GamePlay.Actor.Grenade.GrenadeActorBase'
      local mod = package and package.loaded and package.loaded[name]
      if type(mod) ~= 'table' then
        local loaded, value = pcall(require, name)
        if loaded then mod = value end
      end
      if type(mod) ~= 'table' then return end
      mod = rawget(mod, '__inner_impl') or mod
      if type(mod.ShowThrowTimeInfoPanel) ~= 'function' or type(mod.HideThrowTimeInfoPanel) ~= 'function' then
        return
      end
      if not rawget(mod, '__OwenHeldActorHooks') then
        local show, hide = mod.ShowThrowTimeInfoPanel, mod.HideThrowTimeInfoPanel
        mod.ShowThrowTimeInfoPanel = function(actor, projectile, ...)
          local result = table.pack(show(actor, projectile, ...))
          local current = _G.OwenNeonBomb
          if current then
            pcall(function()
              local owner = actor:GetOwner()
              local def = actor:GetItemDefineID()
              local id = tonumber(def and def.TypeSpecificID)
              local kind = ( { [602001] = 'Flash', [602002] = 'Smoke', [602003] = 'Molotov', [602004] = 'Grenade' })[id]
              if Valid(projectile) and kind then
                current.Held[actor] = { Actor = projectile, Kind = kind, Active = true, Held = false,
                Projectile = projectile, ActorEvent = true, Expires = bombNow() + 8 }
              end
            end)
          end
          return table.unpack(result, 1, result.n)
        end
        mod.HideThrowTimeInfoPanel = function(actor, ...)
          local current = _G.OwenNeonBomb;
          if current then
            current.Held[actor] = nil
          end
          return hide(actor, ...)
        end
        rawset(mod, '__OwenHeldActorHooks', true)
      end
      self.ActorHooked = true
    end
    function B:InstallHeldHook()
      if self.HeldHooked then
        return
      end
      local now = bombNow()
      if now < (self.NextHeldHook or 0) then
        return
      end
      self.NextHeldHook = now + 1
      local name = 'GameLua.Mod.BaseMod.GamePlay.Component.ThrowComponent.GrenadeThrowComponent'
      local mod = package and package.loaded and package.loaded[name]
      if type(mod) ~= 'table' then
        local loaded, value = pcall(require, name)
        if loaded then
          mod = value
        end
      end
      if type(mod) ~= 'table' then
        self.HeldHookStatus = 'module_unavailable';
        return
      end
      local impl = rawget(mod, '__inner_impl')
      if type(impl) == 'table' and type(impl.ReceiveThrowStateChanged) == 'function' then
        mod = impl
      end
      if type(mod.ReceiveThrowStateChanged) ~= 'function' then
        return
      end
      local ok, states = pcall(import, 'EThrowState')
      if not ok or not states or states.Prepare == nil or states.Aim == nil then
        return
      end
      if not rawget(mod, '__OwenHeldBombHooks') then
        local original = mod.ReceiveThrowStateChanged
        mod.ReceiveThrowStateChanged = function(component, state, ...)
          local result = table.pack(original(component, state, ...))
          local current = _G.OwenNeonBomb
          if current then
            pcall(function()
              if state == states.Prepare or state == states.Aim then
                current.Thrown[component] = nil
                local owner = component.GetOwnerPawn and component:GetOwnerPawn()
                if Valid(owner) then current.HeldT[owner] = nil end
                current.RecordHeld(current, component, false, true)
              elseif state == states.Release or state == states.Drop then
                -- Keep the throw flag until InitializeNewProjectile links the projectile.
                current:DropHeld(component)
              end
            end)
          end
          return table.unpack(result, 1, result.n)
        end
        local initialize = mod.InitializeNewProjectile
        if type(initialize) == 'function' then
          mod.InitializeNewProjectile = function(component, ...)
            local result = table.pack(initialize(component, ...))
            local current = _G.OwenNeonBomb
            if current then
              pcall(function()
                local projectile = component.NewProjectile
                local active = false
                if Valid(projectile) then
                  active = current:PinPulled(projectile) or current:HasFuse(projectile)
                end
                if current.ThrowStates[component] == true or (current.ThrowStates[component] == nil and active) then
                  current:DropHeld(component)
                end
              end)
            end
            return table.unpack(result, 1, result.n)
          end
        end
        local finish = mod.ReceiveEndPlay
        if type(finish) == 'function' then
          mod.ReceiveEndPlay = function(component, ...)
            local current = _G.OwenNeonBomb
            if current then
              current.Held[component] = nil;
              current.ThrowStates[component] = nil;
              current.Thrown[component] = nil
            end
            return finish(component, ...)
          end
        end
        local show = mod.ShowThrowTimeInfoPanel
        if type(show) == 'function' then
          mod.ShowThrowTimeInfoPanel = function(component, ...)
            local result = table.pack(show(component, ...))
            local current = _G.OwenNeonBomb
            if current then
              pcall(current.DropHeld, current, component)
            end
            return table.unpack(result, 1, result.n)
          end
        end
        local hide = mod.HideThrowTimeInfoPanel
        if type(hide) == 'function' then
          mod.HideThrowTimeInfoPanel = function(component, ...)
            local current = _G.OwenNeonBomb
            if current then
              pcall(current.RecordHeld, current, component, true, true)
            end
            return hide(component, ...)
          end
        end
        rawset(mod, '__OwenHeldBombHooks', true)
      end
      self.HeldHooked = true;
      self.HeldHookStatus = 'installed'
    end
    function B:Clear()
      if not self.Owner and not next(self.Items or {}) and not self.Classes and not self.Job and not next(self.Held or {}) then return end
      for key, it in pairs(self.Items) do
        if it.w and Valid(it.w) then
          pcall(it.w.RemoveFromParent, it.w)
        end
        if PlayerMapMarker._ProtectedWidgetStrs and it.w then
          PlayerMapMarker._ProtectedWidgetStrs[tostring(it.w)] = nil
        end
        self.Items[key] = nil
      end
      self.Buckets = {};
      self.Job = nil;
      self.Seen = {};
      self.Kinds = setmetatable( {}, { __mode = 'k' });
      self.Classes = nil;
      self.Canvas = nil;
      self.Owner = nil;
      self.NextScan = 0;
      self.Cursor = 1
      self.OwnHeldKey = nil;
      self.Held = {};
      self.Thrown = setmetatable( {}, { __mode = 'k' })
      self.ThrowStates = setmetatable( {}, { __mode = 'k' })
      self.HeldT = setmetatable( {}, { __mode = 'k' })
      self.HeldProjectiles = setmetatable( {}, { __mode = 'k' })
      self.NextClassRetry = 0
    end
    function B:Kind(actor)
      local id, name, active; pcall(function()
        local define = actor.GetItemDefineID and actor:GetItemDefineID() or actor.ItemDefineID
        id = tonumber(define and define.TypeSpecificID or actor.CurGrenadeID or actor.ItemID or actor.ItemId or actor.GrenadeID)
        name = string.lower(tostring(actor:GetClass():GetName()))
        active = self:PinPulled(actor) or self:HasFuse(actor)
      end)
      name = name or string.lower(tostring(actor))
      for _, token in ipairs( { 'scope', 'sight', 'suppressor', 'compensator', 'hider', 'grip', 'stock',
      'quiver', 'muzzle', 'choke' }) do
        if name:find(token, 1, true) then
          return
        end
      end
      local kind = ( { [602001] = 'Flash', [602002] = 'Smoke', [602003] = 'Molotov', [602004] = 'Grenade' })[id]
      if not kind then
        if name:find('smoke', 1, true) then
          kind = 'Smoke'
        elseif name:find('molotov', 1, true) or name:find('burn', 1, true) then
          kind = 'Molotov'
        elseif name:find('flash', 1, true) or name:find('stun', 1, true) then
          kind = 'Flash'
        elseif name:find('grenade', 1, true) or name:find('frag', 1, true) then
          kind = 'Grenade'
        elseif name:find('launcher', 1, true) or name:find('m79', 1, true) then
          kind = 'Launcher'
        end
      end
      if not kind then
        return
      end
      if name:find('projectile', 1, true) or name:find('thrown', 1, true) then
        active = true
      end
      if name:find('pickup', 1, true) or name:find('wrapper', 1, true) or name:find('ground', 1, true) then
        active = false
      end
      local projectile = name:find('projectile', 1, true) or name:find('thrown', 1, true)
      return kind, active == true, projectile ~= nil
    end
    function B:WarningState(actor, target)
      if target.Held then
        local heldWeapon = target.Weapon or target.Projectile
        if actor == self.Owner and self.OwnHoldKnown and not self.OwnHolding and not self:PinPulled(heldWeapon) then
          return nil
        end
        return 'held'
      end
      if self.HeldProjectiles[actor] then
        return nil
      end
      if target.ActorEvent then
        return 'thrown'
      end
      local attached, attachmentKnown = false, false
      if type(actor.GetAttachParentActor) == 'function' then
        local ok, parent = pcall(actor.GetAttachParentActor, actor)
        attachmentKnown = ok
        attached = ok and Valid(parent)
      end
      local pin = self:PinPulled(actor)
      local timed = self:HasFuse(actor)
      if attached then
        return (pin or timed) and 'held' or nil
      end
      if attachmentKnown and (target.Active or pin or timed) then
        return 'thrown'
      end
      local memo = self.Kinds[actor]
      if target.Active then
        if pin and memo and not memo.Projectile then
          return 'held'
        end
        return 'thrown'
      end
      if pin or timed then
        return 'held'
      end
    end
    local bombNames = {
      Grenade = { 'Grenade', 'Lựu đạn', '手雷' },
      Smoke = { 'Smoke', 'Bom khói', '烟雾弹' },
      Molotov = { 'Molotov', 'Bom xăng', '燃烧瓶' },
      Flash = { 'Flash', 'Bom choáng', '震爆弹' },
      Launcher = { 'Launcher', 'Đạn phóng', '榴弹' }
    }
    local bombColors = {
      Grenade = {R = 255, G = 35, B = 35, A = 255},
      Launcher = {R = 255, G = 35, B = 35, A = 255},
      Smoke = {R = 40, G = 145, B = 255, A = 255},
      Flash = {R = 255, G = 255, B = 255, A = 255},
      Molotov = {R = 255, G = 215, B = 0, A = 255}
    }
    function B:Label(kind, phase, target)
      local name = (bombNames[kind] or bombNames.Grenade)[2]
      local status = 'Đã ném'
      if phase == 'held' then
        local weapon = target and (target.Weapon or target.Projectile)
        local pinned = target and target.Pinned == true
        if not pinned and Valid(weapon) then pinned = self:PinPulled(weapon) end
        status = pinned and 'Đã rút chốt' or 'Đang cầm'
      end
      return name .. ' — ' .. status
    end
    function B:Tick(pc, player)
      local cfg = _G.LexusConfig or {};
      if cfg.EspBomMaster == nil then cfg.EspBomMaster = cfg.EspBombMaster end
      if cfg.EspActiveBom == nil then cfg.EspActiveBom = cfg.EspBombActive end
      local canvas = PlayerMapMarker.ESPCanvas
      if _G.ChanEsp and _G.ChanEsp.GetMainCanvas then
        local okCanvas, currentCanvas = pcall(_G.ChanEsp.GetMainCanvas)
        if okCanvas and Valid(currentCanvas) then canvas = currentCanvas end
      end
      PlayerMapMarker.ESPCanvas = canvas
      local master = cfg.EspBomMaster
      if master == nil then master = cfg.EspBombMaster end
      local active = cfg.EspActiveBom
      if active == nil then active = cfg.EspBombActive end
      if not (master == true or master == 1) or not (active == true or active == 1) or not Valid(pc) or not Valid(player) or not Valid(canvas) then
        if next(self.Items) or self.Owner then
          self:Clear()
        end;
        return
      end
      if self.Owner ~= player or self.Canvas ~= canvas then
        self:Clear();
        self.Owner = player;
        self.Canvas = canvas
      end
      self:InstallHeldHook()
      self:InstallActorHook()
      self:PollOwnGrenade(player)
      local now = bombNow()
      if not self.Classes or (#self.Classes == 0 and now >= (self.NextClassRetry or 0)) then
        self.Classes = {}
        self.NextClassRetry = now + 1.0
        for _, name in ipairs( { 'STExtraGrenadeBase', 'STProjectileBase' }) do
          local ok, class = pcall(import, name)
          if ok and class then
            local array
            pcall(function() array = slua.Array(class) end)
            self.Classes[#self.Classes + 1] = { Class = class, Array = array, NextScan = 0 }
          end
        end
      end
      if not self.Job and now >= self.NextScan and # self.Classes > 0 then
        self.NextScan = now + 0.25
        local index = self.Cursor;
        local set = self.Classes[index]
        self.Cursor = index % # self.Classes + 1
        local wanted = cfg.EspActiveBom == true or cfg.EspActiveBom == 1
        if wanted and now >= set.NextScan then
          set.NextScan = now + 0.25
          local ok, actors
          if Game and Game.GetActorsByClass then
            ok, actors = pcall(Game.GetActorsByClass, Game, set.Class)
          else
            ok, actors = pcall(function()
              return import('GameplayStatics').GetAllActorsOfClass(slua.getWorld(), set.Class, set.Array)
            end)
          end
          if ok and actors then
            local count = actors.Num and actors:Num() or # actors
            self.Buckets[index] = self.Buckets[index] or {} self.Job = { Actors = actors, Count = math.min(count, 256),
            Index = 1, Bucket = self.Buckets[index], Used = 0 }
          end
        end
      end
      local job = self.Job
      if job and not (cfg.EspActiveBom == true or cfg.EspActiveBom == 1) then
        self.Job = nil;
        job = nil
      end
      if job then
        for _ = 1, 16 do
          if job.Index > job.Count then
            break
          end
          local i = job.Index;
          job.Index = i + 1
          local actor = job.Actors.Get and job.Actors:Get(i - 1) or job.Actors[i]
          if Valid(actor) then
            local kind, active, projectile
            local memo = self.Kinds[actor]
            if memo then
              kind, active = memo.Kind, memo.Active
              if kind then
                active = memo.Projectile or self:PinPulled(actor) or self:HasFuse(actor)
              end
            else
              kind, active, projectile = self:Kind(actor);
              self.Kinds[actor] = { Kind = kind, Active = active, Projectile = projectile }
            end
            if kind then
              job.Used = job.Used + 1
              local record = job.Bucket[job.Used] or {};
              job.Bucket[job.Used] = record
              record.Actor = actor;
              record.Kind = kind;
              record.Active = active
            end
          end
        end
        if job.Index > job.Count then
          for i = # job.Bucket, job.Used + 1, - 1 do
            job.Bucket[i] = nil
          end
          self.Job = nil
        end
      end
      local heldBucket = self.Buckets.Held or {};
      self.Buckets.Held = heldBucket
      for i = # heldBucket, 1, - 1 do
        heldBucket[i] = nil
      end
      for actor in pairs(self.HeldProjectiles) do
        self.HeldProjectiles[actor] = nil
      end
      for component, record in pairs(self.Held) do
        if not Valid(record.Actor) or now >= record.Expires then
          self.Held[component] = nil
        else
          local ok, projectile = pcall(function()
            return component.NewProjectile
          end)
          if ok and not record.Polled and not record.ActorEvent then
            record.Projectile = projectile
          end
          heldBucket[ # heldBucket + 1] = record
          if record.Held and Valid(record.Projectile) then
            self.HeldProjectiles[record.Projectile] = true
          end
        end
      end
      local seen = self.Seen;
      for key in pairs(seen) do
        seen[key] = nil
      end
      local count = 0;
      local origin = PlayerMapMarker.GetMyLocation()
      if not origin then
        return
      end
      for _, bucket in pairs(self.Buckets) do
        for _, target in ipairs(bucket) do
          local actor = target.Actor
          local phase = Valid(actor) and self:WarningState(actor, target)
          if phase and count < 64 and Valid(actor) and (target.Held or (actor.bHidden ~= true and actor.bHidden ~= 1)) and actor.bTearOff ~= true and actor.bTearOff ~= 1 and (cfg.EspActiveBom == true or cfg.EspActiveBom == 1) then
            local key = tostring(actor)
            if not seen[key] then
              local anchor = target.Held and target.Projectile or actor
              local loc
              if Valid(anchor) then
                local ok, value = pcall(function() return anchor:K2_GetActorLocation() end)
                if ok and value and (value.X ~= 0 or value.Y ~= 0 or value.Z ~= 0) then loc = value end
              end
              if target.Held and (not loc or (loc.X == 0 and loc.Y == 0 and loc.Z == 0)) then
                pcall(function()
                  local mesh = actor.Mesh or (actor.GetMesh and actor:GetMesh())
                  if Valid(mesh) and mesh.GetSocketLocation then
                    for _, socket in ipairs({'hand_r', 'Hand_R', 'weapon_r', 'Weapon_R'}) do
                      local value = mesh:GetSocketLocation(socket)
                      if value and (value.X ~= 0 or value.Y ~= 0 or value.Z ~= 0) then loc = value; break end
                    end
                  end
                end)
                if not loc and type(actor.GetBonePos) == 'function' then
                  local output = { X = 0, Y = 0, Z = 0 }
                  local ok, value = pcall(actor.GetBonePos, actor, 'hand_r', output)
                  value = value or output
                  if ok and value and (value.X ~= 0 or value.Y ~= 0 or value.Z ~= 0) then loc = value end
                end
              end
              local d = loc and PlayerMapMarker._Dist3D(origin, loc) / 100
              if d and d <= (tonumber(cfg.EspBombDistance) or 150) then
                local on, pos = PlayerMapMarker.ProjectWorldToCanvasLocal(pc, loc)
                if on and pos then
                  seen[key] = true;
                  count = count + 1
                  local it = self.Items[key]
                  if not it or not Valid(it.w) then
                    it = PlayerMapMarker._NewLabelText(canvas, PlayerMapMarker.LabelFontName or 13, PlayerMapMarker.BoxColor, 0.5, 1)
                    if it then self.Items[key] = it end
                  end
                  if it then
                  local text = self:Label(target.Kind, phase, target)
                  if phase == 'thrown' and not (cfg.EspBombCountdown == false or cfg.EspBombCountdown == 0) then
                    local okC, remain = pcall(self.Countdown, self, target.Kind, target, actor, anchor)
                    if okC and remain then
                      text = text .. '  [' .. string.format('%.1f', math.max(0, remain)) .. 's]'
                    end
                  end
                  PlayerMapMarker._LabelColor(it, bombColors[target.Kind] or bombColors.Grenade)
                  PlayerMapMarker._LabelText(it, text .. '\n' .. math.floor(d + 0.5) .. 'm')
                  PlayerMapMarker._LabelSet(it, true, pos.X, pos.Y, 1)
                  end
                end
              end
            end
          end
        end
      end
      for key, it in pairs(self.Items) do
        if not seen[key] then
          if it.w and Valid(it.w) then
            pcall(it.w.RemoveFromParent, it.w)
          end
          if PlayerMapMarker._ProtectedWidgetStrs and it.w then
            PlayerMapMarker._ProtectedWidgetStrs[tostring(it.w)] = nil
          end
          self.Items[key] = nil
        end
      end
    end
  end)()

if not _G.ChanEsp.ResetWidgets then
    _G.ChanEsp.ResetWidgets = function(deferRemoval)
        local function removeWidget(widget)
            if widget and IsValid(widget) then
                if deferRemoval and _G.QueueChannWidgetCleanup then _G.QueueChannWidgetCleanup(widget)
                else pcall(widget.RemoveFromParent, widget) end
            end
        end
        for _, bd in pairs(ChanEsp.BoxWidgets) do
            if bd then
                removeWidget(bd.CornerContainer); removeWidget(bd.BgWidget); removeWidget(bd.HealthWidget)
                removeWidget(bd.WeaponWidget); removeWidget(bd.FlagWidget); removeWidget(bd.NameWidget)
                removeWidget(bd.DistWidget); removeWidget(bd.StateWidget)
            end
        end
        for _, ld in pairs(ChanEsp.LineWidgets) do if ld then removeWidget(ld.Widget) end end
        local CD = ChanEsp.CounterData
        if CD then
            removeWidget(CD.ImgPlayer); removeWidget(CD.ImgBot); removeWidget(CD.TxtPlayer); removeWidget(CD.TxtBot)
        end

        -- ============ RESET TOÀN BỘ CACHE ============
        ChanEsp.BoxWidgets = {}
        ChanEsp.LineWidgets = {}
        ChanEsp._VisCheckCache = {}
        ChanEsp.ESPCanvas = nil          -- Force lấy lại canvas
        ChanEsp._WidgetCanvas = nil
        ChanEsp._WidgetOwner = nil
        ChanEsp._WidgetWorld = nil
        ChanEsp._LastCanvas = nil
        ChanEsp._LastTransformTime = 0
        ChanEsp._LastHeavyUpdateTime = 0
        ChanEsp._LastVisCheckTime = 0
        ChanEsp._LastUpdateTime = 0
        ChanEsp._CanvasScaleX = 1.0
        ChanEsp._CanvasScaleY = 1.0
        ChanEsp._CanvasOffsetX = 0.0
        ChanEsp._CanvasOffsetY = 0.0

        -- Reset counter đầy đủ
        ChanEsp.CounterData = {
            ImgPlayer = nil, SlotPlayer = nil,
            ImgBot = nil, SlotBot = nil,
            TxtPlayer = nil, SlotTxtPlayer = nil,
            TxtBot = nil, SlotTxtBot = nil,
            LastPlayerCount = -1, LastBotCount = -1,
            PlayerLoaded = false, BotLoaded = false,
            LastDownloadRetry = 0, bCreated = false
        }
        
        -- Không xóa texture cache vì đó là texture tải từ mạng (giữ để tái sử dụng)
        -- EnemyCounterTextureCache = {}  -- Nếu muốn xóa thì bỏ comment
    end
end
