-- =========================== KẾT THÚC BOX ESP =================================
-- ==============================================================================

end)

pcall(function()
-- VehicleESP: giữ nhận diện xe, khoảng cách và màu theo trạng thái tài xế; không đọc HP/nhiên liệu

local VehicleESP = {
    bActive = false,
    VehicleWidgets = {},
    _LastScanTime = 0,
    _CachedVehicles = nil,
    _LastCanvas = nil,
    _CanvasScaleX = 1.0,
    _CanvasScaleY = 1.0,
    _CanvasOffsetX = 0.0,
    _CanvasOffsetY = 0.0,
    _LastTransformTime = 0,
    _ESPCanvas = nil,
    _bDestroyedWhenOff = false,
}

local VehFVector2D    = _G.FVector2D    or import("Vector2D")
local VehFLinearColor = _G.FLinearColor or import("LinearColor")
local VehFSlateColor  = (pcall(import, "SlateColor") and import("SlateColor")) or (pcall(import, "/Script/SlateCore.SlateColor") and import("/Script/SlateCore.SlateColor")) or nil
local VehSBL          = (pcall(import, "SlateBlueprintLibrary") and import("SlateBlueprintLibrary")) or nil
local VehWLL          = (pcall(import, "WidgetLayoutLibrary") and import("WidgetLayoutLibrary")) or nil

local function VehValid(obj)
    if not obj then return false end
    if slua and slua.isValid then return slua.isValid(obj) end
    return true
end

-- ==========================================
-- LẤY CANVAS
-- ==========================================
function VehicleESP.GetCanvas()
    if VehicleESP._ESPCanvas and VehValid(VehicleESP._ESPCanvas) then return VehicleESP._ESPCanvas end
    local InGameUITools = package.loaded["GameLua.Mod.BaseMod.Common.UI.InGameUITools"]
    if not InGameUITools then
        pcall(function() InGameUITools = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools") end)
    end
    if not InGameUITools then return nil end

    local MainUI = nil
    if InGameUITools.GetMainControlBaseUI then MainUI = InGameUITools.GetMainControlBaseUI() end
    if not VehValid(MainUI) then return nil end

    local canvas = nil
    if MainUI.CanvasPanel_0 and VehValid(MainUI.CanvasPanel_0) then canvas = MainUI.CanvasPanel_0
    elseif MainUI.CanvasPanel_42 and VehValid(MainUI.CanvasPanel_42) then canvas = MainUI.CanvasPanel_42 end

    if canvas then
        VehicleESP._ESPCanvas = canvas
        VehicleESP._LastCanvas = canvas
    end
    return canvas
end

-- ==========================================
-- TẠO WIDGET TEXT CHO XE
-- ==========================================
function VehicleESP.CreateVehicleWidget(ParentCanvas)
    if not VehFVector2D or not VehFLinearColor then return nil end

    local Container = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", ParentCanvas)
    if not VehValid(Container) then return nil end

    local MainSlot = ParentCanvas:AddChildToCanvas(Container)
    if not MainSlot then return nil end

    MainSlot:SetAutoSize(false)
    MainSlot:SetZOrder(1000)
    MainSlot:SetAlignment(VehFVector2D(0.5, 0.5))

    local txt = CGame:NewObjectFromPath("/Script/UMG.TextBlock", Container)
    if not VehValid(txt) then
        pcall(function() Container:RemoveFromParent() end)
        return nil
    end

    pcall(function()
        txt:SetText("")
        if txt.Font then
            local f = txt.Font
            f.Size = 13
            if f.OutlineSettings then
                f.OutlineSettings.OutlineSize = 1
                f.OutlineSettings.OutlineColor = VehFLinearColor(0.0, 0.0, 0.0, 1.0)
            end
            if txt.SetFont then txt:SetFont(f) else txt.Font = f end
        end
        if txt.SetFontSize then txt:SetFontSize(13) end
        txt:SetJustification(1)
        if txt.SetHorizontalAlignment then txt:SetHorizontalAlignment(1) end
        if txt.SetVerticalAlignment then txt:SetVerticalAlignment(1) end
        if txt.SetAutoWrapText then txt:SetAutoWrapText(false) end
        if txt.SetShadowOffset then txt:SetShadowOffset(VehFVector2D(1.0, 1.0)) end
        if txt.SetShadowColorAndOpacity then txt:SetShadowColorAndOpacity(VehFLinearColor(0.0, 0.0, 0.0, 1.0)) end
        txt:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
    end)

    if VehFSlateColor then
        pcall(function() txt:SetColorAndOpacity(VehFSlateColor(VehFLinearColor(0.0, 1.0, 0.6, 1.0))) end)
    else
        pcall(function() txt:SetColorAndOpacity(VehFLinearColor(0.0, 1.0, 0.6, 1.0)) end)
    end

    local txtSlot = Container:AddChildToCanvas(txt)
    if txtSlot then
        txtSlot:SetAutoSize(true)
        txtSlot:SetAlignment(VehFVector2D(0.5, 0.5))
        txtSlot:SetPosition(VehFVector2D(0, 0))
        txtSlot:SetZOrder(1001)
    end

    return {
        Container = Container,
        Slot = MainSlot,
        Text = txt,
        TextSlot = txtSlot,
        _lastX = -99999,
        _lastY = -99999,
        _lastText = "",
        _lastColorHash = "",
        _smoothedZ = nil,
        bVisible = true,
    }
end

-- ==========================================
-- CANVAS TRANSFORM
-- ==========================================
function VehicleESP.UpdateCanvasTransform(PC)
    if not VehicleESP._ESPCanvas or not VehValid(VehicleESP._ESPCanvas) then return end
    local success = false
    pcall(function()
        if VehSBL and VehSBL.AbsoluteToLocal and VehFVector2D then
            local cg = VehicleESP._ESPCanvas:GetCachedGeometry()
            if cg then
                local p0 = VehSBL.AbsoluteToLocal(cg, VehFVector2D(0, 0))
                local p1 = VehSBL.AbsoluteToLocal(cg, VehFVector2D(100, 100))
                if p0 and p1 then
                    VehicleESP._CanvasScaleX  = (p1.X - p0.X) / 100
                    VehicleESP._CanvasScaleY  = (p1.Y - p0.Y) / 100
                    VehicleESP._CanvasOffsetX = p0.X
                    VehicleESP._CanvasOffsetY = p0.Y
                    success = true
                end
            end
        end
    end)
    if not success then
        local scale = 1.0
        pcall(function()
            if VehWLL and VehWLL.GetViewportScale then
                local s = VehWLL.GetViewportScale(PC)
                if tonumber(s) and s > 0 then scale = s end
            end
        end)
        VehicleESP._CanvasScaleX  = 1.0 / scale
        VehicleESP._CanvasScaleY  = 1.0 / scale
        VehicleESP._CanvasOffsetX = 0.0
        VehicleESP._CanvasOffsetY = 0.0
    end
end

-- ==========================================
-- PROJECT WORLD -> CANVAS LOCAL
-- ==========================================
function VehicleESP.ProjectToCanvas(PC, WorldLoc)
    if not VehValid(PC) or not WorldLoc or not VehFVector2D then return false, 0, 0 end
    local pix = VehFVector2D(0, 0)
    local ok = false
    pcall(function()
        local res = PC:ProjectWorldLocationToScreen(WorldLoc, pix, true)
        ok = (res == true or res == 1 or (pix and (pix.X ~= 0 or pix.Y ~= 0)))
    end)
    if not ok then return false, 0, 0 end
    local fx = pix.X * VehicleESP._CanvasScaleX + VehicleESP._CanvasOffsetX
    local fy = pix.Y * VehicleESP._CanvasScaleY + VehicleESP._CanvasOffsetY
    return true, fx, fy
end

-- ==========================================
-- SHOW / HIDE / DESTROY
-- ==========================================
function VehicleESP.ShowWidget(data)
    if not data or data.bVisible then return end
    data.bVisible = true
    pcall(function() data.Container:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
end

function VehicleESP.HideWidget(data)
    if not data or not data.bVisible then return end
    data.bVisible = false
    pcall(function() data.Container:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
end

function VehicleESP.DestroyWidget(data)
    if not data then return end
    if data.Container and VehValid(data.Container) then
        pcall(function()
            data.Container:RemoveFromParent()
        end)
    end
end

-- ==========================================
-- SCAN XE
-- ==========================================
function VehicleESP.ScanVehicles(gameInstance)
    if not _G.CachedGameplayStatics then _G.CachedGameplayStatics = import("GameplayStatics") end
    if not _G.CachedActorClass_ForVehicle then _G.CachedActorClass_ForVehicle = import("STExtraVehicleBase") end
    if not _G.CachedVehicleArray then
        _G.CachedVehicleArray = slua.Array(UEnums.EPropertyClass.Object, _G.CachedActorClass_ForVehicle)
    end

    local allVehicles = _G.CachedGameplayStatics.GetAllActorsOfClass(
        gameInstance, _G.CachedActorClass_ForVehicle, _G.CachedVehicleArray
    )

    local activeVehicles = {}
    if allVehicles then
        for _, veh in pairs(allVehicles) do
            if slua.isValid(veh) and not veh.bHidden and not veh.bTearOff then
                local isPendingKill = false
                pcall(function()
                    if type(veh.IsPendingKill) == "function" then
                        isPendingKill = veh:IsPendingKill()
                    end
                end)

                if not isPendingKill then
                    local vehName = "Xe"
                    local hasDriver = false
                    pcall(function()
                        if type(veh.GetVehicleName) == "function" then
                            vehName = veh:GetVehicleName()
                        elseif veh.VehicleName then
                            vehName = veh.VehicleName
                        end
                        local driver = type(veh.GetDriver) == "function" and veh:GetDriver() or nil
                        if slua.isValid(driver) then hasDriver = true end


                    end)

                    local nameLower = string.lower(tostring(vehName) .. tostring(veh))
                    local displayName = "Xe"
                    if string.find(nameLower, "uaz") then displayName = "UAZ"
                    elseif string.find(nameLower, "dacia") then displayName = "Dacia"
                    elseif string.find(nameLower, "buggy") then displayName = "Buggy"
                    elseif string.find(nameLower, "mirado") then displayName = "Mirado"
                    elseif string.find(nameLower, "bike") or string.find(nameLower, "motor") then displayName = "Motor"
                    elseif string.find(nameLower, "scooter") then displayName = "Scooter"
                    elseif string.find(nameLower, "coupe") then displayName = "Coupe RB"
                    elseif string.find(nameLower, "brdm") then displayName = "BRDM"
                    elseif string.find(nameLower, "boat") or string.find(nameLower, "aquarail") then displayName = "Thuyền"
                    elseif string.find(nameLower, "glider") then displayName = "Tàu lượn"
                    else displayName = "Xe (" .. string.sub(vehName, 1, 8) .. ")" end

                    table.insert(activeVehicles, {
                        act = veh,
                        name = displayName,
                        hasDriver = hasDriver,
                        key = tostring(veh)
                    })
                end
            end
        end
    end
    return activeVehicles
end

-- ==========================================
-- UPDATE ESP XE (MAIN)
-- ==========================================
function VehicleESP.Update()
    if not _G.LexusConfig then return end
    local C = _G.LexusConfig

    VehicleESP.bActive = C.EspVehicle ~= false
    if not VehicleESP.bActive then
        if not VehicleESP._bDestroyedWhenOff then
            VehicleESP._bDestroyedWhenOff = true
            VehicleESP.Reset()
        end
        return
    else
        VehicleESP._bDestroyedWhenOff = false
    end

    local ParentCanvas = VehicleESP.GetCanvas()
    if not ParentCanvas then return end

    local GameplayData = package.loaded["GameLua.GameCore.Data.GameplayData"] or _G.GameplayData
    if not GameplayData then return end

    local LocalPlayer = GameplayData.GetPlayerCharacter and GameplayData.GetPlayerCharacter()
    if not VehValid(LocalPlayer) then return end

    local PC = GameplayData.GetPlayerController and GameplayData.GetPlayerController()
    if not VehValid(PC) then return end

    local curTime = os.clock and os.clock() or 0
    if VehicleESP._LastCanvas ~= ParentCanvas or (curTime - VehicleESP._LastTransformTime > 1.0) then
        VehicleESP.UpdateCanvasTransform(PC)
        VehicleESP._LastCanvas = ParentCanvas
        VehicleESP._LastTransformTime = curTime
    end

    -- Scan xe mỗi 1 giây
    if not VehicleESP._LastScanTime or (curTime - VehicleESP._LastScanTime) > 1.0 then
        VehicleESP._LastScanTime = curTime
        local ui_util = require("client.common.ui_util")
        local gameInstance = ui_util and ui_util.GetGameInstance()
        if gameInstance then
            VehicleESP._CachedVehicles = VehicleESP.ScanVehicles(gameInstance)
        end
    end

    if not VehicleESP._CachedVehicles then return end

    local SeenKeys = {}

    for _, item in ipairs(VehicleESP._CachedVehicles) do
        local veh = item.act
        if slua.isValid(veh) and not veh.bHidden then
            local isShow = false
            if item.name == "Dacia" then isShow = C.EspVeh_Dacia
            elseif item.name == "UAZ" then isShow = C.EspVeh_UAZ
            elseif item.name == "Buggy" then isShow = C.EspVeh_Buggy
            elseif item.name == "Coupe RB" then isShow = C.EspVeh_Coupe
            elseif item.name == "Mirado" then isShow = C.EspVeh_Mirado
            elseif item.name == "Motor" or item.name == "Scooter" then isShow = C.EspVeh_Motor
            else isShow = C.EspVeh_Other end

            if isShow then
                local distM = 0
                pcall(function() distM = LocalPlayer:GetDistanceTo(veh) / 100 end)

                if distM > 9 and distM <= 400 then
                    local KeyStr = item.key
                    SeenKeys[KeyStr] = true

                    local data = VehicleESP.VehicleWidgets[KeyStr]
                    if not data then
                        data = VehicleESP.CreateVehicleWidget(ParentCanvas)
                        if data then
                            VehicleESP.VehicleWidgets[KeyStr] = data
                        end
                    end

                    if data and VehValid(data.Container) then
                        local vehLoc = veh:K2_GetActorLocation()
                        if vehLoc then
                            -- Smoothing Z
                            local smoothZ = vehLoc.Z
                            if data._smoothedZ then
                                smoothZ = data._smoothedZ * 0.85 + vehLoc.Z * 0.15
                            end
                            data._smoothedZ = smoothZ

                            local bottomLoc = {
                                X = vehLoc.X,
                                Y = vehLoc.Y,
                                Z = smoothZ - 80
                            }

                            local ok, canvasX, canvasY = VehicleESP.ProjectToCanvas(PC, bottomLoc)

                            if ok then
                                VehicleESP.ShowWidget(data)

                                local textStr = string.format("%s - %dm", item.name, math.floor(distM))

                                if data._lastText ~= textStr then
                                    pcall(function() data.Text:SetText(textStr) end)
                                    data._lastText = textStr
                                end

                                local colorHash = item.hasDriver and "driver" or "empty"
                                if data._lastColorHash ~= colorHash then
                                    local col
                                    if item.hasDriver then
                                        col = VehFLinearColor and VehFLinearColor(1.0, 0.31, 0.55, 1.0)
                                                                    or {R=255, G=80, B=140, A=255}
                                    else
                                        col = VehFLinearColor and VehFLinearColor(0.0, 1.0, 0.6, 1.0)
                                                                    or {R=0, G=255, B=150, A=255}
                                    end
                                    pcall(function()
                                        if VehFSlateColor then
                                            data.Text:SetColorAndOpacity(VehFSlateColor(col))
                                        else
                                            data.Text:SetColorAndOpacity(col)
                                        end
                                    end)
                                    data._lastColorHash = colorHash
                                end

                                if math.abs(canvasX - data._lastX) > 1.0 or math.abs(canvasY - data._lastY) > 1.0 then
                                    data._lastX = canvasX
                                    data._lastY = canvasY
                                    pcall(function()
                                        data.Slot:SetPosition(VehFVector2D(canvasX, canvasY))
                                    end)
                                end
                            else
                                VehicleESP.HideWidget(data)
                            end
                        end
                    end
                end
            end
        end
    end

    -- Xóa widget của xe không còn trong scene
    for KeyStr, data in pairs(VehicleESP.VehicleWidgets) do
        if not SeenKeys[KeyStr] then
            VehicleESP.DestroyWidget(data)
            VehicleESP.VehicleWidgets[KeyStr] = nil
        end
    end
end

-- ==========================================
-- RESET KHI HẾT TRẬN
-- ==========================================
function VehicleESP.Reset(deferRemoval)
    for KeyStr, data in pairs(VehicleESP.VehicleWidgets) do
        if deferRemoval and data and data.Container and _G.QueueChannWidgetCleanup then
            _G.QueueChannWidgetCleanup(data.Container)
        else
            VehicleESP.DestroyWidget(data)
        end
    end
    VehicleESP.VehicleWidgets = {}
    VehicleESP._CachedVehicles = nil
    VehicleESP._ESPCanvas = nil
    VehicleESP._LastCanvas = nil
    VehicleESP._LastScanTime = 0
    VehicleESP._LastTransformTime = 0
    VehicleESP._CanvasScaleX = 1.0
    VehicleESP._CanvasScaleY = 1.0
    VehicleESP._CanvasOffsetX = 0.0
    VehicleESP._CanvasOffsetY = 0.0
end

_G.ChanEsp.Vehicle = VehicleESP

-- VehicleESP is updated only by ChanEsp.Tick; no separate PlayerController timer.
end)
-- ==============================================================================
-- [WEAPON SKIN IN BACKPACK] - FULL SYSTEM
-- ==============================================================================
local function InstallWSBModule()
-- [1] Biến toàn cục
_G.WeaponSkinBackpack = _G.WeaponSkinBackpack or {
    mappings = {},
    mappingsDirty = true,
    lastBuildTime = 0,
    lastAppliedWeaponID = 0,
    lastAppliedSkinID = 0,
    watcherActive = false,
    weaponHookGuardUntil = 0,
    globalFrame = 0,
    _typeIDCache = {},
    -- [NEW] Cache cho GetWeaponAvatarRes
    _bpAvatarResCache = {},
    _bpAvatarResTicks = {},
}
local WSB = _G.WeaponSkinBackpack

-- [2] Build mapping weaponID → skinResID
local function WSB_BuildMappings()
    local now = os.clock()
    if not WSB.mappingsDirty and (now - WSB.lastBuildTime) < 0.5 then
        return WSB.mappings
    end
    WSB.lastBuildTime = now
    WSB.mappingsDirty = false
    
    local m = WSB.mappings
    for k in pairs(m) do m[k] = nil end
    
    -- Lấy từ cache AddOutfit
    if _G.AddOutfit and _G.AddOutfit.cache then
        local cch = _G.AddOutfit.cache()
        if cch and cch.weapons then
            for wid, w in pairs(cch.weapons) do
                wid = tonumber(wid)
                if wid and w.resID and w.resID > 0 then
                    m[wid] = tonumber(w.resID)
                end
            end
        end
    end
    
    -- Fallback từ MATCH_CONFIG
    if _G.AddOutfit and _G.AddOutfit.MATCH_CONFIG and _G.AddOutfit.MATCH_CONFIG.weaponSkins then
        for wid, res in pairs(_G.AddOutfit.MATCH_CONFIG.weaponSkins) do
            wid = tonumber(wid)
            res = tonumber(res)
            if wid and res and res > 0 and not m[wid] then
                m[wid] = res
            end
        end
    end
    
    return m
end

-- [3] Resolve WeaponID (loại súng) từ ResID
local function WSB_ResolveWeaponTypeID(weaponResID)
    weaponResID = tonumber(weaponResID) or 0
    if weaponResID <= 0 then return 0 end
    
    if WSB._typeIDCache[weaponResID] ~= nil then 
        return WSB._typeIDCache[weaponResID] 
    end
    
    local found = 0
    pcall(function()
        local wc = CDataTable.GetTableData("WeaponConfig", weaponResID)
        if wc then found = tonumber(wc.WeaponID or wc.WeaponId or 0) end
    end)
    if found <= 0 then
        pcall(function()
            local ic = CDataTable.GetTableData("Item", weaponResID)
            if ic then found = tonumber(ic.WeaponID or ic.weaponId or 0) end
        end)
    end
    
    local result = found > 0 and found or weaponResID
    WSB._typeIDCache[weaponResID] = result
    return result
end

-- [4] Lấy Skin ID mong muốn
local function WSB_GetTargetSkinID(currentGunID, maxIt)
    currentGunID = tonumber(currentGunID) or 0
    maxIt = tonumber(maxIt) or 0
    if currentGunID <= 0 and maxIt <= 0 then return 0 end
    
    local m = WSB_BuildMappings()
    local wid = maxIt > 0 and maxIt or currentGunID
    
    if m[wid] and m[wid] > 0 then return m[wid] end
    
    local typeId = WSB_ResolveWeaponTypeID(wid)
    if typeId ~= wid and m[typeId] and m[typeId] > 0 then 
        return m[typeId] 
    end
    
    return wid
end

-- [5] Lấy Skin ID từ synData
local function WSB_GetSynMasterSkinID(weapon)
    if not slua.isValid(weapon) then return 0 end
    local id = 0
    pcall(function()
        local arr = weapon.synData
        if not arr or not slua.isValid(arr) then return end
        local att = arr:Get(7)
        if not att then return end
        local defRef = slua.IndexReference(att, "defineID")
        if defRef then id = tonumber(defRef.TypeSpecificID) or 0 end
    end)
    return id
end

-- [6] Áp dụng skin cho 1 cây súng
local function WSB_ApplySkinToWeapon(CurWeapon)
    if not slua.isValid(CurWeapon) then return false end
    
    local AttachmentArray = CurWeapon.synData
    if not AttachmentArray or not slua.isValid(AttachmentArray) then return false end
    
    local AttachmentData = AttachmentArray:Get(7)
    if not AttachmentData then return false end
    
    local current_gunid = 0
    pcall(function()
        current_gunid = slua.IndexReference(AttachmentData, "defineID").TypeSpecificID or 0
    end)
    current_gunid = tonumber(current_gunid) or 0
    if current_gunid <= 0 then return false end
    
    local MaxIt = 0
    pcall(function()
        if CurWeapon.GetWeaponID then MaxIt = CurWeapon:GetWeaponID() end
        if MaxIt <= 0 then MaxIt = CurWeapon:GetItemDefineID().TypeSpecificID end
    end)
    MaxIt = tonumber(MaxIt) or 0
    if MaxIt <= 0 then return false end
    
    local tmp_id = WSB_GetTargetSkinID(current_gunid, MaxIt)
    tmp_id = tonumber(tmp_id) or 0
    if tmp_id <= 0 or tmp_id == current_gunid then return false end
    
    local wac = CurWeapon.WeaponAvatarComponent
    local currentVisualID = 0
    if slua.isValid(wac) then 
        currentVisualID = wac.CachedLoadedID or 0 
    end
    
    if currentVisualID == tmp_id then return true end
    
    _G.AddOutfitLastAppliedSkin = _G.AddOutfitLastAppliedSkin or {}
    _G.AddOutfitLastAppliedSkin[current_gunid] = tmp_id
    
    pcall(function()
        local defRef = slua.IndexReference(AttachmentData, "defineID")
        defRef.TypeSpecificID = tmp_id
        local c0 = CDataTable.GetTableData("Item", tmp_id)
        if c0 and c0.ItemType and defRef.Type ~= nil then 
            defRef.Type = c0.ItemType 
        end
        AttachmentData.operationType = 0
        AttachmentArray:Set(7, AttachmentData)
    end)
    
    if CurWeapon.DelayHandleAvatarMeshChanged then 
        CurWeapon:DelayHandleAvatarMeshChanged() 
    end
    
    -- Delayed re-apply
    pcall(function()
        local char = nil
        if GameplayData and GameplayData.GetPlayerCharacter then
            char = GameplayData.GetPlayerCharacter()
        end
        if char and slua.isValid(char) and char.AddGameTimer then
            for _, delay in ipairs({0.3, 0.6, 1.0}) do
                char:AddGameTimer(delay, false, function()
                    if slua.isValid(CurWeapon) then
                        local aa = CurWeapon.synData
                        if aa and slua.isValid(aa) then
                            if _G.autoApplyAttachments and _G.LexusConfig.SkinAttachment then
                                pcall(_G.autoApplyAttachments, aa, tmp_id)
                            end
                        end
                    end
                end)
            end
        end
    end)
    
    if _G.autoApplyAttachments and _G.LexusConfig.SkinAttachment and tmp_id >= 1000000 then
        pcall(_G.autoApplyAttachments, AttachmentArray, tmp_id)
    end
    
    WSB.weaponHookGuardUntil = WSB.globalFrame + 45
    WSB.lastAppliedWeaponID = MaxIt
    WSB.lastAppliedSkinID = tmp_id
    
    return true
end

-- [7] Quét TẤT CẢ súng trong balo
local function WSB_EquipAllWeaponsInBackpack(char)
    if not char or not slua.isValid(char) then return false end
    
    local WeaponManager = char:GetWeaponManager()
    if not WeaponManager or not slua.isValid(WeaponManager) then return false end
    
    local uWeaponList = WeaponManager:GetAllInventoryWeaponList(false)
    if not uWeaponList or not slua.isValid(uWeaponList) then return false end
    
    local appliedAny = false
    local count = uWeaponList:Num()
    
    for i = 0, count - 1 do
        local CurWeapon = uWeaponList:Get(i)
        if slua.isValid(CurWeapon) and WSB_ApplySkinToWeapon(CurWeapon) then
            appliedAny = true
        end
    end
    
    return appliedAny
end

-- ==============================================================================
-- [8] HOOK BackPackFunctionLibrary.GetWeaponAvatarRes (QUAN TRỌNG NHẤT!)
-- ==============================================================================
local _wsbHookedGetWeaponAvatarRes = false

local function WSB_HookBackpackWeaponAvatarRes()
    if _wsbHookedGetWeaponAvatarRes then return true end
    
    local okHook, hookErr = pcall(function()
        local BPL = require("GameLua.Mod.BaseMod.Client.Backpack.BackPackFunctionLibrary")
        if not BPL or not BPL.GetWeaponAvatarRes then 
            print("[WSB] Không tìm thấy BackPackFunctionLibrary.GetWeaponAvatarRes")
            return 
        end
        
        if BPL._wsb_hooked_avatar_res then
            _wsbHookedGetWeaponAvatarRes = true
            return true
        end
        BPL._wsb_hooked_avatar_res = true
        
        local origGetRes = BPL.GetWeaponAvatarRes
        
        BPL.GetWeaponAvatarRes = function(WeaponID, AdditionalDataArray)
            WeaponID = tonumber(WeaponID) or 0
            if WeaponID <= 0 then 
                return origGetRes(WeaponID, AdditionalDataArray) 
            end
            
            -- ✅ CACHE: Kiểm tra cache trước (5 giây TTL)
            local nowTick = WSB.globalFrame or 0
            local cached = WSB._bpAvatarResCache[WeaponID]
            local cacheTick = WSB._bpAvatarResTicks[WeaponID] or 0
            if cached and (nowTick - cacheTick) < 150 then
                return cached, ""
            end
            
            local targetSkinID = 0
            
            -- ✅ BƯỚC 1: Tra cache AddOutfit trực tiếp
            if _G.AddOutfit and _G.AddOutfit.cache then
                local cch = _G.AddOutfit.cache()
                if cch and cch.weapons then
                    local typeId = WSB_ResolveWeaponTypeID(WeaponID)
                    local w = cch.weapons[typeId] or cch.weapons[WeaponID]
                    if w and w.resID and w.resID > 0 then
                        targetSkinID = tonumber(w.resID)
                    end
                end
            end
            
            -- ✅ BƯỚC 2: Fallback dùng WSB_GetTargetSkinID
            if targetSkinID <= 0 or targetSkinID == WeaponID then
                local sid = WSB_GetTargetSkinID(WeaponID, WeaponID)
                targetSkinID = tonumber(sid) or 0
            end
            
            -- ✅ BƯỚC 3: Cache kết quả và return
            if targetSkinID > 0 and targetSkinID ~= WeaponID then
                WSB._bpAvatarResCache[WeaponID] = targetSkinID
                WSB._bpAvatarResTicks[WeaponID] = nowTick
                
                -- Kiểm tra config skin tồn tại
                local skinCfg = CDataTable.GetTableData("Item", targetSkinID)
                if skinCfg then
                    return targetSkinID, ""
                end
            end
            
            -- Fallback: cache và trả về skin gốc
            WSB._bpAvatarResCache[WeaponID] = WeaponID
            WSB._bpAvatarResTicks[WeaponID] = nowTick
            return origGetRes(WeaponID, AdditionalDataArray)
        end
        
        _wsbHookedGetWeaponAvatarRes = true
        print("[WSB] Đã hook BackPackFunctionLibrary.GetWeaponAvatarRes")
        return true
    end)
    if not okHook then WSB.lastHookError = tostring(hookErr) end
    return okHook and _wsbHookedGetWeaponAvatarRes == true
end

-- ==============================================================================
-- [9] HOOK BackpackUtils (bypass BPID validation)
-- ==============================================================================
local function WSB_HookBackpackUtils()
    if _G.WSB_BP_HOOKED then return true end
    
    local okHook, hookErr = pcall(function()
        local BU = import("BackpackUtils")
        if not BU then
            print("[WSB] Không tìm thấy BackpackUtils")
            return false
        end
        
        if BU.GetBPIDByResID and not _G.WSB_OrigBPID then
            _G.WSB_OrigBPID = BU.GetBPIDByResID
            BU.GetBPIDByResID = function(resID)
                resID = tonumber(resID)
                if not resID then 
                    return _G.WSB_OrigBPID(resID) 
                end
                
                local isInjected = false
                if _G.AddOutfit and _G.AddOutfit.isInjectedRes then
                    isInjected = _G.AddOutfit.isInjectedRes(resID)
                end
                
                if isInjected then
                    local bp = _G.WSB_OrigBPID(resID)
                    if bp and bp > 0 then return bp end
                    return resID
                end
                
                return _G.WSB_OrigBPID(resID)
            end
            print("[WSB] Đã hook BackpackUtils.GetBPIDByResID")
        end
        _G.WSB_BP_HOOKED = true
        return true
    end)
    if not okHook then WSB.lastHookError = tostring(hookErr) end
    return okHook and _G.WSB_BP_HOOKED == true
end

-- ==============================================================================
-- [10] ĐĂNG KÝ SKIN SÚNG VỚI PLAYER CONTROLLER
-- ==============================================================================
local _wsbAvatarItemsRegistered = false

local function WSB_GetDesiredWeaponSkins()
    local out, seen = {}, {}
    local m = WSB_BuildMappings()
    
    for wid, resID in pairs(m) do
        resID = tonumber(resID)
        if resID and resID > 0 and not seen[resID] then
            seen[resID] = true
            out[#out + 1] = resID
        end
    end
    
    return out
end

local function WSB_RegisterWeaponAvatarItems(char)
    if not char or not slua.isValid(char) then return false end
    
    local pc = char.GetPlayerControllerSafety and char:GetPlayerControllerSafety()
    if not slua.isValid(pc) then return false end
    
    local BU = import("BackpackUtils")
    local AU = import("AvatarUtils")
    
    if not BU or not AU then return false end
    
    local addedCount = 0
    local skins = WSB_GetDesiredWeaponSkins()
    if #skins == 0 then return false end
    
    for _, resID in ipairs(skins) do
        local doneDirect = false
        
        -- Cách 1: API native
        pcall(function()
            if pc.AddWeaponAvatarItem then
                pc:AddWeaponAvatarItem(tonumber(resID))
                doneDirect = true
                addedCount = addedCount + 1
            end
        end)
        
        -- Cách 2: Fallback qua BackpackUtils
        if not doneDirect then
            pcall(function()
                local skinBPID = BU.GetBPIDByResID(tonumber(resID))
                if not skinBPID or skinBPID <= 0 then return end
                
                local arr = slua.Array(UEnums.EPropertyClass.Int)
                local parents = AU.GetWeaponAvatarParentIDList(skinBPID, arr, false)
                
                if parents and parents.Num and parents:Num() > 0 and pc.WeaponAvatarItemList then
                    for _, parentID in pairs(parents) do
                        pc.WeaponAvatarItemList:Add(parentID, skinBPID)
                    end
                    addedCount = addedCount + 1
                end
            end)
        end
    end
    
    if addedCount == 0 then return false end
    
    pcall(function() if pc.InitWeaponAvatarItems then pc:InitWeaponAvatarItems() end end)
    pcall(function() if pc.OnWeaponAvatarUpdate then pc:OnWeaponAvatarUpdate() end end)
    print(string.format("[WSB] Đã đăng ký %d skin súng với PC", addedCount))
    return true
end

