-- ==============================================================================
-- [12] SMART WATCHER - Quét súng theo cache + cursor
-- Dùng chung inventory cache để tránh lấy lại danh sách và quét toàn bộ mỗi lượt.
-- ==============================================================================
_G.ChannWeaponWatchCache = _G.ChannWeaponWatchCache or { Cursor = 0 }
_G.ChannGetNextCachedWeapon = function(pChar, weaponManager)
    if not pChar or not weaponManager then return nil end

    local cache = _G.ChannWeaponWatchCache
    local now = os.clock()
    if type(_G.RealNow) == "function" then
        local ok, value = pcall(_G.RealNow)
        if ok and type(value) == "number" then now = value end
    end
    local list = cache.List

    if cache.Owner ~= pChar
        or cache.Manager ~= weaponManager
        or now >= (cache.ExpiresAt or 0)
        or not list
        or not slua.isValid(list) then
        local ok, refreshed = pcall(function()
            return weaponManager:GetAllInventoryWeaponList(false)
        end)
        if not ok or not refreshed or not slua.isValid(refreshed) then
            cache.List = nil
            cache.Owner = pChar
            cache.Manager = weaponManager
            cache.ExpiresAt = now + 0.25
            return nil
        end

        cache.Owner = pChar
        cache.Manager = weaponManager
        cache.List = refreshed
        cache.ExpiresAt = now + 1.11
        cache.Cursor = 0
        list = refreshed
    end

    local count = list:Num()
    if count <= 0 then return nil end

    local index = (cache.Cursor or 0) % count
    cache.Cursor = index + 1
    return list:Get(index)
end

if not WSB.watcherActive then
    WSB.watcherActive = true
    pcall(function()
        local ticker = require("common.time_ticker")
        if ticker and ticker.AddTimerLoop then
            ticker.AddTimerLoop(0, function()
                local ok, err = pcall(function()
                    if not _G.LexusConfig or not _G.LexusConfig.ModSkin then return end
                    if _G.AddOutfit and _G.AddOutfit.isInRealMatch and not _G.AddOutfit.isInRealMatch() then return end
                    local nowHook = os.clock()
                    if nowHook >= (WSB._nextHookRetry or 0) then
                        WSB._nextHookRetry = nowHook + 5.0
                        if not _wsbHookedGetWeaponAvatarRes then pcall(WSB_HookBackpackWeaponAvatarRes) end
                        if not _G.WSB_BP_HOOKED then pcall(WSB_HookBackpackUtils) end
                    end
                    local pController = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
                    if not pController or not slua.isValid(pController) then return end
                    local pChar = pController:GetPlayerCharacterSafety()
                    if not pChar or not slua.isValid(pChar) then return end
                    if WSB._registeredPC ~= pController then
                        local registered, registerErr = pcall(WSB_RegisterWeaponAvatarItems, pChar)
                        if registered then WSB._registeredPC = pController else WSB.lastRegisterError = tostring(registerErr) end
                    end
                    WSB.globalFrame = WSB.globalFrame + 1
                    local WeaponManager = pChar:GetWeaponManager()
                    if not WeaponManager or not slua.isValid(WeaponManager) then return end
                    local wep = _G.ChannGetNextCachedWeapon(pChar, WeaponManager)
                    if not slua.isValid(wep) then return end

                    local synSkinID = WSB_GetSynMasterSkinID(wep)
                    local baseID = 0
                    pcall(function() baseID = wep:GetItemDefineID().TypeSpecificID end)
                    local tSkin = WSB_GetTargetSkinID(baseID, baseID)
                    if synSkinID ~= tSkin or _G.LexusConfig.SkinAttachment then
                        pcall(WSB_ApplySkinToWeapon, wep)
                    end
                end)
                if not ok then WSB.lastError = tostring(err) else WSB.lastError = nil end
            end, -1, 0.65)
        end
    end)
    print("[WSB] Smart Watcher đã khởi động")
end

