-- ==============================================================================
-- TỐI ƯU CHỐNG DROP FPS — PATCH THAY THẾ CÁC HÀM HOT PATH
-- Dán đè vào sau phần khai báo hàm gốc, trước MainLoop
-- ==============================================================================

-- [1] TĂNG CACHE TTL MESH TỪ 3s LÊN 5s
-- Thay thế dòng: if markData.CachedMeshes and markData.CachedMeshTime and (curTime - markData.CachedMeshTime < 3.0)
-- Đổi 3.0 → 5.0 trong hàm GetAllSkeletalMeshes
local _orig_GetAllSkeletalMeshes = GetAllSkeletalMeshes
GetAllSkeletalMeshes = function(enemy, markData)
    local curTime = os.clock()
    if markData and markData.CachedMeshes and markData.CachedMeshTime
        and (curTime - markData.CachedMeshTime < 5.0) then
        local validMeshes = {}
        for _, cachedMesh in ipairs(markData.CachedMeshes) do
            if Valid(cachedMesh) then table.insert(validMeshes, cachedMesh) end
        end
        markData.CachedMeshes = validMeshes
        return validMeshes
    end
    local meshes = {}
    if Valid(enemy.Mesh) then table.insert(meshes, enemy.Mesh) end
    pcall(function()
        local SkeletalMeshClass = import("SkeletalMeshComponent")
        if SkeletalMeshClass and type(enemy.GetComponentsByClass) == "function" then
            local childs = enemy:GetComponentsByClass(SkeletalMeshClass)
            if childs then
                local count = type(childs.Num) == "function" and childs:Num() or #childs
                for i = 1, count do
                    local comp = type(childs.Get) == "function" and childs:Get(i-1) or childs[i]
                    if Valid(comp) and comp ~= enemy.Mesh then
                        table.insert(meshes, comp)
                    end
                end
            end
        end
    end)
    if markData then
        markData.CachedMeshes = meshes
        markData.CachedMeshTime = curTime
    end
    return meshes
end

-- [2] GATE AIMBOT TẠI 60FPS MAX (tránh chạy 100 lần/giây)
local _AimTouchLastTime = 0
local _AimTouch_Orig = _G.AimTouch
_G.AimTouch = function()
    if not _G.LexusConfig.AimTouchEnable then return end
    local now = os.clock()
    if now - _AimTouchLastTime < 0.016 then return end
    _AimTouchLastTime = now
    _AimTouch_Orig()
end

-- [3] COLORV3 — SKIP TOÀN BỘ NẾU HASH KHÔNG ĐỔI (kể cả mesh count)
local _ApplyColorBodyV3_Orig = ApplyColorBodyV3
ApplyColorBodyV3 = function(enemy, markData)
    -- Kiểm tra hash TRƯỚC KHI lấy mesh
    local cData = _G.LexusState.CustomTextData or {}
    local hidChoice = cData.ColorV3Hidden or 1
    local visChoice = cData.ColorV3Visible or 2
    local v3Thick = cData.ColorV3Thickness or 4
    local quickHash = string.format("%d_%d_%d", hidChoice, visChoice, v3Thick)
    if markData.LastColorV3Hash == quickHash and markData.ColorV3Applied then
        return -- ngủ đông hoàn toàn
    end
    _ApplyColorBodyV3_Orig(enemy, markData)
end

-- [4] COLORNEW — FETCH VŨ KHÍ SAU GUARD (không lãng phí khi hash match)
local _ApplyColorBodyNew_Orig = ApplyColorBodyNew
ApplyColorBodyNew = function(enemy, markData)
    -- Guard trước khi fetch weapon
    local isBot = markData.AK_IS_BOT or false
    local meshCount = markData.CachedMeshes and #markData.CachedMeshes or 0
    local stateHash = (isBot and "BOT" or "PLAYER") .. "_" .. tostring(meshCount)
    if markData.LastColorNewHash == stateHash and markData.ColorNewApplied then
        return
    end
    _ApplyColorBodyNew_Orig(enemy, markData)
end

-- [5] COUNTER WIDGET — GUARD NỘI BỘ ĐỂ TRÁNH GỌI 100x/s TỪ MAINLOOP
local _M_DrawCounter_Orig = _M_DrawCounter
local _M_DrawCounter_LastCall = 0
_M_DrawCounter = function()
    local now = os.clock()
    if now - _M_DrawCounter_LastCall < 0.1 then return end -- tối đa 10fps cho counter
    _M_DrawCounter_LastCall = now
    _M_DrawCounter_Orig()
end
-- ========================================== 
-- VÒNG LẶP CHÍNH (MAIN LOOP) TỐI ƯU CỰC MẠNH
-- ========================================== 
local ChannMainLoopCache = { World=nil, PC=nil, PPM=nil, SecurityCommonUtils=nil, HUD=nil, NextPPMRetry=0, NextSecurityRetry=0 }

local function MainLoop()
    if isExpired then return end

    -- =====================================================================
    -- HỆ THỐNG LẤY HWID GỐC & ĐỔI HWID ẢO (SPOOFER) CHỐNG BAN
    -- =====================================================================
_G.LexusConfig = _G.LexusConfig or {}
if _G.LexusConfig.FakeHWID == nil then _G.LexusConfig.FakeHWID = false end

if not _G.FakeHWID_Hooked then
    local now = os.clock()
    if now >= (_G.ChannKismetNextRetry or 0) then
        _G.ChannKismetNextRetry = now + 5
        pcall(function()
            local SystemLib = import("KismetSystemLibrary")
            if not SystemLib or type(SystemLib.GetDeviceId) ~= "function" then return end

            local rawGetDeviceId = SystemLib.GetDeviceId
            SystemLib.GetDeviceId = function(...)
                if _G.LexusConfig.FakeHWID then
                    if not _G.FakeHWID_String then
                        _G.FakeHWID_String = "SAMSUNG-SM-S918B-FAKE-" .. tostring(math.random(100000, 999999))
                    end
                    return _G.FakeHWID_String
                end
                return rawGetDeviceId(...)
            end

            _G.FakeHWID_Hooked = true
            _G.FakeHWID_Raw = rawGetDeviceId
        end)
    end
end
    -- =====================================================================











    if _G.LexusState.CustomTextData == nil then 
        _G.LexusState.CustomTextData = {OuterSpeed = 10, InnerSpeed = 10, HRecoil = 0.3, VRecoil = 0.3, MagicHead = 1.0, MagicBody = 1.0, MagicLegs = 1.0, IpadViewFOV = 120, 

IpadViewVehicleFOV = 120, IpadViewScopeFOV = 100,

AimTouchHipPrio = 1, AimTouchHipBone = 1, AimTouchHipCond = 1, AimTouchHipSpeed = 50, AimTouchHipFOV = 30, AimTouchHipDist = 250, AimTouchSGPrio = 1, AimTouchSGBone = 2, AimTouchSGCond = 1, AimTouchSGSpeed = 80, AimTouchSGFOV = 40, AimTouchSGDist = 30, AimTouchScopePrio = 1, AimTouchScopeBone = 2, AimTouchScopeCond = 1, AimTouchScopeSpeed = 40, AimTouchScopeFOV = 20, AimTouchScopeDist = 300, AimTouchSniperPrio = 1, AimTouchSniperBone = 1, AimTouchSniperCond = 2, AimTouchSniperSpeed = 30, AimTouchSniperFOV = 20, AimTouchSniperDist = 400, FastCarSpeed = 2000}
    end

    local okData, GameplayData = pcall(require, "GameLua.GameCore.Data.GameplayData") 
    if not okData or not GameplayData then return end 
    local pc = GameplayData.GetPlayerController() 
    local localPlayer = nil
    if Valid(pc) then localPlayer = pc:GetPlayerCharacterSafety() end 

    -- Match transition: dọn một lần rồi return, không lặp cleanup mỗi frame.
    if not Valid(localPlayer) then
        if _G.LexusState._ChanEspMatchCleanupDone then return end
        _G.LexusState._ChanEspMatchCleanupDone = true

-- Match-end cleanup is incremental: never remove hundreds of UE widgets/marks in one frame.
if _G.ChanEsp and _G.ChanEsp.ResetWidgets then pcall(_G.ChanEsp.ResetWidgets, true) end
if _G.ChanEsp then
    _G.ChanEsp._WidgetCanvas = nil
    _G.ChanEsp._WidgetOwner = nil
    _G.ChanEsp._WidgetWorld = nil
    _G.ChanEsp._LastCanvas = nil
    _G.ChanEsp._LastUpdateTime = 0
    _G.ChanEsp._LastTransformTime = 0
    _G.ChanEsp._PawnScanCache = nil
    _G.ChanEsp._LastPawnScanTime = 0
    _G.ChanEsp._LastHeavyUpdateTime = 0
    _G.ChanEsp._LastVisCheckTime = 0
end
_G.CachedItems = {}
if _G.ChanEspItemWidgets then
    for _, data in pairs(_G.ChanEspItemWidgets) do
        if data and data.Widget then _G.QueueChannWidgetCleanup(data.Widget) end
    end
    _G.ChanEspItemWidgets = {}
end
if _G.OwenNeonBomb and _G.OwenNeonBomb.Clear then pcall(_G.OwenNeonBomb.Clear, _G.OwenNeonBomb) end
_G.LastScanItemTime = 0
_G.LastChanEspItemDraw = 0
if _G.ChanEsp and _G.ChanEsp.ResetVehicleESP then pcall(_G.ChanEsp.ResetVehicleESP, true) end
if _G.VehicleESPBoxes and _G.VehicleESPBoxes.Reset then pcall(_G.VehicleESPBoxes.Reset) end

local oldMarks = _G.LexusState.TrackedMarks or {}
if next(_G.LexusState.PendingMarkCleanup or {}) then
    for mark in pairs(oldMarks) do _G.LexusState.PendingMarkCleanup[mark] = true end
else
    _G.LexusState.PendingMarkCleanup = oldMarks
end
_G.LexusState.TrackedMarks = {}
-- Dropping the whole table releases MIDs without a synchronous nested walk.
_G.LexusState.EnemyMarks = {}
        _G.AK_OrigHitboxes = {}
        _G.AK_ModdedPhysAssets = {}
        _G.LexusState.PrevGraphicsState = {}
        
        -- DỌN DẸP WIDGET ĐẾM KẺ ĐỊCH VÀ KHOẢNG CÁCH KHI RA SẢNH (TRÁNH LỖI ĐÈ UI)
        if _G.CleanUpEnemyCounterWidget then _G.CleanUpEnemyCounterWidget() end
        return 
    end

    _G.LexusState._ChanEspMatchCleanupDone = false

    local worldOK, currentWorld = pcall(slua.getWorld)
    if not worldOK then currentWorld = nil end
    if ChannMainLoopCache.World ~= currentWorld then
        ChannMainLoopCache.World = currentWorld
        ChannMainLoopCache.PPM = nil
        ChannMainLoopCache.HUD = nil
    end
    local cacheNow=os.clock and os.clock() or 0
    if not Valid(ChannMainLoopCache.PPM) and cacheNow>=ChannMainLoopCache.NextPPMRetry then
        ChannMainLoopCache.PPM=nil
        pcall(function() ChannMainLoopCache.PPM = import("PostProcessManager").GetInstance() end)
        ChannMainLoopCache.NextPPMRetry=cacheNow+2.0
    end
    if not ChannMainLoopCache.SecurityCommonUtils and cacheNow>=ChannMainLoopCache.NextSecurityRetry then
        local okSecurity, value = pcall(require, "GameLua.Mod.BaseMod.Common.Security.SecurityCommonUtils")
        if okSecurity then ChannMainLoopCache.SecurityCommonUtils = value end
        ChannMainLoopCache.NextSecurityRetry=cacheNow+2.0
    end
    if ChannMainLoopCache.PC ~= pc or not Valid(ChannMainLoopCache.HUD) then
        ChannMainLoopCache.PC = pc
        ChannMainLoopCache.HUD = Valid(pc) and pc.MyHUD or nil
    end
    local Cached_PPM = ChannMainLoopCache.PPM
    local Cached_SecurityCommonUtils = ChannMainLoopCache.SecurityCommonUtils
    local Cached_MyHUD = ChannMainLoopCache.HUD

    if _G.LexusConfig.UnlockFPS then InitializeGraphicsUnlock() end
    ShowLexusVIPMenu()
    
    -- Chỉ giữ một hệ thống hiển thị: ChanEsp. Tắt các ESP người chơi đời cũ.
    local espCfg = _G.LexusConfig or {}
    espCfg.EspVip = false
    espCfg.EspDistance = false
    espCfg.EspVipPro = false
    espCfg.EspRadar = false
    espCfg.EspLoai5 = false
    espCfg.EspLoai6 = false
    espCfg.EspLoai7 = false
    espCfg.EspLoai8 = false
    espCfg.EspAntenna = false
    espCfg.EspOutline = false
    espCfg.WallVehicle = false
    espCfg.Esp3ShowName = false
    espCfg.Esp3ShowHP = false
    espCfg.Esp7_SoLuong = false
    espCfg.Esp7_VuKhi = false
    espCfg.Esp7_TuThe = false
    espCfg.EspLoai9 = false
    espCfg.Esp9_Count = false
    espCfg.Esp9_Name = false
    espCfg.Esp9_HP = false
    espCfg.Esp9_Team = false
    espCfg.Esp9_Weapon = false
    espCfg.Esp9_Distance = false
    espCfg.Esp9_Line = false
    espCfg.Esp9_Skeleton = false
    espCfg.Esp9_LineCheckVis = false

    -- ChanEsp: một điểm cập nhật cho Player + Vehicle + Item.
    if _G.ChanEsp then
        local espMaster = (_G.LexusConfig.EspV3 == true or _G.LexusConfig.EspV3 == 1)
        if espMaster and (not _G.ChanEsp.bActive or _G.ChanEsp._bDestroyedWhenOff) then
            pcall(_G.ChanEsp.Start)
        end
        -- Tick remains responsible for synchronizing child switches and for
        -- independent vehicle/item branches; never rewrite saved config here.
        local okTick, tickErr = pcall(_G.ChanEsp.Tick, pc)
        if not okTick then _G.ChanEsp.LastTickError = tostring(tickErr) end
    end

--
    
    -- HOÀN TRẢ GÓC NHÌN NGAY LẬP TỨC NẾU TẮT IPAD VIEW
--    if _G.LexusConfig.IpadView and _G.LexusState.CustomTextData then
--        pcall(function()
--            local targetTPP = _G.LexusState.CustomTextData.IpadViewFOV or 120
--            local uTPPCam = localPlayer.ThirdPersonCameraComponent
--            if Valid(uTPPCam) and not localPlayer.bIsWeaponAiming then
--                if uTPPCam.FieldOfView ~= targetTPP then uTPPCam.FieldOfView = targetTPP end
--            end
--        end)
--    else
--        pcall(function()
--            local uTPPCam = localPlayer.ThirdPersonCameraComponent
--            if Valid(uTPPCam) and not localPlayer.bIsWeaponAiming then
--                if uTPPCam.FieldOfView ~= 90 then uTPPCam.FieldOfView = 110 end
--            end
--        end)
--    end





-- HOÀN TRẢ GÓC NHÌN NGAY LẬP TỨC NẾU TẮT IPAD VIEW
if _G.LexusConfig.IpadView and _G.LexusState.CustomTextData then
    pcall(function()
        local targetTPP = _G.LexusState.CustomTextData.IpadViewFOV_TPP or 120
        local targetFPP = _G.LexusState.CustomTextData.IpadViewFOV_FPP or 110
        
        -- TPP Camera
        local uTPPCam = localPlayer.ThirdPersonCameraComponent
        if Valid(uTPPCam) and not localPlayer.bIsWeaponAiming then
            if uTPPCam.FieldOfView ~= targetTPP then 
                uTPPCam.FieldOfView = targetTPP 
            end
        end
        
        -- FPP Camera
        local uFPPCam = localPlayer.FPPCameraComp
        if Valid(uFPPCam) and not localPlayer.bIsWeaponAiming then
            if uFPPCam.FieldOfView ~= targetFPP then 
                uFPPCam.FieldOfView = targetFPP 
            end
        end
    end)
else
    pcall(function()
        local defaultTPP = 110
        local defaultFPP = 110
        
        local uTPPCam = localPlayer.ThirdPersonCameraComponent
        if Valid(uTPPCam) and not localPlayer.bIsWeaponAiming then
            if uTPPCam.FieldOfView ~= defaultTPP then 
                uTPPCam.FieldOfView = defaultTPP 
            end
        end
        
        local uFPPCam = localPlayer.FPPCameraComp
        if Valid(uFPPCam) and not localPlayer.bIsWeaponAiming then
            if uFPPCam.FieldOfView ~= defaultFPP then 
                uFPPCam.FieldOfView = defaultFPP 
            end
        end
    end)
end

    -- LOGIC IPAD VIEW (ĐI BỘ, LÁI XE VÀ MỞ SCOPE) ĐÃ NÂNG CẤP
    pcall(function()
        local isAiming = false
        if localPlayer.bIsWeaponAiming or localPlayer.bIsGunADS then isAiming = true end

        local currentVehicle = localPlayer.CurrentVehicle or (type(localPlayer.GetVehicle) == "function" and localPlayer:GetVehicle())
        local isInVehicle = Valid(currentVehicle) or localPlayer.bIsInVehicle
        local uTPPCam = localPlayer.ThirdPersonCameraComponent
        local uVehCam = localPlayer.VehicleCameraComponent
        local camMgr = pc.PlayerCameraManager

        -- 1. XỬ LÝ KHI ĐANG MỞ SCOPE (NGẮM BẮN)
        if isAiming then
            if _G.LexusConfig.IpadViewScope and _G.LexusState.CustomTextData then
                local targetScope = _G.LexusState.CustomTextData.IpadViewScopeFOV or 60
                if type(pc.FOV) == "function" then pc:FOV(targetScope) end
                if Valid(camMgr) then
                    camMgr.DefaultFOV = targetScope
                    if type(camMgr.SetFOV) == "function" then camMgr:SetFOV(targetScope) end
                end
            else
                -- Nếu tắt Ipad Scope, trả lại FOV thật của Game để ngắm chuẩn
                if type(pc.FOV) == "function" then pc:FOV(0) end
                if Valid(camMgr) and type(camMgr.UnlockFOV) == "function" then camMgr:UnlockFOV() end
            end
            return -- Ngắt logic đi bộ/xe vì ưu tiên Scope
        end

        -- 2. XỬ LÝ KHI KHÔNG NGẮM BẮN (ĐI BỘ HOẶC LÁI XE)
        -- Phục hồi camera nếu trước đó vừa tắt Scope
        if not isInVehicle or not _G.LexusConfig.IpadViewVehicle then
            if type(pc.FOV) == "function" then pc:FOV(0) end
            if Valid(camMgr) and type(camMgr.UnlockFOV) == "function" then camMgr:UnlockFOV() end
        end

        -- Đi Bộ
        if not isInVehicle then
            if _G.LexusConfig.IpadView and _G.LexusState.CustomTextData then
                local targetTPP = _G.LexusState.CustomTextData.IpadViewFOV or 120
                if Valid(uTPPCam) and uTPPCam.FieldOfView ~= targetTPP then 
                    uTPPCam.FieldOfView = targetTPP 
                end
            else
                if Valid(uTPPCam) and uTPPCam.FieldOfView ~= 90 then 
                    uTPPCam.FieldOfView = 90 
                end
            end
        end

        -- Lái Xe
        if isInVehicle then
            if _G.LexusConfig.IpadViewVehicle and _G.LexusState.CustomTextData then
                local targetVeh = _G.LexusState.CustomTextData.IpadViewVehicleFOV or 120
                
                if Valid(uVehCam) and uVehCam.FieldOfView ~= targetVeh then 
                    uVehCam.FieldOfView = targetVeh 
                end
                
                if targetVeh > 90 then
                    if type(pc.FOV) == "function" then pc:FOV(targetVeh) end
                    if Valid(camMgr) then
                        camMgr.DefaultFOV = targetVeh
                        if type(camMgr.SetFOV) == "function" then camMgr:SetFOV(targetVeh) end
                    end
                end
            else
                if Valid(uVehCam) and uVehCam.FieldOfView ~= 90 then 
                    uVehCam.FieldOfView = 90 
                end
            end
        end
    end)



    -- ========================================================
    -- LOGIC AIMBOT V2 ROYAL/CUSTOM
    -- ========================================================
    if _G.LexusConfig.AimTouchEnable then
        _G.AimTouch()
    end
    
    -- [THÊM MỚI] LOGIC GLOW SÚNG (ĐỘC LẬP & SIÊU MƯỢT 0.5s/Lần - ĐẢM BẢO 0% DROP FPS)
    if not _G.LastGlowTime or (os.clock() - _G.LastGlowTime) > 0.5 then
        _G.LastGlowTime = os.clock()
        if _G.ApplyWeaponGlow then _G.ApplyWeaponGlow(localPlayer) end
    end

    -- ========================================================
    -- LOGIC BÙ GIẬT (GHÌM TÂM) CHỈ DÀNH RIÊNG CHO AIMBOT GỐC (ĐÃ FIX LAG ĐÔNG NGƯỜI)
    -- ========================================================
    pcall(function()
        if _G.LexusConfig.CustomAimbot and localPlayer.bIsWeaponFiring and localPlayer.bIsGunADS then
            local outerRecoilVal = _G.LexusState.CustomTextData.OuterRecoil or 0
            if outerRecoilVal > 0 then
                local curTime = os.clock()
                
                -- [FIX CPU CỰC MẠNH]: Quét mục tiêu 0.2s/lần thay vì 100 lần/giây để tránh quá tải máy khi check FOV
                if not _G.RecoilTargetCacheTime or (curTime - _G.RecoilTargetCacheTime) > 0.2 then
                    _G.RecoilTargetCacheTime = curTime
                    _G.HasRecoilTargetCached = false
                    
                    local ui_util = require("client.common.ui_util")
                    if ui_util then
                        local viewportSize = ui_util.GetViewportSize()
                        if viewportSize then
                            local centerX = viewportSize.X * 0.5
                            local centerY = viewportSize.Y * 0.5
                            local FOV_RADIUS = (6 / 100.0) * (viewportSize.X / 2.0) 
                            
                            local enemies = _G.GetEnemyTargetsFromActors(40000) 
                            if enemies and #enemies > 0 then
                                local FVector2D = import("Vector2D")
                                for _, target in ipairs(enemies) do
                                    if slua.isValid(target) and target.HealthStatus ~= 1 then 
                                        local tPos = type(target.K2_GetActorLocation) == "function" and target:K2_GetActorLocation() or nil
                                        if tPos then
                                            local screen = FVector2D()
                                            if pc:ProjectWorldLocationToScreen(tPos, screen, false) and screen.X > 0 and screen.Y > 0 then
                                                local dx = screen.X - centerX
                                                local dy = screen.Y - centerY
                                                if math.sqrt(dx*dx + dy*dy) <= FOV_RADIUS then
                                                    _G.HasRecoilTargetCached = true
                                                    break 
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end

                if _G.HasRecoilTargetCached then
                    local currentRot = pc:GetControlRotation()
                    if currentRot then
                        local pullDownForce = (outerRecoilVal / 50.0) * 1.5
                        currentRot.Pitch = currentRot.Pitch - pullDownForce
                        pc:SetControlRotation(currentRot, "CustomAimbotRecoil")
                    end
                end
            end
        else
            _G.HasRecoilTargetCached = false
        end
    end)
    
    -- ========================================================
    -- THỰC THI MOD SKIN ĐƯỢC TÍCH HỢP TRỰC TIẾP VÀO MAIN LOOP (TỐI ƯU TUYỆT ĐỐI)
    -- ========================================================
    -- ========================================================
    -- THỰC THI MOD SKIN HÒM XÁC / PET / KILL MESSAGE / ÉP V7.5 CHẠY
    -- ========================================================
    if _G.LexusConfig.ModSkin then
        -- SRC-style independent glove maintenance (internally throttled to 1.5s).
        pcall(function()
            local outfit = _G.AddOutfit
            if outfit and type(outfit.maintainSelectedGloves) == "function" then
                outfit.maintainSelectedGloves()
            end
        end)
        local curTime = os.clock()
        -- Giãn chu kỳ xử lý ModSkin lên 2.5s để giảm tải tác vụ nền
        if not _G.LastSkinUpdateTime or (curTime - _G.LastSkinUpdateTime) > 2.5 then
            _G.LastSkinUpdateTime = curTime
            pcall(function()
                local isAlive = type(localPlayer.IsAlive) == "function" and localPlayer:IsAlive() or true
                if isAlive then
                    if _G.HandlePetLogic then _G.HandlePetLogic() end
                    
                    if _G.LexusConfig.SkinDeadBox and _G.DeadBox_TemperRequest and _G.NeedCheckDeadBoxTimer > 0 then
                        _G.DeadBox_TemperRequest(pc)
                    end

                    if _G.AddOutfit then
                        -- [PHÂN LUỒNG NGỦ ĐÔNG RÕ RÀNG]
                        if _G.AddOutfit.isInRealMatch() then
                            -- LUỒNG 1: TRONG TRẬN (SẢNH NGỦ ĐÔNG)
                            _G.AddOutfitLobbyRestored = false 
                            
                            -- [FIX FPS] CHIA NHỎ TIẾN TRÌNH TẢI SKIN (STAGGERED LOADING)
                            local ticker = require("common.time_ticker")
                            if ticker and ticker.AddTimerOnce then
                                _G.AddOutfit.matchApplyAllSlots(localPlayer)
                                ticker.AddTimerOnce(0.2, function()
                                    if slua.isValid(localPlayer) and _G.AddOutfit.isInRealMatch() then 
                                        _G.AddOutfit.matchApplyHat(localPlayer) 
                                    end
                                end)
                                ticker.AddTimerOnce(0.4, function()
                                    if slua.isValid(localPlayer) and _G.AddOutfit.isInRealMatch() then 
                                        _G.AddOutfit.matchApplyWeaponSkin(localPlayer)
                                    end
                                end)
                                ticker.AddTimerOnce(0.6, function()
                                    if slua.isValid(localPlayer) and _G.AddOutfit.isInRealMatch() and _G.AddOutfit.isCharacterAirborne(localPlayer) then
                                        _G.AddOutfit.applyAirborneSlots(localPlayer, true)
                                    end
                                end)
                            else
                                _G.AddOutfit.matchApplyAllSlots(localPlayer)
                                _G.AddOutfit.matchApplyHat(localPlayer)
                                _G.AddOutfit.matchApplyWeaponSkin(localPlayer)
                                if _G.AddOutfit.isCharacterAirborne(localPlayer) then
                                    _G.AddOutfit.applyAirborneSlots(localPlayer, true)
                                end
                            end
                        else
                            -- LUỒNG 2: NGOÀI SẢNH LOBBY (TRONG TRẬN NGỦ ĐÔNG)
                            _G.AddOutfit.reapplyLobbyEquipped()
                        end
                    end
                end
            end)
        end
    end

    -- CHẶN HIGGSBOSON THEO THỜI GIAN THỰC LÀM AN TOÀN TUYỆT ĐỐI MÀ KHÔNG GÂY VĂNG GAME
    pcall(function()
        if Valid(pc) then
            if pc.HiggsBoson then pc.HiggsBoson.bMHActive = false; pc.HiggsBoson.bCallPreReplication = false end
            if pc.HiggsBosonComponent then pc.HiggsBosonComponent.bMHActive = false; pc.HiggsBosonComponent.bCallPreReplication = false end
        end
    end)

    -- HOÀN TRẢ VÀ THIẾT LẬP AIMBOT HEAD COMPONENT BẬT/TẮT TỨC THÌ
    pcall(function()
        local autoComp = localPlayer.AutoAimComp
        if Valid(autoComp) then
            if not _G.LexusState.OrigAutoAimCompCached then
                _G.LexusState.OrigAutoAimCompCached = {
                    bOnlyHitHead = autoComp.bOnlyHitHead,
                    HeadBoneName = autoComp.HeadBoneName,
                    Bones = autoComp.Bones,
                    ChestBoneName = autoComp.ChestBoneName,
                    PelvisBoneName = autoComp.PelvisBoneName,
                    HeadPriority = autoComp.AimAssistConfig and autoComp.AimAssistConfig.HeadPriority,
                    ChestPriority = autoComp.AimAssistConfig and autoComp.AimAssistConfig.ChestPriority,
                    PelvisPriority = autoComp.AimAssistConfig and autoComp.AimAssistConfig.PelvisPriority
                }
            end
            
            if _G.LexusConfig.AutoHead then
                autoComp.bOnlyHitHead = true
                autoComp.HeadBoneName = "Head"
                pcall(function() autoComp.Bones = {"Head"} end)
                autoComp.ChestBoneName = "Head"
                autoComp.PelvisBoneName = "Head"
                if autoComp.AimAssistConfig then
                    autoComp.AimAssistConfig.HeadPriority = 100
                    autoComp.AimAssistConfig.ChestPriority = 100
                    autoComp.AimAssistConfig.PelvisPriority = 100
                end
            else
                local orig = _G.LexusState.OrigAutoAimCompCached
                autoComp.bOnlyHitHead = orig.bOnlyHitHead
                autoComp.HeadBoneName = orig.HeadBoneName
                pcall(function() autoComp.Bones = orig.Bones or {"Spine_01", "Pelvis", "Head"} end)
                autoComp.ChestBoneName = orig.ChestBoneName
                autoComp.PelvisBoneName = orig.PelvisBoneName
                if autoComp.AimAssistConfig then
                    autoComp.AimAssistConfig.HeadPriority = orig.HeadPriority or 1
                    autoComp.AimAssistConfig.ChestPriority = orig.ChestPriority or 1
                    autoComp.AimAssistConfig.PelvisPriority = orig.PelvisPriority or 1
                end
            end
        end
    end)

    if _G.LexusConfig.WallClimb then
        pcall(function()
            local charMove = localPlayer.CharacterMovement
            if Valid(charMove) then
                if not _G.LexusState.WallClimbOriginals then
                    _G.LexusState.WallClimbOriginals = { WalkableFloorAngle = charMove.WalkableFloorAngle, MaxStepHeight = charMove.MaxStepHeight }
                end
                charMove.WalkableFloorAngle = 199.0
                charMove.MaxStepHeight = 999.0
                _G.LexusState.WallClimbApplied = true
            end
        end)
    elseif _G.LexusState.WallClimbApplied then
        pcall(function()
            local charMove = localPlayer.CharacterMovement
            if Valid(charMove) and _G.LexusState.WallClimbOriginals then
                charMove.WalkableFloorAngle = _G.LexusState.WallClimbOriginals.WalkableFloorAngle or 50.0
                charMove.MaxStepHeight = _G.LexusState.WallClimbOriginals.MaxStepHeight or 45.0
            end
        end)
        _G.LexusState.WallClimbApplied = false
    end

    if _G.LexusConfig.FastCar then
        pcall(function()
            local currentVehicle = localPlayer.CurrentVehicle or (type(localPlayer.GetVehicle) == "function" and localPlayer:GetVehicle())
            if Valid(currentVehicle) then
                local rootComp = currentVehicle.RootComponent or (type(currentVehicle.K2_GetRootComponent) == "function" and currentVehicle:K2_GetRootComponent())
                
                if Valid(rootComp) and type(rootComp.SetAllPhysicsLinearVelocity) == "function" then
                    local isAccelerating = false
                    local moveComp = currentVehicle.VehicleMovement or currentVehicle.MovementComponent
                    if Valid(moveComp) then
                        local throttle = moveComp.ThrottleInput or 0
                        if type(moveComp.GetThrottleInput) == "function" then
                            throttle = moveComp:GetThrottleInput()
                        end
                        if throttle > 0.05 or throttle < -0.05 then 
                            isAccelerating = true
                        end
                    end
                    if currentVehicle.bIsPressingGas or (currentVehicle.Throttle and currentVehicle.Throttle ~= 0) then
                        isAccelerating = true
                    end

                    local currentVel = nil
                    if type(currentVehicle.GetVelocity) == "function" then
                        currentVel = currentVehicle:GetVelocity()
                    elseif type(rootComp.GetPhysicsLinearVelocity) == "function" then
                        currentVel = rootComp:GetPhysicsLinearVelocity()
                    elseif rootComp.ComponentVelocity then
                        currentVel = rootComp.ComponentVelocity
                    end

                    if currentVel then
                        local currentSpeed = math.sqrt(currentVel.X^2 + currentVel.Y^2)
                        local minSpeedToBoost = 50.0   
                        
                        -- Tốc độ thực tế đã được fix nhân lên từ thanh kéo (Max 6000.0)
                        local maxSpeed = _G.LexusState.CustomTextData.FastCarSpeed or 3000.0        
                        
                        -- Cố định gia tốc nạp mạnh để xe vọt lẹ (trả lại 1.5 gốc)
                        local accelFactor = 1.5
                        
                        local brakeFactor = 0.85       
                        
                        if currentSpeed > minSpeedToBoost then
                            local dirX = currentVel.X / currentSpeed
                            local dirY = currentVel.Y / currentSpeed
                            
                            if isAccelerating then
                                local targetSpeed = currentSpeed * accelFactor
                                if targetSpeed > maxSpeed then targetSpeed = maxSpeed end
                                local newX = dirX * targetSpeed
                                local newY = dirY * targetSpeed
                                local newZ = currentVel.Z 
                                rootComp:SetAllPhysicsLinearVelocity(FVector(newX, newY, newZ), false)
                            else
                                local targetSpeed = currentSpeed * brakeFactor
                                if targetSpeed > minSpeedToBoost then
                                    local newX = dirX * targetSpeed
                                    local newY = dirY * targetSpeed
                                    local newZ = currentVel.Z 
                                    rootComp:SetAllPhysicsLinearVelocity(FVector(newX, newY, newZ), false)
                                end
                            end
                        end
                    end
                end
            end
        end)
    end

