_G.LexusState.LoopToken = (_G.LexusState.LoopToken or 0) + 1 
local myToken = _G.LexusState.LoopToken

local function ExpiredTick()
    if not _G.LexusNotifiedPopup then
        pcall(function()
            local Msg = require("client.slua.logic.common.logic_common_msg_box")
            if Msg and Msg.Show then
                Msg.Show(1, " Mod thực hiện bởi PNHoolVN \n Buy inbox @pnhoolvn", 
                function() 
                    local Web = require("client.slua.logic.url.logic_webview_sdk")
                    if Web and Web.OpenURL then Web:OpenURL("https://t.me/pnhoolvn") end 
                end, 
                function() end, "INBOX CHỦ MOD", "ĐÓNG")
                _G.LexusNotifiedPopup = true 
            end
        end)
        
        if not _G.LexusNotifiedPopup then
            local okTicker, ticker = pcall(require, "common.time_ticker") 
            if okTicker and ticker and ticker.AddTimerOnce then 
                ticker.AddTimerOnce(2.0, ExpiredTick) 
            end
        end
    end
end

local function FastTick()
    if isExpired then
        if not _G.LexusNotifiedExpire then
            Notify("Phạm Ngọc Hiển")
            _G.LexusNotifiedExpire = true
            ExpiredTick()
        end
        return
    end

    if myToken ~= _G.LexusState.LoopToken then
        if _G.OwenRuntimeGuard and _G.OwenRuntimeGuard.Stop then
            _G.OwenRuntimeGuard.Stop("ChannMainLoop")
        end
        return
    end

    pcall(MainLoop)
    pcall(ProcessChannPendingCleanup)
end

if not isExpired then
    local started = false
    if _G.OwenRuntimeGuard and type(_G.OwenRuntimeGuard.Start) == "function" then
        started = _G.OwenRuntimeGuard.Start("ChannMainLoop", 1 / 30, FastTick, 0)
    end

    if not started then
        -- Fallback nếu RuntimeGuard không khả dụng hoặc không đăng ký được timer.
        local okTicker, ticker = pcall(require, "common.time_ticker")
        if okTicker and ticker and ticker.AddTimerOnce then
            local function FallbackTick()
                FastTick()
                if myToken == _G.LexusState.LoopToken then
                    ticker.AddTimerOnce(1 / 30, FallbackTick)
                end
            end
            ticker.AddTimerOnce(0, FallbackTick)
        end
    end
    Notify(" Phạm Ngọc Hiển ")
else
    FastTick()
end

