pcall(function()
local _autoAttachMaps = nil

local function _nameStr(n)
    if n == nil then return "" end
    if type(n) == "string" then return n end
    if type(n) == "userdata" then
        local s
        pcall(function() if n.ToString then s = n:ToString() end end)
        if s then return s end
        pcall(function() if n.ToWString then s = n:ToWString() end end)
        if s then return s end
    end
    if type(n) == "table" and n.SourceString then return n.SourceString end
    return tostring(n)
end

local WEAPON_SUFFIX = {
    { kw = {"kar98","awm","m24","amr","mosin","win94","mk14"},
      sf = {"(Snipers)","(Sniper Rifles)"} },
    { kw = {"m249","mg3","dp-28","dp28"},
      sf = {"(Machine Guns)"} },
    { kw = {"ump","p90","vector","bizon","uzi","thompson","mp5","mp5k","tommy"},
      sf = {"(SMG)","(SMG, Pistols)","(Rifles, SMG)"} },
    { kw = {"p1911","p92","p18c","deagle","r1895","r45","skorpion","g18"},
      sf = {"(Pistols)","(SMG, Pistols)"} },
    { kw = {"akm","m762","scar","famas","m16a4","aug","groza","qbz","m416","mk47","g36c","ace32","k2","m4"},
      sf = {"(AR)","(Rifles, SMG)"} },
}

local function suffixFromName(skinName)
    if type(skinName) ~= "string" or skinName == "" then return {} end
    local low = string.lower(skinName)
    for _, e in ipairs(WEAPON_SUFFIX) do
        for _, k in ipairs(e.kw) do
            if string.find(low, k, 1, true) then return e.sf end
        end
    end
    return {}
end

-- BUILD BẢN ĐỒ: skin súng -> { phụ kiện skin, phụ kiện gốc }
local function buildAutoAttachmentMaps()
    if _autoAttachMaps then return _autoAttachMaps end
    local M = {
        skinParts   = {},   -- [skinId]     = { part1, part2, ... }
        skinBases   = {},   -- [skinId]     = { base1, base2, ... }
        partToBase  = {},   -- [partSkinId] = baseId
        baseToParts = {},   -- [baseId]     = { [skinId] = partSkinId, ... }
    }
    _autoAttachMaps = M

    if not CDataTable or not CDataTable.GetTable then return M end

    -- B1: GroupID -> { PartIds } từ ItemUpgradeUnLockConfig
    local groupParts = {}
    pcall(function()
        local t = CDataTable.GetTable("ItemUpgradeUnLockConfig")
        if not t then return end
        for _, row in pairs(t) do
            local g = tonumber(row.GroupID)
            local p = tonumber(row.PartId or row.PartID)
            if g and p then
                groupParts[g] = groupParts[g] or {}
                groupParts[g][#groupParts[g]+1] = p
            end
        end
    end)

    -- B2: skinId -> GroupID từ ItemUpgradeConfig
    local skinGroup = {}
    pcall(function()
        local t = CDataTable.GetTable("ItemUpgradeConfig")
        if not t then return end
        for _, row in pairs(t) do
            local g = tonumber(row.GroupID)
            local i = tonumber(row.ItemID)
            if g and i and i >= 1000000000 then
                skinGroup[i] = g
            end
        end
    end)

    -- B3: Tên phụ kiện gốc -> { IDs } (chỉ lấy ID < 10 triệu)
    local nameToBase = {}
    local itemTbl = CDataTable.GetTable("Item")
    if itemTbl then
        for k, row in pairs(itemTbl) do
            local id = tonumber(k) or tonumber(row and row.ItemID)
            if id and id >= 1000 and id < 10000000 then
                local nm = _nameStr(row and row.ItemName)
                if nm ~= "" then
                    nameToBase[nm] = nameToBase[nm] or {}
                    nameToBase[nm][#nameToBase[nm]+1] = id
                end
            end
        end
    end

    -- Hàm phụ: chọn ID nhỏ nhất làm base chuẩn
    local function pickBase(list)
        if type(list) ~= "table" or #list == 0 then return 0 end
        local b = list[1]
        for _, v in ipairs(list) do if v < b then b = v end end
        return b
    end

    -- B4: Với mỗi skin súng, resolve từng PartId -> baseId
    for skinId, gid in pairs(skinGroup) do
        local parts = groupParts[gid]
        if parts and #parts > 0 then
            local wc = CDataTable.GetTableData and CDataTable.GetTableData("Item", skinId)
            local skinName = _nameStr(wc and wc.ItemName)
            local sufs = suffixFromName(skinName)

            local bases = {}
            for _, partId in ipairs(parts) do
                local base = 0
                local partRow = itemTbl and (itemTbl[partId] or itemTbl[tostring(partId)])
                if not partRow and CDataTable.GetTableData then
                    partRow = CDataTable.GetTableData("Item", partId)
                end

--[[                if partRow then
                    local nm = _nameStr(partRow.ItemName)
                    if nm ~= "" then
                        base = pickBase(nameToBase[nm])
                        if base == 0 then
                            for _, sf in ipairs(sufs) do
                                base = pickBase(nameToBase[nm .. " " .. sf])
                                if base ~= 0 then break end
                            end
                        end
                    end
                end
]]
if partRow then
    local nm = _nameStr(partRow.ItemName)
    if nm ~= "" then
        -- Lấy danh sách ứng viên (ưu tiên theo tên chính xác, fallback theo suffix)
        local candidates = nameToBase[nm]
        if type(candidates) ~= "table" or #candidates == 0 then
            for _, sf in ipairs(sufs) do
                local lst = nameToBase[nm .. " " .. sf]
                if type(lst) == "table" and #lst > 0 then
                    candidates = lst
                    break
                end
            end
        end

        if type(candidates) == "table" and #candidates > 0 then
            -- ✅ Ưu tiên 1: cùng prefix 6 chữ số (= cùng WeaponID)
            -- partId = 1010040476 → partPrefix = 101004 (M416)
            local partPrefix = math.floor(partId / 1000) % 1000000
            for _, cid in ipairs(candidates) do
                local cPrefix = math.floor(cid / 1000) % 1000000
                if cPrefix == partPrefix then
                    if base == 0 or cid < base then base = cid end
                end
            end

            -- ✅ Ưu tiên 2: cùng prefix 3 chữ số (= cùng loại AR/SMG/Sniper...)
            if base == 0 then
                local partGroup = math.floor(partId / 1000000)  -- 101
                for _, cid in ipairs(candidates) do
                    local cGroup = math.floor(cid / 1000000)
                    if cGroup == partGroup then
                        if base == 0 or cid < base then base = cid end
                    end
                end
            end

            -- ✅ Ưu tiên 3: fallback như cũ — chọn ID nhỏ nhất
            if base == 0 then
                base = pickBase(candidates)
            end
        end
    end
end
                bases[#bases+1] = base
                if base > 0 then
                    M.partToBase[partId] = base
                    M.baseToParts[base] = M.baseToParts[base] or {}
                    M.baseToParts[base][skinId] = partId
                end
            end
            M.skinParts[skinId] = parts
            M.skinBases[skinId] = bases
        end
    end

    local nS, nP = 0, 0
    for _ in pairs(M.skinParts) do nS = nS + 1 end
    for _ in pairs(M.partToBase) do nP = nP + 1 end
    print("[AutoAttach] Đã build bản đồ: " .. nS .. " skin súng, " .. nP .. " phụ kiện")
    return M
end

-- ÁP DỤNG SKIN PHỤ KIỆN TỰ ĐỘNG
local function autoApplyAttachments(AttachmentArray, selectedSkinId)
    if not AttachmentArray or not slua.isValid(AttachmentArray) then return false end
    selectedSkinId = tonumber(selectedSkinId) or 0
    if selectedSkinId <= 0 then return false end

    local M = buildAutoAttachmentMaps()
    local parts = M.skinParts[selectedSkinId]
    local bases = M.skinBases[selectedSkinId]

    local num = 0
    pcall(function() num = AttachmentArray:Num() end)
    if num <= 0 then return false end

    local changed = false

    -- TRƯỜNG HỢP A: Skin súng không có bộ phụ kiện -> revert về gốc
    if not parts or #parts == 0 then
        for i = 0, num - 1 do
            if i ~= 7 then
                local sd = AttachmentArray:Get(i)
                if sd then
                    local cur = 0
                    pcall(function()
                        cur = slua.IndexReference(sd, "defineID").TypeSpecificID or 0
                    end)
                    cur = tonumber(cur) or 0
                    if cur > 0 then
                        local b = M.partToBase[cur]
                        if b and b ~= cur and b > 0 then
                            pcall(function()
                                local r = slua.IndexReference(sd, "defineID")
                                r.TypeSpecificID = b
                                sd.operationType = 0
                                AttachmentArray:Set(i, sd)
                            end)
                            changed = true
                        end
                    end
                end
            end
        end
        return changed
    end

    -- TRƯỜNG HỢP B: Skin súng CÓ bộ phụ kiện
    local validSkin = {}
    for _, id in ipairs(parts) do validSkin[tonumber(id) or 0] = true end

    for i = 0, num - 1 do
        if i ~= 7 then
            local sd = AttachmentArray:Get(i)
            if sd then
                local cur = 0
                pcall(function()
                    cur = slua.IndexReference(sd, "defineID").TypeSpecificID or 0
                end)
                cur = tonumber(cur) or 0
                if cur > 0 and not validSkin[cur] then
                    -- Xác định base của phụ kiện hiện tại
                    local base = 0
                    if M.partToBase[cur] then
                        base = M.partToBase[cur]
                    elseif cur < 10000000 then
                        base = cur
                    end

                    if base and base > 0 then
                        -- Tìm skin tương ứng trong bộ skin hiện tại
                        local newId = 0
                        local bp = M.baseToParts[base]
                        if bp and bp[selectedSkinId] then
                            newId = bp[selectedSkinId]
                        else
                            for k, b in ipairs(bases) do
                                if b == base then
                                    newId = tonumber(parts[k]) or 0
                                    break
                                end
                            end
                        end
                        if newId > 0 and newId ~= cur then
                            pcall(function()
                                local r = slua.IndexReference(sd, "defineID")
                                r.TypeSpecificID = newId
                                sd.operationType = 0
                                AttachmentArray:Set(i, sd)
                            end)
                            changed = true
                        end
                    end
                end
            end
        end
    end
    return changed
end

    _G.buildAutoAttachmentMaps = buildAutoAttachmentMaps
    _G.autoApplyAttachments = autoApplyAttachments


end)



local cached_GameplayStatics = nil
local cached_PlayerTombBox = nil
local cached_ActorClass = nil
_G.NeedCheckDeadBoxTimer = 0

_G.DeadBox_TemperRequest = function(PlayerController)
    if not _G.LexusConfig.SkinDeadBox or _G.NeedCheckDeadBoxTimer <= 0 then return end
    
    local curTime = os.clock()
    if _G.LastCheckDeadBoxTime and (curTime - _G.LastCheckDeadBoxTime) < 2.0 then return end
    _G.LastCheckDeadBoxTime = curTime
    _G.NeedCheckDeadBoxTimer = _G.NeedCheckDeadBoxTimer - 1

    local PlayerCharacter = PlayerController:GetPlayerCharacterSafety()
    if not slua.isValid(PlayerCharacter) then return end
    
    if not cached_GameplayStatics then
        cached_GameplayStatics = import("GameplayStatics")
        cached_ActorClass = import("Actor")
        cached_PlayerTombBox = import("PlayerTombBox")
    end
    
    if not _G.CachedActorArray_DB then
        _G.CachedActorArray_DB = slua.Array(UEnums.EPropertyClass.Object, cached_ActorClass)
    end
    
    local UI_Util = require("client.common.ui_util")
    local GameInstance = UI_Util and UI_Util.GetGameInstance()
    if not GameInstance or not cached_GameplayStatics then return end

    -- Tối ưu: Lấy trước ID người chơi và ID súng/xe ở ngoài vòng lặp để tránh tính toán lại
    local myPlayerKey = PlayerController.PlayerKey
    local currentBoxSkinId = 0
    pcall(function()
        local curVeh = PlayerCharacter.CurrentVehicle or (type(PlayerCharacter.GetCurrentVehicle) == "function" and PlayerCharacter:GetCurrentVehicle())
        if slua.isValid(curVeh) and _G.CurrentEquipVehicleID and _G.CurrentEquipVehicleID ~= 0 then
            currentBoxSkinId = tonumber(tostring(_G.CurrentEquipVehicleID) .. "1") or 0
        else
            -- [FIX CHUẨN VIP]: Lấy ID của vũ khí đang cầm trên tay để xuất đúng hòm xác, Bỏ vòng lặp để chống Drop FPS
            local curWeapon = PlayerCharacter.GetCurrentWeapon and PlayerCharacter:GetCurrentWeapon() or PlayerCharacter.CurrentWeapon
            if slua.isValid(curWeapon) then
                local defineIDObj = curWeapon.GetItemDefineID and curWeapon:GetItemDefineID()
                local curWeaponID = (defineIDObj and slua.isValid(defineIDObj)) and defineIDObj.TypeSpecificID or 0
                
                -- Đối chiếu với kho Skin đã lưu để lấy đúng ID Skin hiện tại
                if curWeaponID > 0 and _G.AddOutfitLastAppliedSkin and _G.AddOutfitLastAppliedSkin[curWeaponID] then
                    local skinID = _G.AddOutfitLastAppliedSkin[curWeaponID]
                    if skinID and skinID > 1000000 then 
                        currentBoxSkinId = skinID 
                    end
                end
            end
        end
    end)

    if currentBoxSkinId == 0 then return end

    local deadBoxes = cached_GameplayStatics.GetAllActorsOfClass(GameInstance, cached_PlayerTombBox, _G.CachedActorArray_DB)
    if not deadBoxes then return end
    
    local count = type(deadBoxes.Num) == "function" and deadBoxes:Num() or #deadBoxes
    for i = 1, count do
        local deadBoxActor = type(deadBoxes.Get) == "function" and deadBoxes:Get(i-1) or deadBoxes[i]
        if slua.isValid(deadBoxActor) and not deadBoxActor.bIsTDSkinApplied then
            local damageCauser = deadBoxActor.DamageCauser
            -- So sánh cực nhanh bằng MyPlayerKey đã cache
            if slua.isValid(damageCauser) and damageCauser.PlayerKey == myPlayerKey then
                local DeadBoxAvatarComponent = deadBoxActor.DeadBoxAvatarComponent_BP
                if slua.isValid(DeadBoxAvatarComponent) then
                    pcall(function()
                        DeadBoxAvatarComponent:ResetItemAvatar()
                        DeadBoxAvatarComponent:PreChangeItemAvatar(currentBoxSkinId)
                        DeadBoxAvatarComponent:SyncChangeItemAvatar(currentBoxSkinId)
                    end)
                    deadBoxActor.bIsTDSkinApplied = true
                end
            end
        end
    end
end

