-- Loại ID trùng trong danh sách gốc, giữ nguyên thứ tự và chú thích.
do
    local seen, write = {}, 1
    for read = 1, #ITEMS do
        local id = tonumber(ITEMS[read])
        if id and not seen[id] then
            seen[id] = true
            ITEMS[write] = id
            write = write + 1
        end
    end
    for i = #ITEMS, write, -1 do ITEMS[i] = nil end
end

-- Dùng danh sách ITEMS tĩnh lấy nguyên từ Chann.lua.
-- Không quét ItemTable lúc chạy; tránh spike CPU khi vào sảnh/trận.
F._ChannAllItems = F._ChannAllItems or {
    ready = true, added = 0,
    queue = { entity = nil, index = 1, active = false, doneEntity = nil, doneCount = 0, generation = 0 },
    batchSize = 128, batchDelay = 0.03
}
F._ChannAllItems.ready = true
F._ChannAllItems.scan = nil


pcall(function()

-- Tự động build danh sách skin từ data game (không cần hardcode)
local ITEMSWEAPON = {}

-- Quét tất cả skin súng có trong ItemUpgradeConfig để inject
local function buildItemListFromGameData()
    local list = {}
    if not CDataTable or not CDataTable.GetTable then return list end

    pcall(function()
        local t = CDataTable.GetTable("ItemUpgradeConfig")
        if t then
            for _, row in pairs(t) do
                local i = tonumber(row.ItemID)
                if i and i >= 1000000000 then
                    list[#list + 1] = i
                end
            end
        end
    end)

    -- Thêm các phụ kiện của từng skin
    local M = buildAutoAttachmentMaps()
    for _, parts in pairs(M.skinParts) do
        for _, pid in ipairs(parts) do
            list[#list + 1] = pid
        end
    end

    -- Loại bỏ trùng lặp
    local seen, unique = {}, {}
    for _, id in ipairs(list) do
        if not seen[id] then seen[id] = true; unique[#unique + 1] = id end
    end
    return unique
end

ITEMSWEAPON = buildItemListFromGameData()
print(string.format("[AutoAttach] Tự động nạp %d item từ data game", #ITEMSWEAPON))

end)






