function F.matchApplyFaceWear(char)
    local maskRes = F.getDesiredMask()
    local glassRes = F.getDesiredGlass()
    local FootRes = F.getDesiredFoot()
    if (not maskRes or maskRes <= 0) and (not glassRes or glassRes <= 0) and (not FootRes or FootRes <= 0) then
        return true
    end
    char = char or F.getLocalChar()
    if not char then return false end
    local comp = F.getAvatarComp2(char)
    if not comp then return false end

    local ok = false
    pcall(function()
        local EAvatarSlotType = import("EAvatarSlotType")
        local ESyncOperation = import("ESyncOperation")
        local net = comp.NetAvatarData
        local applyData = net and net.SlotSyncData

        local function forceApplySlot(resID, slotID, slotNameStr)
            if not resID or resID <= 0 then return end
            
            local slotEnum = EAvatarSlotType and EAvatarSlotType[slotNameStr]
            local needRep = false
            
            -- 1. GHI ĐÈ DATA MẠNG (Chống lỗi không đồng bộ)
            if applyData and slua.isValid(applyData) then
                local found = false
                for i = 0, applyData:Num() - 1 do
                    local equipment = applyData:Get(i)
                    if equipment and equipment.SlotID == slotID then
                        found = true
                        local cur = tonumber(equipment.ItemId) or tonumber(equipment.ItemID) or 0
                        if cur ~= resID then
                            F.ensureSkinDownload(resID)
                            equipment.ItemId = resID
                            if equipment.ItemID ~= nil then equipment.ItemID = resID end
                            if equipment.FakeItemID ~= nil then equipment.FakeItemID = resID end
                            applyData:Set(i, equipment)
                            needRep = true
                        end
                        break
                    end
                end
                
                if not found then
                    F.ensureSkinDownload(resID)
                    local entry = import("AvatarSyncData")()
                    entry.SlotID = slotID
                    entry.ItemId = resID
                    entry.ItemID = resID
                    entry.FakeItemID = resID
                    entry.OperationType = ESyncOperation.PutOn
                    applyData:Add(entry)
                    needRep = true
                end
            end

            -- [LOGIC NGỦ ĐÔNG] - TỐI ƯU FPS TUYỆT ĐỐI
            _G.FaceWearStateCache = _G.FaceWearStateCache or {}
            -- Tạo ID định danh riêng biệt cho nhân vật hiện tại tránh trùng lặp
            local cacheKey = tostring(comp) .. "_" .. tostring(slotID)

            if needRep or _G.FaceWearStateCache[cacheKey] ~= resID then
                -- Lần đầu tiên ép hiển thị / Hoặc ID Skin bị thay đổi -> Chạy Full C++
                if slotEnum then
                    if comp.CancelHideAvatarBySlot then comp:CancelHideAvatarBySlot(slotEnum) end
                    if comp.SetAvatarVisibility then comp:SetAvatarVisibility(slotEnum, true, true) end
                end
                if comp.PutOnCustomEquipmentByID then
                    comp:PutOnCustomEquipmentByID(resID)
                end
                
                -- Cập nhật Cache để vòng lặp sau đi vào Ngủ Đông
                _G.FaceWearStateCache[cacheKey] = resID
                ok = true -- Bật cờ để gọi OnRep_BodySlotStateChanged (vẽ lại Mesh)
            else
                -- TRẠNG THÁI NGỦ ĐÔNG: Data đã đúng, Mesh 3D đã được render.
                -- Chỉ chạy hàm cực nhẹ CancelHide để chống Game tự ẩn khi nhặt Mũ bảo hiểm (1,2,3).
                -- BỎ QUA việc Render lại Mesh để tránh Drop FPS.
                if slotEnum and comp.CancelHideAvatarBySlot then 
                    comp:CancelHideAvatarBySlot(slotEnum) 
                end
            end
        end

        -- Gọi lệnh ép cho Mặt nạ (Mask)
        forceApplySlot(maskRes, F.CUST_SLOT.FaceEquipemtSlot, "EAvatarSlotType_FaceEquipemtSlot")
        -- Gọi lệnh ép cho Mắt kính (Glass)
        forceApplySlot(glassRes, F.CUST_SLOT.GlassEquipemtSlot, "EAvatarSlotType_GlassEquipemtSlot")
        
        -- Cập nhật hình ảnh 3D CHỈ KHI THOÁT KHỎI NGỦ ĐÔNG (Khi cần thiết)
        if ok and comp.OnRep_BodySlotStateChanged then
            comp:OnRep_BodySlotStateChanged()
        end
    end)
    return ok
end

-- SRC port: remember selected lobby head/hair and reapply only to the local pawn in-match.
F.SelectedAppearance = F.SelectedAppearance or {}
F.SelectedAppearanceApplied = F.SelectedAppearanceApplied or setmetatable({}, { __mode = "k" })

function F.rememberSelectedAppearance(kind)
    local ok, avatarData = pcall(require, "client.logic.data.AvatarData")
    if not ok or not avatarData then return false end
    local getter = (kind == 1 and avatarData.GetHeadID) or (kind == 2 and avatarData.GetHairID)
    if type(getter) ~= "function" then return false end
    local got, id = pcall(getter)
    id = got and tonumber(id) or nil
    if not id or id <= 0 then return false end
    F.SelectedAppearance[kind] = id
    local persistKey = kind == 1 and "headAppearance" or (kind == 2 and "hairAppearance")
    if persistKey then
        PERSIST[persistKey] = id
        if type(F.persistMarkDirty) == "function" then F.persistMarkDirty() end
    end
    return true
end

function F.applySelectedAppearance(char)
    if not _G.LexusConfig or (_G.LexusConfig.ModSkin ~= true and _G.LexusConfig.ModSkin ~= 1) then return true end
    if not F.isInRealMatch or not F.isInRealMatch() then return true end
    char = char or (F.getLocalChar and F.getLocalChar())
    if not char or not slua.isValid(char) or char ~= F.getLocalChar() then return false end

    -- Keep the lobby selection as the source of truth. Match-side AvatarData getters
    -- can report the pawn default and must never overwrite the saved selection.
    local selected = F.SelectedAppearance
    if not selected or not next(selected) then return true end
    local comp = F.getAvatarComp2 and F.getAvatarComp2(char)
    if not comp or not slua.isValid(comp) then return false end
    local okEnums, enums = pcall(import, "EAvatarSlotType")
    if not okEnums or not enums then return false end
    local record = F.SelectedAppearanceApplied[comp] or {}
    F.SelectedAppearanceApplied[comp] = record
    local complete = true

    local function readSlotID(slot, expectedID)
        local equipped, synced
        if type(comp.GetEquippedItemDefineID3) == "function" then
            local got, def = pcall(comp.GetEquippedItemDefineID3, comp, slot)
            if got and def then pcall(function() equipped = tonumber(def.TypeSpecificID) end) end
        end
        pcall(function()
            local net = comp.NetAvatarData
            local list = net and net.SlotSyncData
            if not list then return end
            for i = 0, list:Num() - 1 do
                local item = list:Get(i)
                if item and tonumber(item.SlotID) == tonumber(slot) then
                    synced = tonumber(item.ItemId) or tonumber(item.ItemID)
                    break
                end
            end
        end)
        if expectedID and (equipped == expectedID or synced == expectedID) then return expectedID end
        return equipped or synced
    end

    for kind, rawID in pairs(selected) do
        local id = tonumber(rawID)
        local slot = kind == 1 and enums.EAvatarSlotType_HeadEquipemtSlot
            or (kind == 2 and enums.EAvatarSlotType_HairEquipemtSlot)
        if not id or id <= 0 or not slot then
            complete = false
        else
            local current = readSlotID(slot, id)
            if current == id then
                record[kind] = id
            else
                -- Never mark an appearance as applied merely because the fallback
                -- PutOn call was invoked. Wait for the resource and verify the slot.
                if not F.isResourcesReady(id) then
                    F.requestResourceDownload(id)
                    complete = false
                else
                    local okApply, applyResult = pcall(F.matchApplyWearItem, char, id, slot,
                        kind == 1 and "SelectedHead" or "SelectedHair")
                    pcall(function()
                        if comp.SetAvatarVisibility then comp:SetAvatarVisibility(slot, true, true) end
                        if comp.OnRep_BodySlotStateChanged then comp:OnRep_BodySlotStateChanged() end
                    end)
                    local verified = readSlotID(slot, id) == id
                    if okApply and applyResult and verified then
                        record[kind] = id
                    else
                        complete = false
                    end
                end
            end
        end
    end
    return complete
end

function F.installLocalAppearance()
    local ok, appearance = pcall(require, "client.slua.logic.wardrobe.logic_wardrobe_appearance")
    if not ok or not appearance or type(appearance.GenerateAvatarData) ~= "function"
        or type(appearance.PutAvatar) ~= "function" then return false end
    if appearance._ChanLocalAppearanceInstalled then return true end
    appearance._ChanLocalAppearanceInstalled = true
    local generate, put = appearance.GenerateAvatarData, appearance.PutAvatar
    local function enabled()
        return _G.LexusConfig and (_G.LexusConfig.ModSkin == true or _G.LexusConfig.ModSkin == 1)
    end
    local function supported(kind) return kind == 1 or kind == 2 end
    local function compatible(data)
        local good, ad = pcall(require, "client.logic.data.AvatarData")
        if not good or not ad then return false end
        local gender = tonumber(data and data.Gender)
        local got, currentGender = pcall(ad.GetGameGender)
        return not gender or gender == 0 or (got and gender == tonumber(currentGender))
    end
    appearance.GenerateAvatarData = function(self, ...)
        local okData, data = pcall(generate, self, ...)
        if not okData then F.LastAppearanceError = tostring(data); return nil end
        if enabled() and data and supported(tonumber(data.AvatarType)) and compatible(data) then
            data.Owned = true
            data.RemainTime = 0
        end
        return data
    end
    appearance.PutAvatar = function(self, id, kind, bPutOn)
        kind = tonumber(kind)
        if not enabled() or not supported(kind) then
            local okPut, result = pcall(put, self, id, kind, bPutOn)
            if not okPut then F.LastAppearanceError = tostring(result); return false end
            return result
        end
        local good, data = pcall(self.GetAvatarDataById, self, id)
        if not good or bPutOn == false or not data or tonumber(data.AvatarType) ~= kind or not compatible(data) then
            return false
        end
        local value = kind == 1 and tonumber(data.ItemId) or tonumber(data.Hair)
        if not value or value <= 0 then return false end
        local managerOK, manager = pcall(require, "client.logic.avatar.logic_team_avatar_manager")
        if not managerOK or not manager or not manager.GetMainAvatar then return false end
        local gotMain, mainAvatar = pcall(manager.GetMainAvatar)
        if not gotMain or not mainAvatar then return false end
        local okPut, errPut = pcall(function()
            self.AppearanceMap = self.AppearanceMap or self:GetUserDataMap()
            self.TryAvatarMap = self.TryAvatarMap or {}
            self:RestoreToOrigin()
            self:ModifyAvatar(kind, data, false)
        end)
        if not okPut then F.LastAppearanceError = tostring(errPut); return false end
        -- SRC captures the final selected ID from AvatarData after ModifyAvatar.
        -- Keep the item payload as a fallback if the game getter is not updated yet.
        F.SelectedAppearance[kind] = value
        pcall(F.rememberSelectedAppearance, kind)
        local selectedID = tonumber(F.SelectedAppearance[kind]) or value
        F.SelectedAppearance[kind] = selectedID
        local persistKey = kind == 1 and "headAppearance" or "hairAppearance"
        PERSIST[persistKey] = selectedID
        if type(F.persistMarkDirty) == "function" then F.persistMarkDirty() end
        return true
    end
    return true
end

pcall(F.installLocalAppearance)

function F.getDesiredWear(configKey, cacheResKey, globalKey, syncFn)
    local fixed = MATCH_CONFIG[configKey] and tonumber(MATCH_CONFIG[configKey])
    if fixed and fixed > 0 then return fixed end
    local persistKey = cacheResKey and cacheResKey:gsub("Res$", "")
    if persistKey and PERSIST.configSlots then
        local pr = tonumber(PERSIST.configSlots[persistKey])
        if pr and pr > 0 then return pr end
    end
    if syncFn then syncFn() end
    local v = F.cache()[cacheResKey]
    if v and tonumber(v) > 0 then return tonumber(v) end
    return tonumber(_G[globalKey]) or nil
end

local EQUIP_APPLY = { lastBagWrite = 0, lastHelmetWrite = 0 }

function F.levelSkinID(baseSkin, level)
    level = tonumber(level) or 1
    if level < 1 then level = 1 end
    local mapped = 0
    pcall(function()
        local t = CDataTable.GetTableData("BackpackMapping", baseSkin)
        if t then
            if level <= 1 then mapped = tonumber(t.SkinItemIDLv1) or 0
            elseif level == 2 then mapped = tonumber(t.SkinItemIDLv2) or 0
            else mapped = tonumber(t.SkinItemIDLv3) or 0 end
        end
    end)
    if mapped > 0 then return mapped end
    return baseSkin + (level - 1) * 1000
end

function F.applyEquipSkinToComp(comp, bagRes, helmetRes)
    local applied, found = false, false
    pcall(function()
        local EAvatarSlotType = import("EAvatarSlotType")
        local BackpackUtils = import("BackpackUtils")
        local function doSlot(slotEnum, res, levelFn, lastKey)
            res = tonumber(res) or 0
            if res <= 0 or not slotEnum then return end
            local sync = comp.GetSlotSyncData and comp:GetSlotSyncData(slotEnum)
            if not sync then return end
            local cur = tonumber(sync.ItemID) or 0
            local addID = tonumber(sync.AdditionalItemID) or 0
            if cur <= 0 and addID <= 0 then return end
            found = true
            local lvl = 1
            pcall(function()
                if levelFn then lvl = levelFn(addID > 0 and addID or cur) or 1 end
            end)
            if lvl < 1 then lvl = 1 end
            local target = F.levelSkinID(res, lvl)
            if target > 0 and cur ~= target then
                sync.ItemID = target
                comp:ChangeSlotSyncData(sync)
                applied = true
                EQUIP_APPLY[lastKey] = target
            end
        end
        doSlot(EAvatarSlotType.EAvatarSlotType_BackpackEquipemtSlot, bagRes,
               BackpackUtils.GetEquipmentBagLevel, "lastBagWrite")
        doSlot(EAvatarSlotType.EAvatarSlotType_HelmetEquipemtSlot, helmetRes,
               BackpackUtils.GetEquipmentHelmetLevel, "lastHelmetWrite")
    end)
    return applied, found
end

function F.matchApplyEquipmentSkin(char, bagRes, helmetRes)
    bagRes = tonumber(bagRes) or 0
    helmetRes = tonumber(helmetRes) or 0
    if bagRes <= 0 and helmetRes <= 0 then return true end
    local comp = char.CharacterAvatarComp2_BP
    if not slua.isValid(comp) then return false end

    local applied, found = F.applyEquipSkinToComp(comp, bagRes, helmetRes)

    if applied then
        pcall(function()
            if comp.OnRep_BodySlotStateChanged then comp:OnRep_BodySlotStateChanged() end
        end)
        return true
    end
    return found
end

function F.hookEquipmentRectify()
    _G.AddOutfitEquipRectifyFn = function(self)
        pcall(function()
            if self.IsLobbyActor and self:IsLobbyActor() then return end
            if not (self.IsSelf and self:IsSelf()) then return end
            local bagRes = F.getDesiredWear("bagRes", "bagRes", "AddOutfitLastLobbyBagRes", F.syncBodyCacheFromLobby)
            local helmetRes = F.getDesiredWear("helmetRes", "helmetRes", "AddOutfitLastLobbyHelmetRes", F.syncBodyCacheFromLobby)
            if (tonumber(bagRes) or 0) <= 0 and (tonumber(helmetRes) or 0) <= 0 then return end
            F.applyEquipSkinToComp(self, bagRes, helmetRes)
        end)
    end
    pcall(function()
        local MCAC = require("GameLua.Mod.TPlan.Component.MetroCharacterAvatarComponent")
        if MCAC._AddOutfitRectifyHooked then return end
        MCAC._AddOutfitRectifyHooked = true
        local o = MCAC.ProcessClientAvatarRectify
        MCAC.ProcessClientAvatarRectify = function(self)
            o(self)
            if _G.AddOutfitEquipRectifyFn then _G.AddOutfitEquipRectifyFn(self) end
        end
    end)
end

function F.applyAirborneSlots(char, forceInAir)
    local comp = F.getAvatarComp2(char)
    if not comp or not slua.isValid(comp) then return false end
