-- Gloves: SRC-style verified application with bounded native recovery.
-- Keep this path separate from the generic outfit batch because the hand slot can
-- appear later than the other avatar slots during pawn initialization.
function F.gloveTransitionActive(char)
    if not char then return false end
    local now = (_G.RealNow and _G.RealNow()) or os.clock()
    local state = F.GloveADSState
    if not state or state.Char ~= char then
        state = { Char = char, Until = 0 }
        F.GloveADSState = state
    end
    local probe = _G.OwenProbe
    if probe and type(probe.ADS) == "function" then
        local ok, ads = pcall(probe.ADS, char)
        if ok and ads then
            state.Until = now + 0.5
            return true
        end
    end
    return now < (state.Until or 0)
end

function F.ensureSelectedGloveSlot(comp, res, slot)
    if F.skinOff() or not F.isInRealMatch() or (tonumber(res) or 0) <= 0 then return false end
    local ok, result = pcall(function()
        local net = comp and comp.NetAvatarData
        local data = net and net.SlotSyncData
        if not data or not slua.isValid(data) then return false end
        for i = 0, data:Num() - 1 do
            local row = data:Get(i)
            if row and tonumber(row.SlotID) == tonumber(slot) then return true end
        end
        local row = import("AvatarSyncData")()
        row.SlotID, row.ItemId, row.ItemID, row.AdditionalItemID = slot, res, res, res
        row.OperationType = import("ESyncOperation").PutOn
        data:Add(row)
        if comp.OnRep_BodySlotStateChanged then comp:OnRep_BodySlotStateChanged() end
        return true
    end)
    return ok and result == true
end

function F.rebuildSelectedGloves(comp, res, observed)
    if F.skinOff() or not F.isInRealMatch() or not comp or not slua.isValid(comp)
        or F.gloveTransitionActive(F.getLocalChar())
        or type(comp.PutOnCustomEquipmentByID) ~= "function" then return false end
    F.GloveNativeRecovery = F.GloveNativeRecovery or setmetatable({}, { __mode = "k" })
    local row = F.GloveNativeRecovery[comp]
    if not row or row.Res ~= res then
        row = { Res = res, Attempts = 0, Next = 0 }
        F.GloveNativeRecovery[comp] = row
    end
    local now = (_G.RealNow and _G.RealNow()) or os.clock()
    if now < (row.Next or 0) or (row.Attempts or 0) >= 3 then return false end
    row.Attempts = (row.Attempts or 0) + 1
    row.Next = now + 1
    local ok = pcall(comp.PutOnCustomEquipmentByID, comp, res)
    return ok
end

function F.matchApplyGloves(char)
    if F.skinOff() or not F.isInRealMatch() or not char or not slua.isValid(char)
        or char ~= F.getLocalChar() then return false end
    if F.gloveTransitionActive(char) then return false end

    local res = tonumber(F.getDesiredWear("glovesRes", "glovesRes", "AddOutfitLastLobbyGlovesRes", F.syncBodyCacheFromLobby)) or 0
    if res <= 0 then return true end
    if not F.isResourcesReady(res) then
        F.requestResourceDownload(res)
        return false
    end

    local comp = F.getAvatarComp2(char)
    if not comp or not slua.isValid(comp) then return false end
    local slot = F.CUST_SLOT.HandEffectEquipemtSlot
    pcall(function()
        local enum = import("EAvatarSlotType")
        slot = enum.EAvatarSlotType_HandEffectEquipemtSlot or slot
    end)

    F.GloveNativeRecovery = F.GloveNativeRecovery or setmetatable({}, { __mode = "k" })
    local row = F.GloveNativeRecovery[comp]
    if not row or row.Res ~= res then
        row = { Res = res, Attempts = 0, Next = 0 }
        F.GloveNativeRecovery[comp] = row
    end

    local function equipped()
        local id
        pcall(function()
            if comp.GetEquippedItemDefineID3 then
                local item = comp:GetEquippedItemDefineID3(slot)
                id = item and tonumber(item.TypeSpecificID)
            end
            if not id or id <= 0 then
                local sync = comp.GetSlotSyncData and comp:GetSlotSyncData(slot)
                id = sync and tonumber(sync.ItemID or sync.ItemId)
            end
            if not id or id <= 0 then
                local data = comp.NetAvatarData and comp.NetAvatarData.SlotSyncData
                if data and slua.isValid(data) then
                    for i = 0, data:Num() - 1 do
                        local item = data:Get(i)
                        if item and tonumber(item.SlotID) == tonumber(slot) then
                            id = tonumber(item.ItemID or item.ItemId)
                            break
                        end
                    end
                end
            end
        end)
        return id
    end

    local observed = equipped()
    if observed ~= res then
        row.Confirmed = nil
        F.ensureSelectedGloveSlot(comp, res, slot)
        pcall(F.setMakeSkin, comp, res, slot, { allowPutOn = false })
        if equipped() ~= res then F.rebuildSelectedGloves(comp, res, observed) end
        if equipped() ~= res then return false end
    end

    if type(comp.GetMeshCompBySlot) == "function" then
        local ok, mesh = pcall(comp.GetMeshCompBySlot, comp, slot)
        if not ok or not mesh or not slua.isValid(mesh) then
            if row.Confirmed then return true end
            local now = (_G.RealNow and _G.RealNow()) or os.clock()
            row.MissingSince = row.MissingSince or now
            if now - row.MissingSince < 1.5 then return false end
            F.rebuildSelectedGloves(comp, res, equipped())
            ok, mesh = pcall(comp.GetMeshCompBySlot, comp, slot)
            if not ok or not mesh or not slua.isValid(mesh) then return false end
        end
        row.MissingSince = nil
    end

    row.Confirmed = true
    if F.GloveLOD then pcall(F.GloveLOD.ApplyAvatar, comp, nil, char) end
    return true
end

-- SRC parity: persistent glove maintenance, independently throttled to 1.5s.
-- The match bootstrap timer is intentionally finite; this watcher keeps gloves
-- synchronized if the avatar/hand slot finishes loading after that timer ends.
function F.maintainSelectedGloves()
    if F.skinOff() then
        F.GloveRecovery = nil
        F.GloveNativeRecovery = nil
        F.GloveADSState = nil
        return
    end

    local now = (_G.RealNow and _G.RealNow()) or os.clock()
    if now < (F.GlovePollNext or 0) then return end
    F.GlovePollNext = now + 1.5

    local inMatch = F.isInRealMatch() == true
    if not inMatch then
        F.GloveNativeRecovery = nil
        F.GloveADSState = nil
    end

    local lobby = _G.OwenNeonLobbySceneAllowed
        and _G.OwenNeonLobbySceneAllowed() == true
    if not inMatch and not lobby then return end

    local res = tonumber(F.getDesiredWear(
        "glovesRes", "glovesRes", "AddOutfitLastLobbyGlovesRes", F.syncBodyCacheFromLobby
    )) or 0
    if res <= 0 then
        F.GloveRecovery = nil
        return
    end

    local char = F.getLocalChar()
    local comp = (inMatch and char) and F.getAvatarComp2(char) or nil
    local key = tostring(res) .. ":" .. tostring(lobby)
    local row = F.GloveRecovery
    if not row or row.Char ~= char or row.Comp ~= comp or row.Key ~= key then
        row = { Char = char, Comp = comp, Key = key, Next = 0, Attempts = 0 }
        F.GloveRecovery = row
    end
    if now < (row.Next or 0) then return end
    row.Next = now + 1

    if not F.isResourcesReady(res) then
        row.WaitingForResource = true
        if (row.DownloadAttempts or 0) < 10 then
            row.DownloadAttempts = (row.DownloadAttempts or 0) + 1
            pcall(F.requestResourceDownload, res)
        end
        return
    end
    if row.WaitingForResource then
        row.WaitingForResource = nil
        row.Attempts = 0
        row.DownloadAttempts = 0
    end

    if lobby then
        local ins = R.resToIns[res]
        if not ins then return end
        local worn = F.findWornInsBySubType(GLOVES_SUB)
        if tonumber(worn) ~= tonumber(ins) or row.Applied ~= res then
            if row.Attempts >= 10 then return end
            row.Attempts = row.Attempts + 1
            local ok, applied = pcall(F.putOnGloves, ins)
            if ok and applied == true then row.Applied = res end
        end
    elseif inMatch and char and slua.isValid(char) then
        if F.gloveTransitionActive(char) or row.Attempts >= 10 then return end
        local ok, applied = pcall(F.matchApplyGloves, char)
        if ok and applied == true then
            row.Attempts = 0
            row.Applied = res
        else
            row.Attempts = row.Attempts + 1
        end
    end
end

