function F.afterInjectApply(firstTime)
    F.mergeInjectedArmorySkins()
    F.cleanArmoryPollution()
    if firstTime then
        F.refreshWardrobeOnce()
        F.persistApplyLoaded()
        F.hookGarageTheme()
        F.syncLobbyVehicleResFromIns()
        F.reapplyVehicleSlotsFromConfig(true)
        F.reapplyHallThemeFromConfig(true)
        F.reapplyWeaponsFromConfig()
        F.scheduleLobbyReapplyOnce()
    else
        F.reapplyWeaponsFromConfig()
    end
end

-- add

-- ==============================================================================
    -- ================= HỆ THỐNG MOD EMOTE VIP (SẢNH + TRONG TRẬN) =================
    -- ==============================================================================
  do
    local E = {
      Hooks = {},
      IDs = nil
    }
    _G.ChannEmoteSlots = E
    function E.Enabled()
      local cfg = _G.LexusConfig
      return type(cfg) == 'table' and (cfg.ModEmote == true or cfg.ModEmote == 1)
    end
    function E.GetIDs()
      if E.IDs then
        return E.IDs
      end
      local ids, seen = {}, {}
      local function add(id)
        id = tonumber(id);
        if id and id > 0 and not seen[id] then
          seen[id] = true;
          ids[ # ids + 1] = id
        end
      end
      for _, id in ipairs(_G.ChannExtraEmotes or {}) do
        add(id)
      end
      local ok, items = pcall(function()
        return CDataTable.GetTable('Item')
      end)
      if ok and type(items) == 'table' then
        for key, row in pairs(items) do
          if type(row) == 'table' and tonumber(row.ItemType) == 22 and (tonumber(row.ItemSubType) == 2201 or tonumber(row.ItemSubType) == 2206) and (tonumber(row.BPID) or 0) > 0 then
            add(row.ItemID or row.ID or key)
          end
        end
      end
      table.sort(ids)
      if ok and type(items) == 'table' then
        E.IDs = ids
      end
      return ids
    end
  end
  do
    local E = _G.ChannEmoteSlots
    E.Records = {};
    E.Hooks = {};
    E.VirtualBase = 8000000000000
    local unpack = unpack or table.unpack
    local function pack( ...)
      return { n = select('#', ...), ... }
    end
    local function load(path)
      local ok, m = pcall(require, path);
      return ok and m or nil
    end
    function E.Record(ins)
      ins = tonumber(ins);
      if not ins then
        return nil
      end
      if E.Records[ins] then
        return E.Records[ins]
      end
      local id = ins - E.VirtualBase
      if id <= 0 or id ~= math.floor(id) or id > 1000000000 then
        return nil
      end
      local ok, cfg = pcall(function()
        return CDataTable.GetTableData('Item', id)
      end)
      if ok and cfg and tonumber(cfg.ItemType) == 22 and (tonumber(cfg.ItemSubType) == 2201 or tonumber(cfg.ItemSubType) == 2206) and (tonumber(cfg.BPID) or 0) > 0 then
        E.Records[ins] = { insID = ins, resID = id, count = 1, lock_cnt = 0, expireTS = 0, validHours = 0,
        itemQuality = cfg.ItemQuality or cfg.Quality or 0, isNew = false }
        return E.Records[ins]
      end
    end
    function E.Data(ins)
      return E.Wardrobe and E.Wardrobe:GetValidHallDepotItemDataByInsID(ins)
    end
    function E.Catalog(base, tab)
      if not E.Enabled() then
        return base
      end
      local out, seen = {}, {}
      for key, row in pairs(base or {}) do
        out[key] = row;
        if type(row) == 'table' and row.resID then
          seen[tonumber(row.resID)] = true
        end
      end
      for _, id in ipairs(E.GetIDs()) do
        local cfg = CDataTable.GetTableData('Item', id)
        if cfg and (tonumber(cfg.BPID) or 0) > 0 then
          local ins = E.VirtualBase + id
          local row = E.Records[ins]
          if not row then
            row = { insID = ins, resID = id, count = 1, lock_cnt = 0, expireTS = 0, validHours = 0, itemQuality = cfg.ItemQuality or cfg.Quality or 0,
            isNew = false }
            E.Records[ins] = row
          end
          if not seen[id] then
            local entry = {};
            for k, v in pairs(row) do
              entry[k] = v
            end
            entry.mainTabType = tab.subTabConfig.pageId;
            entry.subTabType = tab.subTabConfig.subTabId
            out[ins] = entry
          end
        end
      end
      return out
    end
    function E.Decode(text)
      if type(text) ~= 'string' or text:sub(1, 3) ~= 'v1;' then
        return nil
      end
      local slots, seen = {}, {}
      for rawIndex, kind, rawValue in text:gmatch('(%d+):([ri])(%d+);') do
        local index, value = tonumber(rawIndex), tonumber(rawValue)
        if index >= 1 and index <= 12 and value > 0 then
          local ins = kind == 'r' and E.VirtualBase + value or value
          if not seen[ins] and E.Data(ins) then
            slots[index] = ins;
            seen[ins] = true
          end
        end
      end
      return slots
    end
    function E.Slots(kind, native)
      local key = kind == 'wheel' and 'EmoteWheelSlots' or 'EmoteQuickSlots'
      local slots = E.Decode(_G.LexusConfig[key])
      if slots then
        return slots
      end
      slots = {};
      for rawIndex, rawIns in pairs(native or {}) do
        local index, ins = tonumber(rawIndex), tonumber(rawIns)
        if index and index >= 1 and index <= 12 and ins and ins > 0 then
          slots[index] = ins
        end
      end
      return slots
    end
    function E.Save(kind, slots)
      local parts = { 'v1;' }
      for index = 1, 12 do
        local ins = tonumber(slots[index]);
        local data = ins and E.Data(ins)
        if data then
          parts[ # parts + 1] = index .. ':' .. (E.Record(ins) and 'r' .. data.resID or 'i' .. string.format('%.0f', ins)) .. ';'
        end
      end
      _G.LexusConfig[kind == 'wheel' and 'EmoteWheelSlots' or 'EmoteQuickSlots'] = table.concat(parts)
      if kind == 'wheel' then
        local motions = {}
        for i = 1, 12 do
          local data = slots[i] and E.Data(slots[i])
          local cfg = data and CDataTable.GetTableData('Item', data.resID)
          if cfg and tonumber(cfg.ItemType) == 22 then
            motions[i] = slots[i]
          end
        end
        E.Save('quick', motions)
      end
      if _G.SaveModSettings then
        pcall(_G.SaveModSettings)
      end
    end
    function E.Notify(kind)
      local t = kind == 'wheel' and _G.EVENTTYPE_WARDROBE or _G.EVENTTYPE_MOTION
      local id = kind == 'wheel' and _G.EVENTID_UPDATE_PLACING_SLOT_LIST or _G.EVENTID_MOTION_UPDATE_SLOT_LIST
      if EventSystem and t and id then
        EventSystem:postEvent(t, id)
      end
    end
    function E.WithMotion(fn, ...)
      if not E.Enabled() or not DataMgr then
        return fn( ...)
      end
      local old = DataMgr.MotionSlotList
      local slots = E.Slots('quick', old);
      local list = {}
      for i = 1, math.min(12, tonumber(DataMgr.MotionSlotMax) or 12) do
        list[i] = slots[i] or 0
      end
      DataMgr.MotionSlotList = list
      local depth = E.MotionDepth or 0;
      E.MotionDepth = depth + 1
      local result = pack(pcall(fn, ...));
      DataMgr.MotionSlotList = old;
      E.MotionDepth = depth
      if not result[1] then
        error(result[2], 0)
      end
      return unpack(result, 2, result.n)
    end
    function E.Merge(base, lobby)
      if not E.Enabled() or base == nil or lobby or not _G.LexusConfig.EmoteQuickSlots then
        return base
      end
      local out, seen = {}, {}
      local bound = {}
      for _, row in ipairs(base or {}) do
        local id = row.DefineID and row.DefineID.TypeSpecificID
        if id and (row.bWeaponShow or row.bClothEmote) then
          bound[id] = row
        end
      end
      local slots = E.Slots('quick', DataMgr and DataMgr.MotionSlotList)
      for i = 1, 12 do
        local data = slots[i] and E.Data(slots[i])
        if data and not seen[data.resID] then
          out[ # out + 1] = bound[data.resID] or {
            DefineID = { TypeSpecificID = data.resID },
            Name = tostring(data.resID),
            Count = 1
          };
          seen[data.resID] = true
        end
      end
      local catalog = {};
      for _, id in ipairs(E.GetIDs()) do
        catalog[id] = true
      end
      for _, row in ipairs(base or {}) do
        local id = row.DefineID and row.DefineID.TypeSpecificID
        if id and (row.bWeaponShow or row.bClothEmote or not catalog[id]) and not seen[id] then
          out[ # out + 1] = row;
          seen[id] = true
        end
      end
      return out
    end
    function E.Hook(module, key, build)
      if type(module) ~= 'table' then
        return
      end
      local impl = rawget(module, '__inner_impl') or module
      local marks = E.Hooks[module];
      if not marks then
        marks = {};
        E.Hooks[module] = marks
      end
      if marks[key] then
        return
      end
      local original = module[key];
      if type(original) ~= 'function' then
        return
      end
      local fn = build(original)
      rawset(impl, key, fn);
      if impl ~= module then
        rawset(module, key, fn)
      end
      marks[key] = true
    end
    function E.Install()
      if not E.Enabled() then
        return
      end
      local wd = load('client.slua.logic.wardrobe.wardrobe_data');
      E.Wardrobe = wd
      for _, key in ipairs( { 'GetHallDepotItemDataByInsID', 'GetValidHallDepotItemDataByInsID' }) do
        E.Hook(wd, key, function(original)
          return function(self, ins, ...)
            if E.Enabled() and E.Record(ins) then
              return E.Record(ins)
            end
            return original(self, ins, ...)
          end
        end)
      end
      E.Hook(DataMgr, 'GetMotionItemDatas', function(original)
        return function( ...)
          if not E.Enabled() or (E.MotionDepth or 0) == 0 then
            return original( ...)
          end
          local out = {}
          for i, ins in ipairs(DataMgr.MotionSlotList or {}) do
            out[i] = E.Data(ins) or {}
          end
          return out
        end
      end)
      local action = load('client.slua.umg.Wardrobe.subtab_action')
      E.Hook(action, 'GetArrayHallDepotItemInfo', function(original)
        return function(self, ...)
          return E.Catalog(original(self, ...), self)
        end
      end)
      for _, key in ipairs( { 'RefreshActionSlot', 'CheckActionIsUsing' }) do
        E.Hook(action, key, function(original)
          return function( ...)
            return E.WithMotion(original, ...)
          end
        end)
      end
      local logic = load('client.slua.logic.wardrobe.logic_wardrobe_new')
      E.Hook(logic, 'EquipMotion', function(original)
        return function(self, ins, index, ...)
          if not E.Enabled() then
            return original(self, ins, index, ...)
          end
          ins, index = tonumber(ins), tonumber(index)
          if not ins or not index or index < 1 or index > math.min(12, tonumber(DataMgr.MotionSlotMax) or 12) or not E.Data(ins) then
            return
          end
          local slots = E.Slots('quick', DataMgr.MotionSlotList)
          local previous;
          for i, v in pairs(slots) do
            if v == ins then
              previous = i;
              break
            end
          end
          if previous then
            slots[previous] = slots[index]
          end
          slots[index] = ins;
          E.Save('quick', slots);
          E.Notify('quick')
        end
      end)
      E.Hook(logic, 'unequip_motion_req', function(original)
        return function(self, ins, index, ...)
          if not E.Enabled() then
            return original(self, ins, index, ...)
          end
          local slots = E.Slots('quick', DataMgr.MotionSlotList);
          index = tonumber(index)
          if index and slots[index] == tonumber(ins) then
            slots[index] = nil;
            E.Save('quick', slots);
            E.Notify('quick')
          end
        end
      end)
      E.Hook(load('client.slua.umg.Souvenirs.Expression_Util'), 'GetMotionDataList', function(original)
        return function( ...)
          return E.WithMotion(original, ...)
        end
      end)
      E.Hook(load('client.slua.umg.lobby.ExpressionPopUIBP'), 'UpdateUI', function(original)
        return function( ...)
          return E.WithMotion(original, ...)
        end
      end)
      E.Hook(load('GameLua.Mod.BaseMod.Client.Emote.QuickExpressionUtils'), 'GetShowExpressionList', function(original)
        return function( ...)
          if not E.Enabled() then
            return original( ...)
          end
          local result = pack(original( ...));
          result[1] = E.Merge(result[1], false)
          return unpack(result, 1, result.n)
        end
      end)
      local function hookWheel(m)
        E.Hook(m, 'CopyWheelData', function(original)
          return function(self, ...)
            if not E.Enabled() then
              return original(self, ...)
            end
            return E.Slots('wheel', self.wheelData)
          end
        end)
        for _, key in ipairs( { 'GetSlotItemData', 'GetAllSlotData', 'GetSlotEquipData', 'GetSlotEquipCount',
        'IsEquippedInWheel', 'FindSlotByInsId' }) do
          E.Hook(m, key, function(original)
            return function(self, ...)
              if not E.Enabled() then
                return original(self, ...)
              end
              local old = self.wheelData;
              self.wheelData = E.Slots('wheel', old)
              local result = pack(pcall(original, self, ...));
              self.wheelData = old
              if not result[1] then
                error(result[2], 0)
              end
              return unpack(result, 2, result.n)
            end
          end)
        end
        E.Hook(m, 'SendWheelConfig', function(original)
          return function(self, slots, ...)
            if not E.Enabled() then
              return original(self, slots, ...)
            end
            E.Save('wheel', slots);
            E.Notify('wheel')
          end
        end)
      end
      hookWheel(load('client.slua.logic.wardrobe.logic_wardrobe_wheel'))
      local manager = load('client.module_framework.ModuleManager')
      if manager and manager.LobbyModuleConfig and manager.GetModule then
        local ok, instance = pcall(manager.GetModule, manager.LobbyModuleConfig.logic_wardrobe_wheel)
        if ok then
          hookWheel(instance)
        end
      end
      E.Hook(load('client.slua_ui_framework.manager'), 'ShowUI', function(original)
        return function( ...)
          if E.Enabled() and not E.Installing then
            E.Installing = true;
            pcall(E.Install);
            E.Installing = false
          end
          return original( ...)
        end
      end)
          end
    function E.OnChanged()
      if E.Enabled() then
        E.Install()
      end
            E.Notify('quick');
      E.Notify('wheel')
    end
    pcall(E.Install)
  end
