        F.afterInjectApply(firstLobby)
        return
    end
    local tries = 0
    local function retry()
        tries = tries + 1
        if F.injectAll() then
            local ft = not _G.AddOutfitLobbyInitDone
            if ft then _G.AddOutfitLobbyInitDone = true end
            F.afterInjectApply(ft)
            return
        end
        if tries < INJECT_RETRY_MAX then F.later(INJECT_RETRY_SEC, retry) end
    end
    F.later(INJECT_RETRY_SEC, retry)
end


pcall(function()
-- ============================================================
-- BẮT ĐẦU: GRENADE V1 MODULE
-- ============================================================
-- ============================================================
-- GRENADE V1 + FX — full merged module
--   GrenadeV1 : skin inject (skin cache / avatar list / hooks)
--   GrenadeFX : particle + voice (port L98_2/L112_2/L117_2/L120_2/L125_2)
-- Contract: F / R / PERSIST từ injector host
-- ============================================================

-- ============================================================
-- MODULE 1 — GRENADE V1 (skin inject)
-- ============================================================
local GrenadeV1 = (function()
    local M = {}

    local GRENADE_SUB = { [612] = true, [613] = true, [614] = true, [615] = true }
    local GRENADE_BASE_BY_SUB = {
        [612] = 602004, [613] = 602002, [614] = 602001, [615] = 602003,
    }
    local GRENADE_ITEMID_TO_SUB = {
        [602001] = 614, [602002] = 613, [602003] = 615, [602004] = 612,
    }
    local THROW_SUB = {
        [612] = "shoulei", [613] = "smoke", [614] = "stun", [615] = "burn",
    }
    local THROW_AVATAR_KEY = {
        shoulei = "GrenadeAvatarShoulei", smoke = "GrenadeAvatarSmoke",
        stun    = "GrenadeAvatarStun",    burn  = "GrenadeAvatarBurn",
    }

    -- FX state (fallback path — active only when GrenadeFX not installed)
    local _fxVoiceCache = {}
    local _fxFired      = setmetatable({}, { __mode = "k" })

    function M.Bind(F, R, PERSIST)
        F.GRENADE_SUB           = GRENADE_SUB
        F.GRENADE_BASE_BY_SUB   = GRENADE_BASE_BY_SUB
        F.GRENADE_ITEMID_TO_SUB = GRENADE_ITEMID_TO_SUB
        F.THROW_SUB             = THROW_SUB
        F.THROW_AVATAR_KEY      = THROW_AVATAR_KEY

        -- ── helpers ──────────────────────────────────────────
        function F.isGrenadeSkinRes(resID)
            resID = tonumber(resID)
            if not resID then return false end
            return GRENADE_SUB[F.subType(F.cfg(resID))] == true
        end

        function F.grenadeBaseFromSkin(resID)
            resID = tonumber(resID)
            if not resID then return nil end
            local st = F.subType(F.cfg(resID))
            return st and GRENADE_BASE_BY_SUB[st] or nil
        end

        local function resolveSkinByItemID(itemID)
            local cch = F.cache()
            if not cch.throwObjects then return nil end
            local sub = itemID and GRENADE_ITEMID_TO_SUB[tonumber(itemID)]
            local info = sub and cch.throwObjects[sub]
            return (info and info.resID and info.resID > 0) and info or nil
        end

        local function resolveSkinFromProjectile(self)
            local itemID
            pcall(function()
                if self.GetItemTypeID then
                    itemID = tonumber(self:GetItemTypeID())
                elseif self.ItemDefineID then
                    itemID = tonumber(self.ItemDefineID.TypeSpecificID)
                end
            end)
            return resolveSkinByItemID(itemID)
        end

        -- ── cache ─────────────────────────────────────────────
        function F.saveGrenadeToCache(base, resID, insID)
            base, resID, insID = tonumber(base), tonumber(resID), tonumber(insID)
            if not base or not resID then return end
            -- All grenade consumers index throwObjects by item subtype (612..615),
            -- not by throwable weapon ID (602001..602004).
            local sub = tonumber(F.subType(F.cfg(resID)))
            if not sub or not GRENADE_SUB[sub] then return end
            local cch = F.cache()
            cch.throwObjects = cch.throwObjects or {}
            cch.throwObjects[sub] = { resID = resID, insID = insID or 0 }
            PERSIST.configThrowObjects = PERSIST.configThrowObjects or {}
            PERSIST.configThrowObjects[sub] = cch.throwObjects[sub]
            _G._savedThrowObjects = _G._savedThrowObjects or {}
            _G._savedThrowObjects[sub] = cch.throwObjects[sub]
            if F.persistMarkDirty then pcall(F.persistMarkDirty) end
        end

        function F.syncThrowObjectCacheFromLobby()
            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
                if not bag or not bag.throw_object_list then return end
                local cch = F.cache()
                cch.throwObjects = cch.throwObjects or {}
                for subType, insID in pairs(bag.throw_object_list) do
                    insID, subType = tonumber(insID), tonumber(subType)
                    if insID and insID > 0 and GRENADE_SUB[subType] then
                        local resID
                        if F.isInjectedIns(insID) then
                            resID = R.insToRes[insID]
                        else
                            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                            local d = wd:GetHallDepotItemDataByInsID(insID)
                            resID = d and tonumber(d.resID)
                        end
                        if resID and F.isInjectedRes(resID) then
                            cch.throwObjects[subType] = { resID = resID, insID = insID }
                        end
                    end
                end
            end)
        end

        function F.restorePersistedThrowObjects()
            if not _G.AddOutfitPersistLoaded then return end
            pcall(function()
                if not _G._savedThrowObjects then return end
                local cch = F.cache()
                cch.throwObjects = cch.throwObjects or {}
                for st, info in pairs(_G._savedThrowObjects) do
                    if info and info.resID and info.resID > 0 then
                        cch.throwObjects[st] = info
                    end
                end
            end)
        end

        -- ── put on lobby ─────────────────────────────────────
        function F.putOnGrenade(insID)
            insID = tonumber(insID)
            if not insID or insID <= 0 then return false end
            local resID = R.insToRes[insID]
            if not resID then
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                local d = wd:GetValidHallDepotItemDataByInsID(insID)
                      or wd:GetHallDepotItemDataByInsID(insID)
                resID = d and tonumber(d.resID)
            end
            if not resID or not F.isGrenadeSkinRes(resID) then return false end
            local base = F.grenadeBaseFromSkin(resID)
            if not base then return false end
            local st = F.subType(F.cfg(resID))
            if not st then return false end
            if not R.insToRes[insID] then
                R.insToRes[insID] = resID
                R.resToIns[resID] = insID
            end
            F.ensureDepotItemValid(insID, resID)
            F.ensureInjectedItemAlive(nil, resID, insID)
            F.saveGrenadeToCache(base, resID, insID)
            local ready = F.isResourcesReady(resID)
            if not ready then F.requestResourceDownload(resID) end
            pcall(function()
                local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
                if fbd.PutOnThrowObjectSkin then fbd:PutOnThrowObjectSkin(insID) end
            end)
            pcall(F.applyInitialConsumableAvatar)
            pcall(function()
                local lw = require("client.slua.logic.wardrobe.logic_wardrobe_new")
                if lw and lw.ShowGrenadeModel then lw:ShowGrenadeModel(resID, true) end
            end)
            if ready then
                local item = {
                    res_id = resID, resID = resID,
                    instid = insID, ins_id = insID, insID = insID,
                    expire_ts = 0, expireTS = 0, count = 1,
                    itemSubType = st,
                }
                local ok, WRH = pcall(require, "client.network.Protocol.WardRobeHandler")
                if ok and WRH and WRH.on_depot_put_on_rsp then
                    WRH.on_depot_put_on_rsp(NetErrorCode_NONE or 0, item, nil, 1, insID, 0)
                end
            end
            pcall(function()
                if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_PUT_ON_DATA then
                    EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_PUT_ON_DATA,
                        { instid = insID, res_id = resID, count = 1 })
                end
            end)
            return true
        end

        -- ── apply to controller ─────────────────────────────
        function F.applyInitialConsumableAvatar()
            local pc = F.getPC()
            if not pc or not slua.isValid(pc) then return false end
            local cch = F.cache()
            if not cch.throwObjects then return false end
            local applied = false
            pcall(function()
                if pc.InitialConsumableAvatar then
                    for st, info in pairs(cch.throwObjects) do
                        local key = THROW_AVATAR_KEY[THROW_SUB[st]]
                        if key and info.resID and info.resID > 0 then
                            pc.InitialConsumableAvatar[key] = info.resID
                        end
                    end
                end
                if pc.InitGrenadeAvatarList then pc:InitGrenadeAvatarList(false) end
                if pc.AddToGrenadeAvatarItemList then
                    for st, info in pairs(cch.throwObjects) do
                        if info.resID and info.resID > 0 and GRENADE_SUB[st] then
                            pc:AddToGrenadeAvatarItemList(info.resID)
                            applied = true
                        end
                    end
                end
                if pc.OnWeaponAvatarUpdate then pc:OnWeaponAvatarUpdate() end
            end)
            return applied
        end

        function F.applyGrenadeSkinsToController()
            local pc = F.getPC()
            if not pc or not slua.isValid(pc) then return false end
            local cch = F.cache()
            if not cch.throwObjects then return false end
            pcall(function()
                if pc.AddToGrenadeAvatarItemList then
                    for st, info in pairs(cch.throwObjects) do
                        if info.resID and info.resID > 0 and GRENADE_SUB[st] then
                            pc:AddToGrenadeAvatarItemList(info.resID)
                        end
                    end
                end
                if pc.OnWeaponAvatarUpdate then pc:OnWeaponAvatarUpdate() end
                local char = F.getLocalChar()
                if not char then return end
                local curWeapon = char.GetCurrentWeapon and char:GetCurrentWeapon()
                if not curWeapon or not slua.isValid(curWeapon) then return end
                local wid = 0
                pcall(function() wid = curWeapon:GetWeaponID() end)
                local sub = GRENADE_ITEMID_TO_SUB[wid]
                if not sub then return end
                local info = cch.throwObjects[sub]
                if not info or not info.resID or info.resID <= 0 then return end
                if slua.isValid(curWeapon.GrenadeAvatarComponent_BP) then
                    curWeapon.GrenadeAvatarComponent_BP:ChangeItemAvatar(info.resID, false)
                end
                if curWeapon.DelayHandleAvatarMeshChanged then curWeapon:DelayHandleAvatarMeshChanged() end
                if curWeapon.HandleAvatarMeshChanged then curWeapon:HandleAvatarMeshChanged() end
            end)
            return true
        end

        -- ── FX fallback (active only when GrenadeFX not installed) ──
        local function resolveExplosionVoice(resID)
            resID = tonumber(resID)
            if not resID or resID <= 0 then return nil, nil end
            local c = _fxVoiceCache[resID]
            if c ~= nil then
                if c == false then return nil, nil end
                return c[1], c[2]
            end
            local voice, bank
            pcall(function()
                local row
                pcall(function()
                    row = CDataTable.GetTableData("GrenadeExplosionVoiceTable", resID)
                end)
                if not row then
                    local wID
                    pcall(function()
                        local m = ModuleManager.GetModule(
                            ModuleManager.CommonModuleConfig.ItemUpgradeModule)
                        if m and m.GetNormalWeaponID then
                            wID = tonumber(m:GetNormalWeaponID(resID))
                        end
                    end)
                    local ids = {}
                    if wID and wID > 0 then ids[#ids + 1] = wID end
                    ids[#ids + 1] = resID
                    for _, id in ipairs(ids) do
                        pcall(function()
                            row = CDataTable.GetTableData("GrenadeExplosionVoiceTable", id)
                        end)
                        if row and row.GrenadeExplosionVoice and row.GrenadeExplosionVoice ~= "" then
                            break
                        end
                    end
                end
                if row and row.GrenadeExplosionVoice and row.GrenadeExplosionVoice ~= "" then
                    voice = tostring(row.GrenadeExplosionVoice)
                    bank  = row.BankName
                end
            end)
            if not voice then
                _fxVoiceCache[resID] = false
                return nil, nil
            end
            _fxVoiceCache[resID] = { voice, bank }
            return voice, bank
        end

        local function playGrenadeVoice(projectile, resID)
            local voice, bank = resolveExplosionVoice(resID)
            if not voice then return false end
            pcall(function()
                if not slua.isValid(projectile) then return end
                local ok, KA = pcall(require, "GameLua.GameCore.Framework.KismetAudioLibrary")
                if ok and KA and KA.PlaySound2D then
                    KA:PlaySound2D(voice, 1.0, 1.0, 0.0, nil, bank)
                    return
                end
                local world = projectile:GetWorld()
                if world and world.SpawnSoundAtLocation then
                    world:SpawnSoundAtLocation(voice, projectile:K2_GetActorLocation(), 1.0, 1.0)
                end
            end)
            return true
        end

        -- Only frag grenades (item 602004 / skin subtype 612) may run custom explosion visuals.
        local function isFragProjectile(projectile, resID)
            local itemID
            pcall(function()
                if projectile and projectile.GetItemTypeID then
                    itemID = tonumber(projectile:GetItemTypeID())
                end
                if not itemID and projectile and projectile.GetItemDefineID then
                    local def = projectile:GetItemDefineID()
                    itemID = tonumber(def and def.TypeSpecificID)
                end
                if not itemID and projectile and projectile.ItemDefineID then
                    itemID = tonumber(projectile.ItemDefineID.TypeSpecificID)
                end
                if not itemID and projectile then
                    itemID = tonumber(projectile.CurGrenadeID or projectile.GrenadeID)
                end
            end)
            if itemID and itemID > 0 and itemID ~= 602004 then return false end
            -- Prefer the avatar ID on this projectile's own component over any owner fallback.
            pcall(function()
                local comp = projectile and (projectile.GrenadeAvatarComponent_BP or projectile.GrenadeAvatarComponent)
                if comp and comp.GetCurGrenadeAvatarID then
                    local current = tonumber(comp:GetCurGrenadeAvatarID())
                    if current and current > 0 then resID = current end
                end
            end)
            resID = tonumber(resID)
            return resID ~= nil and tonumber(F.subType(F.cfg(resID))) == 612
        end

        -- FIRE — frag-only explosion mesh/VFX; other throwables keep native effects.
        local function fireExplosionVFX(projectile, resID)
            if not slua.isValid(projectile) then return false end
            if _fxFired[projectile] == "ok" then return false end

            resID = resID or projectile._grenadev1_resID
            if not resID or resID <= 0 then
                pcall(function()
                    local owner = projectile.GetOwner and projectile:GetOwner()
                    if owner and owner._grenadev1_resID then
                        resID = owner._grenadev1_resID
                    end
                end)
            end
            if not resID or resID <= 0 then
                local info = resolveSkinFromProjectile(projectile)
                resID = info and info.resID
            end
            if not resID or resID <= 0 then
                _fxFired[projectile] = "fail"
                return false
            end
            if not isFragProjectile(projectile, resID) then
                return false
            end

            -- Always swap explosion mesh so skin shows (frag only)
            local comp = projectile.GrenadeAvatarComponent_BP
                             or projectile.GrenadeAvatarComponent
            if slua.isValid(comp) then
                pcall(function()
                    if comp.ChangeExplosionAvatar then
                        comp:ChangeExplosionAvatar(resID)
                    elseif comp.ChangeItemAvatar then
                        comp:ChangeItemAvatar(resID, true)
                    end
                    if comp.PlayExplode         then comp:PlayExplode()         end
                    if comp.PlayExplosionEffect then comp:PlayExplosionEffect() end
                end)
            end

            -- Delegate particle + voice to GrenadeFX (correct decompile path)
            if _G.GrenadeFX_Installed and F.fireGrenadeFX and slua.isValid(comp) then
                local fxOK, fxPlayed = pcall(F.fireGrenadeFX, projectile, comp, nil)
                if fxOK and fxPlayed == true then
                    _fxFired[projectile] = "ok"
                    pcall(function()
                        if projectile.AddGameTimer then
                            projectile:AddGameTimer(0.5, false, function() _fxFired[projectile] = nil end)
                        end
                    end)
                    return true
                end
                _fxFired[projectile] = "fail"
                return false
            end

            -- Legacy fallback (KismetAudio) — only when GrenadeFX not loaded
            playGrenadeVoice(projectile, resID)
            _fxFired[projectile] = "ok"
            pcall(function()
                if projectile.AddGameTimer then
                    projectile:AddGameTimer(0.5, false, function()
                        _fxFired[projectile] = nil
                    end)
                end
            end)
            return true
        end

        local function muteExplosionFX(obj)
            if not obj then return false end
            if obj._grenadev1_fx_muted then return true end
            local muted = false
            pcall(function()
                if type(obj.SpawnExplosionEffect) == "function" then
                    obj._grenadev1_fx_orig   = obj.SpawnExplosionEffect
                    obj.SpawnExplosionEffect = function() end
                    obj._grenadev1_fx_muted  = true
                    muted = true
                end
            end)
            return muted
        end

        local function restoreExplosionFX(obj)
            if not obj then return end
            pcall(function()
                if obj._grenadev1_fx_muted and obj._grenadev1_fx_orig then
                    obj.SpawnExplosionEffect = obj._grenadev1_fx_orig
                end
                obj._grenadev1_fx_orig  = nil
                obj._grenadev1_fx_muted = nil
            end)
        end

        F.fireExplosionVFX   = fireExplosionVFX
        F.playGrenadeVoice   = playGrenadeVoice
        F.muteExplosionFX    = muteExplosionFX
        F.restoreExplosionFX = restoreExplosionFX

        -- ── HOOK 1: AvatarDataUtil — lookup ─────────────────
        function F.hookGrenadeAvatarLookup()
            pcall(function()
                local AvatarDataUtil = require("GameLua.Mod.Library.GamePlay.Avatar.AvatarDataUtil")
                if not AvatarDataUtil or AvatarDataUtil._grenadev1_lookup_hooked then return end
                AvatarDataUtil._grenadev1_lookup_hooked = true

                local function skinOrOrig(orig, ctrl, ItemID, ...)
                    local info = resolveSkinByItemID(ItemID)
                    if info then return info.resID end
                    return orig(ctrl, ItemID, ...)
                end

                local origFlight = AvatarDataUtil.TryGetGrenadeAvatarID
                if origFlight then
                    AvatarDataUtil.TryGetGrenadeAvatarID = function(ctrl, ItemID, ...)
                        return skinOrOrig(origFlight, ctrl, ItemID, ...)
                    end
                end

                for k, v in pairs(AvatarDataUtil) do
                    if type(v) == "function" and k ~= "TryGetGrenadeAvatarID" then
                        local kl = k:lower()
                        local hasGrenade = kl:find("grenade") ~= nil
                        local hasExplode = kl:find("explo")   ~= nil
                                        or kl:find("detona")  ~= nil
                                        or kl:find("blast")   ~= nil
                                        or kl:find("burst")   ~= nil
                        if hasGrenade and hasExplode then
                            local orig = v
                            AvatarDataUtil[k] = function(ctrl, ItemID, ...)
                                return skinOrOrig(orig, ctrl, ItemID, ...)
                            end
                        end
                    end
                end
            end)
        end

        -- ── HOOK 2: GrenadeAvatarComponent class ────────────
        function F.hookGrenadeAvatarComponent()
            pcall(function()
                local COMP_PATHS = {
                    "GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.GrenadeAvatarComponent",
                    "GameLua.Mod.BaseMod.GamePlay.Actor.Grenade.GrenadeAvatarComponent",
                    "GameLua.GameCore.Actor.Projectile.GrenadeAvatarComponent",
                    "GameLua.Mod.AvatarSystem.GrenadeAvatarComponent",
                }
                local impl
                for _, path in ipairs(COMP_PATHS) do
                    local ok, cls = pcall(require, path)
                    if ok and cls then
                        local candidate = cls.__inner_impl or (type(cls) == "table" and cls or nil)
                        if candidate and (candidate.ChangeItemAvatar or candidate.PlayExplode) then
                            impl = candidate
                            break
                        end
                    end
                end
                if not impl or impl._grenadev1_comp_hooked then return end
                impl._grenadev1_comp_hooked = true

                local origChange = impl.ChangeItemAvatar
                if origChange then
                    impl.ChangeItemAvatar = function(self, resID, isExploding, ...)
                        local cch = F.cache()
                        if cch.throwObjects then
                            for st, info in pairs(cch.throwObjects) do
                                if info.resID and info.resID > 0 then
                                    local base = GRENADE_BASE_BY_SUB[st]
                                    if base == resID or info.resID == resID then
                                        resID = info.resID
                                        self._grenadev1_resID = info.resID
                                        break
                                    end
                                end
                            end
                        end
                        return origChange(self, resID, isExploding, ...)
                    end
                end

                local origPlay = impl.PlayExplode
                if origPlay then
                    impl.PlayExplode = function(self, ...)
                        local resID = self._grenadev1_resID
                        if not resID or resID <= 0 then
                            pcall(function()
                                resID = self:GetOwner() and self:GetOwner()._grenadev1_resID
                            end)
                        end
                        if resID and resID > 0 then
                            fireExplosionVFX(self:GetOwner() or self, resID)
                        end
                        return origPlay(self, ...)
                    end
                end

                for _, key in ipairs({ "PlayExplosionEffect", "PlayExplodeEffect", "BeginExplode" }) do
                    local orig = impl[key]
                    if orig then
                        impl[key] = function(self, ...)
                            local resID = self._grenadev1_resID
                            if resID and resID > 0 then
                                local owner = self:GetOwner() or self
                                if _fxFired[owner] ~= "ok" then
                                    fireExplosionVFX(owner, resID)
                                end
                            end
                            return orig(self, ...)
                        end
                    end
                end
            end)
        end

        -- ── HOOK 3: Projectile flight + destroy ─────────────
        function F.hookProjectileGrenadeAvatar()
            pcall(function()
                local ProjectileBase = require("GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.ProjectileBase")
                local impl = ProjectileBase and ProjectileBase.__inner_impl
                if not impl or impl._grenadev1_hooked then return end
                impl._grenadev1_hooked = true

                local function applyFlight(self, info)
                    if not info then return end
                    self._grenadev1_resID = info.resID
                    if not slua.isValid(self.GrenadeAvatarComponent_BP) then return end
                    pcall(function()
                        self.GrenadeAvatarComponent_BP:ChangeItemAvatar(info.resID, false)
                        self.GrenadeAvatarComponent_BP._grenadev1_resID = info.resID
                    end)
                end

                local origBegin = impl.BeginInitialize
                if origBegin then
                    impl.BeginInitialize = function(self, ...)
                        local r = origBegin(self, ...)
                        applyFlight(self, resolveSkinFromProjectile(self))
                        return r
                    end
                end

                local origUpdate = impl.UpdateGrenadeAvatar
                if origUpdate then
                    impl.UpdateGrenadeAvatar = function(self)
                        if self.bAuthority then return origUpdate(self) end
                        local info = resolveSkinFromProjectile(self)
                        if info then applyFlight(self, info); return end
                        return origUpdate(self)
                    end
                end

                local origDestroyed = impl.Destroyed
                impl.Destroyed = function(self, ...)
                    fireExplosionVFX(self)
                    if origDestroyed then return origDestroyed(self, ...) end
                end

                local origBD = impl.BeginDestroy
                impl.BeginDestroy = function(self, ...)
                    fireExplosionVFX(self)
                    if origBD then return origBD(self, ...) end
                end
            end)
        end

        -- ── HOOK 4: PC init ─────────────────────────────────
        function F.hookGrenadeAvatarInit()
            pcall(function()
                local PCB = require("GameLua.GameCore.Framework.PlayerControllerBase")
                local impl = PCB and PCB.__inner_impl
                if not impl or impl._grenadev1_pc_hooked then return end
                impl._grenadev1_pc_hooked = true
                local origInit = impl.InitGrenadeAvatarList
                if origInit then
                    impl.InitGrenadeAvatarList = function(self, ReInitial)
                        origInit(self, ReInitial)
                        local localPC = F.getPC()
                        if not localPC or self ~= localPC then return end
                        if ReInitial then
                            pcall(function()
                                local cch = F.cache()
                                if self.AddToGrenadeAvatarItemList and cch.throwObjects then
                                    for st, info in pairs(cch.throwObjects) do
                                        if info.resID and info.resID > 0 and GRENADE_SUB[st] then
                                            self:AddToGrenadeAvatarItemList(info.resID)
                                        end
                                    end
                                end
                            end)
                        end
                    end
                end
            end)
        end

        -- ── tick ─────────────────────────────────────────────
        local _tickPCCache, _tickPCCacheTime = nil, 0
        function F.grenadeTick()
            if not _G._grenadeV1_lastApply then _G._grenadeV1_lastApply = 0 end
            local now = os.clock()
            if now - _G._grenadeV1_lastApply < 0.5 then return end
            _G._grenadeV1_lastApply = now
            if now - _tickPCCacheTime > 2 then
                _tickPCCache = F.getPC()
                _tickPCCacheTime = now
            end
            F.syncThrowObjectCacheFromLobby()
            local pc = _tickPCCache
            if pc and slua.isValid(pc) then
                local cch = F.cache()
                if cch.throwObjects then
                    pcall(function()
                        for st, info in pairs(cch.throwObjects) do
                            if info.resID and info.resID > 0 and GRENADE_SUB[st] then
                                local key = THROW_AVATAR_KEY[THROW_SUB[st]]
                                if key and pc.InitialConsumableAvatar then
                                    pc.InitialConsumableAvatar[key] = info.resID
                                end
                                if pc.AddToGrenadeAvatarItemList then
                                    pc:AddToGrenadeAvatarItemList(info.resID)
                                end
                            end
                        end
                        if pc.OnWeaponAvatarUpdate then pc:OnWeaponAvatarUpdate() end
                    end)
                    pcall(function()
                        local char = F.getLocalChar()
                        if not char then return end
                        local curWeapon = char.GetCurrentWeapon and char:GetCurrentWeapon()
                        if not curWeapon or not slua.isValid(curWeapon) then return end
                        local wid = 0
                        pcall(function() wid = curWeapon:GetWeaponID() end)
                        local sub = GRENADE_ITEMID_TO_SUB[wid]
                        if not sub then return end
                        local info = cch.throwObjects[sub]
                        if not info or not info.resID or info.resID <= 0 then return end
                        if slua.isValid(curWeapon.GrenadeAvatarComponent_BP) then
                            curWeapon.GrenadeAvatarComponent_BP:ChangeItemAvatar(info.resID, false)
                        end
                        if curWeapon.DelayHandleAvatarMeshChanged then
                            curWeapon:DelayHandleAvatarMeshChanged()
                        end
                    end)
                end
            end
        end

        -- ── init ─────────────────────────────────────────────
        function F.initGrenadeV1()
            F.restorePersistedThrowObjects()
            F.syncThrowObjectCacheFromLobby()
            F.hookGrenadeAvatarLookup()
            F.hookGrenadeAvatarComponent()
            F.hookProjectileGrenadeAvatar()
            F.hookGrenadeAvatarInit()
        end
    end

    return M
end)()

-- ============================================================
-- MODULE 2 — GRENADE FX (port L98_2/L112_2/L117_2/L118_2/L120_2/L125_2)
-- ============================================================
-- ============================================================
-- MODULE 2 — GRENADE FX (fixed)
-- ============================================================
local GrenadeFX = (function()
    local M = {}

    local _voiceCache   = {}
    local _pathCache    = {}  -- false = "đã probe, không có"; nil = "chưa probe"
    local _bankLib      = nil
    local _bankLibTried = false
    local _gameplayStatics = nil
    local _tableAVoice  = nil
    local _tableAGunFx  = nil
    local _tableBFx     = nil

    local function killSwitch()
        return not (_G.LexusConfig and _G.LexusConfig.ModSkin == false)
    end

    -- Strict classification: explicit throwable ID wins; skin subtype is the fallback.
    local function isFragProjectile(projectile, resID, component)
        local itemID
        pcall(function()
            if projectile and projectile.GetItemTypeID then
                itemID = tonumber(projectile:GetItemTypeID())
            end
            if not itemID and projectile and projectile.GetItemDefineID then
                local def = projectile:GetItemDefineID()
                itemID = tonumber(def and def.TypeSpecificID)
            end
            if not itemID and projectile and projectile.ItemDefineID then
                itemID = tonumber(projectile.ItemDefineID.TypeSpecificID)
            end
            if not itemID and projectile then
                itemID = tonumber(projectile.CurGrenadeID or projectile.GrenadeID)
            end
        end)
        if itemID and itemID > 0 and itemID ~= 602004 then return false end
        resID = tonumber(resID)
        if not resID and component then
            pcall(function()
                if component.GetCurGrenadeAvatarID then
                    resID = tonumber(component:GetCurGrenadeAvatarID())
                end
            end)
        end
        return resID ~= nil and tonumber(F.subType(F.cfg(resID))) == 612
    end

    local function diag(...)
        if _G.SKIN_GFX_DIAG then print("[GFX]", ...) end
    end

    local function resolveSoftPath(obj)
        if obj == nil then return nil end
        if type(obj) == "string" then return obj end
        local out
        pcall(function()
            if obj.ToSoftObjectPath then
                local sop = obj:ToSoftObjectPath()
                if sop then
                    if sop.ToString then out = sop:ToString() end
                    if (not out or out == "") and sop.GetAssetPathString then
                        out = sop:GetAssetPathString()
                    end
                end
            end
            if (not out or out == "") and obj.GetAssetPathString then
                out = obj:GetAssetPathString()
            end
            if (not out or out == "") and obj.ToString then
                out = obj:ToString()
            end
        end)
        if type(out) ~= "string" or out == "" then return nil end
        return out
    end

    local function probeTable(candidates, probeId, fieldTest)
        for _, name in ipairs(candidates) do
            local ok, row = pcall(function()
                return CDataTable.GetTableData(name, probeId)
            end)
            if ok and row and fieldTest(row) then return name end
        end
        return nil
    end

    local function findVoiceTable()
        if _tableAVoice ~= nil then return _tableAVoice or nil end
        _tableAVoice = probeTable({
            "GrenadeExplosionVoiceTable","GrenadeVoiceTable","GrenadeData",
            "GrenadeDataTable","GrenadeConfig","GrenadeExplosionData",
            "WeaponAudioTable","ItemAudioTable","AudioDataTable",
            "WwiseEventTable","WeaponData","ItemData",
        }, 602001, function(r)
            return r.GrenadeExplosionVoice ~= nil or r.BankName ~= nil
        end) or false
        return _tableAVoice or nil
    end

    local function findGunFxTableA()
        if _tableAGunFx ~= nil then return _tableAGunFx or nil end
        _tableAGunFx = probeTable({
            "GrenadeData","GrenadeSkinData","WeaponSkinData",
            "ItemSkinData","SkinData","GrenadeDataTable",
            "WeaponData","ItemData","GrenadeConfig",
        }, 602001, function(r) return r.UnlockFxGunIDList_a ~= nil end) or false
        return _tableAGunFx or nil
    end

    local function findFxPathTableB()
        if _tableBFx ~= nil then return _tableBFx or nil end
        for _, probe in ipairs({ 1, 602001, 602002, 602003, 602004 }) do
            _tableBFx = probeTable({
                "FxData","FXData","EffectData","ParticleData",
                "FxPathData","EffectPathData","GrenadeFxData",
                "WeaponFxData","FxTable","EffectTable","FxSeqData",
            }, probe, function(r) return r.FxSeqPath ~= nil or r.FxPath ~= nil end)
            if _tableBFx then return _tableBFx end
        end
        _tableBFx = false
        return nil
    end

    local function resolveVoice(grenadeType)
        grenadeType = tonumber(grenadeType)
        if not grenadeType or grenadeType <= 0 then return nil, nil end
        local cached = _voiceCache[grenadeType]
        if cached ~= nil then
            if cached == false then return nil, nil end
            return cached[1], cached[2]
        end
        local voice, bank
        pcall(function()
            local wID
            pcall(function()
                local m = ModuleManager.GetModule(
                    ModuleManager.CommonModuleConfig.ItemUpgradeModule)
                if m and m.GetNormalWeaponID then
                    wID = tonumber(m:GetNormalWeaponID(grenadeType))
                end
            end)
            local tableName = findVoiceTable()
            if not tableName then return end
            local ids = {}
            if wID and wID > 0 then ids[#ids+1] = wID end
            ids[#ids+1] = grenadeType
            for _, id in ipairs(ids) do
                local row
                pcall(function()
                    row = CDataTable.GetTableData(tableName, id)
                end)
                if row and row.GrenadeExplosionVoice and row.GrenadeExplosionVoice ~= "" then
                    voice = tostring(row.GrenadeExplosionVoice)
                    bank  = row.BankName
                    break
                end
            end
        end)
        if not voice then
            _voiceCache[grenadeType] = false   -- sentinel: đã probe, không có
            return nil, nil
        end
        _voiceCache[grenadeType] = { voice, bank }
        return voice, bank
    end

    -- FIX #3: dùng false sentinel thay vì cache {nil,nil,nil}
    local function resolveFXPaths(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return nil, nil, nil end
        local cached = _pathCache[resID]
        if cached ~= nil then
            if cached == false then return nil, nil, nil end   -- đã probe, không có
            return cached[1], cached[2], cached[3]
        end

        local seqPath, fxPath, overrideIndex
        pcall(function()
            local tableA = findGunFxTableA()
            if not tableA then return end
            local rowA
            pcall(function() rowA = CDataTable.GetTableData(tableA, resID) end)
            if not rowA or not rowA.UnlockFxGunIDList_a then return end

            local list = rowA.UnlockFxGunIDList_a
            local gunIDs = {}
            pcall(function()
                local n = 0
                if list.Num then n = list:Num() end
                for i = 0, n - 1 do
                    local id = tonumber(list:Get(i))
                    if id and id > 0 then gunIDs[#gunIDs+1] = id end
                end
            end)
            if #gunIDs == 0 then return end

            local tableB = findFxPathTableB()
            if not tableB then return end

            for _, gunID in ipairs(gunIDs) do
                local rowB
                pcall(function() rowB = CDataTable.GetTableData(tableB, gunID) end)
                if rowB and (rowB.FxSeqPath or rowB.FxPath) then
                    seqPath = resolveSoftPath(rowB.FxSeqPath)
                    fxPath  = resolveSoftPath(rowB.FxPath)
                    if seqPath or fxPath then
                        overrideIndex = gunID
                        break
                    end
                end
            end
        end)

        if not seqPath and not fxPath then
            _pathCache[resID] = false          -- sentinel
            return nil, nil, nil
        end
        _pathCache[resID] = { seqPath, fxPath, overrideIndex }
        return seqPath, fxPath, overrideIndex
    end

    -- FIX #2: helper verify resID qua throwObjects cache (port L111_2)
    -- Trả về resID nếu nằm trong cache, nil nếu không
    local function ourSkinID_fromComp(comp, throwObjects)
        if not slua.isValid(comp) then return nil end
        local resID
        pcall(function()
            if comp.GetCurGrenadeAvatarID then
                resID = tonumber(comp:GetCurGrenadeAvatarID())
            end
        end)
        if not resID or resID <= 0 then return nil end
        if not throwObjects then return nil end
        for _, info in pairs(throwObjects) do
            if info.resID and tonumber(info.resID) == resID then
                return resID
            end
        end
        return nil
    end

    local function loadAssetSafe(path)
        local obj
        pcall(function()
            local loader = import("/Game/BluePrints/GameCore/Global/BP_AssetMgr")
            if loader and loader.LoadAsset then obj = loader.LoadAsset(path) end
        end)
        if not obj then
            pcall(function() if LoadObject then obj = LoadObject(nil, path) end end)
        end
        return obj
    end

    local function getBankLib()
        if _bankLibTried then return _bankLib end
        _bankLibTried = true
        for _, p in ipairs({
            "GameLua.GameCore.Framework.BankAudioLibrary",
            "GameLua.GameCore.Framework.WwiseAudioLibrary",
            "GameLua.GameCore.Framework.AudioLibrary",
            "GameLua.Mod.Library.GamePlay.Audio.BankAudio",
            "client.slua.logic.audio.bank_audio",
        }) do
            local ok, m = pcall(require, p)
            if ok and m and (m.TryPlayBankAudio or (m.__inner_impl and m.__inner_impl.TryPlayBankAudio)) then
                _bankLib = m.__inner_impl or m
                return _bankLib
            end
        end
        return nil
    end

    -- playGrenadeVoice nhận resID trực tiếp để tránh re-query sau origInEffect
    local function playGrenadeVoice(comp, worldLoc, resID)
        if not killSwitch() then return false end
        if not slua.isValid(comp) then return false end

        -- resID có thể pass vào từ caller (tránh GetCurGrenadeAvatarID sau origInEffect)
        if not resID then
            pcall(function()
                if comp.GetCurGrenadeAvatarID then
                    resID = tonumber(comp:GetCurGrenadeAvatarID())
                end
            end)
        end
        if not resID or resID <= 0 then return false end

        local voice, bank = resolveVoice(resID)
        if not voice then return false end

        local now = os.time()
        if comp._lava_gfx_sndPlayed and now > 0 then
            local last = tonumber(comp._lava_gfx_sndPlayedAt) or 0
            if now - last < 2 then return false end
        end
        comp._lava_gfx_sndPlayed   = true
        comp._lava_gfx_sndPlayedAt = now

        if not worldLoc then
            pcall(function() worldLoc = comp:K2_GetComponentLocation() end)
        end
        if not worldLoc then
            pcall(function()
                local owner = comp:GetOwner()
                if owner and slua.isValid(owner) then
                    worldLoc = owner:K2_GetActorLocation()
                end
            end)
        end

        local lib = getBankLib()
        if not lib or not lib.TryPlayBankAudio then
            diag("bank lib missing")
            return false
        end
        local ok, result = pcall(lib.TryPlayBankAudio, voice, bank, nil, true, worldLoc)
        diag("TryPlayBankAudio:", voice, bank, "->", ok, result)
        return ok and result ~= false
    end

    local function swapFX(projectile, component)
        if not slua.isValid(projectile) then return nil end
        if not slua.isValid(component) then return nil end
        local resID
        pcall(function()
            if component.GetCurGrenadeAvatarID then
                resID = tonumber(component:GetCurGrenadeAvatarID())
            end
        end)
        if not resID or resID <= 0 then return nil end
        if not isFragProjectile(projectile, resID, component) then return nil end

        local seqPath, fxPath, overrideIdx = resolveFXPaths(resID)
        if not seqPath and not fxPath then return nil end

        if seqPath and seqPath ~= "" then
            pcall(function() projectile.ExLevelSeqPath = seqPath end)
        end
        if overrideIdx and projectile.SetOverrideFxIndex then
            pcall(function() projectile:SetOverrideFxIndex(overrideIdx) end)
        end
        if overrideIdx and projectile.SetOverrideSoundIndex then
            pcall(function() projectile:SetOverrideSoundIndex(overrideIdx) end)
        end
        if not projectile._lava_gfx_spawn_shim then
            pcall(function()
                local orig = projectile.SpawnHighLevelParticleActor
                projectile._lava_gfx_spawn_shim = orig
                projectile.SpawnHighLevelParticleActor = function(self, ...)
                    pcall(function()
                        local r
                        if component.GetCurGrenadeAvatarID then
                            r = tonumber(component:GetCurGrenadeAvatarID())
                        end
                        if r and r > 0 then
                            local sp = resolveFXPaths(r)
                            if sp and sp ~= "" then self.ExLevelSeqPath = sp end
                        end
                    end)
                    if orig then return orig(self, ...) end
                end
            end)
        end
        return seqPath
    end

    -- FIX #2: verify resID qua throwObjects cache trước khi fire
    local function fireGrenadeFX(projectile, component, worldLoc)
        if not killSwitch() then return false end
        if not slua.isValid(projectile) or not slua.isValid(component) then
            return false
        end

        -- Lấy resID từ GetCurGrenadeAvatarID
        local resID
        pcall(function()
            if component.GetCurGrenadeAvatarID then
                resID = tonumber(component:GetCurGrenadeAvatarID())
            end
        end)

        -- Verify qua throwObjects cache (tương đương L111_2 trong doc 1)
        if resID and resID > 0 then
            local cch = _G._grenadeVxCacheRef  -- set từ wiring, xem bên dưới
            if cch and cch.throwObjects then
                local verified = false
                for _, info in pairs(cch.throwObjects) do
                    if info.resID and tonumber(info.resID) == resID then
                        verified = true; break
                    end
                end
                if not verified then resID = nil end
            end
        end

        if not resID or resID <= 0 then return false end
        if not isFragProjectile(projectile, resID, component) then
            return false, resID
        end

        local seqPath, fxPath = resolveFXPaths(resID)
        if (not seqPath or seqPath == "") and (not fxPath or fxPath == "") then
            return false
        end

        local now = os.time()
        if component._lava_gfx_played and now > 0 then
            local last = tonumber(component._lava_gfx_playedAt) or 0
            if now - last < 2 then return false end
        end
        if not worldLoc then
            pcall(function() worldLoc = projectile:K2_GetActorLocation() end)
        end
        if not worldLoc then
            pcall(function() worldLoc = component:K2_GetComponentLocation() end)
        end
        if not worldLoc then
            pcall(function()
                local owner = component:GetOwner()
                if owner and slua.isValid(owner) then
                    worldLoc = owner:K2_GetActorLocation()
                end
            end)
        end

        local radius = 1.0
        pcall(function()
            local mod = projectile.DynamicModifier
            if mod and mod.EffectRange then
                local r = tonumber(mod.EffectRange)
                if r and r > 0 then radius = r end
            end
        end)

        local played = false

        if seqPath and seqPath ~= "" then
            local ok = xpcall(function()
                component:CreateLevelSequenceActor(seqPath, worldLoc)
            end, tostring)
            if ok then
                pcall(function() component.ExLevelSeqPath = "" end)
                _G._lava_lastGrenadeBlast = { t = now, resID = resID }
                played = true
                diag("FX-A seq:", seqPath)
            end
        end

        if not played and fxPath and fxPath ~= "" and worldLoc then
            local ok = xpcall(function()
                if not _gameplayStatics then
                    for _, p in ipairs({
                        "GameLua.GameCore.Framework.GameplayStatics",
                        "GameLua.GameCore.Framework.KismetSystemLibrary",
                    }) do
                        local pok, m = pcall(require, p)
                        if pok and m and m.SpawnEmitterAtLocation then
                            _gameplayStatics = m; break
                        end
                    end
                    if not _gameplayStatics then
                        _gameplayStatics = import("/Game/BluePrints/GameCore/Global/BP_GameplayStatics")
                    end
                end
                if not _gameplayStatics or not _gameplayStatics.SpawnEmitterAtLocation then
                    error("GameplayStatics missing")
                end
                local world = slua_GameFrontendHUD and slua_GameFrontendHUD:GetWorld()
                if not world or not slua.isValid(world) then error("world invalid") end
                local emitter = loadAssetSafe(fxPath)
                if not emitter then error("loadAsset failed: "..fxPath) end
                _gameplayStatics.SpawnEmitterAtLocation(
                    world, emitter, worldLoc,
                    FRotator(0, 0, 0),
                    FVector(radius, radius, radius),
                    true
                )
            end, tostring)
            if ok then
                _G._lava_lastGrenadeBlast = { t = now, resID = resID }
                played = true
                diag("FX-B emitter:", fxPath)
            end
        end

        if not played and seqPath and seqPath ~= "" and worldLoc then
            local ok = xpcall(function()
                local world = slua_GameFrontendHUD and slua_GameFrontendHUD:GetWorld()
                if not world then error("world missing") end
                local transform = FTransform(
                    FRotator(0, 0, 0), worldLoc,
                    FVector(radius, radius, radius)
                )
                local callback = _G.GrenadeFX or {}
                local actor = Game:PlayLevelSequence(
                    world, projectile, seqPath, transform, callback, false)
                if actor and slua.isValid(actor) then
                    projectile:AddGameTimer(0.1, false, function()
                        if slua.isValid(actor) then
                            pcall(function() actor:Play(0.0) end)
                        end
                    end)
                end
            end, tostring)
            if ok then
                _G._lava_lastGrenadeBlast = { t = now, resID = resID }
                played = true
                diag("FX-C PlayLevelSequence:", seqPath)
            end
        end

        if played then
            component._lava_gfx_played = true
            component._lava_gfx_playedAt = now
        else
            component._lava_gfx_played = nil
            component._lava_gfx_playedAt = nil
        end
        return played, resID   -- chỉ đánh dấu hoàn tất khi effect thực sự được spawn
    end

    local function muteStockClass()
        if not killSwitch() then return nil end
        local patched = {}
        for _, path in ipairs({
            "GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.GrenadeAvatarComponent",
            "GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.ProjectileBase",
            "GameLua.GameCore.Actor.Projectile.GrenadeAvatarComponent",
        }) do
            pcall(function()
                local cls = require(path)
                local impl = cls and (cls.__inner_impl or cls)
                if impl and type(impl.SpawnExplosionEffect) == "function"
                   and not impl._gfx_mute_installed then
                    impl._gfx_mute_installed = true
                    local orig = impl.SpawnExplosionEffect
                    impl.SpawnExplosionEffect = function() end
                    patched[#patched+1] = { t = impl, f = orig }
                end
            end)
        end
        if #patched == 0 then return nil end
        return function()
            for _, p in ipairs(patched) do
                pcall(function()
                    p.t.SpawnExplosionEffect = p.f
                    p.t._gfx_mute_installed  = nil
                end)
            end
        end
    end

    -- Preload bank sounds (port L116_2)
    local function preloadGunBank(resID)
        resID = tonumber(resID)
        if not resID or resID <= 0 then return end
        local voice, bank = resolveVoice(resID)
        if not bank then return end
        pcall(function()
            local audio = require("client.slua.logic.audio.bank_audio")
                       or require("GameLua.GameCore.Framework.BankAudioLibrary")
            if audio and audio.IsBankExist then
                audio.IsBankExist(bank, true)
            end
        end)
    end

    local function onGrenadeUpdate(projectile, _tag)
        if not slua.isValid(projectile) then return end
        pcall(function()
            if not projectile._lava_gfx_thrownAt then
                projectile._lava_gfx_thrownAt = os.time()
            end
            local comp = projectile.GrenadeAvatarComponent_BP
            if slua.isValid(comp) then
                if not comp._lava_gfx_thrownAt then
                    comp._lava_gfx_thrownAt = projectile._lava_gfx_thrownAt
                end
                swapFX(projectile, comp)
            end
        end)
    end

    function M.install()
        if not killSwitch() then return false end
        if _G.GrenadeFX_Installed then return true end

        local patched = false

        pcall(function()
            local PB = require("GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.ProjectileBase")
            local impl = PB and PB.__inner_impl
            if not impl then return end

            local origUpdate = impl.UpdateGrenadeAvatar
            if origUpdate and not impl._gfx_hooked_update then
                impl._gfx_hooked_update = true
                impl.UpdateGrenadeAvatar = function(self)
                    if self.bAuthority then return origUpdate(self) end
                    onGrenadeUpdate(self, "Update")
                    return origUpdate(self)
                end
                patched = true
            end

            local origBegin = impl.BeginInitialize
            if origBegin and not impl._gfx_hooked_begin then
                impl._gfx_hooked_begin = true
                impl.BeginInitialize = function(self, ...)
                    local r = origBegin(self, ...)
                    pcall(onGrenadeUpdate, self, "Init")
                    pcall(function()
                        self:AddGameTimer(0.5, false, function()
                            pcall(onGrenadeUpdate, self, "Deferred")
                        end)
                    end)
                    return r
                end
                patched = true
            end

            -- FIX #1: voice AFTER origInEffect
            local origInEffect = impl.BeginInEffect
            if origInEffect and not impl._gfx_hooked_effect then
                impl._gfx_hooked_effect = true
                impl.BeginInEffect = function(self, ...)
                    local comp = nil
                    local firedResID = nil
                    local restore = nil

                    pcall(function()
                        comp = slua.isValid(self.GrenadeAvatarComponent_BP)
                               and self.GrenadeAvatarComponent_BP
                            or slua.isValid(self.GrenadeAvatarComponent)
                               and self.GrenadeAvatarComponent
                    end)

                    if comp then
                        -- Lấy resID TRƯỚC khi origInEffect thay đổi state
                        pcall(function()
                            if comp.GetCurGrenadeAvatarID then
                                firedResID = tonumber(comp:GetCurGrenadeAvatarID())
                            end
                        end)

                        pcall(preloadGunBank, firedResID)
                        pcall(swapFX, self, comp)

                        -- Chỉ mute hiệu ứng gốc khi custom particle/sequence đã spawn thành công.
                        local fxOK, fxPlayed, resolvedID = pcall(fireGrenadeFX, self, comp, nil)
                        if resolvedID and resolvedID > 0 then firedResID = resolvedID end
                        if fxOK and fxPlayed == true then
                            restore = muteStockClass()
                        end
                    end

                    -- Gọi original
                    local r = origInEffect(self, ...)

                    -- Restore mute SAU origInEffect
                    if restore then
                        pcall(restore)
                    end

                    -- FIX #1: Voice SAU origInEffect, dùng firedResID đã lưu
                    if comp then
                        pcall(playGrenadeVoice, comp, nil, firedResID)
                    end

                    return r
                end
                patched = true
            end
        end)

        pcall(function()
            local PB = require("GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.ProjectileBase")
            local impl = PB and PB.__inner_impl
            if not impl then return end
            local orig = impl.IsGrenadeHasAvatar
            if orig and not impl._gfx_hooked_has_avatar then
                impl._gfx_hooked_has_avatar = true
                impl.IsGrenadeHasAvatar = function(self)
                    local r = orig(self)
                    pcall(function()
                        local comp = self.GrenadeAvatarComponent_BP
                        if slua.isValid(comp) then swapFX(self, comp) end
                    end)
                    return r
                end
            end
        end)

        pcall(function()
            local cls = require("GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.ProjectileBase")
            local impl = cls and (cls.__inner_impl or cls)
            if impl and impl.GetSequencePath and not impl._gfx_hooked_seqpath then
                impl._gfx_hooked_seqpath = true
                local orig = impl.GetSequencePath
                impl.GetSequencePath = function(self, ...)
                    local r = orig(self, ...)
                    local override
                    pcall(function()
                        local comp = self.GrenadeAvatarComponent_BP
                        if not slua.isValid(comp) then return end
                        local id = comp.GetCurGrenadeAvatarID
                                   and tonumber(comp:GetCurGrenadeAvatarID())
                        if id and id > 0 and isFragProjectile(self, id, comp) then
                            local sp = resolveFXPaths(id)
                            if sp and sp ~= "" then override = sp end
                        end
                    end)
                    return override or r
                end
            end
        end)

        _G.GrenadeFX_Installed = patched
        diag("install done, patched=", patched)
        return patched
    end

    M.fireGrenadeFX    = fireGrenadeFX
    M.swapFX           = swapFX
    M.resolveVoice     = resolveVoice
    M.resolveFXPaths   = resolveFXPaths
    M.playGrenadeVoice = playGrenadeVoice
    M.muteStockClass   = muteStockClass
    M.onGrenadeUpdate  = onGrenadeUpdate

    return M
end)()

