pcall(function()
-- language: Lua — thay thế toàn bộ F.applyWakeFlameToChar hiện tại
-- Xử lý wake flame / move trail (453xxxx) và foot effect (454xxxx)
-- Chèn 3 tầng: SlotSyncData[23] → comp.MoveEffectItem → AdditionEffectMgr

function F.applyWakeFlameToChar(char, resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then return false end
    char = char or F.getLocalChar()
    if not char then return false end

    local comp = F.getAvatarComp2(char)
    if not comp or not slua.isValid(comp) then return false end

    F.ensureSkinDownload(resID)

    local st = F.subType(F.cfg(resID))  -- 453 = wake flame, 454 = footprint
    local isFoot = (st == FOOT_SUB) or (resID >= 4541000 and resID < 4542000)
    local isWake = (st == WAKE_SUB) or (resID >= 4531000 and resID < 4532000)

    if not isFoot and not isWake then return false end

    local applied = false

    -- ============================================================
    -- TẦNG 1: SlotSyncData — cho 453 dùng slot 23, cho 454 dùng slot 22
    -- ============================================================
    pcall(function()
        local net = comp.NetAvatarData
        local sd = net and net.SlotSyncData
        if not sd or not slua.isValid(sd) then return end

        local slotID = isFoot and 22 or 23

        for i = 0, sd:Num() - 1 do
            local e = sd:Get(i)
            if e and tonumber(e.SlotID) == slotID then
                local cur = tonumber(e.ItemId) or tonumber(e.ItemID) or 0
                if cur == resID then applied = true; return end
                e.ItemId = resID
                if e.ItemID ~= nil then e.ItemID = resID end
                if e.FakeItemID ~= nil then e.FakeItemID = resID end
                sd:Set(i, e)
                applied = true
                return
            end
        end

        local ok, entry = pcall(function() return import("AvatarSyncData")() end)
        if not ok or not entry then return end
        local ESyncOperation = import("ESyncOperation")
        entry.SlotID = slotID
        entry.ItemId = resID
        entry.ItemID = resID
        entry.FakeItemID = resID
        entry.OperationType = (ESyncOperation and ESyncOperation.PutOn) or 1
        sd:Add(entry)
        applied = true
    end)

    -- ============================================================
    -- TẦNG 2: Ghi trực tiếp vào component — engine đọc để render
    -- ============================================================
    pcall(function()
        if isWake then
            if comp.MoveEffectItem ~= resID then
                comp.MoveEffectItem = resID
                if comp.OnRep_MoveEffectItem then
                    pcall(function() comp:OnRep_MoveEffectItem(0) end)
                end
                applied = true
            end
            if comp.MoveEffectItemId ~= nil and comp.MoveEffectItemId ~= resID then
                comp.MoveEffectItemId = resID
            end
            if comp.WakeFlameItemId ~= nil and comp.WakeFlameItemId ~= resID then
                comp.WakeFlameItemId = resID
            end
        end

        if isFoot then
            if comp.FootStepEffectItem ~= resID then
                comp.FootStepEffectItem = resID
                if comp.OnRep_FootStepEffectItem then
                    pcall(function() comp:OnRep_FootStepEffectItem(0) end)
                end
                applied = true
            end
            if comp.FootStepEffectItemId ~= nil and comp.FootStepEffectItemId ~= resID then
                comp.FootStepEffectItemId = resID
            end
        end
    end)

    -- ============================================================
    -- TẦNG 3: AdditionEffectMgr — bộ quản lý hiệu ứng phụ
    -- ============================================================
    pcall(function()
        local mgr = comp.AdditionEffectMgr
            or comp.CharacterAvatarAdditionEffectMgr
            or comp.AvatarAdditionEffectMgr

        if not mgr then
            local ok, cls = pcall(function() return import("CharacterAvatarAdditionEffectMgr") end)
            if ok and cls and comp.GetComponentByClass then
                mgr = comp:GetComponentByClass(cls)
            end
        end
        if not slua.isValid(mgr) then return end

        if isWake then
            local cur = tonumber(mgr.MoveEffectItem) or 0
            if cur ~= resID then
                if mgr.SetMoveEffectItem then
                    pcall(function() mgr:SetMoveEffectItem(resID) end)
                    applied = true
                end
            end
        end

        if isFoot then
            local cur = tonumber(mgr.FootStepEffectItem) or 0
            if cur ~= resID then
                if mgr.SetFootStepEffectItem then
                    pcall(function() mgr:SetFootStepEffectItem(resID) end)
                    applied = true
                end
            end
        end
    end)

    -- ============================================================
    -- TẦNG 4: GoldenLeavesTrail (module v1 dùng cho 453)
    -- ============================================================
    pcall(function()
        if not isWake then return end
        local Trail = _G.GoldenLeavesTrail
        if not Trail then return end
        if Trail.TRAIL_ITEM_ID ~= resID then
            Trail.TRAIL_ITEM_ID = resID
        end
        if not Trail.Enabled then Trail.Enabled = true end
        if Trail._appliedChar ~= char then
            Trail._appliedChar = char
        end
        if Trail.Apply then pcall(Trail.Apply) end
        applied = true
    end)

    -- ============================================================
    -- Đảm bảo engine vẽ lại mesh nếu cần
    -- ============================================================
    if applied then
        pcall(function()
            if comp.OnRep_BodySlotStateChanged then
                comp:OnRep_BodySlotStateChanged()
            end
        end)
    end

    return applied
end
end)

_G.AddOutfit = F
F.start()

-- [Chann] Final Kill 61950002: chỉ kích hoạt tại thời điểm kết thúc trận.
-- Không ép ID vào TriggerParticleEffect/PrepareItem toàn cục để tránh đổi hiệu ứng hạ gục thường.
function F.installFinalKillEffect()
    local EFFECT_ID = 61950002

    -- Giữ fallback của SRC/ChannHi khi cấu hình Sequence cho ID này bị thiếu.
    pcall(function()
        local actor = require("GameLua.Mod.Library.GamePlay.Actor.FinalKillEffectLevelSequenceActor")
        if actor and not actor._ChannFinalKillSequenceHooked then
            local originalBeginPlay = actor.ReceiveBeginPlay
            if type(originalBeginPlay) == "function" then
                actor.ReceiveBeginPlay = function(self)
                    if tonumber(self.ItemId) == EFFECT_ID then
                        local cfg
                        pcall(function() cfg = CDataTable.GetTableData("FinalKillEffectCfg", self.ItemId) end)
                        if not cfg or not cfg.Sequence or cfg.Sequence == "" then
                            if self.Callback and type(self.Callback.OnPlay) == "function" then
                                pcall(self.Callback.OnPlay)
                            end
                            return
                        end
                    end
                    return originalBeginPlay(self)
                end
                actor._ChannFinalKillSequenceHooked = true
            end
        end
    end)

    if _G.Chann_FinalKillEffectHooksInstalled then return true end

    local function triggerAtMatchEnd()
        if _G.Chann_FinalKillEffectTriggered then return false end
        local function retrySoon()
            local tries = tonumber(_G.Chann_FinalKillRetryCount) or 0
            if tries < 5 then
                _G.Chann_FinalKillRetryCount = tries + 1
                F.later(0.25, triggerAtMatchEnd)
            end
        end
        local char = F.getLocalChar()
        if not char or not slua.isValid(char) then
            retrySoon()
            return false
        end
        local ok, triggered = pcall(function()
            if not char.FinalKillEffect and char.EnsureDynamicFeature then
                char:EnsureDynamicFeature("FinalKillEffect")
            end
            local feature = char.FinalKillEffect
            if not feature or type(feature.TriggerParticleEffect) ~= "function" then return false end
            local location = char:K2_GetActorLocation()
            local rotation = FRotator(0, 0, 0)
            local playerName = char.PlayerName or ""
            feature:TriggerParticleEffect(EFFECT_ID, location, rotation, playerName)
            return true
        end)
        if ok and triggered then
            _G.Chann_FinalKillEffectTriggered = true
            return true
        end
        retrySoon()
        return false
    end

    local hooked = false
    pcall(function()
        local br = rawget(_G, "BattleResult")
        if type(br) == "table" and type(br.on_game_result) == "function" and not br._ChannFinalKillHooked then
            local original = br.on_game_result
            br.on_game_result = function(...)
                triggerAtMatchEnd()
                return original(...)
            end
            br._ChannFinalKillHooked = true
            hooked = true
        end
        if type(br) == "table" and type(br.on_game_over) == "function" and not br._ChannFinalKillOverHooked then
            local original = br.on_game_over
            br.on_game_over = function(...)
                triggerAtMatchEnd()
                return original(...)
            end
            br._ChannFinalKillOverHooked = true
            hooked = true
        end
    end)
    pcall(function()
        if EventSystem and type(EventSystem.registEvent) == "function"
            and EVENTTYPE_STATE and EVENTID_GAMESTATE_ON_PRE_BATTLE_RESULT
            and not _G.Chann_FinalKillEventRegistered then
            EventSystem:registEvent(EVENTTYPE_STATE, EVENTID_GAMESTATE_ON_PRE_BATTLE_RESULT, triggerAtMatchEnd)
            _G.Chann_FinalKillEventRegistered = true
            hooked = true
        end
    end)
    if hooked then _G.Chann_FinalKillEffectHooksInstalled = true end
    return hooked
end

-- Event/module globals có thể được nạp muộn; thử lại hữu hạn, không tạo loop nền.
F.installFinalKillEffect()
F._finalKillInstallTries = 0
function F.retryFinalKillInstall()
    if _G.Chann_FinalKillEffectHooksInstalled or F._finalKillInstallTries >= 12 then return end
    F._finalKillInstallTries = F._finalKillInstallTries + 1
    if not F.installFinalKillEffect() then F.later(1.0, F.retryFinalKillInstall) end
end
if not _G.Chann_FinalKillEffectHooksInstalled then F.later(1.0, F.retryFinalKillInstall) end

pcall(function()
    if F.restorePersistedThrowObjects then F.restorePersistedThrowObjects() end
