                self._myCustomIsCauser = (DamageRecordData.Causer == SelfName)
            else
                self._myCustomIsCauser = false
            end
        end
        
        -- Gọi hàm gốc (giữ nguyên data, giữ hiệu ứng)
        if old_FileItem then
            return old_FileItem(self, DamageRecordData)
        end
    end
    
    
    -- ✅ HOOK UpdateColorLua: Đổi tên CHỈ KHI mình kill
    local old_UpdateColorLua = KillInfo.__inner_impl.UpdateColorLua
