--                end
            end)
            
            -- ✅ RANDOM MÀU CHỈ KHI MÌNH KILL
            math.randomseed(os.time())
            local FinalColor = FLinearColor(
                math.random(0, 255) / 255,
                math.random(0, 255) / 255,
                math.random(0, 255) / 255,
                1
            )
            
            if self.Image_KillType then
                self.Image_KillType:SetColorAndOpacity(FinalColor)
            end
            if self.Image_WeaponIcon then
                self.Image_WeaponIcon:SetColorAndOpacity(FinalColor)
            end
        end
    end
end)



