local CUSTOM_NAME2 = "Quỳnh Chann Bảo Bối"
local BID_TEXT     = "PHẠM NGỌC HIỂN x NGUYỄN TRẦN QUỲNH TRANG"

local COLOR_GOLD = FLinearColor(1, 0.84, 0, 1)
local COLOR_CYAN = FLinearColor(0, 1, 0.5, 1)
local COLOR_BLUE = FLinearColor(0, 0.5, 1, 1)
local COLOR_PINK = FLinearColor(1, 0.2, 0.6, 1)

local PALETTE_HEX = {
    "FF0000","FF7F00","FFD700","00FF00","00CED1",
    "1E90FF","4B0082","8B00FF","FF1493","FF69B4",
    "FFA07A","ADFF2F","40E0D0","EE82EE","DC143C",
    "FF8C00","7FFF00","00BFFF","DA70D6",
}

local function log(m) print("[FIN] " .. tostring(m)) end

-- ============================================================
-- 1. Kill ZOULE global watermark
-- ============================================================
_G._ZOULE_MOD_applyWatermarkText = function() end
log("no-op _G._ZOULE_MOD_applyWatermarkText")

-- ============================================================
-- 2. Markup + widget helpers
-- ============================================================
local function build_markup(text)
    local out, i = {}, 0
    for _, cp in utf8.codes(text) do
        i = i + 1
        local hex = PALETTE_HEX[((i - 1) % #PALETTE_HEX) + 1]
        out[#out + 1] = string.format('<span color="#%s">%s</span>', hex, utf8.char(cp))
    end
    return table.concat(out)
end
local BID_MARKUP = build_markup(BID_TEXT)

local function widget_class_name(w)
    if w and w.GetClass then
        local ok, cls = pcall(function() return w:GetClass() end)
        if ok and cls and cls.GetName then
            local ok2, n = pcall(function() return cls:GetName() end)
            if ok2 and n then return tostring(n) end
        end
    end
    return "?"
end

local function is_rich(w)
    return widget_class_name(w):lower():find("richtext") ~= nil
end

local function apply_bid(w)
    if not (w and slua.isValid(w)) then return end
    if is_rich(w) then
        pcall(function() w:SetText(BID_MARKUP) end)
    else
        pcall(function() w:SetText(BID_TEXT) end)
    end
    if w.SetColorAndOpacity then
        pcall(function() w:SetColorAndOpacity(FSlateColor(COLOR_PINK)) end)
    end
end

local function find_bid_hour(self)
    if not self then return nil, nil end
    local bid = self.TextBlock_BID
    if not bid and self.UIRoot then bid = self.UIRoot.TextBlock_BID end
    local hour = self.TextBlock_Hour
    if not hour and self.UIRoot then hour = self.UIRoot.TextBlock_Hour end
    return bid, hour
end

