-- 3. ShowServerTime override (5 class) — giữ từ fix trước
-- ============================================================
for _, p in ipairs({
    "GameLua.Mod.BaseMod.Client.MainControlUI.MainControlBaseUI",
    "GameLua.Mod.BaseMod.Client.InGameUI.MainControlBaseUI",
    "GameLua.Mod.BaseMod.Client.MainControlBaseUI",
    "client.slua.umg.main_city.MainCity_IngameImmersion_UIBP",
    "GameLua.Mod.BaseMod.Client.InGameUI.BIDHourUI",
}) do
    local ok, cls = pcall(require, p)
    if ok and type(cls) == "table" and cls.__inner_impl then
        cls.__inner_impl.ShowServerTime = function(self, ...)
            local bid, hour = find_bid_hour(self)
            apply_bid(bid)
            apply_bid(hour)
        end
        cls.__inner_impl.__ZOULE_MOD_custom_version = true
    end
end

