-- ============================================================
-- 7. HARD HOOK SetText — chặn mọi lần ghi lên widget
-- ============================================================
-- Đây là fix cho Hour: callback timer capture self ghi trực tiếp
-- override method không chặn được → hook SetText trên widget

local hooked = setmetatable({}, { __mode = "k" })

local function hard_hook(w, label)
    if not (w and slua.isValid(w)) then return false end
    if hooked[w] then return true end

    local orig = w.SetText
    if type(orig) ~= "function" then
        log("hook SKIP " .. label .. " — không có SetText")
        return false
    end

    local final_text = is_rich(w) and BID_MARKUP or BID_TEXT

    local wrapper = function(self, _, ...)
        return orig(self, final_text, ...)
    end

    -- thử gán trực tiếp
    local ok = pcall(function() w.SetText = wrapper end)
    if not ok then
        -- thử rawset (bypass metatable)
        ok = pcall(function() rawset(w, "SetText", wrapper) end)
    end

    if not ok then
        log("hook FAIL " .. label .. " — userdata không cho gán")
        return false
    end

    hooked[w] = true
    pcall(function() orig(w, final_text) end)
    if w.SetColorAndOpacity then
        pcall(function() w:SetColorAndOpacity(FSlateColor(COLOR_PINK)) end)
    end
    log("hook OK " .. label)
    return true
end

-- ============================================================
-- 8. Hook all widgets
-- ============================================================
local function get_base_ui()
    for _, p in ipairs({
        "GameLua.Mod.BaseMod.Common.UI.InGameUITools",
        "client.slua_ui_framework.InGameUITools",
        "client.slua.ui.InGameUITools",
    }) do
        local ok, t = pcall(require, p)
        if ok and t and t.GetMainControlBaseUI then
            return t.GetMainControlBaseUI()
        end
    end
    return nil
end

local function hook_all()
    local baseUI = get_base_ui()
    if not slua.isValid(baseUI) then return 0 end
    local n = 0
    if hard_hook(baseUI.TextBlock_BID,  "d_BID")  then n = n + 1 end
    if hard_hook(baseUI.TextBlock_Hour, "d_Hour") then n = n + 1 end
    if slua.isValid(baseUI.UIRoot) then
        if hard_hook(baseUI.UIRoot.TextBlock_BID,  "n_BID")  then n = n + 1 end
        if hard_hook(baseUI.UIRoot.TextBlock_Hour, "n_Hour") then n = n + 1 end
    end
    return n
end

-- ============================================================
-- 9. Poll — apply + re-hook widget recreate
-- ============================================================
local function schedule(delay, fn)
    if type(AddGameTimer) == "function" then
        if pcall(AddGameTimer, delay, false, fn) then return true end
    end
    if slua_GameFrontendHUD and slua_GameFrontendHUD.AddTimer then
        if pcall(function() slua_GameFrontendHUD:AddTimer(delay, false, fn) end) then return true end
    end
    if type(SetTimer) == "function" then
        if pcall(SetTimer, delay, fn) then return true end
    end
    return false
end

local tries = 0
local function poll()
    tries = tries + 1
    local baseUI = get_base_ui()
    if slua.isValid(baseUI) then
        hard_hook(baseUI.TextBlock_BID,  "d_BID")
        hard_hook(baseUI.TextBlock_Hour, "d_Hour")
        if slua.isValid(baseUI.UIRoot) then
            hard_hook(baseUI.UIRoot.TextBlock_BID,  "n_BID")
            hard_hook(baseUI.UIRoot.TextBlock_Hour, "n_Hour")
        end
        -- belt-suspenders: apply trực tiếp phòng hook fail
        apply_bid(baseUI.TextBlock_BID)
        apply_bid(baseUI.TextBlock_Hour)
        if slua.isValid(baseUI.UIRoot) then
            apply_bid(baseUI.UIRoot.TextBlock_BID)
            apply_bid(baseUI.UIRoot.TextBlock_Hour)
        end
    end
    if tries == 1 then
        log("first poll: " .. tostring(hook_all()) .. " hook(s)")
    elseif tries % 120 == 0 then
        log("poll alive try#" .. tries)
    end
    schedule(0.5, poll)
end

hook_all()
schedule(0.5, poll)
log("FINAL loaded — SetText hooked, Hour sẽ không bị đè nữa")
end)
