-- ============================================================
-- SRC FAKE DISPLAY NAME / ID (adapted to LexusConfig)
-- ============================================================
function _G.ChanInstallIdentityAndProfile()
  do
    local S = {
      Budget = 96,
      MaxNodes = 4096,
      Fields = { 'TextBlock_Name', 'TextBlock_PlayerName', 'Text_PlayerName', 'Text_Name', 'TextName',
      'PlayerName', 'TeammateNameText', 'UTRichTextBlock_Name', 'TextBlock_UID', 'Text_UID', 'Text_ID',
      'TextBlock_ID', 'TextBlock_Player', 'TextBlock_Teammate_Name', 'TextBlock_NickName', 'TextBlock_Nickname',
      'UTRichTextBlock_Nickname', 'TextBlock_Player2', 'TextBlock_PlayerID', 'TextBlock_MyName', 'nameText',
      'NameTexBlock_1', 'Text_Name01', 'Text_Name02', 'TextBlock_PlayerName01', 'TextBlock_PlayerName02',
      'TextBlock_Name_1', 'TextBlock_Name_2', 'targetName', 'TextMessage' }
    }
    _G.OwenIdentityScan = S
    local function read(o, k)
      local ok, v = pcall(function()
        return o and o[k]
      end);
      if ok then
        return v
      end
    end
    S.SCENE_FIGHT_KEYS = { 'IsInFightingNotMainCity', 'IsInFightingStatus' }
    function S.Scene()
      local now = (_G.RealNow and _G.RealNow()) or os.clock()
      if S.SceneValue ~= nil and now < (S.SceneUntil or 0) then
        return S.SceneValue
      end
      local value = 'unknown'
      local failed = false
      local status = _G.GameStatus
      if type(status) == 'table' then
        for _, key in ipairs(S.SCENE_FIGHT_KEYS) do
          local fn = status[key]
          if type(fn) == 'function' then
            local ok, v = pcall(fn)
            if not ok then
              value = 'unknown';
              failed = true;
              break
            end
            if v == true or v == 1 then
              value = 'match';
              break
            end
          end
        end
        if not failed and value == 'unknown' and type(status.IsInLobbyOrMainCity) == 'function' then
          local ok, v = pcall(status.IsInLobbyOrMainCity)
          if ok and (v == true or v == 1) then
            value = 'lobby'
          end
        end
      end
      S.SceneValue = value;
      S.SceneUntil = now + 0.1
      return value
    end
    local function visible(ui)
      local show = read(ui, 'IsShow')
      if type(show) == 'function' then
        local ok, v = pcall(show, ui);
        return ok and (v == true or v == 1)
      end
      local root = read(ui, 'UIRoot') or ui
      local fn = read(root, 'IsVisible')
      if type(fn) == 'function' then
        local ok, v = pcall(fn, root);
        return ok and (v == true or v == 1)
      end
      return true
    end
    function S.Configs(manager)
      local now = (_G.RealNow and _G.RealNow()) or os.clock()
      if S.Manager == manager and S.ConfigMap and now < (S.ConfigUntil or 0) then
        return S.ConfigMap
      end
      local map = {}
      for _, spec in ipairs( {
{ manager.UI_Config, 'lobby' },
{ manager.UI_Config_InGame, 'match' }
      }) do
        if type(spec[1]) == 'table' then
          for key, entry in pairs(spec[1]) do
            map[key] = spec[2]
            local name = read(entry, 'keyName');
            if name then
              map[name] = spec[2]
            end
          end
        end
      end
      S.Manager = manager;
      S.ConfigMap = map;
      S.ConfigUntil = now + 5
      return map
    end
    local function phase(ui, key, map)
      local config = read(ui, '_config');
      local name = read(config, 'keyName')
      if name and map[name] then
        return map[name]
      end
      if map[key] then
        return map[key]
      end
      local combat = read(ui, 'bIsInCombatState')
      if type(combat) == 'boolean' then
        return combat and 'match' or 'lobby'
      end
    end
    local function uidValue(o)
      for _, key in ipairs( { 'UID', 'uid', 'playerUID', 'PlayerUID', 'roleUID', 'RoleUID' }) do
        local v = read(o, key)
        if (type(v) == 'string' or type(v) == 'number') and tostring(v):match('^%d+$') and tonumber(v) ~= 0 then
          return tostring(v)
        end
      end
    end
    function S.Owner(widget, inherited, rootKey)
      local own = _G.DataMgr and _G.DataMgr.roleData and _G.DataMgr.roleData.uid
      if own == nil then
        return nil
      end;
      own = tostring(own)
      local found = uidValue(widget)
      for _, key in ipairs( { 'uPlayerState', 'PlayerState', 'profile', 'playerData', 'roleData', 'data' }) do
        local uid = uidValue(read(widget, key))
        if uid then
          found = uid;
          break
        end
      end
      if found then
        return found == own
      end
      local root = read(widget, 'UIRoot') or widget
      local label = read(root, 'TextBlock_PlayerID')
      local getter = read(label, 'GetText')
      if type(getter) == 'function' then
        local ok, v = pcall(getter, label);
        v = ok and tostring(v)
        local changed = _G.OwenFakeDisplayUID and _G.OwenFakeDisplayUID.Changed[label]
        if changed and v == changed.Alias then
          v = changed.Original
        end
        if v and v:match('^%d+$') then
          return v == own
        end
      end
      local cfg = read(widget, '_config');
      local name = read(cfg, 'keyName') or rootKey
      if name == 'Lobby_Mid_Message_UIBP' then
        return true
      end
      return inherited
    end
    function S.Run(N, manager, rewrite)
      local scene = S.Scene()
      if N.Scene ~= scene then
        N.Restore();
        N.Scan = nil;
        N.Scene = scene
      end
      if scene == 'unknown' then
        N.Scan = nil;
        N.ScanStatus = 'scene_pending';
        return
      end
      if N.CompletedScene == scene then
        return
      end
      local map = S.Configs(manager);
      local scan = N.Scan
      if not scan or scan.Manager ~= manager then
        scan = {
          Manager = manager,
          Queue = {},
          Head = 1,
          Seen = {},
          Count = 0
        };
        N.Scan = scan
        local instances
        if type(manager.GetUIInstances) == 'function' then
          local ok, v = pcall(manager.GetUIInstances);
          if ok and type(v) == 'table' then
            instances = v
          end
        end
        local roots = {}
        local function root(ui, key)
          if ui and not roots[ui] and phase(ui, key, map) == scene and visible(ui) then
            roots[ui] = true;
            scan.Queue[ # scan.Queue + 1] = { ui, 0, nil, nil, key }
          end
        end
        if instances then
          for key, ui in pairs(instances) do
            root(ui, key)
          end
        end
        local config = scene == 'match' and manager.UI_Config_InGame or manager.UI_Config
        if not instances and type(config) == 'table' and type(manager.GetUI) == 'function' then
          for key, entry in pairs(config) do
            local ok, ui = pcall(manager.GetUI, entry);
            if ok then
              root(ui, key)
            end
          end
        end
      end
      local currentOwner, currentContext
      local function enqueue(widget, depth, field)
        if (type(widget) == 'table' or type(widget) == 'userdata') and depth <= 12 and not scan.Seen[widget] and # scan.Queue < S.MaxNodes then
          scan.Seen[widget] = true;
          scan.Queue[ # scan.Queue + 1] = { widget, depth, field, currentContext }
        end
      end
      local processed = 0
      while scan.Head <= # scan.Queue and processed < S.Budget do
        local item = scan.Queue[scan.Head];
        scan.Head = scan.Head + 1
        local widget, depth, field = item[1], item[2], item[3]
        processed = processed + 1
        local inherited;
        local context = item[4]
        while context do
          local owner = S.Owner(context.Widget, nil, context.RootKey)
          if owner ~= nil then
            inherited = owner;
            break
          end
          context = context.Parent
        end
        if field == 'targetName' or field == 'TextMessage' or field == 'TextBlock_PlayerName01' or field == 'TextBlock_PlayerName02' then
          inherited = nil
        end
        currentOwner = S.Owner(widget, inherited, item[5])
        currentContext = { Widget = widget, Parent = item[4], RootKey = item[5] }
        local allowed = phase(widget, nil, map)
        local skip = (allowed and allowed ~= scene) or not visible(widget) or currentOwner == false
        local state = read(widget, 'uPlayerState')
        if state and read(widget, 'sTeammatePlayerName') ~= nil then
          local uid = read(state, 'UID');
          local own = _G.DataMgr and _G.DataMgr.roleData and _G.DataMgr.roleData.uid
          if uid ~= nil and own ~= nil and tostring(uid) ~= tostring(own) then
            skip = true
          end
        end
        if not skip then
          local get, set = read(widget, 'GetText'), read(widget, 'SetText')
          if type(get) == 'function' and type(set) == 'function' then
            if not read(widget, 'OnTextChanged') then
              local ok, text = pcall(get, widget)
              if not field then
                local fn = read(widget, 'GetName');
                if type(fn) == 'function' then
                  local success, v = pcall(fn, widget);
                  if success then
                    field = tostring(v)
                  end
                end
              end
              if ok and text ~= nil then
                local original = tostring(text);
                local replacement = rewrite(original, field, currentOwner)
                if replacement and replacement ~= original and pcall(set, widget, replacement) then
                  N.Changed[widget] = { Original = original, Alias = replacement };
                  if _G.OwenNameAudit then
                    pcall(_G.OwenNameAudit.Applied, N, widget, original, replacement, 'scoped_scan')
                  end
                end
              end
            end
          else
            enqueue(read(widget, 'UIRoot'), depth + 1)
            for _, key in ipairs( { 'TeamItemList', '_childUIList' }) do
              local values = read(widget, key)
              if type(values) == 'table' then
                local n = 0;
                for _, v in pairs(values) do
                  n = n + 1;
                  if n > 128 then
                    break
                  end;
                  enqueue(v, depth + 1)
                end
              end
            end
            local getRoot = read(widget, 'GetRootWidget')
            if type(getRoot) == 'function' then
              local ok, v = pcall(getRoot, widget);
              if ok then
                enqueue(v, depth + 1)
              end
            end
            enqueue(read(read(widget, 'WidgetTree'), 'RootWidget'), depth + 1)
            local lookup = read(widget, 'GetWidgetFromName')
            for _, key in ipairs(S.Fields) do
              enqueue(read(widget, key), depth + 1, key)
              if type(lookup) == 'function' then
                local ok, v = pcall(lookup, widget, key);
                if ok then
                  enqueue(v, depth + 1, key)
                end
              end
            end
            local total, child = read(widget, 'GetChildrenCount'), read(widget, 'GetChildAt')
            if type(total) == 'function' and type(child) == 'function' then
              local ok, n = pcall(total, widget)
              if ok and type(n) == 'number' then
                for i = 0, math.min(n, 128) - 1 do
                  local success, v = pcall(child, widget, i);
                  if success then
                    enqueue(v, depth + 1)
                  end
                end
              end
            end
            if type(widget) == 'table' then
              local n = 0
              for key, v in pairs(widget) do
                n = n + 1;
                if n > 128 then
                  break
                end
                if type(key) == 'string' and (key:find('Text', 1, true) or key:find('Name', 1, true) or key:lower():find('uid', 1, true)) then
                  enqueue(v, depth + 1, key)
                end
              end
            end
          end
        end
      end
      N.LastVisited = processed;
      scan.Count = scan.Count + processed
      N.ScanStatus = scan.Head > # scan.Queue and 'cycle_complete' or 'scanning'
      if scan.Head > # scan.Queue then
        N.Scan = nil;
        N.CompletedScene = scene
        local R = _G.OwenRuntimeGuard
        if R and N.TimerKey then
          R.Stop(N.TimerKey)
        end
      end
    end
  end
  _G.OwenNameAudit = {
    Next = 0,
    Rows = 0,
    Limit = 500,
    Bytes = 0,
    Cursors = {},
    WriteAfter = {},
    Recent = setmetatable( {}, { __mode = 'k' })
  }
  do
    local A = _G.OwenNameAudit
    local function enabled(kind)
      local c = _G.LexusConfig or {};
      local value = kind == 'uid' and c.FakeDisplayUID or c.FakeDisplayName
      if kind == 'uid' then
        value = c.FakeDisplayUID
      end
      return value == true or value == 1
    end
    local function identity(N)
      if N == _G.OwenFakeDisplayName then
        return 'name'
      end
      if N == _G.OwenFakeDisplayUID then
        return 'uid'
      end
    end
    local function clean(v)
      return tostring(v or ''):gsub('[%c]', ' '):sub(1, 160)
    end
    function A.Record()
    end
    function A.Applied(N, widget, before, after, source)
      local kind = identity(N);
      if not kind or not enabled(kind) then
        return
      end
      local row = N.Changed[widget];
      if row then
        row.AuditText = tostring(after)
      end
      A.Record('fake_' .. kind .. '_applied', widget, before, after, source, kind)
    end
    function A.Native(N, widget, source)
      local kind = identity(N);
      if not kind or not enabled(kind) then
        return
      end
      local row = N.Changed[widget]
      if not row then
        return
      end
      local ok, text = pcall(function()
        return tostring(widget:GetText())
      end)
      if ok and text ~= row.Alias then
        A.Record('native_refresh_replaced_' .. kind, widget, row.Alias, text, source, kind)
        row.AuditText = text
      end
    end
    function A.Tick()
    end
