      if _G.OwenIdentityEvents then
        _G.OwenIdentityEvents.Sync()
      end
      local R = _G.OwenRuntimeGuard;
      if not R then
        return
      end
      local cfg = _G.LexusConfig or {} _DISPLAY_TIMER_SPECS[1][3] = _G.OwenFakeDisplayName
      _DISPLAY_TIMER_SPECS[2][3] = _G.OwenFakeDisplayUID
      _G.OwenDisplayLastScene = _G.OwenIdentityScan and _G.OwenIdentityScan.Scene() or "unknown"
      for _, spec in ipairs(_DISPLAY_TIMER_SPECS) do
        local enabled = cfg[spec[2]] == true or cfg[spec[2]] == 1
        local object = spec[3]
        if object then
          if enabled then
            object.TimerKey = spec[1]
            local scene = _G.OwenIdentityScan.Scene()
            if object.Scene ~= scene then
              object.Restore();
              object.Scene = scene
            end
            local scanAllowed = scene == 'lobby' or scene == 'match'
            if not scanAllowed then
              object.Scan = nil
              object.ScanStatus = 'scene_pending'
            end
            local now = (_G.RealNow and _G.RealNow()) or os.clock()
            if object.RetryScene ~= scene then
              object.RetryScene = scene;
              object.RetryCount = 0;
              object.RetryAt = now + 2
            end
            if scanAllowed and enabled and scene ~= 'unknown' and object.CompletedScene == scene and (object.RetryCount or 0) < 3 and now >= (object.RetryAt or 0) then
              object.CompletedScene = nil;
              object.Scan = nil
              object.RetryCount = (object.RetryCount or 0) + 1;
              object.RetryAt = now + 5
            end
            if ( not scanAllowed or object.CompletedScene == scene) and R.Loops[spec[1]] then
              R.Stop(spec[1])
            end
            if scanAllowed and scene ~= 'unknown' and object.CompletedScene ~= scene and not R.Loops[spec[1]] then
              R.Start(spec[1], 0.5, object.Tick, 1.0)
            end
          else
            if R.Loops[spec[1]] then
              R.Stop(spec[1])
            end
            if object.Scan or next(object.Changed) then
              object.Restore()
            end
          end
        end
      end
      local anyEnabled = (cfg.FakeDisplayName == true or cfg.FakeDisplayName == 1)
          or (cfg.FakeDisplayUID == true or cfg.FakeDisplayUID == 1)
      if anyEnabled then
        if not R.Loops.LocalDisplaySceneWatch then
          R.Start("LocalDisplaySceneWatch", 1.0, function()
            local live = _G.LexusConfig or {}
            if not (live.FakeDisplayName == true or live.FakeDisplayName == 1
                or live.FakeDisplayUID == true or live.FakeDisplayUID == 1) then
              R.Stop("LocalDisplaySceneWatch")
              return
            end
            local scene = _G.OwenIdentityScan and _G.OwenIdentityScan.Scene() or "unknown"
            if scene ~= _G.OwenDisplayLastScene then _G.OwenSyncDisplayTimers() end
          end, 1.0)
        end
      else
        R.Stop("LocalDisplaySceneWatch")
      end
    end
    _G.OwenSyncDisplayTimers()
  end

