    local function enabled()
      local value = (_G.LexusConfig or {}).ProfileCustomization
      return inLobby() and (value == true or value == 1)
    end
    local function custom()
      _G.LexusState = _G.LexusState or {};
      _G.LexusState.CustomTextData = _G.LexusState.CustomTextData or {}
      return _G.LexusState.CustomTextData
    end
    local function config(g, id)
      if not CDataTable then
        return nil
      end
      if CDataTable.GetTableData then
        for _, key in ipairs( { id, tostring(id) }) do
          local ok, row = pcall(CDataTable.GetTableData, g.Table, key)
          if ok and (type(row) == 'table' or type(row) == 'userdata') then
            return row
          end
        end
      end
      return g.NativeById and g.NativeById[id]
    end
    function P:Choices(g)
      local now = os.clock()
      if g.Choices and now < (g.ChoicesUntil or 0) then
        return g.Choices
      end
      local raw
      if CDataTable and CDataTable.GetTable then
        local ok, result = pcall(CDataTable.GetTable, g.Table);
        if ok then
          raw = result
        end
      end
      local byId = {}
      if raw then
        pcall(function()
          for key, row in pairs(raw) do
            if type(row) == 'table' or type(row) == 'userdata' then
              local id = tonumber(row.SkinID or row.ID or row.ItemID or row.PlanID)
              if not id and type(key) == 'string' then
                id = tonumber(key)
              end
              if id and id > 0 then
                byId[id] = row
              end
            end
          end
        end)
      end
      g.NativeById = byId
      local rows, seen = {}, {}
      for _, item in ipairs(g.Items) do
        if config(g, item[1]) then
          rows[ # rows + 1] = item;
          seen[item[1]] = true
        end
      end
      for id, row in pairs(byId) do
        if not seen[id] then
          rows[ # rows + 1] = { id, tostring(row.Name or row.ItemName or row.AliasName or (g.En .. ' ' .. id)) }
        end
      end
      table.sort(rows, function(a, b)
        return a[1] < b[1]
      end)
      g.Choices = rows;
      g.ChoicesUntil = now + (next(byId) and 30 or 2);
      return rows
    end
    local function module(key, common)
      local MM = require('client.module_framework.ModuleManager')
      local list = common and MM.CommonModuleConfig or MM.LobbyModuleConfig
      local token = list and list[key]
      return token and MM.GetModule(token)
    end
    local function event(name, ...)
      if EventSystem and EVENTTYPE_ROLEINFO and _G[name] then
        EventSystem:postEvent(EVENTTYPE_ROLEINFO, _G[name], ...)
      end
    end
    function P:RefreshLobbyIdentity()
      local d = DataMgr and DataMgr.roleData;
      if not d then
        return
      end
      pcall(function()
        local info = require('client.logic.roleinfo.logic_roleinfo')
        local basic = info.PersonalBasicInfo
        if basic then
          basic.role_avatar = d.headIconUrl;
          basic.role_avatar_frame = d.cur_avatar_box_id
        end
      end)
      local function post(kind, id, ...)
        if kind and id and EventSystem then
          pcall(EventSystem.postEvent, EventSystem, kind, id, ...)
        end
      end
      post(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_HEAD_INFO, d.headIconUrl)
      post(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_AVATAR_FRAME_INFO)
      post(EVENTTYPE_LOBBY, EVENTID_UPDATE_LOBBY_AVATAR)
      post(EVENTTYPE_LOBBY_SOCIAL, EVENTID_LOBBY_SOCIAL_UPDATE_HEAD_ICON)
      post(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_AVATAR_PORTRAIT)
    end
    local function profile()
      local m = module('logic_profile')
      local hook = P.Native and P.Native.ProfileGetter
      if m and hook and hook.Object == m then
        return hook.Original(m, DataMgr.roleData.uid)
      end
      return m and m.GetLocalProfile and m:GetLocalProfile(DataMgr.roleData.uid)
    end
    local function state(g)
      local d = DataMgr and DataMgr.roleData
      if not d or not d.uid then
        return nil
      end
      local ok, cached = pcall(profile)
      local localProfile = ok and cached or {} localProfile = localProfile or {}
      if g.Key == 'Avatar' then
        if type(DataMgr.UpdateHeadIconUrl) ~= 'function' then
          return nil
        end
        return { Read = function()
          return d.headIconUrl
        end, Write = function(id)
          DataMgr.UpdateHeadIconUrl(tostring(id));
          localProfile.picUrl = tostring(id)
          event('EVENTID_ROLEINFO_UPDATE_USE_AVATAR');
          event('EVENTID_ROLEINFO_UPDATE_HEAD_INFO', tostring(id))
        end }
      elseif g.Key == 'AvatarFrame' then
        if type(DataMgr.UpdateAvatarBoxId) ~= 'function' then
          return nil
        end
        return { Read = function()
          return d.cur_avatar_box_id
        end, Write = function(id)
          DataMgr.UpdateAvatarBoxId(id);
          localProfile.cur_avatar_box_id = id
          local info = require('client.logic.roleinfo.logic_roleinfo')
          if info.PersonalBasicInfo then
            info.PersonalBasicInfo.role_avatar_frame = tonumber(id)
          end
          event('EVENTID_ROLEINFO_UPDATE_AVATAR_FRAME_INFO')
        end }
      elseif g.Key == 'Title' then
        if not d.alias then
          return nil
        end
        return {
          Read = function()
            return { id = d.alias.id, title = d.alias.title, nation = d.alias.nation, rank_id = d.alias.rank_id }
          end,
          Matches = function(id)
            return tonumber(d.alias.id) == id
          end,
          Write = function(id, row)
            if type(id) == 'table' then
              for key,
              value in pairs(id) do
                d.alias[key] = value
              end
            else
              d.alias.id = id;
              d.alias.title = row and row.AliasName or '';
              d.alias.nation = '';
              d.alias.rank_id = 0
            end
            localProfile.alias = localProfile.alias or {};
            for key,
            value in pairs(d.alias) do
              localProfile.alias[key] = value
            end
            local info = require('client.logic.roleinfo.logic_roleinfo')
            if info.PersonalBasicInfo then
              info.PersonalBasicInfo.role_aliasId = d.alias.id;
              info.PersonalBasicInfo.role_aliasTitle = d.alias.title
            end
            event('EVENTID_ROLEINFO_UPDATE_ALL_TITLE')
          end
        }
      elseif g.Key == 'NameTag' then
        if type(d.nameFrameData) ~= 'table' then
          return nil
        end
        local nm = require('client.slua.logic.person_space.logic_roleinfo_nameframe')
        return {
          Read = function()
            local old = {
              Used = nm.nUsedID,
              Rows = {}
            }
            for id,
            row in pairs(d.nameFrameData) do
              old.Rows[id] = row.is_used
            end
            return old
          end,
          Matches = function(id)
            return nm.nUsedID == id and tonumber(localProfile.brand_id) == id and d.nameFrameData[id] and d.nameFrameData[id].is_used == 1
          end,
          Write = function(id)
            if type(id) == 'table' then
              for key,
              row in pairs(d.nameFrameData) do
                if id.Rows[key] ~= nil then
                  row.is_used = id.Rows[key]
                elseif row._OwenProfileSynthetic then
                  d.nameFrameData[key] = nil
                end
              end
              nm.nUsedID = id.Used
            else
