          end,
          Matches = function(id)
            return m:GetEquipedOpeningID() == id and d.social_card and d.social_card.social_info_bg and ENUM_ITEM_SUBTYPE and d.social_card.social_info_bg[ENUM_ITEM_SUBTYPE.PersonalOpening] == id
          end,
          Write = function(id)
            local restore = type(id) == 'table' m:SetCurrentOpeningItemID(restore and id.Current or id)
