    local function copy(t)
      local out = {};
      for key, value in pairs(t or {}) do
        if type(value) == 'table' then
          local row = {};
          for k, v in pairs(value) do
            row[k] = v
          end;
          out[key] = row
        else
          out[key] = value
        end
      end;
      return out
    end
    local function overlay(obj, field, build, refresh)
      local slots = N.Overlays[obj];
      if not slots then
        slots = {};
        N.Overlays[obj] = slots
      end
      local old = slots[field]
      if old and obj[field] == old.Value and not refresh then
        return
      end
      local original = obj[field]
      if old and obj[field] == old.Value then
        original = old.Original
      end
      local value = build(copy(obj[field]))
      slots[field] = { Original = original, Value = value };
      obj[field] = value
    end
    local function restore(obj)
      local slots = N.Overlays[obj] or {}
      if slots.FrameMap then
        obj.FrameList = nil
      end
      if slots.CarteFrameMap then
        obj.CarteFrameList = nil
      end
      for field, row in pairs(N.Overlays[obj] or {}) do
        if obj[field] == row.Value then
          local marks = {}
          if field == 'nameFrameData' then
            for id, item in pairs(obj[field] or {}) do
              marks[id] = item.is_used
            end
          end
          obj[field] = row.Original
          if field == 'nameFrameData' then
            for id, item in pairs(obj[field] or {}) do
              if item._OwenProfileSynthetic then
                obj[field][id] = nil
              elseif marks[id] ~= nil then
                item.is_used = marks[id]
              end
            end
          end
        end
      end
      N.Overlays[obj] = nil
    end
    local function prepare(g, obj, refresh)
      local baseOverlay = overlay
      local function overlay(target, field, build)
        return baseOverlay(target, field, build, refresh)
      end
      if not enabled() then
        restore(obj);
        return
      end
      local def = definitions[g.Key]
      if not g.NativeRows or os.clock() >= (g.NativeRowsUntil or 0) then
        g.NativeRows = P:Choices(g);
        g.NativeRowsUntil = g.ChoicesUntil or (os.clock() + 2)
      end
      local rows = g.NativeRows
      if # rows == 0 then
        return
      end
      if g.Key == 'Avatar' then
        overlay(obj, 'HeadportraitList', function(out)
          for _, row in ipairs(rows) do
            if row[1] ~= 10002 then
              out[tostring(row[1])] = 1
            end
          end;
          return out
        end)
      elseif g.Key == 'AvatarFrame' then
        overlay(obj, 'AvatarFrameList', function(out)
          for _, row in ipairs(rows) do
            out[row[1]] = { expire_time = 1 }
          end;
          return out
        end)
      elseif g.Key == 'NameTag' then
        local d = DataMgr and DataMgr.roleData
        if d then
          overlay(d, 'nameFrameData', function(out)
            for _, row in ipairs(rows) do
              out[row[1]] = out[row[1]] or { id = row[1], expire_ts = 0, is_used = 0 }
            end;
            return out
          end)
        end
      elseif g.Key == 'Title' then
        overlay(obj, 'alias_list_info', function(out)
          for _, row in ipairs(rows) do
            local cfg = config(g, row[1])
            out[row[1]] = out[row[1]] or {
              state = 1,
              title = cfg.AliasName or row[2],
              rank = 0,
              rank_id = 0,
              ext_info = {},
              receive_time = 0,
              expire_ts = 0
            }
          end;
          return out
        end)
        local current = DataMgr and DataMgr.roleData and DataMgr.roleData.alias and tonumber(DataMgr.roleData.alias.id)
        local saved = tonumber(custom().SkinProfileTitleID)
        if saved and (saved == 0 or config(g, saved)) then
          current = saved
        end
        for _, row in ipairs(rows) do
          local item = obj.alias_list_info[row[1]];
          item.state = row[1] == current and 2 or 1;
          item.expire_ts = 0
        end
      elseif def.Field then
        overlay(obj, def.Field, function(out)
          for _, row in ipairs(rows) do
            local cfg = config(g, row[1]);
            out[row[1]] = out[row[1]] or { config = cfg }
            out[row[1]].bLock = false;
            out[row[1]].bRed = false;
            out[row[1]].expire_ts = 0
          end;
          return out
        end)
        if g.Key == 'InfoCard' then
          obj.CarteFrameList = nil
        else
          obj.FrameList = nil
        end
      elseif g.Key == 'NicknameEffect' or g.Key == 'ChatBubble' then
        local cfgField = g.Key == 'NicknameEffect' and 'friend_nickname_skin_cfg' or 'chat_bubble_cfg' overlay(obj, 'unlockData', function(out)
          for _, row in ipairs(rows) do
            out[row[1]] = { expire_ts = 0 }
          end;
          return out
        end)
        overlay(obj, cfgField, function(out)
          for index, row in ipairs(rows) do
            out[row[1]] = out[row[1]] or { is_show = 1, start_display_ts = 0, display_order = index,
            access_display_ts = 0 }
          end
          return out
        end)
        overlay(obj, 'showDataList', function()
          local out = {};
          local current = tonumber(custom()['SkinProfile' .. g.Key .. 'ID']) or tonumber((DataMgr and DataMgr.roleData or {})[g.Key == 'NicknameEffect' and 'friend_nickname_skin' or 'chat_bubble'])
          for index, row in ipairs(rows) do
            local cfg = config(g, row[1]);
            out[ # out + 1] = { ID = row[1], BPPath = cfg.BPPath or '', GetDescID = cfg.GetDescID, GetJumpUrl = cfg.GetJumpUrl,
            bIsLock = false, bIsUse = row[1] == current, bReddot = false, expire_ts = 0, display_order = index,
            access_display_ts = 0, levelType = cfg.LevelType, level = cfg.Level }
          end
          return out
        end)
      end
    end
    function N:Hook(obj, name, g, mode)
      local original = obj and obj[name];
      if type(original) ~= 'function' then
        return
      end
      self.Hooks[obj] = self.Hooks[obj] or {}
      if self.Hooks[obj][name] and obj[name] == self.Hooks[obj][name].Wrapper then
        return
      end
      local def = definitions[g.Key]
      local static = mode ~= 'view' and def.Static
      local wrapper = function( ...)
        if not enabled() then
          restore(obj);
          return original( ...)
        end
        local args = { ... };
        local index = static and 1 or 2
        local id = tonumber(args[index])
        if mode == 'card_response' then
          local saved = tonumber(custom().SkinProfileInfoCardID)
          if tonumber(args[2]) == 0 and saved and saved > 0 and config(g, saved) then
            args[4] = saved
          end
          return original((table.unpack or unpack)(args, 1, select('#', ...)))
        elseif mode == 'effect_response' then
          local saved = tonumber(custom()['SkinProfile' .. g.Key .. 'ID'])
          if saved and saved > 0 and config(g, saved) and type(args[2]) == 'table' then
            args[2] = copy(args[2]);
            args[2].equip = saved
          end
          return original((table.unpack or unpack)(args, 1, select('#', ...)))
        elseif mode == 'effect_change' then
          local saved = tonumber(custom()['SkinProfile' .. g.Key .. 'ID'])
          if saved and saved > 0 and config(g, saved) then
            args[2] = saved
          end
          return original((table.unpack or unpack)(args, 1, select('#', ...)))
        elseif mode == 'response' and tonumber(args[1]) == 0 and type(args[2]) == 'table' then
          local source = args[2];
          local value = copy(source)
          for _, row in ipairs(P:Choices(g)) do
            if g.Key == 'Avatar' then
              if row[1] ~= 10002 then
                value[tostring(row[1])] = 1
              end
            else
              value[row[1]] = { expire_time = 1 }
            end
          end
          N.Overlays[obj] = N.Overlays[obj] or {} N.Overlays[obj][def.Field] = { Original = source, Value = value }
          args[2] = value
          local saved = tonumber(custom()['SkinProfile' .. g.Key .. 'ID'])
          if saved and saved > 0 and config(g, saved) then
            args[3] = g.Key == 'Avatar' and tostring(saved) or saved
          end
          return original((table.unpack or unpack)(args, 1, select('#', ...)))
        elseif mode == 'view' then
          local ok, err = pcall(function()
            local target = def.Path and require(def.Path) or module(def.Module, def.Common)
            if target then
              prepare(g, target, true)
            end
          end)
          P.NativeErrors = P.NativeErrors or {};
          P.NativeErrors[g.Key] = not ok and tostring(err) or nil
          local result = original( ...)
          if type(result) == 'table' then
            for _, row in pairs(result) do
              if type(row) == 'table' then
                local rowId = tonumber(row.id or row.ID or row.SkinID or (row.config and row.config.SkinID))
                if rowId and config(g, rowId) then
                  if g.Key == 'Avatar' or g.Key == 'AvatarFrame' then
                    local d = DataMgr and DataMgr.roleData or {}
                    local current = g.Key == 'Avatar' and tonumber(d.headIconUrl) or tonumber(d.cur_avatar_box_id)
                    row.state = rowId == current and 3 or 1
                  elseif row.bLock ~= nil then
                    row.bLock = false
                  end
                end
              end
            end
          end
          return result
        elseif mode == 'has' then
          if id and config(g, id) then
            return true
          end
        elseif mode == 'select' then
          if id and (id == 0 or config(g, id)) then
            if args[index + 1] == false then
              id = 0
            end
            local accepted = P:Select(g.Key, id)
            if accepted then
              if g.Key == 'Title' and obj.initAliasInfo then
                prepare(g, obj, true);
                obj.initAliasInfo()
              end
              if g.Key == 'InfoCard' or g.Key == 'InfoCardFrame' or g.Key == 'SocialPlayerCardFrame' then
                if obj.SortFrameList then
                  obj:SortFrameList()
                elseif obj.SortCarteFrameList then
                  obj:SortCarteFrameList()
                end
              end
            end
            return accepted
          end
        elseif mode == 'list' then
          prepare(g, obj, true)
          if g.Key == 'InfoCard' and name == 'GetCarteFrameList' and obj.SortCarteFrameList then
            obj:SortCarteFrameList()
          end
          if g.Key == 'CollectionNickname' and name == 'GetAllColors' then
            local result = {};
            for _, row in ipairs(g.NativeRows or {}) do
              result[row[1]] = { expire_time = 1 }
            end;
            return result
          end
        end
        return original( ...)
      end
      obj[name] = wrapper;
      self.Hooks[obj][name] = { Original = original, Wrapper = wrapper }
    end
    function P:ProfileView(value, uid)
      local own = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
      local cfg = _G.LexusConfig or {}
      if not (cfg.ProfileCustomization == true or cfg.ProfileCustomization == 1) or not own or tostring(uid or (value and value.uid)) ~= tostring(own) or type(value) ~= 'table' then
        return value
      end
      local out = {};
      for k, v in pairs(value) do
        out[k] = v
      end
      for key, field in pairs( { Avatar = 'picUrl', AvatarFrame = 'cur_avatar_box_id', NameTag = 'brand_id',
      NicknameEffect = 'friend_nickname_skin', ChatBubble = 'chat_bubble' }) do
        local id = tonumber(custom()['SkinProfile' .. key .. 'ID'])
        if id and id > 0 and config(self.ByKey[key], id) then
          out[field] = key == 'Avatar' and tostring(id) or id
        end
      end
      local card = tonumber(custom().SkinProfileInfoCardID)
      if card and card > 0 and config(self.ByKey.InfoCard, card) then
        out.social_card = copy(value.social_card);
        out.social_card.carte_frame_equip_id = card
        out.social_card.carte_frame = copy(out.social_card.carte_frame)
        out.social_card.carte_frame[card] = { expire_ts = 0 }
      end
      return out
    end
    function P:SuspendNative()
      for obj, hooks in pairs(N.Hooks) do
        for name, h in pairs(hooks) do
          if obj[name] == h.Wrapper then
            obj[name] = h.Original
          end
        end
      end
      N.Hooks = setmetatable( {}, { __mode = 'k' })
      for obj in pairs(N.Overlays) do
        restore(obj)
      end
      local getter = N.ProfileGetter
      if getter and getter.Object.GetLocalProfile == getter.Wrapper then
        getter.Object.GetLocalProfile = getter.Original
      end
      N.ProfileGetter = nil
      for _, list in ipairs( {
        N.ProfileHooks or {},
        N.SocialProfileHooks or {}
      }) do
        for name, h in pairs(list) do
          if h.Object[name] == h.Wrapper then
            h.Object[name] = h.Original
          end
        end
      end
      N.ProfileHooks = {};
      N.SocialProfileHooks = {};
      for name, h in pairs(N.NicknameColorHooks or {}) do
        if h.Object and h.Object[name] == h.Wrapper then
          h.Object[name] = h.Original
        end
      end
      N.NicknameColorHooks = {}
      self.NativeInstallNext = 0
    end
    function P:InstallNative()
      if not enabled() then
        for _, g in ipairs(self.Groups) do
          pcall(self.Restore, self, g)
        end
        for obj in pairs(N.Overlays) do
          restore(obj)
        end
        return
      end
      local views = { Avatar = 'Avatar', AvatarFrame = 'AvatarFrame', Title = 'Title', NameTag = 'Teambrand',
      NicknameEffect = 'Nickname', ChatBubble = 'ChatBubble', InfoCard = 'InformationCard', SocialPlayerCard = 'SocialCard',
      InformationBackground = 'RoleInfoBG', MatchStartAnimation = 'Opening', InfoCardFrame = 'ProfileFrame',
      SocialPlayerCardFrame = 'SocialCardFrame' }
      self.NativeErrors = self.NativeErrors or {} pcall(function()
        local m = module('logic_profile');
        if not m or type(m.GetLocalProfile) ~= 'function' then
          return
        end
        if N.ProfileGetter and N.ProfileGetter.Object == m and m.GetLocalProfile == N.ProfileGetter.Wrapper then
          return
        end
        local original = m.GetLocalProfile
        local wrapper = function(self, uid, ...)
          local value = original(self, uid, ...)
          return P:ProfileView(value, uid)
        end
        m.GetLocalProfile = wrapper;
        N.ProfileGetter = { Object = m, Wrapper = wrapper, Original = original }
      end)
      pcall(function()
        local m = module('NicknameColorManager', true)
        if not m then return end
        N.NicknameColorHooks = N.NicknameColorHooks or {}
        local function savedColor()
          if not enabled() then return nil end
          local id = tonumber(custom().SkinProfileCollectionNicknameID)
          local g = P.ByKey.CollectionNickname
          if id and id > 0 and g and config(g, id) then return id end
          return nil
        end
        if type(m.GetUserData) == 'function' and type(m._ChanProfileOriginalGetUserData) ~= 'function' then
          m._ChanProfileOriginalGetUserData = m.GetUserData
        end
        local oldGet = m._ChanProfileOriginalGetUserData or m.GetUserData
        local getHook = N.NicknameColorHooks.GetUserData
        if type(oldGet) == 'function' and not (getHook and m.GetUserData == getHook.Wrapper) then
          local wrapper = function(self, uid, ...)
            local own = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
            local id = savedColor()
            if id and own and tostring(uid) == tostring(own) then
              return id
            end
            return oldGet(self, uid, ...)
          end
          m.GetUserData = wrapper
          N.NicknameColorHooks.GetUserData = { Object = m, Original = oldGet, Wrapper = wrapper }
        end
        local oldRsp = m.on_get_collect_award_privilege_rsp
        local rspHook = N.NicknameColorHooks.on_get_collect_award_privilege_rsp
        if type(oldRsp) == 'function' and not (rspHook and m.on_get_collect_award_privilege_rsp == rspHook.Wrapper) then
          local wrapper = function(self, data, ...)
            local result = oldRsp(self, data, ...)
            local own = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
            local id = savedColor()
            if id and own then
              self.msg_recolor = self.msg_recolor or {}
