              if type(data) == 'table' then
                data.msg_recolor = data.msg_recolor or {}
                data.msg_recolor.all_colors = data.msg_recolor.all_colors or {}
                data.msg_recolor.all_colors[id] = data.msg_recolor.all_colors[id] or { expire_time = 1 }
                data.msg_recolor.use_color = id
