      local apply, restore, selectChoice, tick, refresh = P.Apply, P.Restore, P.Select, P.Tick, P.RefreshLobbyIdentity
      function P:RefreshLobbyIdentity()
        if not lobby() then
          return false
        end
        local d = DataMgr and DataMgr.roleData;
