        end
        refresh(self)
        local ok, ui = pcall(require, 'client.slua_ui_framework.manager')
        if ok and ui and ui.GetUI and ui.UI_Config and ui.UI_Config.Lobby_Mid_Message_UIBP then
          local view = ui.GetUI(ui.UI_Config.Lobby_Mid_Message_UIBP)
          if view and view.UpdatePlayerAvatar then
            view:UpdatePlayerAvatar();
