          end
        end
        return false
      end
      function P:Apply(g, id)
        if not lobby() then
          return false
        end
        local d = DataMgr and DataMgr.roleData
        local old = d and (g.Key == 'Avatar' and d.headIconUrl or g.Key == 'AvatarFrame' and d.cur_avatar_box_id)
        local result = apply(self, g, id)
        if result and not self.IdentityBatch and (g.Key == 'Avatar' or g.Key == 'AvatarFrame') and tonumber(old) ~= tonumber(id) then
          pcall(self.RefreshLobbyIdentity, self)
        end
        return result
      end
      function P:Restore(g)
        if not lobby() then
          return false
        end;
        return restore(self, g)
      end
      function P:Select(key, id)
        if not lobby() then
          return false
        end
        local result = selectChoice(self, key, id)
        if result and (key == 'Avatar' or key == 'AvatarFrame' or key == 'NameTag') and lobby() then
          self.IdentityKey = nil;
          self.IdentityAttempts = 0 pcall(self.RefreshLobbyIdentity, self)
        end
        return result
      end
      function P:Tick()
        if not lobby() then
          self.LastLobby = false;
          self.IdentityKey = nil;
          self.IdentityAttempts = 0;
          return
        end
        local d = DataMgr and DataMgr.roleData
        if active() and d and d.uid then
          local choices = (_G.LexusState or {}).CustomTextData or {}
          local key = tostring(d.uid) .. ':' .. tostring(choices.SkinProfileAvatarID) .. ':' .. tostring(choices.SkinProfileAvatarFrameID) .. ':' .. tostring(choices.SkinProfileNameTagID)
          if self.IdentityKey ~= key then
            self.IdentityKey = key;
            self.IdentityAttempts = 0
          end
          if not tonumber(choices.SkinProfileAvatarID) and not tonumber(choices.SkinProfileAvatarFrameID) and not tonumber(choices.SkinProfileNameTagID) then
            self.IdentityAttempts = 8
          end
          if (self.IdentityAttempts or 0) < 8 then
            self.IdentityAttempts = (self.IdentityAttempts or 0) + 1
            local ready = true
            self.IdentityBatch = true
            for _, name in ipairs( { 'Avatar', 'AvatarFrame', 'NameTag' }) do
              local g = self.ByKey[name];
              local id = tonumber(choices['SkinProfile' .. name .. 'ID'])
              if g and id and id > 0 then
                local ok, result = pcall(self.Apply, self, g, id);
                ready = ready and ok and result
              end
            end
            self.IdentityBatch = nil
            local ok, shown = pcall(self.RefreshLobbyIdentity, self)
            if ready and ok and shown then
              self.IdentityAttempts = 8
            end
          end
        end
        return tick(self)
      end
    end
