-- ============================================================
-- BASE64 + URL ENCODE
-- ============================================================
local function Base64Encode(data)
    if type(data) ~= "string" or #data == 0 then return "" end
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local output, oi, i = {}, 0, 1

    while i <= #data - 2 do
        local a, b, c = string.byte(data, i, i + 2)
        local v = a * 65536 + b * 256 + c
        oi = oi + 1
        output[oi] = string.char(
            string.byte(alphabet, math.floor(v / 262144) + 1),
            string.byte(alphabet, math.floor(v / 4096) % 64 + 1),
            string.byte(alphabet, math.floor(v / 64) % 64 + 1),
            string.byte(alphabet, v % 64 + 1)
        )
        i = i + 3
    end

    local rem = #data - i + 1
    if rem == 2 then
        local a, b = string.byte(data, i, i + 1)
        local v = a * 65536 + b * 256
        oi = oi + 1
        output[oi] = string.char(
            string.byte(alphabet, math.floor(v / 262144) + 1),
            string.byte(alphabet, math.floor(v / 4096) % 64 + 1),
            string.byte(alphabet, math.floor(v / 64) % 64 + 1),
            string.byte("=")
        )
    elseif rem == 1 then
        local v = string.byte(data, i) * 65536
        oi = oi + 1
        output[oi] = string.char(
            string.byte(alphabet, math.floor(v / 262144) + 1),
            string.byte(alphabet, math.floor(v / 4096) % 64 + 1),
            string.byte("="),
            string.byte("=")
        )
    end
    return table.concat(output)
end

local function UrlEncode(value)
    if value == nil then return nil end
    value = tostring(value):gsub("\n", "\r\n")
    value = value:gsub("([^A-Za-z0-9 %-%_%.%~])", function(c)
        return string.format("%%%02X", string.byte(c))
    end)
    return value:gsub(" ", "+")
end

-- base64 cho body: escape +, /, = để không bị form-urlencoded phá
local function EscapeBase64(b64)
    b64 = b64:gsub("%+", "%%2B")
    b64 = b64:gsub("/", "%%2F")
    b64 = b64:gsub("=", "%%3D")
    return b64
end

-- ============================================================
-- RANK / PLAYER
-- ============================================================
local function GetRankName(rank)
    rank = tonumber(rank) or 0
    if rank <= 0 then return "Chưa xác định" end
    if rank < 1700 then return "Đồng"
    elseif rank < 2200 then return "Bạc"
    elseif rank < 2700 then return "Vàng"
    elseif rank < 3200 then return "Bạch Kim"
    elseif rank < 3700 then return "Kim Cương"
    elseif rank < 4200 then return "Cao Thủ"
    elseif rank < 4700 then return "Quán Quân"
    elseif rank < 5200 then return "Bậc Thầy Siêu Việt"
    elseif rank < 5600 then return "Người Thống Trị Siêu Việt"
    end
    return "Chí Tôn"
end

local function GetRankAndSegment()
    local rank, segment = 0, 0
    pcall(function()
        local br = _G.BP_STRUCT_BattleResultData
        local rating = br and (br.rating or br.BP_STRUCT_BTRating)
        if rating then
            rank    = tonumber(rating.rank_rating) or 0
            segment = tonumber(rating.new_segment) or 0
        end
        if rank == 0 then
            local funcUtil = GetModule("common.func_util")
            local roleData = _G.DataMgr and _G.DataMgr.roleData
            if funcUtil and type(funcUtil.GetCurMaxSegementLevel) == "function"
                and roleData and roleData.allzoneSegment then
                segment = tonumber(funcUtil.GetCurMaxSegementLevel(roleData.allzoneSegment)) or 0
            end
            if roleData and roleData.segment_rating then
                for _, v in pairs(roleData.segment_rating) do
                    if type(v) == "table" then
                        for _, nv in pairs(v) do
                            if type(nv) == "number" and nv > rank then rank = nv end
                        end
                    elseif type(v) == "number" and v > rank then
                        rank = v
                    end
                end
            end
        end
    end)
    return rank, segment
end

local function GetPlayerInfo()
    local roleData = _G.DataMgr and _G.DataMgr.roleData or nil
    local uid = nil
    local playerName = nil

    if type(roleData) == "table" or roleData ~= nil then
        pcall(function()
            uid = roleData.uid or roleData.UID or roleData.Uid
        end)
        -- Các tên trường thường gặp trong roleData; chỉ lấy giá trị chuỗi có thật.
        local nameKeys = {
            "nickname", "nickName", "nick_name", "playerName",
            "player_name", "roleName", "RoleName", "name", "Name"
        }
        for _, key in ipairs(nameKeys) do
            if playerName == nil or playerName == "" then
                pcall(function()
                    local value = roleData[key]
                    if type(value) == "string" and value ~= "" then
                        playerName = value
                    end
                end)
            end
        end
    end

    if (uid == nil or tostring(uid) == "") and _G._PNH_UK then
        uid = _G._PNH_UK
    end
    if (playerName == nil or playerName == "") and _G.LocalPlayerName then
        playerName = _G.LocalPlayerName
    end

    uid = uid ~= nil and tostring(uid) or "unknown"
    playerName = (type(playerName) == "string" and playerName ~= "")
        and playerName or "Chưa xác định"
    return playerName, uid
end

local function GetWinnerKills()
    local kills = 0
    pcall(function()
        local likeUtil = GetModule("GameLua.Mod.BaseMod.Client.Like.IngameLikeUtilClient")
        if likeUtil and type(likeUtil.GetMyPlayerState) == "function" then
            local ps = likeUtil.GetMyPlayerState()
            if ps and ps.Kills then kills = tonumber(ps.Kills) or 0 end
        end
        if kills == 0 then
            local rl = GetModule(
                "GameLua.Mod.BaseMod.Client.BattleResult.BattleResultData.BattleResultDataLogic",
                false)
            if rl and type(rl.GetBattleResultData) == "function" then
                local r = rl:GetBattleResultData()
                if r and r.BP_mykill then kills = tonumber(r.BP_mykill) or 0 end
            end
        end
    end)
    return kills
end

-- ============================================================
-- SCREENSHOT DIRECTORY
-- ============================================================
local function GetScreenshotDirectory()
    local dirs = {}
    local home = os.getenv("HOME")
    if home and home ~= "" then
        table.insert(dirs, home .. "/Documents/ShadowTrackerExtra/Saved/")
    end
    for _, pkg in ipairs({
        "com.tencent.ig","com.tencent.igce","com.vng.pubgmobile","com.pubg.krmobile",
        "com.rekoo.pubgm","com.pubg.imobile"
    }) do
        table.insert(dirs,
            "/storage/emulated/0/Android/data/" .. pkg
            .. "/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/")
    end
    local selected = dirs[1]
    for _, dir in ipairs(dirs) do
        local tp = dir .. "t.tmp"
        local f = io.open(tp, "w")
        if f then f:close(); os.remove(tp); selected = dir; break end
    end
    return selected
end

-- ============================================================
-- MATCH METADATA — map + mode, adapted from ChannLeak
-- ============================================================
local function GetMatchInfo()
    local mapName, modeName = "Chưa xác định", "Chưa xác định"
    local function read(obj, key)
        local ok, value = pcall(function() return obj and obj[key] end)
        if ok then return value end
    end
    local function call(obj, key, ...)
        local fn = read(obj, key)
        if type(fn) ~= "function" then return nil end
        local ok, value = pcall(fn, ...)
        if ok then return value end
    end
    local function localized(value)
        local id = tonumber(value)
        if id and id > 0 then
            local loc = rawget(_G, "LocUtil")
            for _, key in ipairs({"TryGetLocalizeResStr", "GetLocalizeResStr"}) do
                local fn = read(loc, key)
                if type(fn) == "function" then
                    local ok, text = pcall(fn, id)
                    if ok and type(text) == "string" and text ~= "" and not text:match("^%[?%d+%]?$") then
                        return text
                    end
                end
            end
            return ""
        end
        return type(value) == "string" and value or ""
    end
    local function mapAlias(value)
        local name = localized(value):lower()
        local aliases = {
            {"fourmaps", "Livik"}, {"summerland_mian", "Karakin"},
            {"baltic", "Erangel"}, {"dihorotok", "Vikendi"},
            {"savagemain", "Sanhok"}, {"savage_main", "Sanhok"},
            {"pubg_desert", "Miramar"}, {"map_desert", "Miramar"},
            {"pubg_neon_main", "Rondo"}
        }
        for _, public in ipairs({"Erangel", "Livik", "Rondo", "Miramar", "Sanhok", "Vikendi", "Karakin", "Nusa"}) do
            if name:find(public:lower(), 1, true) then return public end
        end
        for _, entry in ipairs(aliases) do
            if name:find(entry[1], 1, true) then return entry[2] end
        end
        return ""
    end

    pcall(function()
        local mgr = GetModule("client.slua.logic.match.logic_mode_mgr")
        local native = GetModule("GameLua.GameCore.Main.GameMainConfig")
        local subMode = tonumber(read(mgr, "nInGameModeID")) or 0
        if subMode <= 0 then subMode = tonumber(call(native, "GetModeID")) or 0 end
        if subMode <= 0 then subMode = tonumber(read(rawget(_G, "CGameState"), "GameModeID")) or 0 end
        if subMode <= 0 then subMode = tonumber(rawget(_G, "ModeID")) or 0 end

        local cdt = rawget(_G, "CDataTable")
        local cfg = subMode > 0 and call(cdt, "GetTableData", "BTMode", subMode) or nil
        local mapID = tonumber(read(cfg, "MapID")) or tonumber(rawget(_G, "MapID")) or 0
        local mapRow = mapID > 0 and call(cdt, "GetTableData", "Map", mapID) or nil
        local game = rawget(_G, "CGame")
        local candidates = {
            call(game, "GetMapName", game) or "",
            read(mapRow, "MapPath") or "", read(mapRow, "MapNameInternal") or "",
            read(mapRow, "MapKey") or "", read(mapRow, "ShowName") or "", read(mapRow, "MapName") or "",
            call(native, "GetMapNameInternal") or "", call(native, "GetMapType", subMode) or ""
        }
        for _, value in ipairs(candidates) do
            local found = mapAlias(value)
            if found ~= "" then mapName = found; break end
        end

        local mainMode = tonumber(read(mgr, "nSelectMatchID")) or 0
        local localMode = localized(call(mgr, "GetClassicModeWord", mainMode, subMode))
        if localMode == "" and cfg then
            localMode = localized(read(cfg, "Name"))
        end
        local modType = tostring(read(cfg, "ModType") or "")
        local low = (localMode .. " " .. modType):lower()
        local rankedIDs = { [101]=true,[102]=true,[103]=true,[401]=true,[402]=true,[403]=true,[723]=true,[733]=true }
        local normalIDs = { [111]=true,[112]=true,[113]=true,[411]=true,[412]=true,[413]=true }
        local ranked = rankedIDs[mainMode] or rankedIDs[subMode] or low:find("rank", 1, true)
        local normal = normalIDs[mainMode] or normalIDs[subMode]
        if low:find("xếp hạng", 1, true) or low:find("rank", 1, true) then ranked = true end
        if low:find("đấu thường", 1, true) or low:find("classic", 1, true) then normal = true end
        if localMode ~= "" then
            modeName = localMode
        elseif ranked then
            modeName = "Xếp Hạng"
        elseif normal then
            modeName = "Đấu Thường"
        elseif modType ~= "" then
            modeName = modType:gsub(";", " / ")
        elseif subMode > 0 then
            modeName = "BattleRoyale"
        end
        local fpp = read(cfg, "IsFpp")
        if fpp and fpp ~= 0 and fpp ~= false then modeName = modeName .. " [FPP]" end
    end)

    local function escape(value)
        return tostring(value):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")
    end
    return escape(mapName), escape(modeName)
end

-- ============================================================
-- SEND FEEDBACK — form-urlencoded về worker
-- ============================================================
function AutoFeedback.SendFeedback(path, kills, rank, segment, matchMap, matchMode)
    Log("SendFeedback: " .. tostring(path))

    local httpManager = GetModule("client.slua.logic.http.http_manager")
    if not httpManager or type(httpManager.Post) ~= "function" then
        Log("HTTP manager unavailable.")
        return
    end

    local attempts = 0
    local function TrySend()
        local imageData = ReadFile(path)
        if #imageData > 0 then
            kills   = tonumber(kills) or 0
            rank    = tonumber(rank) or 0
            segment = tonumber(segment) or 0

            local name, maskedUid = GetPlayerInfo()
            local mapName, modeName = matchMap, matchMode
            if not mapName or not modeName then
                mapName, modeName = GetMatchInfo()
            end
            local rankText = GetRankName(rank)
            if rank > 0 then
                rankText = rankText .. " (" .. tostring(math.floor(rank)) .. " điểm)"
            end
            local caption = string.format(
                "🏆 <b>PNH VIP</b> 🏆\n" ..
                "🔥 <b>AUTO FEEDBACK PNH</b> 🔥\n" ..
                "⏰ <b>Time:</b> %s\n" ..
                "👤 <b>Player name:</b> %s\n" ..
                "🔑 <b>UID:</b> %s\n" ..
                "🗺 <b>Map:</b> %s\n" ..
                "🎮 <b>Mode:</b> %s\n" ..
                "🔫 <b>Kills:</b> %d\n" ..
                "🎖 <b>Rank:</b> %s\n" ..
                "💬 <b>TELEGRAM:</b> @pnhoolvn",
                os.date("%H:%M:%S %d/%m/%Y"),
                name, maskedUid, mapName, modeName, kills, rankText
            )

            local encodedImage = EscapeBase64(Base64Encode(imageData))
            local body = "base64_image=" .. encodedImage
                .. "&caption=" .. UrlEncode(caption)

            Notify("[PNH] Đang gửi feedback Top 1...")
            httpManager:Post(
                AutoFeedback.Config.WorkerURL,
                {["Content-Type"] = "application/x-www-form-urlencoded"},
                body, nil,
                function(success, _, response, errorMessage)
                    local res = tostring(response or errorMessage or "")
                    if success and (res:find('"status"%s*:%s*true') or res:find('"ok"%s*:%s*true')) then
                        Notify("[PNH] Gửi thành công! (Kills: " .. tostring(kills) .. ")")
                    else
                        Notify("[PNH] Lỗi worker: " .. res:sub(1, 80))
                    end
                    RemoveFile(path)
                end, 60)
            return
        end
        attempts = attempts + 1
        if attempts < 5 and AddTimerOnce(1.0, TrySend) then return end
        Notify("[PNH] Chụp ảnh thất bại!!")
        RemoveFile(path)
    end

    local ok, err = pcall(TrySend)
    if not ok then Log("SendFeedback Error: " .. tostring(err)) end
end

-- ============================================================
-- HUD HIDE
-- ============================================================
local HudNames = {
    "BattleChat_UIBP","Chat_UIBP","ChatMsg_UIBP","TeamAvatar_UIBP","Team_UIBP",
    "VoiceChat_UIBP","MiniMap_UIBP","Bag_UIBP","PickUp_UIBP","PickUpList_UIBP",
    "SystemChat_UIBP","InGameChat_UIBP","InGameChatPanel_UIBP","KillFeed_UIBP",
    "Elimination_UIBP","ChatHUD_UIBP","ChatPanel_UIBP","MainHUD_UIBP","BattleHUD_UIBP"
}

local function CreateHudController()
    local hidden = {}
    local function SetHidden(hide)
        local UIManager = _G.UIManager
        if not UIManager then return end

        if hide then
            for _, name in ipairs(HudNames) do
                local config
                if UIManager.UI_Config_InGame and UIManager.UI_Config_InGame[name] then
                    config = UIManager.UI_Config_InGame[name]
                elseif UIManager.UI_Config and UIManager.UI_Config[name] then
                    config = UIManager.UI_Config[name]
                end
                if config then
                    local view = type(UIManager.GetUI) == "function" and UIManager.GetUI(config) or nil
                    if view then
                        pcall(function()
                            if type(view.SetVisibility) == "function" then
                                view:SetVisibility(2)
                            elseif view.UIRoot and type(view.UIRoot.SetVisibility) == "function" then
                                view.UIRoot:SetVisibility(2)
                            elseif type(UIManager.HideUI) == "function" then
                                UIManager.HideUI(config)
                            elseif type(UIManager.CloseUI) == "function" then
                                UIManager.CloseUI(config)
                            end
                        end)
                        table.insert(hidden, {config = config, view = view})
                    end
                end
            end
            return
        end

        for _, item in ipairs(hidden) do
            pcall(function()
                if item.view and type(item.view.SetVisibility) == "function" then
                    item.view:SetVisibility(0)
                elseif item.view and item.view.UIRoot and type(item.view.UIRoot.SetVisibility) == "function" then
                    item.view.UIRoot:SetVisibility(0)
                elseif type(UIManager.ShowUI) == "function" then
                    UIManager.ShowUI(item.config)
                end
            end)
        end
        hidden = {}
    end
    return SetHidden
end

-- ============================================================
-- CAPTURE
-- ============================================================
local function CaptureAndSend(kills, rank, segment, restoreHud, matchMap, matchMode)
    local restored = false
    local function RestoreHudOnce()
        if not restored then restored = true; restoreHud(false) end
    end

    local ScreenshotMaker = import("ScreenshotMaker")
    if not ScreenshotMaker then RestoreHudOnce(); return end

    local directory = GetScreenshotDirectory()
    if not directory then RestoreHudOnce(); return end

    local path = directory .. string.format("pnhwin_%s.jpg", os.time())
    local uiUtil = GetModule("client.common.ui_util")
    local gi = uiUtil and uiUtil.GetGameInstance and uiUtil.GetGameInstance()
    local preTick = gi and gi.EnginePreTick
    if not preTick or type(preTick.Add) ~= "function" then
        RestoreHudOnce(); return
    end

    local ticker = GetModule("common.time_ticker")
    if not ticker or type(ticker.AddTimerOnce) ~= "function" then
        RestoreHudOnce(); return
    end

    preTick:Add(function()
        local actualPath = ScreenshotMaker.MakePictureByName(path, true)
        if type(preTick.Clear) == "function" then preTick:Clear() end
        if actualPath and actualPath ~= "" then path = actualPath end

        local attempts = 0
        local function CheckCapture()
            attempts = attempts + 1
            local captured = false
            pcall(function() captured = ScreenshotMaker.HasCaptured(path) end)

            if captured then
                RestoreHudOnce()
                Log("HasCaptured=true. Resize + send.")
                pcall(ScreenshotMaker.ResizePicture, path, 0.6, path)
                ticker.AddTimerOnce(2.0, function()
                    if #ReadFile(path) > 0 then
                        AutoFeedback.SendFeedback(path, kills, rank, segment, matchMap, matchMode)
                    else
                        Notify("[PNH] Lỗi đọc ảnh!")
                    end
                end)
            elseif attempts < 15 then
                ticker.AddTimerOnce(1, CheckCapture)
            else
                RestoreHudOnce()
                Notify("[PNH] Chụp ảnh thất bại!")
            end
        end
        ticker.AddTimerOnce(1, CheckCapture)
    end)
end

-- ============================================================
-- PROCESS WIN — mọi rank, top 1 là bắn
-- ============================================================
function AutoFeedback.ProcessWin(kills)
    kills = tonumber(kills) or 0
    local rank, segment = GetRankAndSegment()
    -- Snapshot metadata before hiding the HUD / waiting for the screenshot.
    local matchMap, matchMode = GetMatchInfo()

    Log(string.format("TOP 1 — Kills=%d Rank=%s (%d) — feedback mọi rank.",
        kills, GetRankName(rank), rank))

    Notify("[PNH] TOP 1 — đang chụp feedback...")
    local setHudHidden = CreateHudController()
    setHudHidden(true)

    local ok, err = pcall(CaptureAndSend, kills, rank, segment, setHudHidden, matchMap, matchMode)
    if not ok then
        setHudHidden(false)
        Log("ProcessWin Error: " .. tostring(err))
    end
end

-- ============================================================
-- HOOK UIManager.ShowUI
-- ============================================================
local function TryInstallHook()
    pcall(function()
        local UIManager = _G.UIManager
        if not UIManager or not UIManager.ShowUI or UIManager.__PNHHooked then return end

        Log("Hooking UIManager.ShowUI...")
        local originalShowUI = UIManager.ShowUI
        UIManager.ShowUI = function(config, params, ...)
            local result = originalShowUI(config, params, ...)
            pcall(function()
                local inGameConfig = UIManager.UI_Config_InGame
                local winnerConfig = inGameConfig and inGameConfig.GameOverCountDown_UIBP
                local isWinner = params and (params.Reason == "win" or params.ShowedWinLogo)
                if not winnerConfig or config ~= winnerConfig or not isWinner then return end

                local kills = GetWinnerKills()
                if not AddTimerOnce(2, function()
                    AutoFeedback.ProcessWin(kills)
                end) then
                    AutoFeedback.ProcessWin(kills)
                end
            end)
            return result
        end

        UIManager.__PNHHooked = true
        AutoFeedback.Hooked = true
        Log("UIManager hook OK.")
    end)
end

-- ============================================================
-- INSTALL
-- ============================================================
function AutoFeedback.Install()
    Log("Installing PNH AutoFeedback (worker relay, mọi rank)...")

    if AutoFeedback.Config.TestMode then
        pcall(function()
            AddTimerOnce(5.0, function()
                local dir = GetScreenshotDirectory()
                if not dir then return end
                local p = io.popen('ls -t "' .. dir .. '" 2>/dev/null | head -n1')
                if p then
                    local n = p:read("*l"); p:close()
                    if n then AutoFeedback.ProcessWin(10) end
                end
            end)
        end)
    end

    pcall(function()
        local ticker = GetModule("common.time_ticker")
        if ticker and type(ticker.AddTimer) == "function" then
            ticker.AddTimer(3.0, TryInstallHook)
        else
            TryInstallHook()
        end
    end)
end

