AutoFeedback.Base64Encode           = Base64Encode
AutoFeedback.UrlEncode              = UrlEncode
AutoFeedback.GetRankName            = GetRankName
AutoFeedback.GetRankAndSegment      = GetRankAndSegment
AutoFeedback.GetScreenshotDirectory = GetScreenshotDirectory

_G.PNH_AutoFeedback = AutoFeedback

AutoFeedback.Install()
return AutoFeedback

end)
