local cache = {}

local function imp(name)
    local v = cache[name]
    if v == nil then
        local ok, r = pcall(import, name)
        if ok then v = r; cache[name] = v end
    end
    return v
end

local function req(name)
    local v = cache[name]
    if v == nil then
        local ok, r = pcall(require, name)
        if ok then v = r; cache[name] = v end
    end
    return v
end

