-- ============================================================
function PNH.GetCharacter()
    local GD = GetGameplayData()
    if not GD then return nil end
    local char = GD.GetPlayerCharacter()
    if slua.isValid(char) then return char end
    return nil
end

function PNH.IsCharacterReady(char)
    if not char or not slua.isValid(char) then return false end
    local EP = GetEPawnState()
    if not EP then return false end

    local standing = false
    pcall(function()
        standing = (char.CurrentStates == (1 << EP.Stand))
        if standing and char.IsHandleInFold and char:IsHandleInFold() then
            standing = false
        end
    end)

    local inVehicle, dead = false, false
    pcall(function()
        inVehicle = char:HasState(EP.InVehicle) or char:HasState(EP.DriveVehicle)
        dead = char:HasState(EP.Save) or char:HasState(EP.Pick)
    end)

    return standing and not inVehicle and not dead
end

function PNH.GetWeaponAvatarComponent(char)
    if not char or not slua.isValid(char) then return nil end
    local weapon = char.GetCurrentWeapon and char:GetCurrentWeapon()
    if slua.isValid(weapon) and slua.isValid(weapon.WeaponAvatarComponent) then
        return weapon.WeaponAvatarComponent
    end
    return nil
end

-- ============================================================
-- SOFT OBJECT PATH
-- ============================================================
local function softToString(softObj)
    local result
    pcall(function()
        if not softObj then return end
        if softObj.ToSoftObjectPath then
            local sp = softObj:ToSoftObjectPath()
            if sp then
                if sp.ToString then result = sp:ToString() end
                if (not result) and sp.GetAssetPathString then
                    result = sp:GetAssetPathString()
                end
            end
        end
        if (not result) and softObj.ToString then result = softObj:ToString() end
    end)
    return result
end

-- ============================================================
-- RESOLVE ANIMATION CONFIG
-- ============================================================
local function ResolveConfig(char)
    local seqPath, actorPath, duration = nil, nil, 0

    pcall(function()
        local wac = PNH.GetWeaponAvatarComponent(char)
        if not wac then return end

        local ES = GetESocket()
        local ET = GetELvSeq()
        if not ES or not ET then return end

        local handle = wac:GetEquippedHandle(ES.MasterGun)
        if handle and slua.isValid(handle) and handle.WeaponSpecialLevelSequenceList then
            for _, seq in pairs(handle.WeaponSpecialLevelSequenceList) do
                if seq.LevelSequenceType == ET.ECharSpecLvSeq_WeaponCheck
                   and seq.LevelSequenceConfig then
                    local cfg = seq.LevelSequenceConfig
                    seqPath   = softToString(cfg.LevelSequence)
                    actorPath = softToString(cfg.SequenceActorTemplate)
                    duration  = cfg.LevelSequenceDuration or 0
                    break
                end
            end
        end

        if not actorPath or actorPath == "" then
            local AU = GetAvatarUtils()
            if AU and wac.GetEquippedItemDefineID then
                local skinID = wac:GetEquippedItemDefineID(ES.MasterGun).TypeSpecificID
                if skinID <= 0 then
                    local weapon = char:GetCurrentWeapon()
                    if weapon then
                        skinID = weapon:GetItemDefineID().TypeSpecificID
                    end
                end
                local base = AU.GetWeaponAvatarParentID(AU.GetBPIDByResID(skinID), false)
                local data = CDataTable.GetTableData("WeaponCheckSkill", base)
                if data and data.SequenceActorPath and data.SequenceActorPath ~= "" then
                    actorPath = data.SequenceActorPath
                end
            end
        end
    end)

    if not actorPath or actorPath == "" then actorPath = DEFAULT_ACTOR end
    if not duration or duration <= 0 then duration = PNH.DEFAULT_DUR end

    return { seqPath = seqPath, actorPath = actorPath, duration = duration }
end

PNH.ResolveAnimationConfig = ResolveConfig

-- ============================================================
-- PLAY ONCE
-- ============================================================
local function PlayOnce(char, cfg)
    if not cfg or not cfg.seqPath or cfg.seqPath == "" then return false end

    local ok = false
    pcall(function()
        local KM = GetKismet()
        if not KM then return end

        local loc = PNH._origLoc or char:K2_GetActorLocation()
        local rot = PNH._origRot or char:K2_GetActorRotation()
        local transform = KM.MakeTransform(loc, rot, FVector(1, 1, 1))

        local seqActor = Game:PlayLevelSequence(
            char, cfg.seqPath, transform,
            cfg.actorPath or DEFAULT_ACTOR,
            false, nil, char
        )

        if slua.isValid(seqActor) then
            if seqActor.SetCharacterAndPlay then
                seqActor:SetCharacterAndPlay(char)
            end
            char.CurrentLevelSequence = seqActor
            PNH._lastSeq = seqActor
            ok = true
        end
    end)

    return ok
end

local function IsSeqAlive()
    return PNH._lastSeq and slua.isValid(PNH._lastSeq)
end

-- ============================================================
-- STOP
-- ============================================================
function PNH.Stop()
    if PNH._timer and PNH._char and slua.isValid(PNH._char) then
        pcall(function() PNH._char:RemoveGameTimer(PNH._timer) end)
    end
    PNH._running = false
    PNH._timer   = nil
    PNH._lastSeq = nil
    PNH._char    = nil
    PNH._cfg     = nil
    PNH._origLoc = nil
    PNH._origRot = nil
end

-- ============================================================
-- START
-- ============================================================
function PNH.Start()
    if not PNH._enabled or PNH._running then return false end

    local char = PNH.GetCharacter()
    if not char or not slua.isValid(char) then return false end
    if not PNH.IsCharacterReady(char) then return false end

    local cfg = ResolveConfig(char)
    if not cfg.seqPath or cfg.seqPath == "" then return false end

    PNH._cfg     = cfg
    PNH._char    = char
    PNH._running = true
    PNH._origLoc = char:K2_GetActorLocation()
    PNH._origRot = char:K2_GetActorRotation()

    if not PlayOnce(char, cfg) then
        PNH._running = false
        PNH._char    = nil
        PNH._cfg     = nil
        return false
    end

    local t_start      = os.clock()
    local t_lastReplay = t_start

    pcall(function()
        PNH._timer = char:AddGameTimer(PNH.TICK, true, function()
            local now = os.clock()

            local cur = PNH.GetCharacter()
            if not cur or not slua.isValid(cur) or not PNH.IsCharacterReady(cur) then
                PNH.Stop(); return
            end

            if PNH.LOOP then
                local sinceReplay = now - t_lastReplay
                local due = (not IsSeqAlive())
                         or (sinceReplay >= (cfg.duration - PNH.REPLAY_LEAD))

                if due then
                    if PNH._enabled then
                        t_lastReplay = now
                        PlayOnce(cur, cfg)
                    else
                        PNH.Stop(); return
                    end
                end
                if (now - t_start) >= PNH.TOTAL_SEC then
                    PNH.Stop()
                end
            else
                if (not IsSeqAlive()) and (now - t_lastReplay) > 0.3 then
                    PNH.Stop(); return
                end
                if (now - t_start) >= (cfg.duration + 1) then
                    PNH.Stop()
                end
            end
        end)
    end)

    return true
end

function PNH.Restart()
    PNH.Stop()
    return PNH.Start()
end

-- ============================================================
-- SETENABLED / ISENABLED
-- ============================================================
function PNH.SetEnabled(enabled)
    PNH._enabled = enabled == true
    PNH.AUTO_START = false
    SaveEnabled(PNH._enabled)

    if not PNH._enabled then
        PNH.Stop()
    end
end

function PNH.IsEnabled() return PNH._enabled end

-- Keep the native weapon-inspection method untouched.
function PNH.BindToWeaponCheck()
    -- Do not wrap QuickExpression.TryDoCheckGun: the SLua proxy may forward
    -- back into __inner_impl and recurse. Leave the game's native method intact.
    PNH._checkHookInstalled = false
    return true
end

-- ============================================================
-- AUTO START LOOP
-- ============================================================
function PNH.AutoStartLoop()
    return false
end

-- ============================================================
-- PUBLIC API
-- ============================================================
_G.StartPNH   = PNH.Start
_G.StopPNH    = PNH.Stop
_G.RestartPNH = PNH.Restart
_G.SetPNH     = PNH.SetEnabled

-- Legacy aliases
_G.StartBIZAPRO   = PNH.Start
_G.StopBIZAPRO    = PNH.Stop
_G.RestartBIZAPRO = PNH.Restart
_G.SetBIZAPRO     = PNH.SetEnabled

_G.StartWeaponAnimation   = PNH.Start
_G.StopWeaponAnimation    = PNH.Stop
_G.RestartWeaponAnimation = PNH.Restart
_G.SetWeaponAnimation     = PNH.SetEnabled

-- SRC.lua weapon inspection implementation (exact-handle sequence + safe cleanup).
-- SRC-compatible weapon inspection hook owner.
-- PNH._enabled controls this feature; no automatic animation loop is started.
do
    local E = _G.OwenLobbyEmotes or {}
    _G.OwenLobbyEmotes = E
    E.Hooks = E.Hooks or {}

    function E.Enabled()
        return _G.PNH ~= nil and _G.PNH._enabled == true
    end

    function E.Hook(module, key, build)
        if type(module) ~= "table" then return false end
        local impl = rawget(module, "__inner_impl") or module
        local marks = E.Hooks[module]
        if not marks then marks = {}; E.Hooks[module] = marks end
        if marks[key] then return true end
        local original = module[key]
        if type(original) ~= "function" then return false end
        local wrapped = build(original)
        if type(wrapped) ~= "function" then return false end
        rawset(impl, key, wrapped)
        if impl ~= module then rawset(module, key, wrapped) end
        marks[key] = true
        return true
    end
end

  do
    local E = _G.OwenLobbyEmotes
    local I = {
      Attempts = 0,
      Ready = {},
      Order = {},
      Status = 'idle',
      ExtraDuration = 3,
      Durations = setmetatable( {}, { __mode = 'k' })
    };
    _G.OwenWeaponInspect = I
    local unpack = unpack or table.unpack
    local function pack( ...)
      return { n = select('#', ...), ... }
    end
    local function load(path)
      local ok, m = pcall(require, path);
      return ok and m or nil
    end
    local function valid(obj)
      return obj and slua and slua.isValid(obj)
    end
    local function identity(obj)
      return obj and (obj.Object or obj)
    end
    function I.Path(value)
      if not value then
        return nil, 'missing_value'
      end
      local function usable(path)
        return type(path) == 'string' and path ~= '' and path ~= 'None'
      end
      if type(value) == 'string' then
        return usable(value) and value or nil, 'string'
      end
      local function call(obj, name)
        return pcall(function()
          local fn = obj[name];
          if fn then
            return fn(obj)
          end
        end)
      end
      local ok, soft = call(value, 'ToSoftObjectPath')
      if not ok or not soft then
        soft = value
      end
      for _, obj in ipairs(soft == value and { value } or { soft, value }) do
        for _, name in ipairs( { 'GetAssetPathString', 'ToString' }) do
          local got, path = call(obj, name)
          if got and usable(path) then
            return path, name
          end
        end
      end
      local null, isNull = call(soft, 'IsNull')
      return nil, null and isNull == true and 'null_reference' or 'path_methods_unavailable_or_empty'
    end
    function I.Snapshot()
      local data = load('GameLua.GameCore.Data.GameplayData')
      local pawn = data and data.GetPlayerCharacter()
      if not valid(pawn) or not pawn.GetCurrentWeapon then
        return
      end
      local weapon = pawn:GetCurrentWeapon()
      if not valid(weapon) or not valid(weapon.WeaponAvatarComponent) then
        return
      end
      local socket = import('EWeaponAttachmentSocketType').MasterGun
      local comp = weapon.WeaponAvatarComponent
      local skin = comp:GetEquippedItemDefineID(socket).TypeSpecificID
      if (tonumber(skin) or 0) <= 0 then
        skin = weapon:GetItemDefineID().TypeSpecificID
      end
