    end
    function I.SkinEmote(snapshot)
      I.WeaponEmoteID = nil;
      I.MappingSource = 'missing';
      I.EffectRowFound = false;
      I.RawEmoteID = nil;
      I.SkinBPID = nil
      local ids = { snapshot.Skin }
      local avatar = import('AvatarUtils')
      local ok, bp = pcall(avatar.GetBPIDByResID, snapshot.Skin)
      if ok then
        I.SkinBPID = bp
      end
      if ok and tonumber(bp) and bp ~= snapshot.Skin then
        ids[ # ids + 1] = bp
      end
      for _, id in ipairs(ids) do
        local got, cfg = pcall(CDataTable.GetTableData, 'WeaponAvatarBattleEffect', id)
        if got and cfg then
          I.EffectRowFound = true;
          I.RawEmoteID = cfg.WeaponEmoteID
        end
        local emote = got and cfg and tonumber(cfg.WeaponEmoteID)
        if emote and emote > 0 then
          I.WeaponEmoteID = emote;
          I.MappingSource = 'WeaponAvatarBattleEffect:' .. tostring(id)
          return emote
        end
      end
    end
    function I.Paths(snapshot)
      I.HasSkinSequence = false;
      I.ExpectedDuration = nil;
      I.SequenceConfig = nil;
      I.SequenceRow = nil;
      I.SequenceRows = 0;
      I.SequenceIssue = 'missing_list' I.SkinEmote(snapshot)
      local paths, seen = {}, {}
      local function add(v)
        local path = I.Path(v);
        if path and not seen[path] then
          paths[ # paths + 1] = path;
          seen[path] = true
        end
      end
      local handle = snapshot.Handle
      if valid(handle) and handle.WeaponSpecialLevelSequenceList then
        local kind = import('ECharSpecialLevelSequenceType').ECharSpecLvSeq_WeaponCheck
        I.SequenceIssue = 'no_weapon_check_row'
        for _, row in pairs(handle.WeaponSpecialLevelSequenceList) do
          I.SequenceRows = I.SequenceRows + 1
          if row.LevelSequenceType == kind and row.LevelSequenceConfig then
            local cfg = row.LevelSequenceConfig
            I.SequenceIssue = 'invalid_duration_or_path'
            local duration = tonumber(cfg.LevelSequenceDuration) or 0
            local actor, sequence = I.Path(cfg.SequenceActorTemplate), I.Path(cfg.LevelSequence)
            if duration > 0 and actor and sequence then
              I.SequenceIssue = 'ready'
              I.HasSkinSequence = true;
              I.ExpectedDuration = duration;
              I.SequenceConfig = cfg;
              I.SequenceRow = row add(actor);
              add(sequence)
              break
            end
          end
        end
      end
      if # paths == 0 then
        local avatar = import('AvatarUtils')
        local bpid = avatar.GetBPIDByResID(snapshot.Skin)
        local parent = avatar.GetWeaponAvatarParentID(bpid, false)
        local cfg = CDataTable.GetTableData('WeaponCheckSkill', parent)
        if cfg then
          add(cfg.LevelSequencePath)
        end
      end
      return paths
    end
    function I.ExtendDuration(snapshot)
      local cfg, row = I.SequenceConfig, I.SequenceRow
      if not cfg or not row or not snapshot.Handle then
        return false
      end
      local key = identity(snapshot.Handle)
      local records = I.Durations[key]
      if not records then
        records = {};
        I.Durations[key] = records
      end
      local path = I.Path(cfg.LevelSequence)
      if not path then
        return false
      end
      local current = tonumber(cfg.LevelSequenceDuration) or 0
      if current <= 0 then
        return false
      end
      local record = records[path]
      if not record or (current ~= record.Base and current ~= record.Applied) then
        record = { Base = current };
        records[path] = record
      end
      local duration = record.Base + I.ExtraDuration
      local ok, err = pcall(function()
        cfg.LevelSequenceDuration = duration
        row.LevelSequenceConfig = cfg
      end)
      if not ok then
        I.DurationError = tostring(err);
        return false
      end
      record.Applied = duration;
      record.Row = row;
      record.Config = cfg
      I.ExpectedDuration = duration;
      I.DurationError = nil
      return true
    end
    function I.RestoreDurations()
      for _, records in pairs(I.Durations) do
        for _, record in pairs(records) do
          pcall(function()
            local cfg = record.Row.LevelSequenceConfig
            if cfg and tonumber(cfg.LevelSequenceDuration) == record.Applied then
