          local comp = pawn:GetPlayEmoteComponent()
          return valid(comp) and tonumber(comp.CurrentPlayEmoteId) == I.WeaponEmoteID
        end)
        if ok and playing then
          return true
        end
      end
      for _, skill in ipairs( { 1014405, 1014408, 1014433 }) do
        local ok, casting = pcall(function()
          if pawn.IsCastingSkillIDFix then
            return pawn:IsCastingSkillIDFix(skill)
          end
          local manager = pawn.GetSkillManager and pawn:GetSkillManager()
          return valid(manager) and manager:IsCastingSkillID(skill)
        end)
        if ok and casting then
          return true
        end
      end
      return false
    end
    function I.Native(original, args, quick)
      local emote = load('GameLua.Mod.Library.GamePlay.Avatar.Emote.logic_emote')
      local old = emote and emote.bCustomWeaponShow
      I.CustomRoute = old == true;
      I.Route = 'base_inspect'
      if emote then
        emote.bCustomWeaponShow = false
      end
      local result = pack(pcall(function()
        local state, skin = quick.GetCurrentCheckGunState(unpack(args, 1, args.n))
        I.NativeState = state;
        I.Skin = skin or I.Skin
        local snapshot = I.Snapshot()
        if snapshot then
          I.Paths(snapshot)
        end
        if state == 0 and snapshot and I.IsPlaying(snapshot.Pawn) then
          I.NativeState = 1;
          I.Route = 'already_playing';
          return
        end
        if state == 0 and snapshot and not I.HasSkinSequence and I.WeaponEmoteID and emote and type(emote.PlayEmote) == 'function' then
          I.Route = 'skin_emote';
          I.PlayResult = emote.PlayEmote(snapshot.Pawn, I.WeaponEmoteID)
          if I.PlayResult == false then
            I.NativeState = - 2
          end
          return I.PlayResult
        end
