        error(result[2], 0)
      end
      return unpack(result, 2, result.n)
    end
    function I.Start(original, quick, ...)
      if not E.Enabled() then
        return original( ...)
      end
      I.Attempts = I.Attempts + 1;
      I.Error = nil;
      I.ExpectedDuration = nil
      local args = pack( ...);
      local snapshot = I.Snapshot()
      if not snapshot then
        I.Status = 'weapon_unavailable';
