      local paths = I.Paths(snapshot)
      local key = tostring(snapshot.Skin) .. '|' .. table.concat(paths, '|')
      if # paths == 0 or I.Ready[key] then
        return I.Native(original, args, quick)
      end
      if I.Pending and I.Pending.Key == key and os.clock() - I.Pending.Time < 10 then
        I.Status = 'loading';
