      end
      local asset = load('common.asset_util')
      if not asset or type(asset.GetAssetsArrayAsyncParallel) ~= 'function' then
        I.Status = 'loader_unavailable';
        return I.Native(original, args, quick)
      end
      local request = { Time = os.clock(), Key = key };
      I.Pending = request;
      I.Status = 'loading'
