      local function sequenceFrom(handle)
        if not valid(handle) then
          return
        end
        local list = handle.WeaponSpecialLevelSequenceList
        if not list then
          return
        end
        local kind = import('ECharSpecialLevelSequenceType').ECharSpecLvSeq_WeaponCheck
        I.ExactSequenceRows = 0;
        I.ExactSequenceIssue = 'no_weapon_check_row'
        I.ExactDuration = nil;
        I.ExactActorPath = nil;
        I.ExactLevelPath = nil
        I.ExactActorRead = nil;
        I.ExactLevelRead = nil
        I.TrackBindingSource = 'missing';
        I.TrackBindingCount = 0;
        I.TrackBindingNames = nil
        for _, row in pairs(list) do
          I.ExactSequenceRows = I.ExactSequenceRows + 1
          local cfg = row.LevelSequenceType == kind and row.LevelSequenceConfig
          if cfg then
            local actor, actorRead = I.Path(cfg.SequenceActorTemplate)
            local sequence, sequenceRead = I.Path(cfg.LevelSequence)
            I.ExactActorRead = actorRead;
            I.ExactLevelRead = sequenceRead
            local duration = tonumber(cfg.LevelSequenceDuration) or 0
            I.ExactDuration = duration;
            I.ExactActorPath = actor;
            I.ExactLevelPath = sequence
            I.ExactSequenceIssue = duration <= 0 and 'duration_not_positive' or duration > 60 and 'duration_over_limit' or not actor and 'actor_path_missing' or not sequence and 'sequence_path_missing' or 'ready'
            if actor and sequence and duration > 0 and duration <= 60 then
              local bindings, source
              for _, owner in ipairs( { cfg, row }) do
                for _, field in ipairs( { 'TrackBindingInfos', 'TrackBindingInfo' }) do
                  local ok, value = pcall(function()
                    return owner[field]
                  end)
                  if ok and value then
                    local validMap, count = pcall(function()
                      local n = 0;
                      for _ in pairs(value) do
                        n = n + 1
                      end;
                      return n
                    end)
                    if validMap and count > 0 then
                      bindings = value;
                      source = (owner == cfg and 'config.' or 'row.') .. field;
                      break
                    end
                  end
                end
                if bindings then
                  break
                end
              end
              I.TrackBindingSource = source or 'missing';
              I.TrackBindingCount = 0;
              I.TrackBindingNames = nil
              if bindings then
                local names = {}
                for name, param in pairs(bindings) do
                  I.TrackBindingCount = I.TrackBindingCount + 1
                  if # names < 12 then
                    names[ # names + 1] = tostring(name) .. ':' .. tostring(param)
                  end
                end
                I.TrackBindingNames = table.concat(names, '|'):gsub('[\r\n]', ' '):sub(1, 400)
              end
              return { Actor = actor, Sequence = sequence, Duration = duration, Bindings = bindings }
            end
          end
        end
      end
      local function play(snapshot, spec, quick)
        if not current(snapshot) then
          I.DirectStatus = 'weapon_changed_or_disabled';
          return
        end
        local state = quick.GetCurrentCheckGunState()
        I.NativeState = state;
        I.Skin = snapshot.Skin
        if state ~= 0 or I.IsPlaying(snapshot.Pawn) then
          I.DirectStatus = 'native_state_blocked';
          return
        end
        local pawn = snapshot.Pawn
        if not pawn.AddGameTimer or not pawn.RemoveGameTimer then
          I.DirectStatus = 'cleanup_timer_unavailable';
          return
        end
        local mathlib = import('KismetMathLibrary')
        local transform = mathlib.MakeTransform(pawn:K2_GetActorLocation(), pawn:K2_GetActorRotation(), FVector(1, 1, 1))
        local actor = Game:PlayLevelSequence(identity(pawn), spec.Sequence, transform, spec.Actor, false, nil, identity(pawn))
        if not valid(actor) then
          I.DirectStatus = 'sequence_actor_unavailable';
          return
        end
        local active = { Actor = actor, Pawn = pawn, Snapshot = snapshot, Elapsed = 0, Limit = spec.Duration + I.ExtraDuration + 1 }
        I.Direct = active;
        I.Route = 'exact_handle_direct';
        I.DirectStatus = 'preparing'
        local ok, err = pcall(function()
          I.CameraCutStatus = 'player_unavailable';
          I.CameraSimulation = nil
          I.PerspectiveStatus = 'methods_unavailable';
          I.StopReason = nil;
          I.StopElapsed = nil
          I.TimelinePosition = nil;
          I.TimelineLength = nil pcall(function()
            if type(pawn.IsFPP) == 'boolean' and pawn.SetCurrentPersonPerspective and pawn.LocalSwitchPersonPerspective then
              active.PreviousFPP = pawn.IsFPP
              if not pawn.IsFPP then
                active.PerspectiveOwned = true pawn:SetCurrentPersonPerspective( true, true)
                pawn:LocalSwitchPersonPerspective( true, true, true)
              end
              I.PerspectiveStatus = 'fpp_requested'
            end
          end)
          pcall(function()
            active.PreviousViewLock = pawn.bEmoteLockChangePersonPerspective
            if active.PreviousViewLock ~= nil then
              pawn.bEmoteLockChangePersonPerspective = true;
              active.ViewLockOwned = true
            end
          end)
          pcall(function()
            if actor.bSimulateCameraCutsOnClients ~= nil then
              actor.bSimulateCameraCutsOnClients = true;
              I.CameraSimulation = true
            end
          end)
          local function enableCameraCuts()
            local player = actor.SequencePlayer
            if not valid(player) then
              return false
            end
            local ok = pcall(function()
              if not player.SetCanUpdateCameraCut then
                I.CameraCutStatus = 'method_unavailable';
                return
              end
              player:SetCanUpdateCameraCut( true);
              I.CameraCutStatus = 'enabled'
            end)
            if not ok then
              I.CameraCutStatus = 'enable_failed'
            end
            return true
          end
          active.CameraConfigured = enableCameraCuts()
          local metadataStarted = false
          if actor.SetMetaData and actor.SetOwner then
            actor:SetOwner(identity(pawn))
            actor:SetMetaData(spec.Bindings, 0)
            I.BindingMethod = 'SetOwner+SetMetaData';
            metadataStarted = true
          elseif actor.SetUpActorForSequence then
            actor:SetUpActorForSequence(identity(pawn));
            I.BindingMethod = 'SetUpActorForSequence'
          elseif actor.SetCharacterAndPlay then
            actor:SetCharacterAndPlay(identity(pawn));
            I.BindingMethod = 'SetCharacterAndPlay'
          else
            error('skin_sequence_binding_method_missing')
          end
          local player = actor.SequencePlayer
          if valid(player) and player.SetPlayRate then
            player:SetPlayRate(1);
            I.RateExtended = false
          else
            I.RateExtended = false
          end
          if metadataStarted then
          elseif actor.Play then
            actor:Play(0.0)
          elseif valid(player) and player.Play then
            player:Play()
          else
            error('skin_sequence_play_method_missing')
          end
          active.Timer = pawn:AddGameTimer(0.1, true, function()
            if I.Direct ~= active then
              return
            end
            active.Elapsed = active.Elapsed + 0.1
            if not active.CameraConfigured then
              active.CameraConfigured = enableCameraCuts()
            end
            if not current(snapshot) then
              I.StopDirect('weapon_changed_or_disabled');
              return
            end
            if snapshot.Pawn.bIsWeaponAiming == true or snapshot.Pawn.bIsADS == true or snapshot.Pawn.bIsWeaponFiring == true then
              I.StopDirect('player_interrupted');
              return
            end
            if not valid(actor) then
              I.StopDirect('sequence_finished');
              return
            end
            if valid(player) and player.IsPlaying then
              pcall(function()
                if player.GetPlaybackPosition then
                  I.TimelinePosition = player:GetPlaybackPosition()
                end
                if player.GetLength then
                  I.TimelineLength = player:GetLength()
                end
              end)
              if player:IsPlaying() then
                active.Started = true
              elseif active.Started then
                I.StopDirect('sequence_finished');
                return
              end
            end
            if active.Elapsed >= active.Limit then
              I.StopDirect('cleanup_deadline')
            end
          end)
          if not active.Timer then
            error('cleanup_timer_not_created')
          end
          I.ExpectedDuration = spec.Duration
          I.Status = 'direct_inspect_requested';
          I.DirectStatus = 'requested_completion_unverified'
        end)
        if not ok then
          I.Error = tostring(err);
          I.StopDirect('direct_play_error')
        end
      end
      function I.Start(original, quick, ...)
        if not E.Enabled() then
          I.StopDirect('disabled');
          return original( ...)
        end
        if I.Direct then
          I.DirectStatus = 'already_playing';
          return
        end
        local snapshot = I.Snapshot()
        if not snapshot then
          return originalStart(original, quick, ...)
        end
        I.DirectStatus = nil;
        I.HandlePathSource = nil;
        I.ExactClassPath = nil
        I.ExactSequence = nil;
        I.ExactActor = nil;
        I.BindingMethod = nil;
        I.RateExtended = nil
        local equipped = sequenceFrom(snapshot.Handle)
        if equipped and not (Game and Game.PlayLevelSequence and snapshot.Pawn.AddGameTimer and snapshot.Pawn.RemoveGameTimer) then
          return originalStart(original, quick, ...)
        end
        local args = pack( ...)
        if I.ExactPending then
          if os.clock() - I.ExactPending.Time < 10 then
            I.DirectStatus = 'exact_handle_loading';
            return
          end
          I.ExactPending = nil
        end
        local asset = load('common.asset_util')
        if not asset or type(asset.GetAssetsArrayAsyncParallel) ~= 'function' then
          return originalStart(original, quick, ...)
        end
        local function fallback(reason)
          I.DirectStatus = reason
          if current(snapshot) then
            return originalStart(original, quick, unpack(args, 1, args.n))
          end
        end
        local function resolve(handle)
          local ok, spec = pcall(sequenceFrom, handle)
          if not ok or not spec then
            return fallback('exact_handle_has_no_skin_sequence')
          end
          I.HasSkinSequence = true;
          I.SequenceIssue = 'ready';
          I.Skin = snapshot.Skin
          I.SequenceRows = I.ExactSequenceRows
          if I.SkinEmote then
            I.SkinEmote(snapshot)
          end
          I.ExactSequence = spec.Sequence;
          I.ExactActor = spec.Actor
          I.Attempts = I.Attempts + 1
          local pending = { Time = os.clock() };
          I.ExactPending = pending
          local success, err = pcall(asset.GetAssetsArrayAsyncParallel, { spec.Actor, spec.Sequence }, function()
            if I.ExactPending ~= pending then
              return
            end
            I.ExactPending = nil
            if os.clock() - pending.Time > 10 then
              I.DirectStatus = 'exact_load_expired';
              return
            end
            local played, why = pcall(play, snapshot, spec, quick)
            if not played then
              I.DirectStatus = 'direct_play_error';
              I.Error = tostring(why);
              I.StopDirect('direct_play_error')
            end
          end)
          if not success then
            I.ExactPending = nil;
            I.Error = tostring(err);
            return fallback('exact_sequence_load_failed')
          end
        end
        if equipped then
          return resolve(snapshot.Handle)
        end
        local cached = I.ExactHandles[snapshot.Skin]
        if valid(cached) then
          return resolve(cached)
        end
        local item = CDataTable.GetTableData('Item', snapshot.Skin)
        local bp = item and item.BPID or import('AvatarUtils').GetBPIDByResID(snapshot.Skin)
        local factory = import('BackpackUtils')
        local define
        if factory.GetItemDefineIDByItemID then
          local ok, value = pcall(factory.GetItemDefineIDByItemID, snapshot.Skin)
          if ok and value and tonumber(value.TypeSpecificID) == snapshot.Skin then
            define = value
          end
        end
        if not define then
          define = FItemDefineID(item and item.ItemType or 2, snapshot.Skin)
        end
        local path
        I.HandlePathSource = nil;
        I.ExactClassPath = nil
        if factory.GetBattleItemHandlePath then
          local ok, value = pcall(factory.GetBattleItemHandlePath, define, false, false)
          if ok then
            path = I.Path(value)
          end
          if path then
            I.HandlePathSource = 'BackpackUtils.GetBattleItemHandlePath:match'
          end
        end
        if not path then
          local row = bp and CDataTable.GetTableData('AvatarBPTable', bp)
          path = I.Path(row and row.AvatarBPPath)
          if path then
            I.HandlePathSource = 'AvatarBPTable'
          end
        end
        I.ExactClassPath = path
        if not path then
          return fallback('exact_skin_class_path_missing')
        end
        local pending = { Time = os.clock() };
        I.ExactPending = pending;
        I.DirectStatus = 'exact_class_loading'
        local ok, err = pcall(asset.GetAssetsArrayAsyncParallel, { path }, function()
          if I.ExactPending ~= pending then
            return
          end
          I.ExactPending = nil
          if not current(snapshot) or os.clock() - pending.Time > 10 then
            I.DirectStatus = 'exact_load_expired';
            return
          end
          local created, handle = pcall(function()
            local def = define
            local obj = factory.CreateBattleItemHandle(def, identity(snapshot.Pawn), false)
            assert(valid(obj), 'exact_handle_factory_failed')
            if obj.Init then
              obj:Init(def)
            end
            local actual = obj.GetDefineID and obj:GetDefineID() or obj.DefineID assert(actual and tonumber(actual.TypeSpecificID) == snapshot.Skin, 'exact_handle_id_mismatch')
            return obj
          end)
          if not created then
            I.Error = tostring(handle);
            return fallback('exact_handle_create_failed')
          end
          I.ExactHandles[snapshot.Skin] = handle;
          I.ExactOrder[ # I.ExactOrder + 1] = snapshot.Skin
          if # I.ExactOrder > 16 then
            I.ExactHandles[table.remove(I.ExactOrder, 1)] = nil
          end
          resolve(handle)
        end)
        if not ok then
          I.ExactPending = nil;
          I.Error = tostring(err);
          return fallback('exact_class_load_failed')
        end
      end
      function I.Install()
        if not E.Enabled() then
          I.ExactPending = nil;
          I.StopDirect('disabled');
          I.ExactHandles = {};
          I.ExactOrder = {}
        end
        return originalInstall()
      end
    end
    pcall(I.Install)
  end

