-- Keep the public PNH toggle/API, but route native inspection through SRC's handler.
do
    local I = _G.OwenWeaponInspect
    local oldSetEnabled, oldStop = PNH.SetEnabled, PNH.Stop
    function PNH.BindToWeaponCheck()
        if I and type(I.Install) == "function" then
            local ok, result = pcall(I.Install)
            PNH._checkHookInstalled = ok and result ~= false
            return PNH._checkHookInstalled
        end
        PNH._checkHookInstalled = false
        return false
    end
    function PNH.SetEnabled(enabled)
        oldSetEnabled(enabled)
        if I then
            if not PNH._enabled and I.StopDirect then pcall(I.StopDirect, "disabled") end
            if I.Install then pcall(I.Install) end
        end
    end
    function PNH.Stop()
        oldStop()
        if I and I.StopDirect then pcall(I.StopDirect, "pnh_stopped") end
    end
    PNH.BindToWeaponCheck()
end

