local function mod(path, g)
    local ok, m = pcall(require, path)
    if ok and type(m) == "table" then return m end
    return _G[g]
end

local function wrap(t, name, fn)
    if type(t[name]) ~= "function" or t["__w_"..name] then return end
    t["__w_"..name] = true
    local orig = t[name]
    t[name] = function(self, ...) return fn(self, orig, ...) end
end

