pcall(function()
    if _G.ApplyEnemyTheme then return end

    local _FLC = import("LinearColor") or _G.FLinearColor
    local function Color(r, g, b, a)
        if _FLC then return _FLC(r, g, b, a or 1.0) end
        return {R=r, G=g, B=b, A=a or 1.0}
    end

    _G.ESP_COLORS = {
        BloodRed       = Color(0.84, 0.010, 0.018, 1.00),
        BloodRedBright = Color(1.00, 0.025, 0.040, 1.00),
        BloodRedSoft   = Color(1.00, 0.24,  0.22,  0.46),
        BloodRedDim    = Color(0.26, 0.002, 0.008, 0.98),
        BloodRedShade  = Color(0.10, 0.000, 0.004, 0.66),
        Yellow         = Color(1.00, 0.76,  0.000, 1.00),
        YellowBright   = Color(1.00, 0.96,  0.10,  1.00),
        YellowSoft     = Color(1.00, 0.88,  0.20,  0.48),
        YellowDim      = Color(0.48, 0.27,  0.000, 0.98),
        YellowShade    = Color(0.16, 0.075, 0.000, 0.66),
        BotRedText     = Color(0.94, 0.010, 0.020, 1.00),
        White          = Color(0.98, 0.98, 0.98, 1.00),
        Gray           = Color(0.42, 0.42, 0.42, 1.00),
    }

    _G.ApplyEnemyTheme = function(data, isAI)
        if not data then return end
        local C = _G.ESP_COLORS
        return {
            stroke = isAI and C.YellowBright or C.BloodRedBright,
            inner  = isAI and C.Yellow       or C.BloodRed,
            dim    = isAI and C.YellowDim    or C.BloodRedDim,
            glow   = isAI and C.YellowSoft   or C.BloodRedSoft,
            shade  = isAI and C.YellowShade  or C.BloodRedShade,
            text   = isAI and C.BotRedText   or C.White,
        }
    end



end)




