pcall(function()

-- ============================================================================
-- SRC.lua FRAG GRENADE BOUND EXPLOSION FX (subtype 612)
-- Uses GrenadeKillGunBindMap -> GrenadeBindWeaponFx, then spawns sequence/particle
-- at the local frag projectile explosion position. Stock effect is retained on failure.
-- ============================================================================
do
    local state = setmetatable({}, { __mode = "k" })
    local cache, cacheCount, loading = {}, 0, 0
    local sequences = {}
    local installed = false

    local function active()
        return not (_G.LexusConfig and _G.LexusConfig.ModSkin == false)
            and F.isInRealMatch and F.isInRealMatch() == true
    end
    local function nativeObject(obj)
        if not obj then return nil end
        local ok, value = pcall(function() return obj.Object end)
        return ok and value or obj
    end
    local function valid(obj)
        local native = nativeObject(obj)
        if not native then return false end
        local ok, result = pcall(slua.isValid, native)
        return ok and result == true
    end
    local function same(a, b)
        if not a or not b then return false end
        local na, nb = nativeObject(a), nativeObject(b)
        return valid(na) and valid(nb) and tostring(na) == tostring(nb)
    end
    local function selectedFragRes()
        local cch = F.cache()
        local function resolve(item)
            local res = type(item) == "table" and tonumber(item.resID) or tonumber(item)
            if res and res > 0 and tonumber(F.subType(F.cfg(res))) == 612 then return res end
        end
        return resolve(PERSIST.configThrowObjects and PERSIST.configThrowObjects[612])
            or resolve(cch.throwObjects and cch.throwObjects[612])
            or resolve(_G._savedThrowObjects and _G._savedThrowObjects[612])
    end
    local function projectileComp(obj)
        return obj and (obj.GrenadeAvatarComponent_BP or obj.GrenadeAvatarComponent)
    end
    local function projectileSkin(obj)
        local comp = projectileComp(obj)
        local id = 0
        pcall(function() if comp and comp.GetCurGrenadeAvatarID then id = tonumber(comp:GetCurGrenadeAvatarID()) or 0 end end)
        if id <= 0 then id = selectedFragRes() or 0 end
        return id
    end
    local function localProjectile(obj)
        if not active() or not valid(obj) or type(obj.GetInstigatorControllerSafety) ~= "function" then return false end
        local ok, owner = pcall(obj.GetInstigatorControllerSafety, obj)
        return ok and same(owner, F.getPC())
    end
    local function path(value)
        if type(value) == "string" then return value:sub(1, 1) == "/" and value or nil end
        if value and value.ToString then
            local ok, str = pcall(value.ToString, value)
            if ok and type(str) == "string" and str:sub(1, 1) == "/" then return str end
        end
        return nil
    end
    local function tableData(name, id)
        local ok, row = pcall(CDataTable.GetTableData, name, id)
        if ok and row then return row end
        if CDataTable.GetTable then
            local rowsOK, rows = pcall(CDataTable.GetTable, name)
            if rowsOK and rows then return rows[id] or rows[tostring(id)] end
        end
        return nil
    end
    local function diagnostic(status, detail)
        _G.ChanFragBoundFXStatus = status
        _G.ChanFragBoundFXDetail = detail and tostring(detail) or nil
    end
    local function prepareFragBoundVisual()
        if not active() then return nil end
        local res = selectedFragRes()
        if not res then diagnostic("no_selected_frag_skin"); return nil end
        local item, now = cache[res], os.clock()
        if item and (valid(item.SequenceAsset) or valid(item.Asset)) then return item, res end
        if item and item.Pending and now - (item.Started or now) > 10 then
            item.Pending = false; item.Token = nil; loading = math.max(0, loading - 1)
        end
        if item and (item.Pending or now < (item.NextTry or 0)) then return nil, res end
        if not item then
            if cacheCount >= 8 then
                for key, value in pairs(cache) do
                    if not value.Pending then cache[key] = nil; cacheCount = cacheCount - 1; break end
                end
                if cacheCount >= 8 then diagnostic("cache_full"); return nil, res end
            end
            item = {}; cache[res] = item; cacheCount = cacheCount + 1
        end
        item.NextTry = now + 5
        if not item.Path and not item.SequencePath then
            local binding = tableData("GrenadeKillGunBindMap", res)
            local candidates = {}
            local function add(list)
                if not list then return end
                if type(list) == "table" and not list.Num then
                    for i, id in ipairs(list) do if i > 16 then break end; candidates[#candidates + 1] = id end
                else
                    pcall(function() for i = 0, math.min(list:Num(), 16) - 1 do candidates[#candidates + 1] = list:Get(i) end end)
                end
            end
            if binding then
                add(binding.UnlockFxGunIDList_a or binding.UnlockFxGunIDList)
                add(binding.GunIDList_a or binding.GunIDList)
                if binding.FxGunID or binding.WeaponID then candidates[#candidates + 1] = binding.FxGunID or binding.WeaponID end
            end
            for _, gunID in ipairs(candidates) do
                local row = tableData("GrenadeBindWeaponFx", tonumber(gunID))
                local fxPath = row and path(row.FxPath)
                local seqPath = row and path(row.FxSeqPath)
                if fxPath or seqPath then
                    item.Path, item.SequencePath, item.BoundID = fxPath, seqPath, tonumber(gunID)
                    break
                end
            end
            if not item.Path and not item.SequencePath then diagnostic("no_visual_mapping", res); return nil, res end
        end
        local useSequence = item.SequencePath and not item.SequenceFailed
        local assetPath = useSequence and item.SequencePath or item.Path
        if not assetPath then item.SequenceFailed = nil; return nil, res end
        if loading >= 2 then return nil, res end
        pcall(function()
            local manager = require("client.slua.logic.download.puffer.puffer_manager")
            local const = require("client.slua.logic.download.puffer.puffer_const")
            local kind = const.ENUM_DownloadType.ODPAK
            for _, resource in ipairs({ item.BoundID, assetPath }) do
                if resource then
                    local done = manager.GetState and const.ENUM_DownloadState
                        and manager.GetState(kind, { resource }) == const.ENUM_DownloadState.Done
                    if not done then manager.Download(kind, { resource }) end
                end
            end
        end)
        item.Pending, item.Started = true, now
        local token = {}; item.Token = token; loading = loading + 1
        local function callback(asset)
            if not item.Pending or item.Token ~= token then return end
            item.Pending = false; loading = math.max(0, loading - 1)
            if not active() or selectedFragRes() ~= res then return end
            if valid(asset) then
                if useSequence then item.SequenceAsset = asset else item.Asset = asset end
                diagnostic(useSequence and "sequence_ready" or "particle_ready", res)
            else
                if useSequence then item.SequenceFailed = true end
                diagnostic("asset_missing", assetPath)
            end
        end
        local ok, err = pcall(function()
            if slua.AsyncLoadAsset then slua.AsyncLoadAsset(assetPath, callback)
            else require("client.slua_ui_framework.util").GetAssetAsync(assetPath, callback) end
        end)
        if not ok then
            item.Pending = false; loading = math.max(0, loading - 1)
            if useSequence then item.SequenceFailed = true end
            diagnostic("load_error", err)
        end
        return (valid(item.SequenceAsset) or valid(item.Asset)) and item or nil, res
    end
    local function playFragBoundVisual(obj)
        if not localProjectile(obj) then return false end
        local item, res = prepareFragBoundVisual()
        if not item then return false end
        local record = state[obj] or {}; state[obj] = record
        if record.BoundEffectPlayed then return true end
        local native = nativeObject(obj)
        local okLoc, location = pcall(function()
            local actor = native or obj
            return actor:K2_GetActorLocation()
        end)
        if not okLoc or not location then diagnostic("position_unavailable", res); return false end
        local x, y, z = tonumber(location.X), tonumber(location.Y), tonumber(location.Z)
        if not x or not y or not z then return false end
        local worldLoc = FVector(x, y, z)
        local scale = tonumber(_G.MWConfig and _G.MWConfig.FragFxScale) or 200
        if scale ~= scale then scale = 200 end
        scale = math.max(100, math.min(200, scale)) / 100
        if valid(item.SequenceAsset) and item.SequencePath then
            for i = #sequences, 1, -1 do if not valid(sequences[i]) then table.remove(sequences, i) end end
            if #sequences >= 8 then
                local oldest = table.remove(sequences, 1)
                if valid(oldest) then pcall(oldest.K2_DestroyActor, oldest) end
            end
            local created
            local played, actor = pcall(function()
                local transformType = rawget(_G, "FTransform") or import("Transform")
                local transform = transformType(FRotator(0, 0, 0), worldLoc, FVector(scale, scale, scale))
                local instance = Game:PlayLevelSequence(obj, item.SequencePath, transform,
                    "/Game/Arts_PlayerBluePrints/DeadBox/DeadBoxSmoke/BP_DeadBoxSmokeSeqActor.BP_DeadBoxSmokeSeqActor_C", false)
                if not valid(instance) then return nil end
                created = instance; sequences[#sequences + 1] = instance
                instance:SetLifeSpan(30); instance:Play(0); return instance
            end)
            if played and valid(actor) then record.BoundEffectPlayed = true; diagnostic("sequence_spawned", res); return true end
            if valid(created) and created.K2_DestroyActor then pcall(created.K2_DestroyActor, created) end
            for i = #sequences, 1, -1 do if sequences[i] == created then table.remove(sequences, i) end end
            item.SequenceAsset, item.SequenceFailed, item.NextTry = nil, true, 0
        end
        if not valid(item.Asset) then prepareFragBoundVisual(); return false end
        local world = obj.GetWorld and obj:GetWorld() or native
        if not valid(world) then diagnostic("world_invalid", res); return false end
        local spawned, particle = pcall(function()
            return import("GameplayStatics").SpawnEmitterAtLocation(nativeObject(world), nativeObject(item.Asset),
                worldLoc, FRotator(0, 0, 0), FVector(scale, scale, scale), true)
        end)
        if spawned and valid(particle) then record.BoundEffectPlayed = true; diagnostic("particle_spawned", res); return true end
        diagnostic("spawn_failed", particle); return false
    end
    local function callNativeFragExplosion(original, obj, ...)
        local record = state[obj]
        if record and record.InNativeExplosion then return original(obj, ...) end
        local okFX, played = pcall(playFragBoundVisual, obj)
        if not okFX or not played then return original(obj, ...) end
        record = state[obj]; record.InNativeExplosion = true
        local saved, targets = {}, { obj }
        local native = nativeObject(obj); if native ~= obj then targets[#targets + 1] = native end
        for _, target in ipairs(targets) do
            local okScale, scale = pcall(function() return target.ExplosionTemplateScale end)
            if okScale and scale ~= nil then
                local isVec, x = pcall(function() return scale.X end)
                local zero = isVec and type(x) == "number" and FVector(0, 0, 0) or (type(scale) == "number" and 0 or nil)
                if zero ~= nil and pcall(function() target.ExplosionTemplateScale = zero end) then
                    saved[#saved + 1] = { Target = target, Key = "ExplosionTemplateScale", Value = scale, Applied = zero }
                end
            end
            for _, key in ipairs({ "ExplosionTemplate", "ExplodeParticleSystem" }) do
                local got, value = pcall(function() return target[key] end)
                if got and valid(value) then
                    local cleared = pcall(function() target[key] = nil end)
                    local readOK, current = pcall(function() return target[key] end)
                    if cleared and readOK and current == nil then saved[#saved + 1] = { Target = target, Key = key, Value = value } end
                end
            end
        end
        local results = { pcall(original, obj, ...) }
        for _, entry in ipairs(saved) do
            if valid(entry.Target) then pcall(function()
                if entry.Applied ~= nil or entry.Target[entry.Key] == nil then entry.Target[entry.Key] = entry.Value end
            end) end
        end
        record.InNativeExplosion = nil
        if not results[1] then error(results[2], 0) end
        return unpack(results, 2)
    end
    local function wrapModule(pathName, method, wrapperFactory)
        local ok, module = pcall(require, pathName)
        if not ok or type(module) ~= "table" then return false end
        local impl = rawget(module, "__inner_impl") or module
        local changed, seen = false, {}
        while type(impl) == "table" and not seen[impl] do
            seen[impl] = true
            local original = rawget(impl, method)
            if type(original) == "function" and not impl["_chan_frag_" .. method] then
                rawset(impl, method, wrapperFactory(original))
                impl["_chan_frag_" .. method] = true
                changed = true
            end
            impl = rawget(impl, "__super_impl")
        end
        return changed
    end
    local function install()
        if installed then return true end
        local root = "GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.SpecificProjectile.FragGrenade.FragGrenade"
        local changed = false
        changed = wrapModule(root, "BeginInitialize", function(original)
            return function(self, ...)
                local rec = state[self]; if rec then rec.BoundEffectPlayed = nil; rec.InNativeExplosion = nil end
                local results = { original(self, ...) }
                return unpack(results)
            end
        end) or changed
        changed = wrapModule(root, "BeginInEffect", function(original)
            return function(self, ...) return callNativeFragExplosion(original, self, ...) end
        end) or changed
        changed = wrapModule(root, "SpawnExplosionEffect", function(original)
            return function(self, ...)
                local okFX, played = pcall(playFragBoundVisual, self)
                if okFX and played then return end
                return original(self, ...)
            end
        end) or changed
        if changed then installed = true; diagnostic("installed") else diagnostic("hook_not_installed", root) end
        return installed
    end
    F.prepareFragBoundVisual = prepareFragBoundVisual
    F.playFragBoundVisual = playFragBoundVisual
    F.InstallFragBoundFX = install
    pcall(install)
end


-- ============================================================================
-- SRC GRENADE PROJECTILE LOGIC (ported to Chann persistence/cache)
-- Keeps Chann lobby skin injection and FragBoundFX; ports SRC flight/effect sync.
-- ============================================================================
do
    local state = setmetatable({}, { __mode = "k" })
    local tracked = setmetatable({}, { __mode = "k" })
    local hooks = {}
    local throwSlots = {
        [602004] = { "fragSkin", 612 },
        [602002] = { "smokeSkin", 613 },
        [602001] = { "stunSkin", 614 },
        [602003] = { "molotovSkin", 615 },
    }

    local function active()
        return not F.skinOff() and F.isInRealMatch and F.isInRealMatch() == true
    end
    local function nativeObject(obj)
        if not obj then return nil end
        local ok, value = pcall(function() return obj.Object end)
        return ok and value or obj
    end
    local function valid(obj)
        local native = nativeObject(obj)
        if not native then return false end
        local ok, result = pcall(slua.isValid, native)
        return ok and result == true
    end
    local function same(a, b)
        if not a or not b then return false end
        local na, nb = nativeObject(a), nativeObject(b)
        return valid(na) and valid(nb) and tostring(na) == tostring(nb)
    end
    local function localProjectile(obj)
        if not active() or not valid(obj) or type(obj.GetInstigatorControllerSafety) ~= "function" then return false end
        local ok, pc = pcall(obj.GetInstigatorControllerSafety, obj)
        return ok and same(pc, F.getPC())
    end
    local function getRes(slot, subtype)
        local cch = F.cache()
        local res = tonumber(PERSIST.configSlots and PERSIST.configSlots[slot])
        if not res then
            local info = cch.throwObjects and (cch.throwObjects[subtype] or cch.throwObjects[tostring(subtype)])
            if not info and PERSIST.configThrowObjects then
                info = PERSIST.configThrowObjects[subtype] or PERSIST.configThrowObjects[tostring(subtype)]
            end
            if not info and _G._savedThrowObjects then
                info = _G._savedThrowObjects[subtype] or _G._savedThrowObjects[tostring(subtype)]
            end
            res = type(info) == "table" and tonumber(info.resID) or tonumber(info)
        end
        if not res or res <= 0 or tonumber(F.subType(F.cfg(res))) ~= subtype then return nil end
        return res
    end
    local function getSpecForProjectile(obj)
        local pc = F.getPC()
        local selected = 0
        if obj.GetAvatarID and pc and pc.InitialConsumableAvatar then
            local ok, id = pcall(obj.GetAvatarID, obj, pc.InitialConsumableAvatar)
            if ok then selected = tonumber(id) or 0 end
        end
        local subtype = tonumber(F.subType(F.cfg(selected)))
        for _, spec in pairs(throwSlots) do
            if spec[2] == subtype then return spec, selected end
        end
        return nil, selected
    end

    function F.applyProjectileFlightSkin(obj)
        if not localProjectile(obj) then return false end
        tracked[obj] = true
        local comp = obj.GrenadeAvatarComponent_BP or obj.GrenadeAvatarComponent
        if not valid(comp) or not comp.ChangeItemAvatar then return false end
        local spec = getSpecForProjectile(obj)
        if not spec then return false end
        local res = getRes(spec[1], spec[2])
        if not res then return false end
        local rec = state[obj] or {}; state[obj] = rec
        if rec.FlightSkin ~= res then
            rec.FlightSkin, rec.FlightAttempts, rec.FlightPending = res, 0, nil
        end
        if rec.FlightApplying or rec.FlightPending then return false end
        if comp.GetCurGrenadeAvatarID and tonumber(comp:GetCurGrenadeAvatarID()) == res then return true end
        if not F.isResourcesReady(res) then
            rec.FlightPending = res
            F.requestResourceDownload(res)
            return false
        end
        if (rec.FlightAttempts or 0) >= 3 then return false end
        rec.FlightAttempts = (rec.FlightAttempts or 0) + 1
        rec.FlightApplying = true
        local ok = pcall(comp.ChangeItemAvatar, comp, res, false)
        rec.FlightApplying = nil
        return ok
    end

    function F.syncProjectileEffects(obj, phase)
        if not localProjectile(obj) then return false end
        tracked[obj] = true
        local comp = obj.GrenadeAvatarComponent_BP or obj.GrenadeAvatarComponent
        if not valid(comp) then return false end
        local ok = pcall(function()
            if obj.ResetGrenadeAvatar then obj:ResetGrenadeAvatar() end
        end)
        local skin = comp.GetCurGrenadeAvatarID and comp:GetCurGrenadeAvatarID() or 0
        _G.ChanGrenadeProjectileSync = {
            phase = tostring(phase or "unknown"), skin = tonumber(skin) or 0,
            refreshed = ok, time = os.clock()
        }
        return ok
    end

    function F.applySmokeProjectileVisual(obj, inActive)
        if not localProjectile(obj) then return false end
        tracked[obj] = true
        local res = getRes("smokeSkin", 613)
        if not res then return false end
        local okConfig, config = pcall(require,
            "GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.SpecificProjectile.SmokeBomb.SmokeBombConfig")
        local effect = okConfig and config and config.SkinIDToEffect and config.SkinIDToEffect[res]
        if not effect then return false end
        local rec = state[obj] or {}; state[obj] = rec
        if rec.SmokeSkin ~= res then rec.SmokeSkin, rec.SmokeRequests = res, {} end
        local requests = rec.SmokeRequests
        local function apply(field, assetPath, activate)
            local comp = obj[field]
            if not assetPath or assetPath == "" or not valid(comp) or not comp.SetTemplate then return end
            local item = requests[field]
            if item and item.Asset and item.Path == assetPath then
                if comp.Template ~= item.Asset then pcall(comp.SetTemplate, comp, item.Asset) end
                if activate and not item.Activated and comp.SetActive then
                    pcall(comp.SetActive, comp, true, true); item.Activated = true
                end
                return
            end
            if item and item.Pending and item.Path == assetPath then
                item.ActivateWanted = item.ActivateWanted or activate
                return
            end
            item = { Path = assetPath, Pending = true, ActivateWanted = activate }
            requests[field] = item
            if not obj.AsyncLoadAsset then item.Pending = false; return end
            local loaded = pcall(obj.AsyncLoadAsset, obj, assetPath, function(asset)
                item.Pending = false
                if not localProjectile(obj) or getRes("smokeSkin", 613) ~= res or requests[field] ~= item then return end
                if not valid(asset) then return end
                local target = obj[field]
                if not valid(target) or not target.SetTemplate then return end
                local old = state[target] or {}; state[target] = old
                if not old.SmokeTemplate then old.SmokeTemplate = { Original = target.Template } end
                pcall(target.SetTemplate, target, asset)
                old.SmokeTemplate.Applied = asset
                item.Asset = asset
                if item.ActivateWanted and target.SetActive then
                    pcall(target.SetActive, target, true, true); item.Activated = true
                end
            end)
            if not loaded then item.Pending = false end
        end
        apply("Smoking", effect.SmokeParticlePath, inActive == true)
        if not inActive then apply("P_White_Smoke_02", effect.SmokeTailParticlePath, false) end
        return true
    end

    local function hook(path, key, wrapper)
        local tag = path .. ":" .. key
        if hooks[tag] then return true end
        local ok, cls = pcall(require, path)
        if not ok or type(cls) ~= "table" then return false end
        local impl = rawget(cls, "__inner_impl") or cls
        local original = rawget(impl, key) or cls[key]
        if type(original) ~= "function" then return false end
        local wrapped = wrapper(original)
        pcall(rawset, impl, key, wrapped)
        pcall(rawset, cls, key, wrapped)
        hooks[tag] = true
        return true
    end

    function F.InstallSrcGrenadeLogic()
        local root = "GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.SpecificProjectile."
        local installedCount = 0
        for _, kind in ipairs({ "FragGrenade", "BurnGrenade", "StunGrenade" }) do
            local path = root .. kind .. "." .. kind
            for _, phase in ipairs({ "BeginInitialize", "BeginInEffect" }) do
                local stage = phase
                if hook(path, stage, function(original)
                    return function(self, ...)
                        if stage == "BeginInitialize" then
                            local rec = state[self]
                            if rec then rec.FlightSkin, rec.FlightAttempts, rec.FlightPending = nil, nil, nil end
                        end
                        local results = { original(self, ...) }
                        if stage == "BeginInitialize" then
                            pcall(F.applyProjectileFlightSkin, self)
                            pcall(F.syncProjectileEffects, self, stage)
                        elseif stage == "BeginInEffect" then
                            pcall(F.syncProjectileEffects, self, stage)
                        end
                        return unpack(results)
                    end
                end) then installedCount = installedCount + 1 end
            end
        end
        if hook(root .. "SmokeBomb.SmokeBomb", "RefreshProjectileSkin", function(original)
            return function(self, inActive, ...)
                local result = original(self, inActive, ...)
                pcall(F.applySmokeProjectileVisual, self, inActive)
                return result
            end
        end) then installedCount = installedCount + 1 end
        if hook("GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.ProjectileBase", "UpdateGrenadeAvatar", function(original)
            return function(self, ...)
                local results = { original(self, ...) }
                pcall(F.applyProjectileFlightSkin, self)
                return unpack(results)
            end
        end) then installedCount = installedCount + 1 end
        if hook("GameLua.Mod.Library.GamePlay.Avatar.Component.GrenadeAvatarComponent",
            "OnGrenadeAvatarEqiuped", function(original)
                return function(self, ...)
                    local result = original(self, ...)
                    local owner = self.GetOwner and self:GetOwner()
                    if valid(owner) and owner.GetInstigatorControllerSafety then
                        local ok, pc = pcall(owner.GetInstigatorControllerSafety, owner)
                        if ok and same(pc, F.getPC()) then
                            pcall(F.applyProjectileFlightSkin, owner)
                            pcall(F.syncProjectileEffects, owner, "OnGrenadeAvatarEqiuped")
                        end
                    end
                    return result
                end
            end) then installedCount = installedCount + 1 end
        _G.ChanSrcGrenadeHooksInstalled = installedCount == 9
        return _G.ChanSrcGrenadeHooksInstalled
    end

    function F.tickSrcGrenadeProjectiles()
        if not active() then return end
        for obj in pairs(tracked) do
            if not valid(obj) then
                tracked[obj] = nil
            elseif localProjectile(obj) then
                pcall(F.applyProjectileFlightSkin, obj)
                local rec = state[obj]
                if rec and rec.FlightPending and F.isResourcesReady(rec.FlightPending) then
                    rec.FlightPending = nil
                    pcall(F.applyProjectileFlightSkin, obj)
                end
            end
        end
    end

    pcall(F.InstallSrcGrenadeLogic)
end


end)

